export const COURSE: SeoLevel[] = [{"id":"beginner","slug":"beginner","title":"Beginner","cefr":"Noldan","text":"Ingliz tilini umuman bilmayman yoki juda kam bilaman. Harflar va tovushlardan boshlaymiz.","units":[{"id":"u1","n":1,"title":"Letters & Sounds","titleUz":"Alifbo va tovushlar: o'qish va talaffuz","description":"Alifbo, ingliz tovushlari, salomlashish, sonlar va birinchi so'zlar.","canDo":["Inglizcha alifboni aytaman","Ismimni harflab ayta olaman","Salomlashib, xayrlashaman","0 dan 20 gacha sanayman"],"lessons":[{"id":"u1-l1","slug":"the-alphabet-a-m","title":"The alphabet: A–M","titleUz":"Alifbo: A–M","goal":"Ingliz alifbosining birinchi 13 ta harfini nomi bilan to'g'ri aytasiz, ularni quloq bilan ajratasiz va shu harflar bilan boshlanadigan 10 ta so'zni bilib olasiz.","words":[{"en":"apple","uz":"olma","ipa":"ˈæp.əl"},{"en":"bag","uz":"sumka","ipa":"bæɡ"},{"en":"cat","uz":"mushuk","ipa":"kæt"},{"en":"dog","uz":"it","ipa":"dɒɡ"},{"en":"egg","uz":"tuxum","ipa":"eɡ"},{"en":"fish","uz":"baliq","ipa":"fɪʃ"},{"en":"girl","uz":"qiz bola","ipa":"ɡɜːl"},{"en":"hand","uz":"qo'l (kaft)","ipa":"hænd"},{"en":"key","uz":"kalit","ipa":"kiː"},{"en":"man","uz":"erkak","ipa":"mæn"}],"summary":["Ingliz alifbosida 26 ta harf bor; bugun A–M ni o'rgandik.","Eng muhim tuzoqlar: E = \"i:\", I = \"ay\", G = \"dji:\", J = \"djey\".","Guruhlar: ey (A, H, J, K) · i: (B, C, D, E, G) · e (F, L, M).","I (men), ismlar va gap boshi — doim katta harf bilan.","Yangi so'zlar: apple, bag, cat, dog, egg, fish, girl, hand, key, man."]},{"id":"u1-l2","slug":"the-alphabet-n-z","title":"The alphabet: N–Z","titleUz":"Alifbo: N–Z","goal":"Alifboning qolgan 13 ta harfini (N–Z) nomi bilan to'g'ri aytasiz, butun alifboni boshidan oxirigacha ayta olasiz va shu harflar bilan boshlanadigan 10 ta yangi so'zni bilib olasiz.","words":[{"en":"nose","uz":"burun","ipa":"nəʊz"},{"en":"orange","uz":"apelsin","ipa":"ˈɒr.ɪndʒ"},{"en":"pen","uz":"ruchka","ipa":"pen"},{"en":"queen","uz":"qirolicha","ipa":"kwiːn"},{"en":"sun","uz":"quyosh","ipa":"sʌn"},{"en":"table","uz":"stol","ipa":"ˈteɪ.bəl"},{"en":"umbrella","uz":"soyabon","ipa":"ʌmˈbrel.ə"},{"en":"van","uz":"furgon (yuk mashinasi)","ipa":"væn"},{"en":"water","uz":"suv","ipa":"ˈwɔː.tə"},{"en":"zoo","uz":"hayvonot bog'i","ipa":"zuː"}],"summary":["Endi butun alifboni bilasiz: A–M va N–Z, jami 26 ta harf.","Tuzoqlar: R = \"a:\", O = \"ou\", U = \"yu:\", W = \"dabl yu:\", Y = \"uay\", Z = \"zed\".","Unli harflar: A, E, I, O, U. Unli bilan boshlansa — an: an orange, an umbrella.","W — lablar dumaloq, \"v\" emas: water (\"uo:ta\").","Yangi so'zlar: nose, orange, pen, queen, sun, table, umbrella, van, water, zoo."]},{"id":"u1-l3","slug":"vowel-sounds-short-long","title":"Vowel sounds: short & long","titleUz":"Unli tovushlar: qisqa va cho'ziq","goal":"Har bir unli harfning qisqa va uzun o'qilishini ajratasiz, \"sehrli e\" qoidasi bilan hat va hate kabi so'zlarni to'g'ri o'qiysiz hamda 10 ta yangi so'zni bilib olasiz.","words":[{"en":"hat","uz":"shlyapa","ipa":"hæt"},{"en":"hate","uz":"yomon ko'rmoq","ipa":"heɪt"},{"en":"bed","uz":"karavot","ipa":"bed"},{"en":"sit","uz":"o'tirmoq","ipa":"sɪt"},{"en":"kite","uz":"varrak","ipa":"kaɪt"},{"en":"hot","uz":"issiq","ipa":"hɒt"},{"en":"home","uz":"uy","ipa":"həʊm"},{"en":"cut","uz":"kesmoq","ipa":"kʌt"},{"en":"cute","uz":"yoqimtoy, shirin","ipa":"kjuːt"},{"en":"tree","uz":"daraxt","ipa":"triː"}],"summary":["Har bir unli ikki xil o'qiladi: qisqa (hat, bed, sit, hot, cut) va uzun — harf nomi (hate, tree, kite, home, cute).","Sehrli e: unli + undosh + e → unli o'z nomini aytadi, e esa eshitilmaydi: kit → kite.","Qisqa u — \"a\"ga o'xshaydi: cut = \"kat\", bus = \"bas\".","ee — uzun \"i:\": tree.","Yangi so'zlar: hat, hate, bed, sit, kite, hot, home, cut, cute, tree."]},{"id":"u1-l4","slug":"letter-teams-sh-ch-th","title":"Letter teams: sh, ch, th…","titleUz":"Harf birikmalari: sh, ch, th…","goal":"sh, ch, th, ph, wh, ck, ng, ee, oo harf birikmalarini ko'rganda to'g'ri o'qiysiz, ayniqsa o'zbek tilida yo'q th tovushini talaffuz qila olasiz va 10 ta yangi so'zni bilib olasiz.","words":[{"en":"ship","uz":"kema","ipa":"ʃɪp"},{"en":"chicken","uz":"tovuq","ipa":"ˈtʃɪk.ɪn"},{"en":"think","uz":"o'ylamoq","ipa":"θɪŋk"},{"en":"photo","uz":"surat, foto","ipa":"ˈfəʊ.təʊ"},{"en":"whale","uz":"kit","ipa":"weɪl"},{"en":"duck","uz":"o'rdak","ipa":"dʌk"},{"en":"sing","uz":"kuylamoq","ipa":"sɪŋ"},{"en":"sheep","uz":"qo'y","ipa":"ʃiːp"},{"en":"book","uz":"kitob","ipa":"bʊk"},{"en":"food","uz":"ovqat","ipa":"fuːd"}],"summary":["Harf birikmasi = bitta tovush: sh (ship), ch (chicken), ng (sing), ph = \"f\" (photo), ck = \"k\" (duck).","th — til uchi tishlar orasida: jarangsiz (think, three) va jarangli (this, the).","wh / w — lablar dumaloq, \"v\" emas: whale, water. Istisno: who = \"hu:\".","ee = uzun \"i:\" (sheep); oo = uzun \"u:\" (food) yoki qisqa \"u\" (book).","Yangi so'zlar: ship, chicken, think, photo, whale, duck, sing, sheep, book, food."]},{"id":"u1-l5","slug":"hello-greetings","title":"Hello! Greetings","titleUz":"Salomlashish va xayrlashish","goal":"Kunning vaqtiga mos salomlashasiz, o'zingizni tanishtirasiz (Hello, I'm… / My name is…), hol-ahvol so'raysiz va xayrlashasiz. please, thank you, sorry kabi odob so'zlarini to'g'ri ishlatasiz.","words":[{"en":"hello","uz":"salom","ipa":"həˈləʊ"},{"en":"hi","uz":"salom (do'stona)","ipa":"haɪ"},{"en":"good morning","uz":"xayrli tong","ipa":"ɡʊd ˈmɔː.nɪŋ"},{"en":"good afternoon","uz":"xayrli kun (tushdan keyin)","ipa":"ɡʊd ˌɑːf.təˈnuːn"},{"en":"good evening","uz":"xayrli kech","ipa":"ɡʊd ˈiːv.nɪŋ"},{"en":"good night","uz":"xayrli tun","ipa":"ɡʊd ˈnaɪt"},{"en":"goodbye","uz":"xayr","ipa":"ɡʊdˈbaɪ"},{"en":"please","uz":"iltimos","ipa":"pliːz"},{"en":"thank you","uz":"rahmat","ipa":"ˈθæŋk juː"},{"en":"sorry","uz":"kechirasiz, uzr","ipa":"ˈsɒr.i"}],"summary":["Salom: Hello (hamma uchun), Hi (do'stona). Vaqtga qarab: Good morning / afternoon / evening.","Good night — faqat xayrlashganda! Xayr: Goodbye, Bye.","Tanishish: I'm Ali. / My name is Ali. — Nice to meet you. — Nice to meet you, too.","How are you? — I'm fine, thanks. And you? (\"am\" ni tushirmang: I'm).","Odob so'zlari: please, thank you (th!), sorry."]},{"id":"u1-l11","slug":"real-life-meeting-someone-new","title":"Real life: meeting someone new","titleUz":"Real hayot: yangi odam bilan tanishish","goal":"Yangi odam bilan salomlashasiz, ismingizni aytasiz, «Qalaysiz?» ga javob berasiz va xayrlashasiz. Faqat 1–5-darslarda o'rganganlaringiz kerak bo'ladi.","words":[],"summary":["Good morning — ertalab, Good night — tunda; vaqtga mos salom tanlang.","My name is Ali. yoki I'm Ali. — o'zingizni tanishtirish.","How are you? → I'm fine, thank you. (I'm = I am: «I fine» demaymiz).","Nice to meet you. — «Tanishganimdan xursandman.»"]},{"id":"u1-l6","slug":"numbers-0-20","title":"Numbers 0–20","titleUz":"Sonlar 0–20","goal":"0 dan 20 gacha sonlarni to'g'ri aytasiz, yozasiz va quloq bilan ajratasiz; -teen sonlarining urg'usini bilasiz va yoshingizni, telefon raqamini inglizcha ayta olasiz.","words":[{"en":"zero","uz":"nol","ipa":"ˈzɪə.rəʊ"},{"en":"three","uz":"uch","ipa":"θriː"},{"en":"five","uz":"besh","ipa":"faɪv"},{"en":"eight","uz":"sakkiz","ipa":"eɪt"},{"en":"eleven","uz":"o'n bir","ipa":"ɪˈlev.ən"},{"en":"twelve","uz":"o'n ikki","ipa":"twelv"},{"en":"thirteen","uz":"o'n uch","ipa":"ˌθɜːˈtiːn"},{"en":"fifteen","uz":"o'n besh","ipa":"ˌfɪfˈtiːn"},{"en":"eighteen","uz":"o'n sakkiz","ipa":"ˌeɪˈtiːn"},{"en":"twenty","uz":"yigirma","ipa":"ˈtwen.ti"}],"summary":["0–10: zero, one, two, three, four, five, six, seven, eight, nine, ten. Tuzoqlar: one = \"uan\", two = \"tu:\", eight = \"eyt\".","11, 12 — alohida so'zlar: eleven, twelve. 13–19 = son + -teen.","Imlo tuzoqlari: thirteen, fifteen, eighteen (bitta t).","Urg'u: thirTEEN (13) ↔ THIRty (30).","Yosh: I'm twelve. (\"I have twelve\" emas). Telefon: raqamma-raqam, 0 = oh, 55 = double five."]},{"id":"u1-l7","slug":"how-do-you-spell-it","title":"How do you spell it?","titleUz":"Harflab aytish va sinf iboralari","goal":"Ismingizni va so'zlarni harfma-harf aytasiz (How do you spell…?), o'qituvchining topshiriqlarini (Open your books, Listen and repeat) tushunasiz va darsda kerakli iboralarni (Sorry, I don't understand. Can you repeat that, please?) ishlatasiz.","words":[{"en":"name","uz":"ism","ipa":"neɪm"},{"en":"spell","uz":"harflab aytmoq","ipa":"spel"},{"en":"letter","uz":"harf","ipa":"ˈlet.ə"},{"en":"word","uz":"so'z","ipa":"wɜːd"},{"en":"repeat","uz":"takrorlamoq","ipa":"rɪˈpiːt"},{"en":"listen","uz":"tinglamoq","ipa":"ˈlɪs.ən"},{"en":"read","uz":"o'qimoq","ipa":"riːd"},{"en":"write","uz":"yozmoq","ipa":"raɪt"},{"en":"open","uz":"ochmoq","ipa":"ˈəʊ.pən"},{"en":"close","uz":"yopmoq","ipa":"kləʊz"}],"summary":["Savol: How do you spell your name? — javob harflar nomi bilan: A-Z-I-Z.","Ikki bir xil harf — double: Anna = A, double N, A. Tutuq belgisi — apostrophe.","Topshiriqlar: Open / Close your books. Listen and repeat. Read. Write.","Kerakli iboralar: Sorry, I don't understand. Can you repeat that, please?","Talaffuz: write (w yo'q), listen (t yo'q), read = \"ri:d\", close = \"klouz\"."]},{"id":"u1-l8","slug":"colours-things","title":"Colours & things","titleUz":"Ranglar va narsalar","goal":"Asosiy ranglarni va big, small, new sifatlarini to'g'ri aytasiz, ularni ot oldiga qo'yib narsalarni tasvirlaysiz (a red bag, an orange, a big dog) va What colour is it? — It's blue. savol-javobini ishlatasiz.","words":[{"en":"red","uz":"qizil","ipa":"red"},{"en":"blue","uz":"ko'k, havorang","ipa":"bluː"},{"en":"green","uz":"yashil","ipa":"ɡriːn"},{"en":"yellow","uz":"sariq","ipa":"ˈjel.əʊ"},{"en":"black","uz":"qora","ipa":"blæk"},{"en":"white","uz":"oq","ipa":"waɪt"},{"en":"brown","uz":"jigarrang","ipa":"braʊn"},{"en":"big","uz":"katta","ipa":"bɪɡ"},{"en":"small","uz":"kichik","ipa":"smɔːl"},{"en":"new","uz":"yangi","ipa":"njuː"}],"summary":["Ranglar: red, blue, green, yellow, black, white, brown (+ orange, pink, grey).","Sifat otdan oldin keladi, o'zbekchadagidek: a red bag, a big dog. Sifat o'zgarmaydi.","a / an birinchi so'zga qarab: an apple → a red apple; a bag → an orange bag.","Ikki sifat: avval o'lcham, keyin rang — a big black dog.","What colour is it? — It's blue. Rang aytganda is shart: The bag is blue."]},{"id":"u1-l9","slug":"meeting-someone-name-spelling-numbers","title":"Meeting someone: name, spelling, numbers","titleUz":"Yangi tanish: ism, harflash, raqam","goal":"Yangi odam bilan tanishasiz, ismingizni harflab aytasiz va telefon raqamingizni raqam-raqam diktant qilasiz. Hammasi 1–8-darslarda o'rganganlaringiz asosida.","words":[{"en":"surname","uz":"familiya","ipa":"ˈsɜː.neɪm"},{"en":"phone","uz":"telefon","ipa":"fəʊn"},{"en":"number","uz":"raqam, son","ipa":"ˈnʌm.bə"},{"en":"again","uz":"yana, qayta","ipa":"əˈɡen"}],"summary":["Tanishuv: Good morning. I'm… — Nice to meet you, too.","Ism so'rash: What's your name? How do you spell it? Harflar nomi bilan aytiladi.","Telefon raqami raqam-raqam aytiladi: nine, zero, one…","Tushunmasangiz: Can you repeat that, please?"]},{"id":"u1-l12","slug":"real-life-at-the-registration-desk","title":"Real life: at the registration desk","titleUz":"Real hayot: ro'yxatdan o'tish stolida","goal":"Til maktabida ro'yxatdan o'tasiz: ismingizni aytasiz, familiyangizni harflab berasiz, telefon raqamingizni raqam-raqam aytasiz, tushunmasangiz muloyim takrorlashni so'raysiz va xayrlashasiz.","words":[],"summary":["My name is Ali Karimov. — ism va familiyani aytish.","Familiya harflab aytiladi: K-A-R-I-M-O-V (harflar nomi bilan).","Telefon raqami raqam-raqam aytiladi: nine, zero, five… Nol — zero.","Tushunmasangiz: Sorry, can you repeat that, please? (Repeat! qo'pol eshitiladi).","Minnatdorchilik: Thank you. — Nice to meet you, too."]},{"id":"u1-l10","slug":"letters-sounds-final-review","title":"Letters & sounds: final review","titleUz":"Alifbo va tovushlar: yakuniy takror","goal":"1-bo'limdagi hamma narsani takrorlaysiz: alifbo, unlilar, harf juftliklari, salomlashish, 0–20 raqamlar, harflab aytish va ranglar. Bo'lim oxirida o'zingizni sinab ko'rasiz.","words":[{"en":"alphabet","uz":"alifbo","ipa":"ˈæl.fə.bet"},{"en":"vowel","uz":"unli harf","ipa":"ˈvaʊ.əl"},{"en":"sound","uz":"tovush","ipa":"saʊnd"},{"en":"colour","uz":"rang","ipa":"ˈkʌl.ə"}],"summary":["Alifbo — 26 harf; unlilar a, e, i, o, u; sehrli e unlini uzun qiladi (hat → hate).","Harf juftliklari: sh, ch, th, ph, ng, oo — bitta tovush beradi.","Salom va tanishuv: Hello, I'm… / Nice to meet you. / I'm fine, thanks.","Raqamlar 0–20, ranglar va a / an — gaplarda ishlating.","Harflash: How do you spell it? — harflar nomi bilan, double bilan."]}]},{"id":"u2","n":2,"title":"To be: Who am I?","titleUz":"Men kimman? Olmoshlar va to be (am / is / are)","description":"Olmoshlar, am / is / are, inkor va savol, a / an, ko'plik, this / that, egalik.","canDo":["O'zim va boshqalar haqida am / is / are bilan gapiraman","Kasb va millatni ayta olaman","a / an va ko'plikni to'g'ri ishlataman","this / that, my / your bilan narsalarni ko'rsataman"],"lessons":[{"id":"u2-l1","slug":"personal-pronouns","title":"Personal pronouns","titleUz":"Kishilik olmoshlari","goal":"Ingliz tilidagi 7 ta kishilik olmoshini (I, you, he, she, it, we, they) to'g'ri aytasiz va ishlatasiz: odam va narsalar o'rniga mos olmoshni tanlaysiz, ayniqsa o'zbekcha \"u\" ni he / she / it ga to'g'ri ajratasiz.","words":[{"en":"friend","uz":"do'st","ipa":"frend"},{"en":"teacher","uz":"o'qituvchi","ipa":"ˈtiː.tʃə"},{"en":"student","uz":"talaba, o'quvchi","ipa":"ˈstjuː.dənt"},{"en":"boy","uz":"o'g'il bola","ipa":"bɔɪ"},{"en":"woman","uz":"ayol","ipa":"ˈwʊm.ən"},{"en":"neighbour","uz":"qo'shni","ipa":"ˈneɪ.bə"},{"en":"classmate","uz":"sinfdosh","ipa":"ˈklɑːs.meɪt"},{"en":"guest","uz":"mehmon","ipa":"ɡest"},{"en":"colleague","uz":"hamkasb","ipa":"ˈkɒl.iːɡ"},{"en":"team","uz":"jamoa","ipa":"tiːm"}],"summary":["7 ta olmosh: I (men), you (sen/siz/sizlar), he, she, it (u), we (biz), they (ular).","O'zbekcha \"u\" = he (erkak), she (ayol), it (narsa, hayvon).","you — sen ham, siz ham, sizlar ham; they — odamlar ham, narsalar ham.","Ingliz gapida ega doim aytiladi: I'm a student, \"Am a student\" emas. I doim katta harf.","Yangi so'zlar: friend, teacher, student, boy, woman, neighbour, classmate, guest, colleague, team."]},{"id":"u2-l2","slug":"to-be-am-is-are","title":"To be: am / is / are","titleUz":"To be: am / is / are","goal":"am / is / are ni har bir olmosh va ism bilan to'g'ri tanlaysiz, qisqa shakllarni (I'm, he's, they're…) aytasiz va o'zingiz hamda boshqalar haqida I'm tired, She's a teacher kabi gaplar tuzasiz.","words":[{"en":"happy","uz":"xursand, baxtli","ipa":"ˈhæp.i"},{"en":"sad","uz":"xafa, g'amgin","ipa":"sæd"},{"en":"tired","uz":"charchagan","ipa":"ˈtaɪəd"},{"en":"hungry","uz":"och (qorni och)","ipa":"ˈhʌŋ.ɡri"},{"en":"thirsty","uz":"chanqagan","ipa":"ˈθɜː.sti"},{"en":"busy","uz":"band","ipa":"ˈbɪz.i"},{"en":"ready","uz":"tayyor","ipa":"ˈred.i"},{"en":"late","uz":"kechikkan, kech","ipa":"leɪt"},{"en":"angry","uz":"jahli chiqqan, g'azablangan","ipa":"ˈæŋ.ɡri"},{"en":"fine","uz":"yaxshi (sog')","ipa":"faɪn"}],"summary":["Ingliz tilida \"kim/qanday\" gaplarida to be shart: I am a student, \"I student\" emas.","I → am, he / she / it → is, you / we / they → are.","Qisqa shakllar: I'm, you're, he's, she's, it's, we're, they're.","Holatlar to be bilan: I'm hungry, I'm tired, I'm late, I'm 18.","Yangi so'zlar: happy, sad, tired, hungry, thirsty, busy, ready, late, angry, fine."]},{"id":"u2-l3","slug":"to-be-negatives","title":"To be: negatives","titleUz":"To be: inkor gaplar","goal":"am / is / are dan keyin not qo'yib inkor gap tuzasiz (I'm not tired, She isn't old), ikkala qisqa shaklni ham bilasiz va odamlar hamda narsalarni qarama-qarshi sifatlar bilan tasvirlaysiz.","words":[{"en":"tall","uz":"baland bo'yli, baland","ipa":"tɔːl"},{"en":"short","uz":"past bo'yli, qisqa","ipa":"ʃɔːt"},{"en":"young","uz":"yosh","ipa":"jʌŋ"},{"en":"old","uz":"qari, keksa; eski","ipa":"əʊld"},{"en":"beautiful","uz":"go'zal, chiroyli","ipa":"ˈbjuː.tɪ.fəl"},{"en":"rich","uz":"boy","ipa":"rɪtʃ"},{"en":"poor","uz":"kambag'al","ipa":"pɔː"},{"en":"cheap","uz":"arzon","ipa":"tʃiːp"},{"en":"expensive","uz":"qimmat","ipa":"ɪkˈspen.sɪv"},{"en":"clean","uz":"toza","ipa":"kliːn"}],"summary":["Inkor: am / is / are + not: I am not, he is not, they are not.","Qisqa shakllar: I'm not; isn't / 's not; aren't / 're not. \"I amn't\" — yo'q!","Xato qilmang: \"I not tired\", \"He not is\", \"I don't tired\" — noto'g'ri.","Juft sifatlar: tall–short, young–old, rich–poor, cheap–expensive, clean–dirty.","Yangi so'zlar: tall, short, young, old, beautiful, rich, poor, cheap, expensive, clean."]},{"id":"u2-l4","slug":"to-be-questions","title":"To be: questions","titleUz":"To be: savollar va qisqa javoblar","goal":"Are you…? Is she…? kabi savollar berasiz, ularga Yes, I am / No, I'm not shaklida to'g'ri qisqa javob qaytarasiz va odamlar qayerdaligini (at home, at work, at school) so'raysiz.","words":[{"en":"home","uz":"uy (o'z uyi)","ipa":"həʊm"},{"en":"school","uz":"maktab","ipa":"skuːl"},{"en":"work","uz":"ish","ipa":"wɜːk"},{"en":"office","uz":"ofis, idora","ipa":"ˈɒf.ɪs"},{"en":"shop","uz":"do'kon","ipa":"ʃɒp"},{"en":"park","uz":"bog', park","ipa":"pɑːk"},{"en":"hospital","uz":"kasalxona","ipa":"ˈhɒs.pɪ.təl"},{"en":"bank","uz":"bank","ipa":"bæŋk"},{"en":"library","uz":"kutubxona","ipa":"ˈlaɪ.brər.i"},{"en":"market","uz":"bozor","ipa":"ˈmɑː.kɪt"}],"summary":["Savolda am / is / are boshiga chiqadi: You are → Are you…?","Qisqa javob: Yes, I am. / No, I'm not. · Yes, she is. / No, she isn't.","\"Yes, I'm\", \"Yes, he's\" — xato: ha javobida qisqartirilmaydi.","Javobda ism emas, olmosh: Is Ali at work? — Yes, he is.","Joylar: at home, at work, at school; at the office / shop / bank / library / market / hospital; in the park."]},{"id":"u2-l5","slug":"a-an-plurals","title":"a / an & plurals","titleUz":"a / an va ko'plik","goal":"a va an ni so'zning tovushiga qarab tanlaysiz (an hour, a university), otlarni ko'plikka to'g'ri o'tkazasiz (-s, -es, -ies, -ves va child → children kabi noto'g'ri shakllar) va -s oxirini /s/, /z/, /ɪz/ deb to'g'ri talaffuz qilasiz.","words":[{"en":"box","uz":"quti","ipa":"bɒks"},{"en":"bus","uz":"avtobus","ipa":"bʌs"},{"en":"watch","uz":"qo'l soati","ipa":"wɒtʃ"},{"en":"baby","uz":"chaqaloq, go'dak","ipa":"ˈbeɪ.bi"},{"en":"city","uz":"shahar","ipa":"ˈsɪt.i"},{"en":"knife","uz":"pichoq","ipa":"naɪf"},{"en":"child","uz":"bola","ipa":"tʃaɪld"},{"en":"person","uz":"odam, kishi","ipa":"ˈpɜː.sən"},{"en":"foot","uz":"oyoq (panja)","ipa":"fʊt"},{"en":"tooth","uz":"tish","ipa":"tuːθ"}],"summary":["Bitta sanaladigan narsa/odam oldidan a / an: I'm a student. It's a box. Ko'plikda — yo'q.","a / an tovushga qarab: an hour, an umbrella, lekin a university, a house.","Ko'plik: -s (cats), -es (buses, boxes, watches), -ies (babies, cities), -ves (knives).","Yod oling: children, people, men, women, feet, teeth. Sondan keyin doim ko'plik: two cats.","-s talaffuzi: /s/ cats · /z/ dogs · /ɪz/ buses."]},{"id":"u2-l12","slug":"a-an-sound-not-letter","title":"a / an: sound, not letter","titleUz":"a / an: harf emas, tovush hal qiladi","goal":"a yoki an ni so'zning birinchi harfiga emas, birinchi tovushiga qarab tanlaysiz: an hour, an honest man, a university, a European city. Tanlovni 3 soniyada qila olasiz.","words":[{"en":"hour","uz":"soat (60 daqiqa)","ipa":"aʊ.ər"},{"en":"honest","uz":"halol, rostgo'y","ipa":"ˈɒn.ɪst"},{"en":"university","uz":"universitet","ipa":"ˌjuː.nɪˈvɜː.sɪ.ti"},{"en":"uniform","uz":"forma (kiyim)","ipa":"ˈjuː.nɪ.fɔːm"},{"en":"European","uz":"yevropalik; Yevropa","ipa":"ˌjʊə.rəˈpiː.ən"},{"en":"onion","uz":"piyoz","ipa":"ˈʌn.jən"}],"summary":["a / an ni tovush hal qiladi: unli tovush → an, undosh tovush → a.","Harf unli, tovush undosh: a university, a uniform, a European city, a one-way street.","Harf undosh, tovush unli: an hour, an honest man (h jim), an MP3, an X-ray.","Shubha bo'lsa so'zni ovoz chiqarib ayting va birinchi tovushni eshiting."]},{"id":"u2-l13","slug":"plurals-spelling-rules","title":"Plurals: spelling rules","titleUz":"Ko'plik: -s, -es, -ies imlosi","goal":"Otning oxirgi harfiga qarab ko'plikni to'g'ri yozasiz (dish → dishes, party → parties, day → days, shelf → shelves) va ko'plik oxirini /s/, /z/, /ɪz/ deb to'g'ri o'qiysiz.","words":[{"en":"toy","uz":"o'yinchoq","ipa":"tɔɪ"},{"en":"class","uz":"sinf; dars","ipa":"klɑːs"},{"en":"story","uz":"hikoya","ipa":"ˈstɔː.ri"},{"en":"party","uz":"ziyofat, bazm","ipa":"ˈpɑː.ti"},{"en":"shelf","uz":"tokcha, javon","ipa":"ʃelf"},{"en":"tomato","uz":"pomidor","ipa":"təˈmɑː.təʊ"}],"summary":["Ko'pchilik otlar: -s (dogs, days, photos).","s, ss, x, sh, ch bilan tugasa: -es (dishes, classes); tomato, potato → tomatoes, potatoes.","Undosh + y → -ies (parties, stories); unli + y → -s (days, toys).","-f / -fe → -ves (shelves, lives, wives), lekin roofs.","Oxiri: /s/ cats · /z/ days · /ɪz/ dishes."]},{"id":"u2-l14","slug":"irregular-plurals","title":"Irregular plurals","titleUz":"Noto'g'ri ko'plik: child → children","goal":"Eng ko'p ishlatiladigan noto'g'ri ko'pliklarni guruhlab eslab qolasiz (man → men, foot → feet, child → children, sheep → sheep) va ular bilan are ishlatasiz: The children are happy.","words":[{"en":"mouse","uz":"sichqon","ipa":"maʊs"},{"en":"sheep","uz":"qo'y","ipa":"ʃiːp"},{"en":"deer","uz":"kiyik","ipa":"dɪər"},{"en":"goose","uz":"g'oz","ipa":"guːs"},{"en":"policeman","uz":"politsiyachi","ipa":"pəˈliːs.mən"},{"en":"businessman","uz":"tadbirkor","ipa":"ˈbɪz.nɪs.mæn"}],"summary":["Unli almashadi: man → men, woman → women, foot → feet, tooth → teeth, goose → geese, mouse → mice.","Alohida shakllar: child → children, person → people.","O'zgarmaydiganlar: sheep, fish, deer (ten sheep).","childs, peoples, mans, foots — mavjud emas. Ko'plikdagi gapda are: The children are happy."]},{"id":"u2-l6","slug":"this-that-these-those","title":"this / that / these / those","titleUz":"this / that / these / those","goal":"Yaqin va uzoqdagi narsalarni this / that / these / those bilan ko'rsatasiz, ularni is / are va birlik/ko'plik bilan to'g'ri moslaysiz, this va these ni talaffuzda ajratasiz hamda kiyim va buyumlar haqida gapirasiz.","words":[{"en":"phone","uz":"telefon","ipa":"fəʊn"},{"en":"window","uz":"deraza","ipa":"ˈwɪn.dəʊ"},{"en":"shoe","uz":"tufli, oyoq kiyim","ipa":"ʃuː"},{"en":"shirt","uz":"ko'ylak (erkaklar)","ipa":"ʃɜːt"},{"en":"dress","uz":"ko'ylak (ayollar)","ipa":"dres"},{"en":"cup","uz":"piyola, chashka","ipa":"kʌp"},{"en":"glass","uz":"stakan; shisha (material)","ipa":"ɡlɑːs"},{"en":"bottle","uz":"shisha, butilka","ipa":"ˈbɒt.əl"},{"en":"chair","uz":"stul","ipa":"tʃeə"},{"en":"jacket","uz":"kurtka, jaket","ipa":"ˈdʒæk.ɪt"}],"summary":["Yaqin: this (bitta) · these (ko'p). Uzoq: that (bitta) · those (ko'p).","this / that + is, these / those + are — va ot ham mos: these shoes.","Talaffuz: this — qisqa \"i\" + s; these — cho'ziq \"i:\" + z; th — til tishlar orasida.","Savolda: Is this…? / Are these…? — javobda it / they: Yes, it is. / No, they aren't.","Yangi so'zlar: phone, window, shoe, shirt, dress, cup, glass, bottle, chair, jacket."]},{"id":"u2-l7","slug":"my-your-his-and-s","title":"my, your, his… and 's","titleUz":"Egalik: my, your, his… va 's","goal":"Egalikni my, your, his, her, its, our, their va 's (Ali's car) bilan ifodalaysiz, his / her ni egasiga qarab tanlaysiz, it's va its ni ajratasiz hamda o'zingiz haqidagi shaxsiy ma'lumotni (familiya, manzil, telefon raqami, email) aytasiz.","words":[{"en":"surname","uz":"familiya","ipa":"ˈsɜː.neɪm"},{"en":"address","uz":"manzil","ipa":"əˈdres"},{"en":"phone number","uz":"telefon raqami","ipa":"ˈfəʊn ˌnʌm.bə"},{"en":"email","uz":"elektron pochta, email","ipa":"ˈiː.meɪl"},{"en":"birthday","uz":"tug'ilgan kun","ipa":"ˈbɜːθ.deɪ"},{"en":"car","uz":"mashina, avtomobil","ipa":"kɑː"},{"en":"house","uz":"uy (bino)","ipa":"haʊs"},{"en":"room","uz":"xona","ipa":"ruːm"},{"en":"wife","uz":"xotin, rafiqa","ipa":"waɪf"},{"en":"husband","uz":"er, turmush o'rtoq","ipa":"ˈhʌz.bənd"}],"summary":["Egalik so'zlari otdan oldin: my, your, his, her, its, our, their + ot.","his — egasi erkak, her — egasi ayol: Aziz and his wife, Malika and her husband.","Ismlar bilan 's: Ali's car, my friend's house (\"car of Ali\" emas).","it's = it is; its = uning (narsa). your / you're, their / they're — bir xil eshitiladi.","Yangi so'zlar: surname, address, phone number, email, birthday, car, house, room, wife, husband."]},{"id":"u2-l8","slug":"countries-nationalities-jobs","title":"Countries, nationalities & jobs","titleUz":"Davlatlar, millatlar va kasblar","goal":"Qayerdan ekaningizni (I'm from Uzbekistan), millatingizni (I'm Uzbek) va kasbingizni (I'm a doctor) to'g'ri aytasiz: davlat va millat nomlarini katta harf bilan yozasiz, kasb oldidan a / an qo'yasiz va bu bo'limda o'rganganlaringiz bilan o'zingizni to'liq tanishtirasiz.","words":[{"en":"country","uz":"davlat, mamlakat","ipa":"ˈkʌn.tri"},{"en":"Uzbekistan","uz":"O'zbekiston","ipa":"ʊzˌbek.ɪˈstɑːn"},{"en":"Uzbek","uz":"o'zbek; o'zbek tili","ipa":"ˈʊz.bek"},{"en":"England","uz":"Angliya","ipa":"ˈɪŋ.ɡlənd"},{"en":"English","uz":"ingliz; ingliz tili","ipa":"ˈɪŋ.ɡlɪʃ"},{"en":"doctor","uz":"shifokor","ipa":"ˈdɒk.tə"},{"en":"engineer","uz":"muhandis","ipa":"ˌen.dʒɪˈnɪə"},{"en":"driver","uz":"haydovchi","ipa":"ˈdraɪ.və"},{"en":"nurse","uz":"hamshira","ipa":"nɜːs"},{"en":"lawyer","uz":"huquqshunos, advokat","ipa":"ˈlɔɪ.ə"}],"summary":["Davlat: I'm from Uzbekistan. Millat: I'm Uzbek. (\"I'm from Uzbek\" — xato).","Davlat, millat va til nomlari doim katta harf bilan: Uzbek, English, Chinese.","Kasb oldidan a / an: She's a doctor. He's an engineer. Ko'plikda: They're doctors.","Urg'u: UzbekiSTAN, UZbek, JapaNESE, engiNEER, DOCtor.","Yangi so'zlar: country, Uzbekistan, Uzbek, England, English, doctor, engineer, driver, nurse, lawyer."]},{"id":"u2-l15","slug":"real-life-where-are-you-from","title":"Real life: where are you from?","titleUz":"Real hayot: qayerdansiz? kasbingiz nima?","goal":"Yangi sinfdosh bilan gaplashasiz: qayerdansiz, kasbingiz, millatingiz haqida aytasiz, qisqa javob berasiz (Yes, I am. / No, I'm not.) va unga qaytib savol berasiz.","words":[],"summary":["I'm from Uzbekistan. — I bilan har doim am (I from… demaymiz).","Kasb oldidan a / an: a student, an engineer (unli tovush oldida an).","Qisqa javob: Yes, I am. / No, I'm not. (Yes, I'm emas).","Davlat va millat: Uzbekistan (davlat) — Uzbek (millat): I'm Uzbek.","Qaytib so'rash: And where are you from?"]},{"id":"u2-l9","slug":"introducing-myself-and-my-family","title":"Introducing myself and my family","titleUz":"O'zim va oilam haqida tanishtirish","goal":"Yangi tanishingizga o'zingizni va oilangizni tanishtirasiz: I'm Aziz. This is my mother. She's a doctor. — to be, my / his / her va a / an bilan.","words":[{"en":"family","uz":"oila","ipa":"ˈfæm.əl.i"},{"en":"mother","uz":"ona","ipa":"ˈmʌð.ə"},{"en":"father","uz":"ota","ipa":"ˈfɑː.ðə"},{"en":"sister","uz":"opa, singil","ipa":"ˈsɪs.tə"}],"summary":["Tanishtirish: This is my mother. She's a teacher. — his / her ni to'g'ri tanlang.","Kasb oldidan a / an, ko'plikda esa yo'q: They're doctors.","Yangi so'zlar: family, mother, father, sister — o'z oilangiz haqida gapiring."]},{"id":"u2-l16","slug":"real-life-my-family-photo","title":"Real life: my family photo","titleUz":"Real hayot: oilaviy surat","goal":"Do'stingizga oilaviy suratni ko'rsatasiz: kim ekanini, ismini va yoshini aytasiz. my / his / her / their ni to'g'ri tanlaysiz va have bilan yosh aytmaysiz.","words":[],"summary":["This is my sister. — my = mening; They are my parents.","Her name is Madina. — qiz/ayol uchun her, o'g'il/erkak uchun his (He name emas).","How old is she? → She is sixteen. (yoshni be bilan aytamiz, have bilan emas).","Is this your father? → No, he isn't. He's my friend.","'s egalik: your sister's name, my father's name."]},{"id":"u2-l10","slug":"at-the-language-school-a-registration-form","title":"At the language school: a registration form","titleUz":"Til maktabida: ro'yxatdan o'tish anketasi","goal":"Til maktabida anketani to'ldirasiz va administrator savollariga javob berasiz: What's your name? Where are you from? What's your job? Davlat, kasb va a / an ni ishlatasiz.","words":[{"en":"form","uz":"anketa, blank","ipa":"fɔːm"},{"en":"first name","uz":"ism","ipa":"ˈfɜːst neɪm"},{"en":"nationality","uz":"millat, fuqarolik","ipa":"ˌnæʃ.ənˈæl.ə.ti"},{"en":"job","uz":"kasb, ish","ipa":"dʒɒb"}],"summary":["Anketa savollari: What's your…? Where are you from? How old are you?","Davlat: I'm from Uzbekistan. Millat: I'm Uzbek. Kasb: I'm a nurse / an engineer.","Yangi so'zlar: form, first name, nationality, job."]},{"id":"u2-l11","slug":"to-be-final-review","title":"To be: final review","titleUz":"To be: yakuniy takror","goal":"To be bo'limini yakunlaysiz: olmoshlar, am / is / are (darak, inkor, savol), a / an, ko'plik, this / that, my / his / her, davlat va kasblar — hammasi bitta joyda.","words":[{"en":"also","uz":"ham, shuningdek","ipa":"ˈɔːl.səʊ"},{"en":"only","uz":"faqat, atigi","ipa":"ˈəʊn.li"},{"en":"married","uz":"turmush qurgan, uylangan","ipa":"ˈmær.id"}],"summary":["I am, he / she / it is, you / we / they are. Inkor: isn't / aren't / am not. Savol: Is she…? Are you…?","Kasb oldidan a / an, ko'plikda yo'q. Davlat — from, millat — from siz.","This / that — bitta, these / those — bir nechta. Egalik: my, your, his, her."]}]},{"id":"u3","n":3,"title":"Everyday Life","titleUz":"Kundalik hayot: Present Simple","description":"Katta sonlar, Present Simple, vaqt, kun tartibi, in / on / at, always / never.","canDo":["Kun tartibimni aytib bera olaman","Soatni va sanani ayta olaman","Odatlarim haqida (always, never…) gapiraman","Do / Does bilan savol beraman"],"lessons":[{"id":"u3-l1","slug":"numbers-20-100-age-prices","title":"Numbers 20–100, age & prices","titleUz":"Sonlar 20–100, yosh va narx","goal":"20 dan 100 gacha sonlarni aytasiz va yozasiz, thirteen / thirty kabi juftliklarni quloq bilan ajratasiz, yoshingizni (I'm 25), narxni (How much is it?) va telefon raqamingizni inglizcha to'g'ri aytasiz.","words":[{"en":"thirty","uz":"o'ttiz (30)","ipa":"ˈθɜː.ti"},{"en":"forty","uz":"qirq (40)","ipa":"ˈfɔː.ti"},{"en":"fifty","uz":"ellik (50)","ipa":"ˈfɪf.ti"},{"en":"sixty","uz":"oltmish (60)","ipa":"ˈsɪk.sti"},{"en":"hundred","uz":"yuz (100)","ipa":"ˈhʌn.drəd"},{"en":"price","uz":"narx","ipa":"praɪs"},{"en":"money","uz":"pul","ipa":"ˈmʌn.i"},{"en":"dollar","uz":"dollar","ipa":"ˈdɒl.ə"},{"en":"sum","uz":"so'm (O'zbekiston puli)","ipa":"sʌm"},{"en":"how much","uz":"qancha (narx)","ipa":"haʊ ˈmʌtʃ"}],"summary":["O'nliklar -ty bilan tugaydi: twenty, thirty, forty (u'siz!), fifty, sixty, seventy, eighty, ninety, a hundred.","Murakkab son — chiziqcha bilan: twenty-one, fifty-eight.","-teen (13–19) urg'u oxirida, -ty (30–90) urg'u boshida: thirTEEN / THIRty.","Yosh: I'm 25 yoki I'm 25 years old — hech qachon \"I have 25\".","Narx: How much is it? — It's 30 dollars. Telefon raqam — raqamma-raqam, 0 = oh, 55 = double five."]},{"id":"u3-l2","slug":"present-simple-i-you-we-they","title":"Present Simple: I / you / we / they","titleUz":"Present Simple: I / you / we / they","goal":"O'zingiz va boshqalar haqida odatlar va doimiy faktlarni aytasiz: I live in Tashkent. We study English. Inglizcha so'z tartibini (ega + fe'l + to'ldiruvchi) to'g'ri qo'llaysiz.","words":[{"en":"live","uz":"yashamoq","ipa":"lɪv"},{"en":"work","uz":"ishlamoq","ipa":"wɜːk"},{"en":"study","uz":"o'qimoq, o'rganmoq","ipa":"ˈstʌd.i"},{"en":"like","uz":"yoqtirmoq","ipa":"laɪk"},{"en":"play","uz":"o'ynamoq","ipa":"pleɪ"},{"en":"speak","uz":"gapirmoq","ipa":"spiːk"},{"en":"drink","uz":"ichmoq","ipa":"drɪŋk"},{"en":"watch","uz":"tomosha qilmoq, ko'rmoq","ipa":"wɒtʃ"},{"en":"learn","uz":"o'rganmoq, bilib olmoq","ipa":"lɜːn"},{"en":"need","uz":"kerak bo'lmoq, muhtoj bo'lmoq","ipa":"niːd"}],"summary":["Present Simple — odatlar va doimiy faktlar: I live in Tashkent.","I / you / we / they + fe'lning lug'at shakli: I work, we work, they work.","So'z tartibi: ega + fe'l + to'ldiruvchi — I learn English, \"I English learn\" emas.","Fe'l bor joyda am / are qo'shilmaydi: I work, \"I am work\" emas.","Yangi fe'llar: live, work, study, like, play, speak, drink, watch, learn, need."]},{"id":"u3-l3","slug":"present-simple-he-she-it","title":"Present Simple: he / she / it","titleUz":"Present Simple: he / she / it","goal":"Boshqa odamlar haqida gapirasiz: She works in a bank. He teaches English. he / she / it bilan fe'lga -s / -es / -ies qo'shishni, uni /s/, /z/, /ɪz/ deb to'g'ri talaffuz qilishni va has, does, goes shakllarini o'rganasiz.","words":[{"en":"go – goes","uz":"bormoq","ipa":"ɡəʊ – ɡəʊz"},{"en":"do – does","uz":"qilmoq","ipa":"duː – dʌz"},{"en":"have – has","uz":"ega bo'lmoq, bor bo'lmoq","ipa":"hæv – hæz"},{"en":"teach – teaches","uz":"o'qitmoq, dars bermoq","ipa":"tiːtʃ – ˈtiː.tʃɪz"},{"en":"wash – washes","uz":"yuvmoq","ipa":"wɒʃ – ˈwɒʃ.ɪz"},{"en":"finish – finishes","uz":"tugatmoq, tugamoq","ipa":"ˈfɪn.ɪʃ – ˈfɪn.ɪ.ʃɪz"},{"en":"fly – flies","uz":"uchmoq","ipa":"flaɪ – flaɪz"},{"en":"try – tries","uz":"harakat qilmoq, urinib ko'rmoq","ipa":"traɪ – traɪz"},{"en":"fix – fixes","uz":"tuzatmoq, ta'mirlamoq","ipa":"fɪks – ˈfɪk.sɪz"},{"en":"catch – catches","uz":"tutmoq, ushlamoq","ipa":"kætʃ – ˈkætʃ.ɪz"}],"summary":["he / she / it (va bitta odam/narsa) bilan fe'l + -s: She works. Ali lives in Fergana.","Imlo: -s, -sh, -ch, -x, -o → -es (washes, teaches, fixes, goes); undosh + y → -ies (studies, flies); unli + y → -s (plays).","Talaffuz: /s/ works · /z/ lives, plays · /ɪz/ watches, washes.","Maxsus: have → has, do → does (\"daz\"), go → goes.","Ko'plikda -s yo'q: My friends live here."]},{"id":"u3-l13","slug":"s-es-spelling","title":"-s / -es: spelling","titleUz":"he / she / it: -s, -es, -ies imlosi","goal":"he / she / it bilan fe'lni imlo xatosiz yozasiz va to'g'ri o'qiysiz: works, watches, studies, goes, has. Oxiri qaysi harfda tugasa, qaysi qo'shimcha (-s, -es, -ies) kerakligini darrov ajratasiz.","words":[{"en":"brush","uz":"tozalamoq, cho'tkalamoq","ipa":"brʌʃ"},{"en":"carry","uz":"ko'tarib yurmoq, olib yurmoq","ipa":"ˈkær.i"},{"en":"worry","uz":"xavotir olmoq","ipa":"ˈwʌr.i"},{"en":"enjoy","uz":"zavqlanmoq, yoqtirmoq","ipa":"ɪnˈdʒɔɪ"},{"en":"relax","uz":"dam olmoq","ipa":"rɪˈlæks"},{"en":"miss","uz":"sog'inmoq; o'tkazib yubormoq","ipa":"mɪs"}],"summary":["Ko'pchilik fe'llar: + s (works, lives). -s, -sh, -ch, -x, -o: + es (watches, brushes, goes).","Undosh + y → -ies (studies, carries). Unli + y → -s (plays, enjoys).","O'qilishi: /s/ works · /z/ carries, enjoys · /ɪz/ watches, relaxes.","Maxsus: have → has, do → does, go → goes."]},{"id":"u3-l4","slug":"dont-doesnt","title":"don't / doesn't","titleUz":"Inkor: don't / doesn't","goal":"Present Simple'da inkor gap tuzasiz: I don't drink coffee. She doesn't eat meat. doesn't dan keyin fe'l -s siz kelishini mustahkamlaysiz va ovqat-ichimliklar haqida gapira olasiz.","words":[{"en":"tea","uz":"choy","ipa":"tiː"},{"en":"coffee","uz":"qahva","ipa":"ˈkɒf.i"},{"en":"juice","uz":"sharbat","ipa":"dʒuːs"},{"en":"bread","uz":"non","ipa":"bred"},{"en":"rice","uz":"guruch","ipa":"raɪs"},{"en":"meat","uz":"go'sht","ipa":"miːt"},{"en":"soup","uz":"sho'rva","ipa":"suːp"},{"en":"sugar","uz":"shakar","ipa":"ˈʃʊɡ.ə"},{"en":"vegetables","uz":"sabzavotlar","ipa":"ˈvedʒ.tə.bəlz"},{"en":"fruit","uz":"meva","ipa":"fruːt"}],"summary":["Inkor: I / you / we / they + don't + fe'l; he / she / it + doesn't + fe'l.","doesn't dan keyin fe'l -s siz: She doesn't like coffee, He doesn't have a car.","Fe'l bor joyda \"I not…\" yoki \"I'm not like…\" emas — I don't like…. Holat uchun esa I'm not hungry.","tea, coffee, bread, rice, meat, sugar, soup, juice, fruit — a/an siz: I eat bread."]},{"id":"u3-l5","slug":"do-does-questions","title":"Do / Does questions","titleUz":"Savollar: Do / Does","goal":"Do / Does bilan savol berasiz (Do you like music? Does she play chess?) va qisqa javob qaytarasiz (Yes, I do. / No, she doesn't.). Sevimli mashg'ulotlar haqida suhbatlasha olasiz.","words":[{"en":"hobby","uz":"sevimli mashg'ulot, xobbi","ipa":"ˈhɒb.i"},{"en":"sport","uz":"sport","ipa":"spɔːt"},{"en":"football","uz":"futbol","ipa":"ˈfʊt.bɔːl"},{"en":"chess","uz":"shaxmat","ipa":"tʃes"},{"en":"music","uz":"musiqa","ipa":"ˈmjuː.zɪk"},{"en":"guitar","uz":"gitara","ipa":"ɡɪˈtɑː"},{"en":"game","uz":"o'yin","ipa":"ɡeɪm"},{"en":"film","uz":"film, kino","ipa":"fɪlm"},{"en":"cinema","uz":"kinoteatr","ipa":"ˈsɪn.ə.mə"},{"en":"party","uz":"bazm, ziyofat","ipa":"ˈpɑː.ti"}],"summary":["Savol: Do + I / you / we / they + fe'l? · Does + he / she / it + fe'l?","Does dan keyin fe'l -s siz: Does she like music?","Qisqa javob: Yes, I do. / No, I don't. · Yes, she does. / No, she doesn't. — \"Yes, I like\" emas.","Fe'l bilan Are you…? emas, Do you…?: Do you play chess?","Iboralar: play football / chess / the guitar · listen to music · go to the cinema · do sport."]},{"id":"u3-l14","slug":"wh-questions-with-do-does","title":"Wh- questions with do / does","titleUz":"Wh-savollar: What do you…? Where does she…?","goal":"What, Where, When, Why, How so'zlari bilan savol berasiz: Where does she live? When do you have lunch? Why do they study English? va ularga qisqa javob qaytarasiz.","words":[{"en":"where","uz":"qayerda, qayerga","ipa":"weə"},{"en":"when","uz":"qachon","ipa":"wen"},{"en":"why","uz":"nega, nima uchun","ipa":"waɪ"},{"en":"because","uz":"chunki","ipa":"bɪˈkɒz"},{"en":"how","uz":"qanday, qanaqa usulda","ipa":"haʊ"},{"en":"by bus","uz":"avtobusda","ipa":"baɪ bʌs"}],"summary":["Wh-savol: so'roq so'zi + do/does + ega + fe'l: Where does she live?","do — I/you/we/they bilan, does — he/she/it bilan; does dan keyin fe'lda -s yo'q.","What — nima, Where — qayerda, When — qachon, Why — nega (Because…), How — qanday (by bus)."]},{"id":"u3-l9","slug":"at-the-cafe-present-simple-in-real-life","title":"At the café: Present Simple in real life","titleUz":"Kafeda: Present Simple hayotda","goal":"Kafeda buyurtma berasiz va savollarga javob qaytarasiz: Do you want sugar? — Yes, please. / No, thanks. Present Simple'ni (do / does / don't / doesn't) real vaziyatda ishlatasiz.","words":[{"en":"order","uz":"buyurtma bermoq","ipa":"ˈɔː.dər"},{"en":"menu","uz":"menyu","ipa":"ˈmen.juː"},{"en":"bill","uz":"hisob (to'lov cheki)","ipa":"bɪl"},{"en":"pay","uz":"to'lamoq","ipa":"peɪ"},{"en":"cup","uz":"piyola, finjon","ipa":"kʌp"}],"summary":["Kafeda savol Do you want…?, javob Yes, please. / No, thanks.","He / she / it bilan: Does… ? va doesn't, fe'l oddiy shaklda: Does it have sugar?","Yangi so'zlar: order, menu, bill, pay — gaplarda ishlating."]},{"id":"u3-l16","slug":"real-life-ordering-at-a-cafe","title":"Real life: ordering at a café","titleUz":"Real hayot: kafeda buyurtma berish","goal":"Kafeda muloyim buyurtma berasiz: I'd like a tea, please. Narxni so'raysiz, «Yana nimadir?» ga javob berasiz va rahmat aytasiz.","words":[],"summary":["What would you like? — «Nima olasiz?»; javob: I'd like a tea, please.","I like coffee — umuman yoqtirishingiz; buyurtma uchun I'd like deymiz.","a / an sanaladigan narsa oldida, some sanalmaydigan narsa oldida: some sugar.","How much is it? — narxni so'rash; Anything else? → No, thank you."]},{"id":"u3-l10","slug":"university-and-work-my-week","title":"University and work: my week","titleUz":"Universitet va ish: mening haftam","goal":"Universitet yoki ish kuningiz haqida Present Simple bilan gapirasiz: I study at university. My lesson starts at nine. Do you like your job?","words":[{"en":"lecture","uz":"ma'ruza","ipa":"ˈlek.tʃər"},{"en":"colleague","uz":"hamkasb","ipa":"ˈkɒl.iːɡ"},{"en":"meeting","uz":"uchrashuv, yig'ilish","ipa":"ˈmiː.tɪŋ"},{"en":"office","uz":"ofis","ipa":"ˈɒf.ɪs"},{"en":"start","uz":"boshlanmoq, boshlamoq","ipa":"stɑːt"},{"en":"finish","uz":"tugamoq, tugatmoq","ipa":"ˈfɪn.ɪʃ"}],"summary":["Doimiy ish / o'qish haqida Present Simple: I study, she works.","Savol: When / Where + do / does + ega + fe'l: When does it start?","Yangi so'zlar: lecture, colleague, meeting, finish."]},{"id":"u3-l11","slug":"present-simple-final-review","title":"Present Simple: final review","titleUz":"Present Simple: yakuniy takror","goal":"Present Simple mavzusini yakunlaysiz: darak, -s, inkor va savol — hammasi bitta joyda. Kafe va ish vaziyatlarida erkin foydalanasiz.","words":[{"en":"near","uz":"yaqin, yaqinida","ipa":"nɪə"},{"en":"busy","uz":"band","ipa":"ˈbɪz.i"},{"en":"early","uz":"erta","ipa":"ˈɜː.li"},{"en":"quiet","uz":"tinch, jim","ipa":"ˈkwaɪ.ət"},{"en":"tired","uz":"charchagan","ipa":"ˈtaɪəd"}],"summary":["Darak: -s faqat he / she / it bilan. Inkor: don't / doesn't. Savol: Do / Does.","Does / doesn't dan keyin fe'l har doim oddiy shaklda.","Kafe va ish vaziyatlarida shu qoliplar ishlaydi: Do you want…? / When does it start?"]},{"id":"u3-l6","slug":"time-daily-routine","title":"Time & daily routine","titleUz":"Vaqt va kun tartibi","goal":"Soatni inglizcha aytasiz (seven o'clock, half past seven, quarter to eight), vaqtni so'raysiz va kun tartibingizni Present Simple bilan tasvirlaysiz: I get up at seven. She has lunch at one.","words":[{"en":"wake up","uz":"uyg'onmoq","ipa":"weɪk ʌp"},{"en":"get up","uz":"o'rnidan turmoq","ipa":"ɡet ʌp"},{"en":"have breakfast","uz":"nonushta qilmoq","ipa":"hæv ˈbrek.fəst"},{"en":"have lunch","uz":"tushlik qilmoq","ipa":"hæv lʌntʃ"},{"en":"have dinner","uz":"kechki ovqat qilmoq","ipa":"hæv ˈdɪn.ə"},{"en":"go to bed","uz":"uxlashga yotmoq","ipa":"ɡəʊ tə bed"},{"en":"o'clock","uz":"soat (butun soat)","ipa":"əˈklɒk"},{"en":"half past","uz":"… yarim (30 daqiqa o'tdi)","ipa":"hɑːf pɑːst"},{"en":"quarter","uz":"chorak (15 daqiqa)","ipa":"ˈkwɔː.tə"},{"en":"minute","uz":"daqiqa","ipa":"ˈmɪn.ɪt"}],"summary":["What time is it? — It's seven o'clock. (o'clock faqat butun soatda)","past — o'tdi (1–30 daqiqa), to — qoldi (31–59): quarter past seven = 7:15, half past seven = 7:30, quarter to eight = 7:45.","Soat oldidan at: I get up at seven. a.m. — tushgacha, p.m. — tushdan keyin.","have breakfast / lunch / dinner (a siz), go to bed (the siz). he/she bilan: gets up, has lunch, goes to bed."]},{"id":"u3-l17","slug":"real-life-at-the-bus-station","title":"Real life: at the bus station","titleUz":"Real hayot: avtobus bekatida","goal":"Avtobus bekatida savol berasiz (Does this bus go...? What time does it leave?), vaqtni tushunasiz, narxni so'raysiz va chipta olasiz.","words":[],"summary":["Does this bus go to the airport? — Does dan keyin fe'l oddiy shaklda: go (goes emas).","What time does the bus leave? — savolda does + leave; -s faqat darak gapda: It leaves at nine.","Vaqt: at half past nine, at nine o'clock, at quarter past ten.","How much is the ticket? — It's twelve dollars.; One ticket to the airport, please."]},{"id":"u3-l7","slug":"days-months-in-on-at","title":"Days, months: in / on / at","titleUz":"Kunlar, oylar: in / on / at","goal":"Hafta kunlari va oylarni to'g'ri aytasiz va katta harf bilan yozasiz. Vaqt predloglarini ajratasiz: at seven, on Monday, in July — o'zbekchadagi bitta \"-da\" o'rniga uchta so'z.","words":[{"en":"Monday","uz":"dushanba","ipa":"ˈmʌn.deɪ"},{"en":"Wednesday","uz":"chorshanba","ipa":"ˈwenz.deɪ"},{"en":"Friday","uz":"juma","ipa":"ˈfraɪ.deɪ"},{"en":"Sunday","uz":"yakshanba","ipa":"ˈsʌn.deɪ"},{"en":"weekend","uz":"dam olish kunlari (shanba–yakshanba)","ipa":"ˌwiːkˈend"},{"en":"week","uz":"hafta","ipa":"wiːk"},{"en":"month","uz":"oy (kalendar oyi)","ipa":"mʌnθ"},{"en":"year","uz":"yil","ipa":"jɪə"},{"en":"January","uz":"yanvar","ipa":"ˈdʒæn.ju.ə.ri"},{"en":"July","uz":"iyul","ipa":"dʒuˈlaɪ"}],"summary":["Hafta kunlari va oylar — doim katta harf bilan: Monday, July.","Talaffuz tuzoqlari: Wednesday \"WENZ-dey\", Tuesday / Thursday, July urg'u oxirida, month oxirida th.","in — oy, yil, kun qismi (in July, in the morning); on — kun (on Monday); at — soat (at seven, at night, at the weekend).","every, today, this oldidan predlog yo'q: every Friday, \"on every Friday\" emas."]},{"id":"u3-l18","slug":"real-life-arranging-to-meet","title":"Real life: arranging to meet","titleUz":"Real hayot: uchrashuv vaqtini kelishish","goal":"Do'stingiz bilan uchrashuv kelishasiz: kun va vaqtni to'g'ri in / on / at bilan aytasiz, rozi bo'lasiz yoki muloyim rad etasiz.","words":[],"summary":["Let's meet on Saturday. — «Shanba kuni uchrashaylik.»","on + kun (on Saturday), at + soat (at six), in + kun qismi (in the evening).","Do you work on Saturday? — No, I don't. — qisqa javob do / don't bilan.","Rad etish: Sorry, I work on Sunday.; xayrlashish: See you on Saturday at six!"]},{"id":"u3-l8","slug":"always-usually-never","title":"always, usually, never…","titleUz":"Qanchalik tez-tez: always, usually, never…","goal":"Ishni qanchalik tez-tez qilishingizni aytasiz: I always get up at seven. She is never late. Chastota ravishlarining gapdagi o'rnini bilasiz, How often…? deb so'raysiz va once a week, every day bilan javob berasiz.","words":[{"en":"always","uz":"doim, har doim","ipa":"ˈɔːl.weɪz"},{"en":"usually","uz":"odatda","ipa":"ˈjuː.ʒu.ə.li"},{"en":"often","uz":"ko'pincha, tez-tez","ipa":"ˈɒf.ən"},{"en":"sometimes","uz":"ba'zan","ipa":"ˈsʌm.taɪmz"},{"en":"rarely","uz":"kamdan-kam","ipa":"ˈreə.li"},{"en":"never","uz":"hech qachon","ipa":"ˈnev.ə"},{"en":"every day","uz":"har kuni","ipa":"ˈev.ri deɪ"},{"en":"once","uz":"bir marta","ipa":"wʌns"},{"en":"twice","uz":"ikki marta","ipa":"twaɪs"},{"en":"how often","uz":"qanchalik tez-tez","ipa":"haʊ ˈɒf.ən"}],"summary":["Chastota: always (100%) → usually → often → sometimes → rarely → never (0%).","Oddiy fe'l bilan ravish fe'ldan oldin: I always get up at seven.","to be bilan ravish am / is / are dan keyin: She is never late.","never — o'zi inkor: I never eat meat, \"I don't never\" emas.","How often…? — every day, once a week, twice a month, three times a year (gap oxirida)."]},{"id":"u3-l15","slug":"my-daily-routine-listening-and-writing","title":"My daily routine: listening and writing","titleUz":"Mening kunim: tinglash va yozish","goal":"Kun tartibi haqidagi suhbatni tinglab vaqt va tafsilotlarni tushunasiz, so'ng o'zingizning kuningiz haqida qisqa abzats yozasiz: I usually get up at half past six. I go to work by bus.","words":[{"en":"routine","uz":"kun tartibi, odat","ipa":"ruːˈtiːn"},{"en":"have a shower","uz":"dush qabul qilmoq","ipa":"hæv ə ˈʃaʊ.ə"},{"en":"leave home","uz":"uydan chiqmoq","ipa":"liːv həʊm"},{"en":"get home","uz":"uyga qaytmoq","ipa":"ɡet həʊm"},{"en":"before","uz":"…dan oldin","ipa":"bɪˈfɔː"},{"en":"after","uz":"…dan keyin","ipa":"ˈɑːf.tə"}],"summary":["Tinglaganda kalit so'zlarni ushlang: vaqt, ish, tez-tez ravishi, kim (I / he / she).","Abzats ketma-ketlikda yoziladi, har bir ishda vaqt: I get up at seven. I go to work by bus.","Foydali so'zlar: before, after, then; ravishlar fe'ldan oldin: I always have lunch.","Yozgandan keyin tekshiring: at, he/she + -s, doesn't + s'siz fe'l."]},{"id":"u3-l19","slug":"real-life-my-day-a-chat-with-a-friend","title":"Real life: my day, a chat with a friend","titleUz":"Real hayot: do'st bilan kun tartibi","goal":"Do'stingiz bilan kun tartibingiz haqida gaplashasiz: nechada turasiz, nima qilasiz, ishga qanday borasiz. always / usually / never ni to'g'ri joyga qo'yasiz va o'zingiz ham savol berasiz.","words":[],"summary":["What time do you get up? → I get up at seven. (soat oldidan at).","Do you…? savoliga: Yes, I do. / No, I don't. Uchinchi shaxs: Does she…? → Yes, she does.","Takrorlanish so'zi fe'ldan oldin turadi: I never drink coffee. (I drink never coffee emas).","he / she bilan fe'lga -s: She gets up at six. (She get up emas).","Savol berish: What time do you finish work? (do + fe'lning oddiy shakli)."]},{"id":"u3-l12","slug":"everyday-life-final-review","title":"Everyday life: final review","titleUz":"Kundalik hayot: yakuniy takror","goal":"Butun bo'limni takrorlaysiz: sonlar, yosh, narx, Present Simple, vaqt, in / on / at, always / never va How often. Haftangiz haqida bemalol gapirasiz.","words":[{"en":"holiday","uz":"ta'til, dam olish","ipa":"ˈhɒl.ə.deɪ"},{"en":"ticket","uz":"chipta","ipa":"ˈtɪk.ɪt"},{"en":"lazy","uz":"dangasa","ipa":"ˈleɪ.zi"},{"en":"late","uz":"kech, kechikkan","ipa":"leɪt"},{"en":"expensive","uz":"qimmat","ipa":"ɪkˈspen.sɪv"},{"en":"salary","uz":"maosh","ipa":"ˈsæl.ər.i"}],"summary":["Yosh va narx: I'm thirty. How much is it? Sonlar 20–100 gacha.","Present Simple: -s (he/she/it), don't / doesn't, Do / Does.","on — kun, in — oy, at — soat.","always, usually, often, never — oddiy fe'ldan oldin, to be dan keyin. How often — chastota haqida savol."]}]},{"id":"u4","n":4,"title":"Describing and Asking","titleUz":"Tasvirlash va so'rash: there is, can, have got","description":"Wh-savollar, there is / are, joy predloglari, much / many, can, buyruq, have got, Present Continuous.","canDo":["There is / There are bilan joyni tasvirlayman","Predloglar (in, on, under…) bilan narsa qayerdaligini aytaman","can / can't bilan qobiliyat va iltimosni bildiraman","Hozir nima qilayotganimni ayta olaman"],"lessons":[{"id":"u4-l1","slug":"wh-questions","title":"Wh- questions","titleUz":"Wh-savollar: what, where, who…","goal":"What, where, when, who, why, how kabi so'roq so'zlari bilan to'g'ri savol tuzasiz (so'roq so'zi + do/does/be + ega) va bunday savollarga qisqa javob bera olasiz.","words":[{"en":"what","uz":"nima","ipa":"wɒt"},{"en":"where","uz":"qayerda, qayerga","ipa":"weə"},{"en":"when","uz":"qachon","ipa":"wen"},{"en":"who","uz":"kim","ipa":"huː"},{"en":"why","uz":"nima uchun, nega","ipa":"waɪ"},{"en":"how","uz":"qanday","ipa":"haʊ"},{"en":"which","uz":"qaysi","ipa":"wɪtʃ"},{"en":"whose","uz":"kimning","ipa":"huːz"},{"en":"how many","uz":"nechta","ipa":"haʊ ˈmen.i"},{"en":"how old","uz":"necha yoshda","ipa":"haʊ ˈəʊld"}],"summary":["So'roq so'zi har doim gap boshida: Where do you live?","Fe'l bilan: so'roq so'zi + do/does + ega + fe'l (does bo'lsa -s yo'q): What does she like?","To be bilan: so'roq so'zi + am/is/are + ega: How old are you?","Who ega bo'lsa do kerak emas: Who lives here?","who / whose \"hu:\" deb o'qiladi; wh-savollarda ovoz oxirida pasayadi ↘."]},{"id":"u4-l2","slug":"there-is-there-are","title":"There is / there are","titleUz":"There is / there are, some / any","goal":"There is / there are yordamida biror joyda nima borligini aytasiz, Is there…? / Are there…? bilan so'raysiz va some / any ni to'g'ri ishlatib, uyingizni tasvirlab bera olasiz.","words":[{"en":"kitchen","uz":"oshxona","ipa":"ˈkɪtʃ.ɪn"},{"en":"bedroom","uz":"yotoqxona","ipa":"ˈbed.ruːm"},{"en":"bathroom","uz":"hammom, vannaxona","ipa":"ˈbɑːθ.ruːm"},{"en":"living room","uz":"mehmonxona (yashash xonasi)","ipa":"ˈlɪv.ɪŋ ruːm"},{"en":"sofa","uz":"divan","ipa":"ˈsəʊ.fə"},{"en":"bed","uz":"karavot","ipa":"bed"},{"en":"lamp","uz":"lampa, chiroq","ipa":"læmp"},{"en":"fridge","uz":"muzlatkich","ipa":"frɪdʒ"},{"en":"shelf","uz":"javon (ko'pl. shelves)","ipa":"ʃelf"},{"en":"carpet","uz":"gilam","ipa":"ˈkɑː.pɪt"}],"summary":["\"…da … bor\" = There is + birlik / There are + ko'plik + joy: There is a sofa in the room.","Inkor: There isn't a… / There aren't any…","Savol: Is there a…? / Are there any…? — Javob: Yes, there is. / No, there aren't.","some — ijobiy gapda, any — inkor va savolda.","Yangi so'zlar: kitchen, bedroom, bathroom, living room, sofa, bed, lamp, fridge, shelf, carpet."]},{"id":"u4-l3","slug":"prepositions-of-place","title":"Prepositions of place","titleUz":"Joy predloglari: in, on, under…","goal":"Narsalar va odamlar qayerda turganini 10 ta joy predlogi bilan (in, on, under, next to, between…) aniq aytasiz va Where is…? / Where are…? savollariga javob bera olasiz.","words":[{"en":"in","uz":"-da, ichida","ipa":"ɪn"},{"en":"on","uz":"ustida","ipa":"ɒn"},{"en":"under","uz":"ostida, tagida","ipa":"ˈʌn.də"},{"en":"next to","uz":"yonida","ipa":"ˈnekst tə"},{"en":"between","uz":"orasida","ipa":"bɪˈtwiːn"},{"en":"behind","uz":"orqasida","ipa":"bɪˈhaɪnd"},{"en":"in front of","uz":"oldida","ipa":"ɪn ˈfrʌnt əv"},{"en":"near","uz":"yaqinida","ipa":"nɪə"},{"en":"opposite","uz":"qarshisida, ro'parasida","ipa":"ˈɒp.ə.zɪt"},{"en":"above","uz":"tepasida, yuqorisida","ipa":"əˈbʌv"}],"summary":["Ingliz tilida predlog otdan oldin: karavot ostida → under the bed.","in (ichida) · on (ustida, tegib) · under (ostida) · above (tepasida, tegmay).","next to (yonida) · near (yaqinida) · between A and B (orasida).","behind (orqasida) · in front of (oldida, the siz) · opposite (ro'parasida, of siz).","Joy haqida gapda to be shart: Where are my keys? — They're in the bag."]},{"id":"u4-l9","slug":"my-room-and-my-town","title":"My room and my town","titleUz":"Xonam va shahrim: there is / there are","goal":"O'z xonangiz va shahringizni tasvirlaysiz: There is a bed next to the window. There are two parks in my town. There is / there are, some / any va joy predloglarini birga ishlatasiz.","words":[{"en":"garden","uz":"bog'","ipa":"ˈɡɑː.dən"},{"en":"street","uz":"ko'cha","ipa":"striːt"},{"en":"flat","uz":"kvartira","ipa":"flæt"},{"en":"wall","uz":"devor","ipa":"wɔːl"}],"summary":["Bitta narsa: There is; bir nechta: There are. Savol: Is there…? / Are there…?","some — darak gapda, any — savol va inkorda.","Joyni predloglar bilan ayting: in, on, next to, near, opposite.","Yangi so'zlar: garden, street, flat, wall."]},{"id":"u4-l4","slug":"countable-uncountable","title":"Countable & uncountable","titleUz":"Sanaladigan / sanalmaydigan, much / many","goal":"Sanaladigan va sanalmaydigan otlarni ajratasiz, much / many / a lot of va How much / How many ni to'g'ri ishlatasiz hamda do'konda a bottle of, a kilo of, a piece of, a packet of bilan miqdorni aytasiz.","words":[{"en":"banana","uz":"banan","ipa":"bəˈnɑː.nə"},{"en":"cheese","uz":"pishloq","ipa":"tʃiːz"},{"en":"butter","uz":"sariyog'","ipa":"ˈbʌt.ə"},{"en":"salt","uz":"tuz","ipa":"sɔːlt"},{"en":"oil","uz":"yog' (o'simlik yog'i)","ipa":"ɔɪl"},{"en":"flour","uz":"un","ipa":"ˈflaʊ.ə"},{"en":"a bottle of","uz":"bir shisha …","ipa":"ə ˈbɒt.əl əv"},{"en":"a kilo of","uz":"bir kilo …","ipa":"ə ˈkiː.ləʊ əv"},{"en":"a piece of","uz":"bir bo'lak …","ipa":"ə ˈpiːs əv"},{"en":"a packet of","uz":"bir paket …","ipa":"ə ˈpæk.ɪt əv"}],"summary":["Sanaladigan: a banana, two bananas. Sanalmaydigan (water, rice, salt, cheese, bread): a/an yo'q, -s yo'q, fe'l birlikda.","many + ko'plik, much + sanalmaydigan (asosan inkor/savolda); ijobiy gapda — a lot of.","How many bananas? · How much flour? · narx: How much is it?","Idishlar: a bottle of oil, a kilo of rice, a piece of cheese, a packet of salt; ko'plikda -s idishga: two bottles of water."]},{"id":"u4-l10","slug":"at-the-shop-much-many-can-i","title":"At the shop: much, many, can I…?","titleUz":"Do'konda: much, many, can","goal":"Do'konda kerakli narsani so'raysiz va to'laysiz: Can I have some bread, please? How much is it? Much / many, how much / how many va Can I…? ni ishlatasiz.","words":[{"en":"cash","uz":"naqd pul","ipa":"kæʃ"},{"en":"card","uz":"karta","ipa":"kɑːd"},{"en":"change","uz":"qaytim","ipa":"tʃeɪndʒ"},{"en":"fresh","uz":"yangi, toza","ipa":"freʃ"}],"summary":["How many + sanaladigan (eggs), How much + sanalmaydigan (rice). Narx: How much is it?","Iltimos: Can I have…? — Can I dan keyin tosiz fe'l.","some — darakda, any — savol va inkorda.","Yangi so'zlar: cash, card, change, fresh."]},{"id":"u4-l5","slug":"can-cant","title":"can / can't","titleUz":"can / can't: qobiliyat va iltimos","goal":"can / can't yordamida nima qila olishingizni va qila olmasligingizni aytasiz, ruxsat va iltimos so'raysiz (Can I…? Can you…?) hamda can va can't ni quloq bilan ajratasiz.","words":[{"en":"swim","uz":"suzmoq","ipa":"swɪm"},{"en":"run","uz":"yugurmoq","ipa":"rʌn"},{"en":"jump","uz":"sakramoq","ipa":"dʒʌmp"},{"en":"drive","uz":"(mashina) haydamoq","ipa":"draɪv"},{"en":"ride","uz":"(ot, velosiped) minmoq","ipa":"raɪd"},{"en":"climb","uz":"tirmashib chiqmoq","ipa":"klaɪm"},{"en":"cook","uz":"ovqat pishirmoq","ipa":"kʊk"},{"en":"dance","uz":"raqsga tushmoq","ipa":"dɑːns"},{"en":"draw","uz":"rasm chizmoq","ipa":"drɔː"},{"en":"ski","uz":"chang'ida uchmoq","ipa":"skiː"}],"summary":["can + fe'l — hamma shaxs uchun bir xil: He can swim. (-s yo'q, to yo'q).","Inkor: can't / cannot; savol: Can you…? — Yes, I can. / No, I can't.","Talaffuz: gapda qisqa \"kən\", can't — uzun \"ka:nt\".","Daraja gap oxirida: very well, well, a little, not … at all.","Ruxsat: Can I…? · Iltimos: Can you…, please?"]},{"id":"u4-l14","slug":"can-i-requests-and-permission","title":"Can I…? Requests and permission","titleUz":"Can I…? Iltimos va ruxsat so'rash","goal":"Can I…? bilan muloyim iltimos qilasiz (Can I have a glass of water?) va ruxsat so'raysiz (Can I open the window?), javobni ham tushunasiz va o'zingiz berasiz: Yes, of course. / Sorry, you can't.","words":[{"en":"borrow","uz":"vaqtincha olmoq","ipa":"ˈbɒr.əʊ"},{"en":"lend","uz":"vaqtincha bermoq","ipa":"lend"},{"en":"use","uz":"ishlatmoq, foydalanmoq","ipa":"juːz"},{"en":"close","uz":"yopmoq","ipa":"kləʊz"},{"en":"toilet","uz":"hojatxona","ipa":"ˈtɔɪ.lət"},{"en":"of course","uz":"albatta","ipa":"əv ˈkɔːs"}],"summary":["Can I + fe'l (to'siz)…? — iltimos (Can I have…?) va ruxsat (Can I open…?).","Ha: Yes, of course. / Sure. / Yes, you can. Yo'q: Sorry, you can't. + sabab.","Can I to…, Can I opens…, Do I can… — xato.","Yangi so'zlar: borrow, lend, use, close, toilet, of course."]},{"id":"u4-l20","slug":"real-life-how-much-is-it","title":"Real life: how much is it?","titleUz":"Real hayot: do'konda narx so'rash","goal":"Do'konda Can I have…, please? deb so'raysiz, Do you have any…? deb mahsulot borligini so'raysiz, How much is it? deb narxini so'raysiz va jami summani tushunasiz.","words":[],"summary":["Can I have some apples, please? — muloyim iltimos (I want apples emas).","Do you have any milk? — so'roq gapda any; javobda some: Yes, we have some milk.","How many + sanaladigan (apples), How much + sanalmaydigan (milk).","How much is it? — narxni so'rash; narxni eshitib jami summani topish.","Here you are. — «Marhamat.»"]},{"id":"u4-l6","slug":"imperatives-object-pronouns","title":"Imperatives & object pronouns","titleUz":"Buyruq gaplar va me, him, her…","goal":"Buyruq va ko'rsatma berasiz (Sit down. Don't wait. Let's go.), ularni please bilan muloyim qilasiz va me, him, her, us, them kabi kelishikdagi olmoshlarni to'g'ri ishlatasiz.","words":[{"en":"sit down","uz":"o'tirmoq","ipa":"sɪt ˈdaʊn"},{"en":"stand up","uz":"o'rnidan turmoq","ipa":"stænd ˈʌp"},{"en":"come in","uz":"kirmoq","ipa":"kʌm ˈɪn"},{"en":"give","uz":"bermoq","ipa":"ɡɪv"},{"en":"take","uz":"olmoq","ipa":"teɪk"},{"en":"help","uz":"yordam bermoq","ipa":"help"},{"en":"wait","uz":"kutmoq","ipa":"weɪt"},{"en":"look at","uz":"qaramoq","ipa":"ˈlʊk ət"},{"en":"stop","uz":"to'xtamoq, to'xtatmoq","ipa":"stɒp"},{"en":"turn on","uz":"yoqmoq","ipa":"tɜːn ˈɒn"}],"summary":["Buyruq gap = fe'lning asosiy shakli, ega yo'q: Sit down. Wait. Muloyim qilish uchun please.","Inkor: Don't + fe'l (Don't stop); sifat bilan be: Don't be late.","Taklif: Let's + fe'l — Let's go! (to yo'q).","Fe'l yoki predlogdan keyin: me, you, him, her, it, us, them — Help me. Look at them."]},{"id":"u4-l13","slug":"object-pronouns-me-you-him-her","title":"Object pronouns: me, you, him, her…","titleUz":"Olmoshning to'ldiruvchi shakli: me, him, her, us, them","goal":"Fe'ldan va predlogdan keyin me, you, him, her, it, us, them ni to'g'ri ishlatasiz: She knows him. Come with me. Send it to them. Odamlar va narsalarni qayta aytmasdan olmosh bilan almashtirasiz.","words":[{"en":"send","uz":"yubormoq","ipa":"send"},{"en":"show","uz":"ko'rsatmoq","ipa":"ʃəʊ"},{"en":"tell","uz":"aytmoq, aytib bermoq","ipa":"tel"},{"en":"invite","uz":"taklif qilmoq","ipa":"ɪnˈvaɪt"},{"en":"ask","uz":"so'ramoq","ipa":"ɑːsk"},{"en":"thank","uz":"rahmat aytmoq","ipa":"θæŋk"}],"summary":["Fe'ldan oldin — ega olmosh (I, he, she, we, they); fe'ldan va predlogdan keyin — me, him, her, us, them.","you va it ikkala o'rinda ham o'zgarmaydi.","Predlogdan keyin ham doim to'ldiruvchi shakl: with me, for him, about them.","send / show / tell + kimga + nimani: Send me a message."]},{"id":"u4-l19","slug":"real-life-asking-the-way","title":"Real life: asking the way","titleUz":"Real hayot: yo'l so'rash","goal":"Ko'chada yo'lni so'raysiz, javobni tushunasiz (Go straight, Turn left, on the right), «Bu yerda … bormi?» deb so'raysiz va minnatdorchilik bildirasiz.","words":[],"summary":["Excuse me, where is the bank? — yo'l so'rash (Where the bank is? emas).","It's next to the shop. / It's opposite the park. — joyni aytish (It's = It is).","Go straight. Turn left. Turn right. on the left / on the right — yo'l ko'rsatish.","Is there a pharmacy near here? — Is there a…? (Is there pharmacy emas, a kerak).","Thank you very much. — katta rahmat."]},{"id":"u4-l7","slug":"have-got-family","title":"have got & family","titleUz":"have got va oila","goal":"have got / has got bilan nimangiz va kimingiz borligini aytasiz, inkor va savol tuzasiz hamda oila a'zolarini inglizcha nomlab, oilangiz haqida gapira olasiz.","words":[{"en":"mother","uz":"ona","ipa":"ˈmʌð.ə"},{"en":"father","uz":"ota","ipa":"ˈfɑː.ðə"},{"en":"parents","uz":"ota-ona","ipa":"ˈpeə.rənts"},{"en":"brother","uz":"aka, uka","ipa":"ˈbrʌð.ə"},{"en":"sister","uz":"opa, singil","ipa":"ˈsɪs.tə"},{"en":"son","uz":"o'g'il","ipa":"sʌn"},{"en":"daughter","uz":"qiz (farzand)","ipa":"ˈdɔː.tə"},{"en":"grandmother","uz":"buvi","ipa":"ˈɡræn.mʌð.ə"},{"en":"grandfather","uz":"bobo","ipa":"ˈɡræn.fɑː.ðə"},{"en":"uncle","uz":"amaki, tog'a","ipa":"ˈʌŋ.kəl"}],"summary":["Egalik: I/you/we/they have got ('ve got), he/she/it has got ('s got).","Inkor: haven't got / hasn't got (ko'plikda + any); do kerak emas.","Savol: Have you got…? Has she got…? — Yes, I have. / No, she hasn't. (javobda got yo'q).","Oila: mother, father, parents, brother (aka/uka), sister (opa/singil), son, daughter, grandmother, grandfather, uncle.","th (mother, brother) — ovozli ð; daughter da gh o'qilmaydi."]},{"id":"u4-l21","slug":"real-life-checking-in-at-a-hotel","title":"Real life: checking in at a hotel","titleUz":"Real hayot: mehmonxonada ro'yxatdan o'tish","goal":"Mehmonxonada ro'yxatdan o'tasiz: bronni aytasiz, ismingizni harflab berasiz, «Wi-Fi bormi?» deb so'raysiz va kalit so'raysiz (Can I have...?).","words":[],"summary":["I have a reservation. — «Menda bron bor.» (a tushib qolmasin).","My name is Ali Karimov. — ism va familiyani aytish; harflab berish uchun spell.","Is there Wi-Fi in the room? → Yes, there is. / No, there isn't.","Can I have the key, please? — nimadir so'rashning xushmuomala yo'li."]},{"id":"u4-l8","slug":"present-continuous","title":"Present Continuous","titleUz":"Present Continuous: hozir nima qilyapman","goal":"am / is / are + -ing yordamida hozir, ayni paytda bo'layotgan ishlarni aytasiz, -ing qo'shishning imlo qoidalarini bilasiz va What are you doing? kabi savol hamda inkor gaplar tuza olasiz.","words":[{"en":"walk","uz":"piyoda yurmoq","ipa":"wɔːk"},{"en":"talk","uz":"gaplashmoq","ipa":"tɔːk"},{"en":"sleep","uz":"uxlamoq","ipa":"sliːp"},{"en":"wear","uz":"kiymoq, kiyib yurmoq","ipa":"weə"},{"en":"rain","uz":"yomg'ir yog'moq","ipa":"reɪn"},{"en":"make","uz":"qilmoq, tayyorlamoq","ipa":"meɪk"},{"en":"sit","uz":"o'tirmoq","ipa":"sɪt"},{"en":"carry","uz":"ko'tarib bormoq","ipa":"ˈkær.i"},{"en":"laugh","uz":"kulmoq","ipa":"lɑːf"},{"en":"write","uz":"yozmoq","ipa":"raɪt"}],"summary":["am / is / are + fe'l-ing — hozir bo'layotgan ish: I'm walking. She's sleeping. (ikkala qism ham shart!).","Imlo: make → making (e tushadi), sit → sitting (undosh ikkilanadi), carry → carrying.","Inkor: isn't / aren't / 'm not + -ing; savol: Are you…ing? — What are you doing? (do yo'q).","Signal so'zlar: now, at the moment, Look!, Listen!; odat uchun esa Present Simple.","-ing oxiri — burun tovushi ŋ, alohida g aytilmaydi."]},{"id":"u4-l17","slug":"ing-spelling","title":"-ing: spelling","titleUz":"-ing qo'shish imlosi: run → running","goal":"Fe'lga -ing qo'shganda imloni xatosiz yozasiz: work → working, make → making, run → running, lie → lying.","words":[{"en":"lie","uz":"yotmoq","ipa":"laɪ"},{"en":"eat","uz":"yemoq","ipa":"iːt"},{"en":"wash","uz":"yuvmoq","ipa":"wɒʃ"},{"en":"paint","uz":"bo'yamoq, rasm chizmoq","ipa":"peɪnt"},{"en":"chat","uz":"suhbatlashmoq, chat qilmoq","ipa":"tʃæt"},{"en":"plan","uz":"rejalashtirmoq","ipa":"plæn"}],"summary":["Odatda: work → working, eat → eating, wash → washing.","-e tushadi: make → making, write → writing, dance → dancing.","Qisqa unli + bitta undosh: undosh ikkilanadi: run → running, sit → sitting, chat → chatting.","lie → lying; -y o'zgarmaydi: play → playing."]},{"id":"u4-l15","slug":"present-continuous-negatives","title":"Present Continuous: negatives","titleUz":"Present Continuous: inkor gaplar","goal":"Hozir bo'lmayotgan ishni aytasiz: I'm not working. He isn't sleeping. They aren't playing. To'g'ri qisqartmalarni tanlaysiz va don't/doesn't bilan chalkashtirmaysiz.","words":[{"en":"listen to","uz":"tinglamoq","ipa":"ˈlɪs.ən tə"},{"en":"shout","uz":"baqirmoq","ipa":"ʃaʊt"},{"en":"cry","uz":"yig‘lamoq","ipa":"kraɪ"},{"en":"bark","uz":"akillamoq","ipa":"bɑːk"},{"en":"snow","uz":"qor yog‘moq","ipa":"snəʊ"},{"en":"stand","uz":"turmoq","ipa":"stænd"}],"summary":["Inkor: am/is/are + not + fe'l-ing: I'm not working. He isn't sleeping. They aren't playing.","I bilan faqat I'm not; isn't = 's not, aren't = 're not.","Hozir uchun isn't/aren't + -ing, odat uchun don't/doesn't + fe'l.","don't/doesn't bilan -ing, va besiz inkor — xato."]},{"id":"u4-l16","slug":"present-continuous-questions","title":"Present Continuous: questions","titleUz":"Present Continuous: savollar va qisqa javoblar","goal":"Hozir bo'layotgan ish haqida savol berasiz va qisqa javob qaytarasiz: Are you working? — Yes, I am. Is she sleeping? — No, she isn't. What are you doing?","words":[{"en":"free","uz":"bo'sh, band emas","ipa":"friː"},{"en":"bored","uz":"zerikkan","ipa":"bɔːd"},{"en":"outside","uz":"tashqarida","ipa":"ˌaʊtˈsaɪd"},{"en":"inside","uz":"ichkarida","ipa":"ˌɪnˈsaɪd"},{"en":"lunch","uz":"tushlik","ipa":"lʌntʃ"},{"en":"homework","uz":"uy vazifasi","ipa":"ˈhəʊm.wɜːk"}],"summary":["Savol: Am / Is / Are + ega + -ing? — Are you working? (do/does yo'q).","Qisqa javob: Yes, I am. / No, she isn't. — fe'l takrorlanmaydi; Yes, I'm ❌.","Wh-savol: What are you doing? Where is he going?","Yangi so'zlar: free, bored, outside, inside, lunch, homework."]},{"id":"u4-l11","slug":"on-the-phone-what-are-you-doing","title":"On the phone: what are you doing?","titleUz":"Telefonda: nima qilyapsiz?","goal":"Telefonda yoki chatda hozir nima qilayotganingizni aytasiz va so'raysiz: What are you doing? — I'm cooking. Where are you? Present Continuous va have got (oila) ni qayta ishlatasiz.","words":[{"en":"call","uz":"qo'ng'iroq qilmoq","ipa":"kɔːl"},{"en":"message","uz":"xabar","ipa":"ˈmes.ɪdʒ"},{"en":"hear","uz":"eshitmoq","ipa":"hɪər"},{"en":"online","uz":"onlayn, internetda","ipa":"ˈɒn.laɪn"}],"summary":["Hozirgi ish: am / is / are + -ing. Savol: What are you doing?","Qisqa javob: Yes, I am. / No, he isn't. Telefonda: I can't hear you. Can you call me later?","Oila haqida: have got / has got: Have you got a brother?","Yangi so'zlar: call, message, hear, online."]},{"id":"u4-l18","slug":"what-are-they-doing-listening-and-speaking","title":"What are they doing? Listening and speaking","titleUz":"Ular nima qilyapti? Tinglash va gapirish","goal":"Rasm yoki telefon suhbatida kim hozir nima qilayotganini tinglab tushunasiz va o'zingiz ham shunday gapirib bera olasiz: A boy is riding a bike. Two girls are sitting on a bench.","words":[{"en":"picture","uz":"rasm, surat","ipa":"ˈpɪk.tʃər"},{"en":"bench","uz":"skameyka","ipa":"bentʃ"},{"en":"ice cream","uz":"muzqaymoq","ipa":"ˈaɪs kriːm"},{"en":"bike","uz":"velosiped","ipa":"baɪk"},{"en":"ball","uz":"to'p","ipa":"bɔːl"},{"en":"ride","uz":"minmoq, haydamoq","ipa":"raɪd"}],"summary":["Tinglaganda kim + am/is/are + fe'l-ing ni toping: Sam is riding a bike.","Rasmni tasvirlash: avval joy (This is a park.), keyin kim nima qilyapti (A girl is eating ice cream.).","Savol-javob: Are your friends there? — Yes, they are.","Yangi so'zlar: picture, bench, ice cream, bike, ball, ride."]},{"id":"u4-l12","slug":"describing-and-asking-final-review","title":"Describing and asking: final review","titleUz":"Tasvirlash va so'rash: yakuniy takror","goal":"4-bo'limni yakunlaysiz: Wh- savollar, there is/are, predloglar, much/many, can/can't, buyruqlar, have got va Present Continuous — hammasi bitta joyda.","words":[{"en":"sure","uz":"albatta; ishonchli","ipa":"ʃɔːr"},{"en":"together","uz":"birga","ipa":"təˈɡeð.ər"},{"en":"quickly","uz":"tez, tezda","ipa":"ˈkwɪk.li"}],"summary":["Wh- savollar: what, where, who, why, which, whose, how many/much.","There is / are, some / any va predloglar bilan joyni tasvirlang.","can / can't, buyruqlar (Sit down. Don't run!), have got / has got.","Present Continuous: am/is/are + -ing — hozirgi ish."]}]},{"id":"u5","n":5,"title":"Past & Future","titleUz":"Kecha, ertaga, hozir: o'tgan va kelasi zamon","description":"Ikki hozirgi zamon farqi, was / were, Past Simple, noto'g'ri fe'llar, going to, will, qiyoslash.","canDo":["Kecha va o'tgan hafta nima bo'lganini aytaman","To'g'ri va noto'g'ri fe'llarni o'tgan zamonda ishlataman","Kelajak rejalarimni (going to, will) ayta olaman","Narsalarni solishtiraman (bigger, the biggest)"],"lessons":[{"id":"u5-l1","slug":"present-simple-vs-continuous","title":"Present Simple vs Continuous","titleUz":"Present Simple yoki Continuous?","goal":"Ikki hozirgi zamonni farqlaysiz: odat va doimiy holat uchun Present Simple (I work), ayni paytdagi ish uchun Present Continuous (I am working). Ob-havo va fasllar haqida gapira olasiz.","words":[{"en":"weather","uz":"ob-havo","ipa":"ˈweð.ə"},{"en":"sunny","uz":"quyoshli","ipa":"ˈsʌn.i"},{"en":"rainy","uz":"yomg'irli","ipa":"ˈreɪ.ni"},{"en":"windy","uz":"shamolli","ipa":"ˈwɪn.di"},{"en":"cloudy","uz":"bulutli","ipa":"ˈklaʊ.di"},{"en":"warm","uz":"iliq","ipa":"wɔːm"},{"en":"spring","uz":"bahor","ipa":"sprɪŋ"},{"en":"summer","uz":"yoz","ipa":"ˈsʌm.ə"},{"en":"autumn","uz":"kuz","ipa":"ˈɔː.təm"},{"en":"winter","uz":"qish","ipa":"ˈwɪn.tə"}],"summary":["Present Simple — odat va doimiy holat: I work in a bank. He usually goes by bus.","Present Continuous — ayni paytdagi ish: I'm working now. Look! It's raining.","Signal so'zlar: every day, usually, often → Simple; now, at the moment, Look! → Continuous.","like, love, want, need, know, understand, have (ega bo'lmoq) -ing olmaydi.","Ob-havo — doim It bilan: It's sunny / windy / cloudy. Fasllar: in spring, summer, autumn, winter."]},{"id":"u5-l2","slug":"was-were","title":"was / were","titleUz":"O'tgan zamon: was / were","goal":"to be fe'lini o'tgan zamonda ishlatasiz: I was at home. They weren't late. Where were you? Qachon va qayerda tug'ilganingizni ayta olasiz (I was born in…).","words":[{"en":"yesterday","uz":"kecha","ipa":"ˈjes.tə.deɪ"},{"en":"last night","uz":"kecha kechqurun","ipa":"ˌlɑːst ˈnaɪt"},{"en":"last week","uz":"o'tgan hafta","ipa":"ˌlɑːst ˈwiːk"},{"en":"ago","uz":"oldin","ipa":"əˈɡəʊ"},{"en":"born","uz":"tug'ilgan","ipa":"bɔːn"},{"en":"museum","uz":"muzey","ipa":"mjuˈziː.əm"},{"en":"beach","uz":"plyaj, sohil","ipa":"biːtʃ"},{"en":"village","uz":"qishloq","ipa":"ˈvɪl.ɪdʒ"},{"en":"at the weekend","uz":"dam olish kunlarida","ipa":"ət ðə ˌwiːkˈend"},{"en":"concert","uz":"konsert","ipa":"ˈkɒn.sət"}],"summary":["am / is → was, are → were: I was, he was, we were, they were.","Inkor: wasn't / weren't. Savol: Was he…? Were you…? — Yes, I was. / No, they weren't.","Tug'ilgan joy va yil: I was born in… (I born ❌).","Vaqt: yesterday, last night, last week, at the weekend, son + ago (two days ago)."]},{"id":"u5-l3","slug":"past-simple-regular-verbs","title":"Past Simple: regular verbs","titleUz":"Past Simple: to'g'ri fe'llar (-ed)","goal":"O'tmishda tugagan ishlar haqida gapirasiz: I visited my grandmother yesterday. -ed ni to'g'ri yozasiz (stopped, studied, played) va uch xil talaffuzini (/t/ /d/ /ɪd/) ajratasiz.","words":[{"en":"visit","uz":"borib ko'rmoq, ziyorat qilmoq","ipa":"ˈvɪz.ɪt"},{"en":"play","uz":"o'ynamoq","ipa":"pleɪ"},{"en":"cook","uz":"ovqat pishirmoq","ipa":"kʊk"},{"en":"clean","uz":"tozalamoq","ipa":"kliːn"},{"en":"start","uz":"boshlamoq, boshlanmoq","ipa":"stɑːt"},{"en":"finish","uz":"tugatmoq, tugamoq","ipa":"ˈfɪn.ɪʃ"},{"en":"open","uz":"ochmoq","ipa":"ˈəʊ.pən"},{"en":"want","uz":"xohlamoq","ipa":"wɒnt"},{"en":"arrive","uz":"yetib kelmoq","ipa":"əˈraɪv"},{"en":"stay","uz":"qolmoq","ipa":"steɪ"}],"summary":["Past Simple — o'tmishda tugagan ish. To'g'ri fe'llar: fe'l + ed, hamma shaxs uchun bir xil (she played).","Imlo: arrive → arrived, study → studied, play → played, stop → stopped.","Talaffuz: /t/ cooked, watched · /d/ played, cleaned · /ɪd/ wanted, visited (faqat t / d dan keyin).","Harakat uchun was kerak emas: I cleaned ✅, I was cleaned ❌."]},{"id":"u5-l13","slug":"ed-spelling","title":"-ed: spelling","titleUz":"-ed qo'shish imlosi: stop → stopped","goal":"Fe'lga -ed ni xatosiz qo'shasiz: play → played, like → liked, study → studied, stop → stopped. To'rt xil imlo qoidasini bilib olasiz.","words":[{"en":"carry","uz":"ko'tarib yurmoq","ipa":"ˈkær.i"},{"en":"plan","uz":"rejalashtirmoq","ipa":"plæn"},{"en":"drop","uz":"tushirib yubormoq","ipa":"drɒp"},{"en":"try","uz":"urinib ko'rmoq","ipa":"traɪ"},{"en":"hurry","uz":"shoshilmoq","ipa":"ˈhʌr.i"},{"en":"travel","uz":"sayohat qilmoq","ipa":"ˈtræv.əl"}],"summary":["Oddiy qoida: fe'l + -ed (worked, played, stayed).","-e bilan tugasa, faqat -d: like → liked, arrive → arrived.","Undosh + y → ied: study → studied, try → tried. Unli + y o'zgarmaydi: played.","Qisqa undosh-unli-undosh fe'l ikkilanadi: stop → stopped, plan → planned.","travel → travelled (Britaniya) yoki traveled (Amerika)."]},{"id":"u5-l14","slug":"ed-pronunciation","title":"-ed: pronunciation","titleUz":"-ed talaffuzi: /t/, /d/, /ɪd/","goal":"-ed ni to'g'ri talaffuz qilasiz: worked (/t/), played (/d/), wanted (/ɪd/). Eshitib qaysi tovush ekanini ajratasiz.","words":[{"en":"walk","uz":"yurmoq, piyoda bormoq","ipa":"wɔːk"},{"en":"jump","uz":"sakramoq","ipa":"dʒʌmp"},{"en":"answer","uz":"javob bermoq","ipa":"ˈɑːn.sər"},{"en":"invite","uz":"taklif qilmoq","ipa":"ɪnˈvaɪt"},{"en":"paint","uz":"bo'yamoq, rasm chizmoq","ipa":"peɪnt"},{"en":"wash","uz":"yuvmoq","ipa":"wɒʃ"}],"summary":["-ed uch xil o'qiladi: /t/, /d/, /ɪd/.","p, k, f, s, sh, ch dan keyin /t/: worked, washed, jumped.","Jarangli tovush va unlidan keyin /d/: played, cleaned, stayed.","t yoki d dan keyin /ɪd/ (qo'shimcha bo'g'in): wanted, needed, invited.","Faqat /ɪd/ da so'z bo'g'inga uzayadi. worked — \"work-id\" emas!"]},{"id":"u5-l4","slug":"irregular-verbs-1","title":"Irregular verbs 1","titleUz":"Noto'g'ri fe'llar 1","goal":"Eng ko'p ishlatiladigan 10 ta noto'g'ri fe'lning o'tgan zamon shaklini (went, came, got, had, did, made, took, saw, said, was/were) bilasiz va kuningiz haqida o'tgan zamonda gapirasiz.","words":[{"en":"be – was/were","uz":"bo'lmoq","ipa":"biː – wɒz/wɜː"},{"en":"have – had","uz":"ega bo'lmoq; yemoq","ipa":"hæv – hæd"},{"en":"do – did","uz":"qilmoq","ipa":"duː – dɪd"},{"en":"go – went","uz":"bormoq","ipa":"ɡəʊ – went"},{"en":"come – came","uz":"kelmoq","ipa":"kʌm – keɪm"},{"en":"get – got","uz":"olmoq; bo'lmoq","ipa":"ɡet – ɡɒt"},{"en":"make – made","uz":"yasamoq, tayyorlamoq","ipa":"meɪk – meɪd"},{"en":"take – took","uz":"olmoq, olib ketmoq","ipa":"teɪk – tʊk"},{"en":"see – saw","uz":"ko'rmoq","ipa":"siː – sɔː"},{"en":"say – said","uz":"aytmoq","ipa":"seɪ – sed"}],"summary":["Noto'g'ri fe'llar -ed olmaydi, V2 ni yodlash kerak; shakl hamma shaxs uchun bir xil.","be – was/were, have – had, do – did, go – went, come – came.","get – got, make – made, take – took, see – saw, say – said (\"sed\"!).","Iboralar: got up, had breakfast, went home, did my homework, made tea, took the bus."]},{"id":"u5-l5","slug":"irregular-verbs-2-didnt-did","title":"Irregular verbs 2: didn't, Did…?","titleUz":"Noto'g'ri fe'llar 2, didn't va Did…?","goal":"Yana 10 ta noto'g'ri fe'lni o'rganasiz va o'tgan zamonda inkor (I didn't go) hamda savol (Did you see…? What did you eat?) tuza olasiz.","words":[{"en":"give – gave","uz":"bermoq","ipa":"ɡɪv – ɡeɪv"},{"en":"know – knew","uz":"bilmoq","ipa":"nəʊ – njuː"},{"en":"think – thought","uz":"o'ylamoq","ipa":"θɪŋk – θɔːt"},{"en":"buy – bought","uz":"sotib olmoq","ipa":"baɪ – bɔːt"},{"en":"eat – ate","uz":"yemoq","ipa":"iːt – et"},{"en":"drink – drank","uz":"ichmoq","ipa":"drɪŋk – dræŋk"},{"en":"write – wrote","uz":"yozmoq","ipa":"raɪt – rəʊt"},{"en":"read – read","uz":"o'qimoq","ipa":"riːd – red"},{"en":"find – found","uz":"topmoq","ipa":"faɪnd – faʊnd"},{"en":"meet – met","uz":"uchrashmoq, tanishmoq","ipa":"miːt – met"}],"summary":["give – gave, know – knew, think – thought, buy – bought, eat – ate.","drink – drank, write – wrote, read – read (\"red\"), find – found, meet – met.","Inkor: didn't + V1 — I didn't go (❌ didn't went).","Savol: Did + ega + V1? — Did you see it? What did you buy? Javob: Yes, I did. / No, I didn't.","to be bilan did yo'q: Were you…? I wasn't…"]},{"id":"u5-l15","slug":"past-simple-short-answers-and-wh-questions","title":"Past Simple: short answers and Wh- questions","titleUz":"Past Simple: qisqa javoblar va Wh-savollar","goal":"Savolga qisqa javob berasiz (Did you go? — Yes, I did.) va so'roq so'zli savollar tuzasiz: What did you do? Where did she go? When did they arrive?","words":[{"en":"ask","uz":"so'ramoq","ipa":"ɑːsk"},{"en":"wait","uz":"kutmoq","ipa":"weɪt"},{"en":"call","uz":"qo'ng'iroq qilmoq","ipa":"kɔːl"},{"en":"reply","uz":"javob qaytarmoq","ipa":"rɪˈplaɪ"},{"en":"early","uz":"erta","ipa":"ˈɜː.li"},{"en":"late","uz":"kech","ipa":"leɪt"}],"summary":["Qisqa javob: Yes, I did. / No, I didn't. Asosiy fe'l takrorlanmaydi.","was / were savoli: Yes, it was. did emas.","Wh-savol tartibi: so'roq so'z + did + ega + V1 (Where did she go?).","did dan keyin fe'l oddiy shaklda: go, eat, do (went, ate, did emas).","To'liq javobda V2: I went to a café."]},{"id":"u5-l9","slug":"yesterday-telling-what-happened","title":"Yesterday: telling what happened","titleUz":"Kecha nima bo'ldi: Past Simple hayotda","goal":"Do'stingizga kecha nima bo'lganini aytib berasiz va savol berasiz: I went to a party. Did you go? — No, I didn't. was / were, Past Simple, didn't va Did…? ni real suhbatda ishlatasiz.","words":[{"en":"party","uz":"ziyofat, bazm","ipa":"ˈpɑː.ti"},{"en":"cinema","uz":"kinoteatr","ipa":"ˈsɪn.ə.mə"},{"en":"funny","uz":"kulgili","ipa":"ˈfʌn.i"},{"en":"boring","uz":"zerikarli","ipa":"ˈbɔː.rɪŋ"}],"summary":["Kecha haqida savol: What did you do yesterday? / Where were you?","was (I, he, she, it) va were (you, we, they); Past Simple: visited, went, saw.","did / didn't dan keyin fe'l oddiy shaklda: Did you go? — I didn't go."]},{"id":"u5-l18","slug":"real-life-how-was-your-weekend","title":"Real life: how was your weekend?","titleUz":"Real hayot: dam olish kuni qanday o'tdi?","goal":"Do'stingizga dam olish kuningiz haqida gapirib berasiz: nima qildingiz, nima qilmadingiz, va o'zingiz ham savol berasiz. Past Simple ni jonli suhbatda ishlatasiz.","words":[],"summary":["How was your weekend? → It was great. (it bilan was, were emas).","Tartibsiz fe'llar: go → went, see → saw, eat → ate (goed emas).","Did you play football? — Did dan keyin fe'lning oddiy shakli: Did you went emas.","No, I didn't. I watched a film. — didn't + oddiy shakl.","What did you do on Sunday? — o'tgan zamondagi savol."]},{"id":"u5-l16","slug":"reading-a-day-last-week","title":"Reading: a day last week","titleUz":"O'qish: o'tgan haftadagi bir kun","goal":"Past Simple'dagi qisqa inglizcha matnlarni o'qib, asosiy fikrni va tafsilotlarni tushunasiz, hamda noma'lum so'zning ma'nosini gapdan topasiz.","words":[{"en":"noisy","uz":"shovqinli","ipa":"ˈnɔɪ.zi"},{"en":"delicious","uz":"mazali","ipa":"dɪˈlɪʃ.əs"},{"en":"wait","uz":"kutmoq","ipa":"weɪt"},{"en":"lucky","uz":"omadli","ipa":"ˈlʌk.i"},{"en":"ill","uz":"kasal","ipa":"ɪl"},{"en":"rest","uz":"dam olmoq","ipa":"rest"}],"summary":["O'qishdan oldin savolga qarang, so'ng vaqt so'zlari (last Saturday, yesterday) va fe'llarni (-ed, went, saw, had) toping.","Noma'lum so'zda to'xtamang: gapning ma'nosidan taxmin qiling.","Past Simple: was / were, -ed, noto'g'ri fe'llar; inkorda didn't + V1 (didn't go).","Yangi so'zlar: noisy, delicious, wait, lucky, ill, rest."]},{"id":"u5-l6","slug":"future-be-going-to","title":"Future: be going to","titleUz":"Kelasi zamon: be going to","goal":"Rejalaringiz haqida gapirasiz (I'm going to visit Bukhara next week) va ko'z oldingizdagi dalilga qarab bashorat qilasiz (Look! It's going to rain). Sayohatga oid 10 ta so'zni bilib olasiz.","words":[{"en":"plan","uz":"reja; rejalashtirmoq","ipa":"plæn"},{"en":"trip","uz":"sayohat, safar","ipa":"trɪp"},{"en":"ticket","uz":"chipta","ipa":"ˈtɪk.ɪt"},{"en":"holiday","uz":"ta'til, dam olish","ipa":"ˈhɒl.ə.deɪ"},{"en":"airport","uz":"aeroport","ipa":"ˈeə.pɔːt"},{"en":"train","uz":"poyezd","ipa":"treɪn"},{"en":"hotel","uz":"mehmonxona","ipa":"həʊˈtel"},{"en":"suitcase","uz":"chamadon","ipa":"ˈsuːt.keɪs"},{"en":"passport","uz":"pasport","ipa":"ˈpɑːs.pɔːt"},{"en":"abroad","uz":"chet elga, chet elda","ipa":"əˈbrɔːd"}],"summary":["am / is / are + going to + V1 — oldindan qilingan reja: I'm going to visit Khiva.","Inkor: She isn't going to fly. Savol: Are you going to stay? — Yes, I am.","Dalilga asoslangan bashorat: Look at the clouds! It's going to rain.","Vaqt: tomorrow, tonight, next week, next summer (the next week ❌). go abroad (to yo'q)."]},{"id":"u5-l7","slug":"future-will","title":"Future: will","titleUz":"Kelasi zamon: will","goal":"will bilan shu zahoti qaror qilasiz, va'da va taklif berasiz, kelajak haqida fikr bildirasiz (I'll help you. I think it will rain.). will va going to ni farqlaysiz.","words":[{"en":"maybe","uz":"balki","ipa":"ˈmeɪ.bi"},{"en":"probably","uz":"ehtimol","ipa":"ˈprɒb.ə.bli"},{"en":"promise","uz":"va'da; va'da bermoq","ipa":"ˈprɒm.ɪs"},{"en":"decide","uz":"qaror qilmoq","ipa":"dɪˈsaɪd"},{"en":"future","uz":"kelajak","ipa":"ˈfjuː.tʃə"},{"en":"soon","uz":"tez orada, yaqinda","ipa":"suːn"},{"en":"later","uz":"keyinroq","ipa":"ˈleɪ.tə"},{"en":"next year","uz":"kelasi yil","ipa":"ˌnekst ˈjɪə"},{"en":"I think","uz":"menimcha, deb o'ylayman","ipa":"aɪ ˈθɪŋk"},{"en":"hope","uz":"umid qilmoq","ipa":"həʊp"}],"summary":["will + V1 (hamma shaxsga bir xil): I'll help. He won't come. Will you…?","will — shu zahoti qaror, va'da, taklif, fikr: I'll close the window. I promise I'll call.","Fikr bilan: I think / maybe / probably / I hope + will.","going to — oldindan reja yoki ko'z oldingizdagi dalil; will — hozirgi qaror yoki shunchaki fikr.","Talaffuz: won't \"wount\" ≠ want \"wont\"."]},{"id":"u5-l8","slug":"comparatives-superlatives","title":"Comparatives & superlatives","titleUz":"Qiyoslash: bigger, the biggest","goal":"Narsalar va odamlarni solishtirasiz: Tashkent is bigger than Samarkand. This is the most interesting book. -er / -est, more / most va good – better – best kabi istisnolarni to'g'ri ishlatasiz.","words":[{"en":"fast","uz":"tez","ipa":"fɑːst"},{"en":"slow","uz":"sekin","ipa":"sləʊ"},{"en":"strong","uz":"kuchli","ipa":"strɒŋ"},{"en":"easy","uz":"oson","ipa":"ˈiː.zi"},{"en":"difficult","uz":"qiyin","ipa":"ˈdɪf.ɪ.kəlt"},{"en":"important","uz":"muhim","ipa":"ɪmˈpɔː.tənt"},{"en":"interesting","uz":"qiziqarli","ipa":"ˈɪn.trə.stɪŋ"},{"en":"good – better – best","uz":"yaxshi – yaxshiroq – eng yaxshi","ipa":"ɡʊd – ˈbet.ə – best"},{"en":"bad – worse – worst","uz":"yomon – yomonroq – eng yomon","ipa":"bæd – wɜːs – wɜːst"},{"en":"far – further – furthest","uz":"uzoq – uzoqroq – eng uzoq","ipa":"fɑː – ˈfɜː.ðə – ˈfɜː.ðɪst"}],"summary":["Qisqa sifatlar: -er than / the -est — bigger than, the biggest; easier, the easiest.","Uzun sifatlar: more … than / the most … — more difficult, the most interesting.","Istisnolar: good – better – best, bad – worse – worst, far – further – furthest.","more va -er birga kelmaydi (more bigger ❌); orttirma darajada the shart.","🎉 Tabriklaymiz — Beginner kursini tugatdingiz! Endi siz o'tmish, hozir va kelajak haqida inglizcha gapira olasiz."]},{"id":"u5-l10","slug":"plans-for-the-weekend","title":"Plans for the weekend","titleUz":"Dam olish kuni rejalari: going to, will","goal":"Dam olish kuni rejalaringiz haqida gapirasiz va joyida qaror qabul qilasiz: I'm going to visit my cousin. — OK, I'll come with you! be going to (reja) va will (qaror, va'da) ni farqlaysiz.","words":[{"en":"picnic","uz":"piknik","ipa":"ˈpɪk.nɪk"},{"en":"relax","uz":"dam olmoq","ipa":"rɪˈlæks"},{"en":"swim","uz":"suzmoq","ipa":"swɪm"},{"en":"cousin","uz":"amakivachcha, xolavachcha","ipa":"ˈkʌz.ən"}],"summary":["be going to — oldindan reja: I'm going to visit my cousin.","will — joyida qaror, va'da, taxmin: I'll come. I promise I won't be late.","will dan keyin to yo'q; going to da am / is / are kerak."]},{"id":"u5-l19","slug":"real-life-plans-for-the-weekend","title":"Real life: plans for the weekend","titleUz":"Real hayot: dam olish kuni rejalari","goal":"Do'stingiz bilan dam olish kuni rejalarini gaplashasiz: rejangizni aytasiz (be going to), ob-havo haqida fikr bildirasiz va shu zahoti qaror qilsangiz will ishlatasiz.","words":[],"summary":["I'm going to visit my grandmother. — oldindan tuzilgan reja: am / is / are + going to + fe'l.","Are you going to play football? → No, I'm not.","I think it will be sunny. — taxmin: will + oddiy fe'l (will be).","I'll help you. — shu zahoti qilingan qaror: will; oldindan reja: going to."]},{"id":"u5-l11","slug":"choosing-in-a-shop-comparing","title":"Choosing in a shop: comparing","titleUz":"Do'konda tanlash: qiyoslash","goal":"Do'konda narsalarni solishtirasiz va tanlaysiz: This jacket is cheaper than that one. I'll take the cheapest. -er / -est, more / most, better / the best ni real vaziyatda ishlatasiz.","words":[{"en":"size","uz":"o'lcham","ipa":"saɪz"},{"en":"choose","uz":"tanlamoq","ipa":"tʃuːz"},{"en":"discount","uz":"chegirma","ipa":"ˈdɪs.kaʊnt"},{"en":"comfortable","uz":"qulay","ipa":"ˈkʌm.fə.tə.bəl"}],"summary":["Ikkita narsa: sifat + er + than (cheaper than), uzun sifat: more expensive than.","Hammasidan eng: the + -est / the most (the cheapest, the most comfortable).","Istisnolar: good – better – the best, bad – worse – the worst."]},{"id":"u5-l17","slug":"listening-and-speaking-my-last-weekend","title":"Listening and speaking: my last weekend","titleUz":"Tinglash va gapirish: o'tgan dam olish kunim","goal":"Dam olish kuningiz haqidagi suhbatni tinglab tushunasiz va o'zingiz o'tgan dam olish kuni haqida (I went… It was… I didn't…) hamda keyingi rejangiz haqida gapira olasiz.","words":[{"en":"lake","uz":"ko'l","ipa":"leɪk"},{"en":"mountain","uz":"tog'","ipa":"ˈmaʊn.tɪn"},{"en":"fishing","uz":"baliq ovlash","ipa":"ˈfɪʃ.ɪŋ"},{"en":"sunny","uz":"quyoshli","ipa":"ˈsʌn.i"},{"en":"rainy","uz":"yomg'irli","ipa":"ˈreɪ.ni"},{"en":"win","uz":"yutmoq","ipa":"wɪn"}],"summary":["Dam olish kunini so'rash: How was your weekend? Where did you go? What did you do? Javob: It was great. I went… I had… I didn't…","Faqat Yes / No demang: Yes, I did. + bitta qo'shimcha gap.","Rejani be going to bilan ayting: Next weekend I am going to visit my cousin.","Namuna matn: Last weekend I was at home. On Saturday we visited my grandmother. On Sunday it was sunny, so I went to the park. We played football, but we didn't win. It was a good weekend."]},{"id":"u5-l20","slug":"real-life-a-day-in-a-new-city","title":"Real life: a day in a new city","titleUz":"Real hayot: yakuniy missiya — yangi shaharda bir kun","goal":"Yangi shaharda bir kun o'tkazasiz: do'st bilan tanishasiz, yo'l so'raysiz, kafeda buyurtma berasiz, kecha nima qilganingizni va ertangi rejangizni aytasiz. Butun Beginner kursi bitta missiyada.","words":[],"summary":["Tanishuv: Nice to meet you. I'm from Uzbekistan. I'm a student. (to be).","Yo'l so'rash: Excuse me, where is the museum?","Kafeda: I'd like a tea, please. How much is it?","Kecha: I went / I met / I visited...; savol: Did you...?","Reja: I'm going to visit the museum tomorrow."]},{"id":"u5-l12","slug":"past-and-future-final-review","title":"Past and future: final review","titleUz":"O'tgan va kelasi zamon: yakuniy takror","goal":"5-bo'lim bo'yicha yakuniy takror: Present Simple va Continuous, was / were, Past Simple, be going to, will va qiyoslash darajalarini bitta suhbatda aralashtirib ishlatasiz.","words":[{"en":"grandmother","uz":"buvi","ipa":"ˈɡræn.mʌð.ər"},{"en":"kind","uz":"mehribon","ipa":"kaɪnd"},{"en":"drive","uz":"mashina haydamoq","ipa":"draɪv"},{"en":"dinner","uz":"kechki ovqat","ipa":"ˈdɪn.ər"}],"summary":["Vaqt belgisiga qarang: now → Continuous, usually → Simple, yesterday → Past, tomorrow → going to / will.","was / were, didn't / Did…? + oddiy fe'l; will + oddiy fe'l; going to oldidan am / is / are.","Qiyoslash: -er … than, the -est, more / the most; istisno: good – better – best."]}]}]},{"id":"a1","slug":"elementary","title":"Elementary","cefr":"A1","text":"Oddiy gaplarni tushunaman, o'zim haqimda biroz gapira olaman.","units":[{"id":"u6","n":6,"title":"People & Places","titleUz":"Odamlar va joylar: tasvirlash, egalik, yo'l so'rash","description":"Tanishuv, odamlarni tasvirlash, mine / yours, tartib sonlar va sanalar, uy, shahar va yo'l so'rash, a / the.","canDo":["O'zimni va boshqalarni tanishtiraman","Odamning tashqi ko'rinishi va xarakterini tasvirlayman","Sana va tartib sonlarni aytaman","Yo'l so'rayman va yo'l ko'rsataman"],"lessons":[{"id":"u6-l1","slug":"nice-to-meet-you","title":"Nice to meet you!","titleUz":"Tanishuv va qisqa suhbat","goal":"Yangi odam bilan tanishib, boshqalarni tanishtirasiz (This is my colleague, Kamola.), What do you do? / Where are you from exactly? kabi savollar bilan suhbatni davom ettirasiz va uni muloyim yakunlaysiz (It was nice to meet you.).","words":[{"en":"introduce","uz":"tanishtirmoq","ipa":"ˌɪn.trəˈdjuːs"},{"en":"journalist","uz":"jurnalist","ipa":"ˈdʒɜː.nə.lɪst"},{"en":"conference","uz":"konferensiya","ipa":"ˈkɒn.fər.əns"},{"en":"small talk","uz":"qisqa suhbat (kundalik gap-so'z)","ipa":"ˈsmɔːl tɔːk"},{"en":"exactly","uz":"aniq, aynan","ipa":"ɪɡˈzækt.li"},{"en":"first name","uz":"ism","ipa":"ˈfɜːst neɪm"},{"en":"hometown","uz":"tug'ilgan shahar, ona shahar","ipa":"ˈhəʊm.taʊn"},{"en":"actually","uz":"aslida, haqiqatda","ipa":"ˈæk.tʃu.ə.li"},{"en":"by the way","uz":"aytgancha","ipa":"baɪ ðə ˈweɪ"},{"en":"pleased","uz":"xursand","ipa":"pliːzd"}],"summary":["Tanishuv: Nice to meet you. — Nice to meet you too. Eski tanishga: Nice to see you!","Boshqani tanishtirish: This is my colleague, Kamola. / These are my parents. (❌ He is…)","What do you do? — kasb; What are you doing? — hozirgi harakat. Savolni qaytaring: And you? / What about you?","Reaksiya: Really? That's interesting!; actually = aslida, by the way = aytgancha.","Xayrlashuv: It was nice to meet you. / Have a nice day!"]},{"id":"u6-l2","slug":"what-does-she-look-like","title":"What does she look like?","titleUz":"Tashqi ko'rinishni tasvirlash","goal":"What does he/she look like? savoliga javob berib, odamning bo'yi, qaddi-qomati, sochi, ko'zlari va yoshini tasvirlaysiz: She's tall and slim. She has long curly black hair. Sifatlar tartibini va look like ning ikki ma'nosini bilasiz.","words":[{"en":"look like","uz":"…ga o'xshamoq","ipa":"ˈlʊk laɪk"},{"en":"slim","uz":"qaddi-qomati kelishgan, ozg'in","ipa":"slɪm"},{"en":"curly","uz":"jingalak","ipa":"ˈkɜː.li"},{"en":"straight","uz":"tekis, to'g'ri (soch)","ipa":"streɪt"},{"en":"fair","uz":"och rang, sariq (soch, teri)","ipa":"feə"},{"en":"beard","uz":"soqol","ipa":"bɪəd"},{"en":"moustache","uz":"mo'ylov","ipa":"məˈstɑːʃ"},{"en":"glasses","uz":"ko'zoynak","ipa":"ˈɡlɑː.sɪz"},{"en":"middle-aged","uz":"o'rta yoshli","ipa":"ˌmɪd.əlˈeɪdʒd"},{"en":"good-looking","uz":"chiroyli, kelishgan","ipa":"ˌɡʊdˈlʊk.ɪŋ"}],"summary":["Savol: What does he/she look like? — tashqi ko'rinish.","be — bo'y, qomat, yosh (She's tall / slim / in her twenties); have (got) — soch, ko'z, soqol; wear — ko'zoynak.","hair sanalmaydi: Her hair is long. Sifatlar tartibi: long curly black hair.","look + sifat (You look tired), look like + ot (She looks like her mum).","Muloyim so'zlar: slim, a bit overweight, elderly; odam — tall, ❌ high."]},{"id":"u6-l3","slug":"personality-very-quite-really","title":"Personality: very, quite, really","titleUz":"Xarakter va sifatlar: very, quite, really","goal":"What is he like? savoliga javob berib, odamning xarakterini tasvirlaysiz (kind, shy, hard-working, rude…) va fikringizni very, really, quite, a bit, not very bilan aniq va muloyim ifodalaysiz.","words":[{"en":"friendly","uz":"do'stona, xushmuomala","ipa":"ˈfrend.li"},{"en":"polite","uz":"odobli, xushmuomala","ipa":"pəˈlaɪt"},{"en":"rude","uz":"qo'pol, odobsiz","ipa":"ruːd"},{"en":"hard-working","uz":"mehnatkash","ipa":"ˌhɑːdˈwɜː.kɪŋ"},{"en":"lazy","uz":"dangasa","ipa":"ˈleɪ.zi"},{"en":"shy","uz":"uyatchan","ipa":"ʃaɪ"},{"en":"talkative","uz":"gapdon, ko'p gapiradigan","ipa":"ˈtɔː.kə.tɪv"},{"en":"patient","uz":"sabrli","ipa":"ˈpeɪ.ʃənt"},{"en":"generous","uz":"saxiy, qo'li ochiq","ipa":"ˈdʒen.ər.əs"},{"en":"funny","uz":"kuldiradigan, hazilkash","ipa":"ˈfʌn.i"}],"summary":["What is she like? — xarakter; What does she look like? — tashqi ko'rinish; What does she like? — nimani yoqtiradi.","Juftliklar: polite – rude, hard-working – lazy, generous – mean, patient – impatient, talkative – quiet/shy.","Kuch darajasi: really / very > quite > a bit > not very. a bit — salbiy sifat bilan.","a very kind man, lekin quite a kind man. Fe'l bilan: I really like… / I like… very much (❌ I very like).","Muloyim tanqid: He isn't very polite."]},{"id":"u6-l9","slug":"meeting-a-new-neighbour","title":"Meeting a new neighbour","titleUz":"Yangi qo'shni bilan tanishuv","goal":"Yangi qo'shni bilan tanishasiz, uning oilasi va ko'rinishi haqida so'raysiz va kichik suhbat qurasiz: Nice to meet you! I'm your new neighbour. Where are you from?","words":[{"en":"neighbour","uz":"qo'shni","ipa":"ˈneɪ.bər"},{"en":"move in","uz":"ko'chib kirmoq","ipa":"muːv ɪn"},{"en":"welcome","uz":"xush kelibsiz","ipa":"ˈwel.kəm"},{"en":"nearby","uz":"yaqin atrofda","ipa":"ˌnɪəˈbaɪ"},{"en":"building","uz":"bino","ipa":"ˈbɪl.dɪŋ"},{"en":"next door","uz":"yonma-yon eshikda","ipa":"ˌnekst ˈdɔː"}],"summary":["Tanishuv: I'm your new neighbour. Nice to meet you. Where are you from?","Ko'rinish: What does she look like? — She has long curly hair. Xarakter: She's friendly.","Yangi so'zlar: neighbour, move in, welcome, nearby, building, next door."]},{"id":"u6-l4","slug":"mine-yours-whose","title":"mine, yours… Whose?","titleUz":"Egalik olmoshlari: mine, yours… va Whose?","goal":"Narsa kimniki ekanini so'raysiz va aytasiz: Whose bag is this? — It's mine / It's Ali's. my – mine, your – yours, her – hers… farqini bilasiz va whose / who's ni adashtirmaysiz.","words":[{"en":"purse","uz":"hamyon","ipa":"pɜːs"},{"en":"wallet","uz":"hamyon","ipa":"ˈwɒl.ɪt"},{"en":"lend","uz":"qarz bermoq, vaqtincha bermoq","ipa":"lend"},{"en":"charger","uz":"quvvatlagich (zaryadlovchi)","ipa":"ˈtʃɑː.dʒə"},{"en":"earphones","uz":"quloqchinlar","ipa":"ˈɪə.fəʊnz"},{"en":"scarf","uz":"sharf, ro'mol","ipa":"skɑːf"},{"en":"belong to","uz":"…ga tegishli bo'lmoq","ipa":"bɪˈlɒŋ tə"},{"en":"borrow","uz":"qarzga (vaqtincha) olmoq","ipa":"ˈbɒr.əʊ"},{"en":"lose","uz":"yo'qotmoq","ipa":"luːz"},{"en":"a friend of mine","uz":"do'stlarimdan biri","ipa":"ə ˈfrend əv maɪn"}],"summary":["Ot bilan: my, your, his, her, our, their; otsiz: mine, yours, his, hers, ours, theirs.","Apostrof yo'q: yours, hers, ours, theirs (❌ your's). ❌ mine bag, ❌ It's my.","Whose bag is this? / Whose is this bag? — It's mine / It's Ali's. Ko'plikda: Whose keys are these? — They're…","whose (kimning) ≠ who's (= who is / who has) — talaffuzi bir xil \"hu:z\".","a friend of mine, belong to + kishi: It belongs to my dad."]},{"id":"u6-l5","slug":"ordinal-numbers-dates","title":"Ordinal numbers & dates","titleUz":"Tartib sonlar va sanalar","goal":"Tartib sonlarni (first, second, third… twenty-first, thirty-first) to'g'ri aytasiz va yozasiz (1st, 2nd, 3rd), sanani o'qiysiz (the fifth of May), yillarni aytasiz (nineteen ninety-eight, twenty twenty-five) va on / in bilan ishlatasiz.","words":[{"en":"date","uz":"sana","ipa":"deɪt"},{"en":"calendar","uz":"taqvim, kalendar","ipa":"ˈkæl.ən.də"},{"en":"floor","uz":"qavat","ipa":"flɔː"},{"en":"celebrate","uz":"nishonlamoq","ipa":"ˈsel.ə.breɪt"},{"en":"public holiday","uz":"davlat bayrami, dam olish kuni","ipa":"ˌpʌb.lɪk ˈhɒl.ə.deɪ"},{"en":"anniversary","uz":"yillik, yubiley","ipa":"ˌæn.ɪˈvɜː.sər.i"},{"en":"wedding","uz":"to'y (nikoh to'yi)","ipa":"ˈwed.ɪŋ"},{"en":"century","uz":"asr","ipa":"ˈsen.tʃər.i"},{"en":"appointment","uz":"uchrashuv (oldindan belgilangan), qabul","ipa":"əˈpɔɪnt.mənt"},{"en":"the day after tomorrow","uz":"indinga","ipa":"ðə ˌdeɪ ˌɑːf.tə təˈmɒr.əʊ"}],"summary":["first, second, third — maxsus; qolganlari + -th. Imlo: fifth, eighth, ninth, twelfth, twentieth.","Murakkab sonlarda faqat oxirgisi: twenty-first (21st), thirty-second (32nd); lekin 11th, 12th, 13th.","Sana: yoziladi 5 May, o'qiladi the fifth of May yoki May the fifth.","Yillar: nineteen ninety-one, two thousand and seven, twenty twenty-five.","on + aniq sana (on the 1st of September), in + oy/yil/asr (in May, in 1991)."]},{"id":"u6-l12","slug":"saying-and-writing-dates","title":"Saying and writing dates","titleUz":"Sanalarni aytish va yozish: the 5th of May","goal":"Sanani yozma (5 May, 5th May, May 5th) va og'zaki (the fifth of May) to'g'ri ifodalaysiz, yilni aytasiz va Britaniya hamda Amerika yozuvini adashtirmaysiz.","words":[{"en":"deadline","uz":"oxirgi muddat","ipa":"ˈded.laɪn"},{"en":"exam","uz":"imtihon","ipa":"ɪɡˈzæm"},{"en":"invitation","uz":"taklifnoma","ipa":"ˌɪn.vɪˈteɪ.ʃən"},{"en":"schedule","uz":"jadval, reja","ipa":"ˈʃed.juːl"},{"en":"leap year","uz":"kabisa yili","ipa":"ˈliːp jɪə"},{"en":"date of birth","uz":"tug'ilgan sana","ipa":"ˌdeɪt əv ˈbɜːθ"}],"summary":["Yozuv: 5 May / 5th May (Britaniya), May 5th (Amerika). Aytilishi: the fifth of May.","Sanada tartib son ishlating, aniq sana oldidan on, oy va yil oldidan in.","03/04 Britaniyada 3-aprel, Amerikada 4-mart. Oyni so'z bilan yozish xavfsizroq.","Yangi so'zlar: deadline, exam, invitation, schedule, leap year, date of birth."]},{"id":"u6-l6","slug":"my-home","title":"My home","titleUz":"Mening uyim: xonalar va jihozlar","goal":"Uyingiz yoki kvartirangizni tasvirlaysiz: xonalar, jihozlar, qavat (I live in a flat on the fourth floor. There's a big sofa in the living room.). there is / there are, in / on va sanalmaydigan furniture ni to'g'ri ishlatasiz.","words":[{"en":"flat","uz":"kvartira","ipa":"flæt"},{"en":"balcony","uz":"balkon","ipa":"ˈbæl.kə.ni"},{"en":"wardrobe","uz":"kiyim javoni, shkaf","ipa":"ˈwɔː.drəʊb"},{"en":"curtain","uz":"parda","ipa":"ˈkɜː.tən"},{"en":"armchair","uz":"kreslo","ipa":"ˈɑːm.tʃeə"},{"en":"kettle","uz":"choynak (elektr)","ipa":"ˈket.əl"},{"en":"cooker","uz":"plita","ipa":"ˈkʊk.ə"},{"en":"mirror","uz":"oyna, ko'zgu","ipa":"ˈmɪr.ə"},{"en":"upstairs","uz":"yuqori qavatda, yuqoriga","ipa":"ʌpˈsteəz"},{"en":"furniture","uz":"mebel","ipa":"ˈfɜː.nɪ.tʃə"}],"summary":["house — hovli-uy, flat — kvartira, home — o'z uyim: at home, go home.","Xonalar in bilan (in the kitchen), lekin on the balcony, on the fourth floor.","Jihozlar: sofa, armchair, carpet, wardrobe, shelf (shelves), mirror, fridge, cooker, curtains.","furniture sanalmaydi: a lot of furniture, ❌ furnitures. cooker — plita, cook — oshpaz.","Tasvir: There is/are + nima + qayerda; upstairs / downstairs — predlogsiz."]},{"id":"u6-l7","slug":"in-town-asking-the-way","title":"In town: asking the way","titleUz":"Shaharda: yo'l so'rash va ko'rsatish","goal":"Shaharda muloyim yo'l so'raysiz (Excuse me, how do I get to…? Is there a pharmacy near here?) va yo'l ko'rsatasiz (Go straight on, take the second left, it's opposite the bank). Javobni tinglab tushunasiz.","words":[{"en":"pharmacy","uz":"dorixona","ipa":"ˈfɑː.mə.si"},{"en":"traffic lights","uz":"svetofor","ipa":"ˈtræf.ɪk laɪts"},{"en":"crossroads","uz":"chorraha","ipa":"ˈkrɒs.rəʊdz"},{"en":"corner","uz":"burchak, muyulish","ipa":"ˈkɔː.nə"},{"en":"roundabout","uz":"aylanma yo'l (halqa)","ipa":"ˈraʊnd.ə.baʊt"},{"en":"straight on","uz":"to'g'riga","ipa":"ˌstreɪt ˈɒn"},{"en":"turn","uz":"burilmoq","ipa":"tɜːn"},{"en":"cross","uz":"kesib o'tmoq","ipa":"krɒs"},{"en":"go past","uz":"yonidan o'tib ketmoq","ipa":"ɡəʊ ˈpɑːst"},{"en":"nearest","uz":"eng yaqin","ipa":"ˈnɪə.rɪst"}],"summary":["Savol: Excuse me, how do I get to…? / Is there a… near here? / Where's the nearest…?","Yo'l ko'rsatish (buyruq): Go straight on, turn left/right, take the second left, go past…, cross the road.","Joylashuv: on the left, opposite (❌ of), next to, between, on the corner, at the end of.","Masofa: It's not far. It's about ten minutes' walk.","Tushunmasangiz: Sorry, can you say that again, please? — va yo'lni qisqa takrorlab tekshiring."]},{"id":"u6-l10","slug":"lost-in-the-city-asking-the-way","title":"Lost in the city: asking the way","titleUz":"Shaharda adashdim: yo'l so'rash","goal":"Shaharda adashib qolsangiz, muloyim yo'l so'raysiz (Excuse me, how do I get to the station?) va javobni tushunasiz: Go straight on, turn left at the traffic lights.","words":[{"en":"lost","uz":"adashgan","ipa":"lɒst"},{"en":"opposite","uz":"qarshisida","ipa":"ˈɒp.ə.zɪt"},{"en":"block","uz":"kvartal","ipa":"blɒk"},{"en":"on foot","uz":"piyoda","ipa":"ɒn fʊt"},{"en":"square","uz":"maydon","ipa":"skweə"},{"en":"slowly","uz":"sekin","ipa":"ˈsləʊ.li"}],"summary":["So'rash: Excuse me, how do I get to…? Is there a … near here? Is it far?","Ko'rsatish: Go straight on. Turn left/right at the … Take the second left. It's opposite …","Tushunmasangiz: Can you say that again, please? Yangi so'zlar: lost, opposite, block, on foot, square, slowly."]},{"id":"u6-l14","slug":"listening-and-speaking-giving-directions","title":"Listening and speaking: giving directions","titleUz":"Tinglash va gapirish: yo'l ko'rsatish","goal":"Yo'l ko'rsatilganini tinglab tushunasiz va o'zingiz aniq yo'l ko'rsatasiz: Go straight on, turn left, it's next to the bank, opposite the pharmacy.","words":[{"en":"bridge","uz":"ko'prik","ipa":"brɪdʒ"},{"en":"entrance","uz":"kirish","ipa":"ˈen.trəns"},{"en":"exit","uz":"chiqish","ipa":"ˈek.sɪt"},{"en":"pavement","uz":"yo'lak, trotuar","ipa":"ˈpeɪv.mənt"},{"en":"tunnel","uz":"tunnel","ipa":"ˈtʌn.əl"},{"en":"at the end of","uz":"oxirida","ipa":"ət ði ˈend əv"}],"summary":["Yo'l ko'rsatish: Go straight on… Turn left/right at… Go past… Cross the bridge…","Joylashuv: next to, opposite, between, behind, in front of, at the end of. Yangi so'zlar: bridge, entrance, exit, pavement, tunnel.","Tushunmasangiz: Can you say that again, please?"]},{"id":"u6-l8","slug":"a-an-the-no-article","title":"a / an / the / no article","titleUz":"Artikllar: a / an / the yoki artiklsiz","goal":"Qachon a / an, qachon the, qachon artiklsiz gapirishni bilasiz: I saw a cat. The cat was black. I like cats. She's a doctor. The sun is hot. I go to work by bus. O'zbek tilida artikl yo'qligi sababli qilinadigan eng ko'p xatolardan qutulasiz.","words":[{"en":"the sun","uz":"quyosh","ipa":"ðə ˈsʌn"},{"en":"the moon","uz":"oy (osmondagi)","ipa":"ðə ˈmuːn"},{"en":"the sky","uz":"osmon","ipa":"ðə ˈskaɪ"},{"en":"the world","uz":"dunyo","ipa":"ðə ˈwɜːld"},{"en":"the internet","uz":"internet","ipa":"ði ˈɪn.tə.net"},{"en":"the city centre","uz":"shahar markazi","ipa":"ðə ˌsɪt.i ˈsen.tə"},{"en":"the same","uz":"bir xil, o'sha","ipa":"ðə ˈseɪm"},{"en":"the only","uz":"yagona","ipa":"ði ˈəʊn.li"},{"en":"by bus","uz":"avtobusda","ipa":"baɪ ˈbʌs"},{"en":"at work","uz":"ishda","ipa":"ət ˈwɜːk"}],"summary":["a / an — birinchi marta, \"bitta, qandaydir\"; kasb oldidan majburiy: I'm a student, She's an engineer.","the — ma'lum narsa (2-marta), yagona (the sun, the world), the biggest, the first, the same, shahardagi joylar (the station), cholg'ular.","Artiklsiz — umumiy ma'no (I like cats. Life is beautiful.), ismlar va ko'p davlatlar, tillar, sport, ovqatlar, by bus.","Iboralar: go to school / work / bed, at home, at work, go home — artiklsiz.","an — unli tovush oldidan: an hour, lekin a university."]},{"id":"u6-l13","slug":"the-or-no-article","title":"The or no article?","titleUz":"the yoki artiklsiz: aniq, yagona va umumiy narsalar","goal":"Gapda the kerakmi yoki artiklsizmi tez hal qilasiz: aniq va yagona narsa — the, umumiy ko'plik va sanalmaydigan ot — artiklsiz.","words":[{"en":"weather","uz":"ob-havo","ipa":"ˈweð.ə"},{"en":"news","uz":"yangiliklar","ipa":"njuːz"},{"en":"capital","uz":"poytaxt","ipa":"ˈkæp.ɪ.təl"},{"en":"airport","uz":"aeroport","ipa":"ˈeə.pɔːt"},{"en":"radio","uz":"radio","ipa":"ˈreɪ.di.əʊ"},{"en":"countryside","uz":"shahar tashqarisi, qishloq joy","ipa":"ˈkʌn.tri.saɪd"}],"summary":["Aniq, ikkalamiz biladigan narsa — the: the music in this café.","Umumiy fikrda ko'plik va sanalmaydigan ot artiklsiz: Dogs are friendly. Water is important.","Yagona narsalar: the weather, the news, the capital, the radio, the airport."]},{"id":"u6-l15","slug":"reading-and-writing-my-new-neighbourhood","title":"Reading and writing: my new neighbourhood","titleUz":"O'qish va yozish: yangi mahallam","goal":"Joy haqidagi qisqa matnlarni o'qib tushunasiz va o'z mahallangiz haqida 4–5 gapli tavsif yozasiz: I live in a quiet area. There's a park next to my house.","words":[{"en":"neighbourhood","uz":"mahalla","ipa":"ˈneɪ.bə.hʊd"},{"en":"crowded","uz":"gavjum, odam ko'p","ipa":"ˈkraʊ.dɪd"},{"en":"lively","uz":"jonli, quvnoq","ipa":"ˈlaɪv.li"},{"en":"local","uz":"mahalliy","ipa":"ˈləʊ.kəl"},{"en":"area","uz":"hudud, tuman","ipa":"ˈeə.ri.ə"},{"en":"playground","uz":"o'yin maydonchasi","ipa":"ˈpleɪ.ɡraʊnd"}],"summary":["Tavsif tartibi: qayerda yashaysiz → nima bor → odamlar → sizga yoqadimi?","There is — birlik, There are — ko'plik; sabab uchun because it's quiet.","Yangi so'zlar: neighbourhood, crowded, lively, local, area, playground."]},{"id":"u6-l11","slug":"people-and-places-final-review","title":"People and places: final review","titleUz":"Odamlar va joylar: yakuniy takror","goal":"Bo'lim bo'yicha yakuniy takror: tanishuv, odamlarni tasvirlash, xarakter, mine / yours / Whose?, tartib sonlar va sanalar, uy, yo'l so'rash va a / an / the.","words":[{"en":"describe","uz":"tasvirlamoq","ipa":"dɪˈskraɪb"},{"en":"twin","uz":"egizak","ipa":"twɪn"},{"en":"tidy","uz":"ozoda, tartibli","ipa":"ˈtaɪ.di"},{"en":"honest","uz":"halol, rostgo'y","ipa":"ˈɒn.ɪst"},{"en":"cheerful","uz":"quvnoq, xushchaqchaq","ipa":"ˈtʃɪə.fəl"}],"summary":["Tanishuv va tasvir: What does she look like? — She has…; xarakter — She's quite shy.","Egalik: my → mine, your → yours, savol: Whose…? Sana: the third of May.","Yo'l: How do I get to…? Go straight on, turn left. Artikl: a / an / the yoki hech narsa."]}]},{"id":"u7","n":7,"title":"Work & Free Time","titleUz":"Ish va bo'sh vaqt: yoqtirish, rejalar, takliflar","description":"Kasblar, like / love / hate + -ing, ravishlar, play / go / do, rejalar, would like, takliflar, soat va jadval.","canDo":["Nimani yoqtirishimni like/love/hate + -ing bilan aytaman","Sport va hobbilar haqida gapiraman","Rejalarimni va takliflarni (would like) bildiraman","How often / How long savollarini beraman"],"lessons":[{"id":"u7-l1","slug":"jobs-workplaces","title":"Jobs & workplaces","titleUz":"Kasblar va ish joylari","goal":"Kasb haqida so'raysiz va javob berasiz: What do you do? — I'm a chef. I work in a restaurant. Kasblar nomini, ish joylari bilan in / at / on / for predloglarini to'g'ri ishlatasiz va ishingiz haqida 4–5 gap aytib berasiz.","words":[{"en":"job","uz":"ish, kasb","ipa":"dʒɒb"},{"en":"chef","uz":"oshpaz (restoranda)","ipa":"ʃef"},{"en":"waiter","uz":"ofitsiant","ipa":"ˈweɪ.tə"},{"en":"shop assistant","uz":"do'kon sotuvchisi","ipa":"ˈʃɒp əˌsɪs.tənt"},{"en":"receptionist","uz":"administrator, qabulxona xodimi","ipa":"rɪˈsep.ʃən.ɪst"},{"en":"mechanic","uz":"mexanik, avtousta","ipa":"mɪˈkæn.ɪk"},{"en":"pilot","uz":"uchuvchi","ipa":"ˈpaɪ.lət"},{"en":"factory","uz":"zavod, fabrika","ipa":"ˈfæk.tər.i"},{"en":"uniform","uz":"forma, maxsus kiyim","ipa":"ˈjuː.nɪ.fɔːm"},{"en":"earn","uz":"pul topmoq, ishlab topmoq","ipa":"ɜːn"}],"summary":["Kasb haqida savol: What do you do? / What does she do? — What are you doing? emas!","Birlikdagi kasb oldida a / an shart: I'm a chef, she's an engineer.","Ish joyi: in an office / a hospital / a factory, at the airport / a school, on a farm, for + kompaniya, as + kasb.","job sanaladi (a new job), work sanalmaydi (a lot of work, go to work).","he / she bilan -s: She works, he earns, he wears a uniform; savolda — does … work?"]},{"id":"u7-l2","slug":"like-love-hate-ing","title":"like, love, hate + -ing","titleUz":"Yoqtirish: like, love, hate + -ing","goal":"Nimani yoqtirishingiz va yoqtirmasligingizni aniq darajada aytasiz: I love cooking. I don't mind ironing. I can't stand getting up early. Fe'lga -ing qo'shish imlosini va bo'sh vaqt haqidagi savollarni o'rganasiz.","words":[{"en":"enjoy","uz":"zavq olmoq, yoqtirmoq","ipa":"ɪnˈdʒɔɪ"},{"en":"don't mind","uz":"qarshi emasman, mayli","ipa":"dəʊnt ˈmaɪnd"},{"en":"can't stand","uz":"chiday olmaslik, umuman yoqtirmaslik","ipa":"kɑːnt ˈstænd"},{"en":"free time","uz":"bo'sh vaqt","ipa":"ˌfriː ˈtaɪm"},{"en":"shopping","uz":"xarid qilish","ipa":"ˈʃɒp.ɪŋ"},{"en":"gardening","uz":"bog'dorchilik","ipa":"ˈɡɑː.dən.ɪŋ"},{"en":"fishing","uz":"baliq ovi","ipa":"ˈfɪʃ.ɪŋ"},{"en":"chat","uz":"suhbatlashmoq, gaplashmoq","ipa":"tʃæt"},{"en":"relax","uz":"dam olmoq, hordiq chiqarmoq","ipa":"rɪˈlæks"},{"en":"take photos","uz":"suratga olmoq","ipa":"teɪk ˈfəʊ.təʊz"}],"summary":["Harakatni yoqtirish: like / love / enjoy / hate + fe'l-ing — I love cooking.","Shkala: love > really like / enjoy > like > don't mind > don't like > hate > can't stand.","enjoy, don't mind, can't stand dan keyin faqat -ing (❌ enjoy to).","Imlo: dance → dancing (e tushadi), swim → swimming (ikkilanadi), lie → lying.","❌ I am like… — like fe'l: I like…, She likes…, I don't like…, Does he like…?"]},{"id":"u7-l3","slug":"adverbs-quickly-well-hard","title":"Adverbs: quickly, well, hard","titleUz":"Ravishlar: quickly, well, hard","goal":"Ish qanday bajarilishini aytasiz: She works quickly. He speaks English well. They work hard. Sifatdan ravish yasashni (-ly), noto'g'ri ravishlarni (well, fast, hard, early, late) va ravishning gapdagi o'rnini o'rganasiz.","words":[{"en":"quickly","uz":"tez, tezda","ipa":"ˈkwɪk.li"},{"en":"slowly","uz":"sekin","ipa":"ˈsləʊ.li"},{"en":"carefully","uz":"ehtiyotkorlik bilan, diqqat bilan","ipa":"ˈkeə.fəl.i"},{"en":"quietly","uz":"jimgina, past ovozda","ipa":"ˈkwaɪ.ət.li"},{"en":"loudly","uz":"baland ovozda","ipa":"ˈlaʊd.li"},{"en":"badly","uz":"yomon","ipa":"ˈbæd.li"},{"en":"easily","uz":"osongina, oson","ipa":"ˈiː.zɪ.li"},{"en":"well","uz":"yaxshi (qanday qilib)","ipa":"wel"},{"en":"hard","uz":"qattiq, astoydil (ishlamoq)","ipa":"hɑːd"},{"en":"early","uz":"erta","ipa":"ˈɜː.li"}],"summary":["Sifat otni tasvirlaydi (a quick worker), ravish fe'lni (works quickly).","Ravish = sifat + -ly: slowly, carefully, easily, gently.","Noto'g'ri ravishlar: good → well, fast → fast, hard → hard, early, late o'zgarmaydi. hardly = deyarli ... emas!","Tartib: fe'l + ob'ekt + ravish — She speaks English well. (❌ speaks well English)","be dan keyin sifat: Your English is good. — fe'ldan keyin ravish: You speak English well."]},{"id":"u7-l4","slug":"sports-hobbies-play-go-do","title":"Sports & hobbies: play, go, do","titleUz":"Sport va hobbi: play, go, do","goal":"Sport va hobbi haqida to'g'ri fe'l bilan gapirasiz: play tennis, go swimming, do yoga. Musiqa asboblari bilan the, go to the gym va go swimming farqini, sport joylari va match, win so'zlarini o'rganasiz.","words":[{"en":"basketball","uz":"basketbol","ipa":"ˈbɑː.skɪt.bɔːl"},{"en":"volleyball","uz":"voleybol","ipa":"ˈvɒl.i.bɔːl"},{"en":"tennis","uz":"tennis","ipa":"ˈten.ɪs"},{"en":"cycling","uz":"velosipedda yurish","ipa":"ˈsaɪ.klɪŋ"},{"en":"hiking","uz":"tog'da piyoda sayohat","ipa":"ˈhaɪ.kɪŋ"},{"en":"yoga","uz":"yoga","ipa":"ˈjəʊ.ɡə"},{"en":"karate","uz":"karate","ipa":"kəˈrɑː.ti"},{"en":"gym","uz":"sport zal","ipa":"dʒɪm"},{"en":"match","uz":"o'yin, uchrashuv (sportda)","ipa":"mætʃ"},{"en":"win – won","uz":"yutmoq, g'olib bo'lmoq","ipa":"wɪn – wʌn"}],"summary":["play — to'p bilan va raqib bilan o'yinlar: play tennis, chess, volleyball.","go + -ing — go swimming, hiking, cycling, fishing (to siz!).","do — to'psiz va kurash turlari: do yoga, karate, judo, gymnastics, exercise.","Asbob oldida the: play the guitar; sport oldida yo'q: play football. Joy: go to the gym / pool.","win – won, lose – lost: We won the match."]},{"id":"u7-l9","slug":"at-a-party-hobbies-and-free-time","title":"At a party: hobbies and free time","titleUz":"Ziyofatda: hobbi va bo'sh vaqt","goal":"Ziyofatda yangi odam bilan tanishib, kasbi va hobbisi haqida suhbatlashasiz: What do you do? What do you like doing in your free time? How often do you go swimming? Javobda like / love / hate + -ing ishlatasiz.","words":[{"en":"cake","uz":"tort, pirog","ipa":"keɪk"},{"en":"present","uz":"sovg‘a","ipa":"ˈprez.ənt"},{"en":"balloon","uz":"shar","ipa":"bəˈluːn"},{"en":"popular","uz":"mashhur, ommabop","ipa":"ˈpɒp.jə.lər"},{"en":"favourite","uz":"sevimli","ipa":"ˈfeɪ.vər.ɪt"}],"summary":["Kasb: What do you do? — I'm a nurse. Hobbi: What do you like doing?","like / love / hate / enjoy + fe'l-ing: I love playing football.","Tez-tezlik: How often…? — Twice a week. Savolni qaytaring: And you?","Yangi so'zlar: favourite, cake, present, balloon, popular."]},{"id":"u7-l5","slug":"plans-present-continuous-for-future","title":"Plans: Present Continuous for future","titleUz":"Rejalar: Present Continuous kelasi zamon uchun","goal":"Aniq kelishilgan rejalaringiz haqida gapirasiz: I'm meeting Aziz tomorrow. We're flying to Istanbul on Friday. Savol bera olasiz: What are you doing tonight? Are you working on Saturday? va kundaligingizdagi haftani aytib berasiz.","words":[{"en":"tonight","uz":"bugun kechqurun","ipa":"təˈnaɪt"},{"en":"this evening","uz":"bugun kechqurun (shu oqshom)","ipa":"ðɪs ˈiːv.nɪŋ"},{"en":"available","uz":"bo'sh, vaqti bor","ipa":"əˈveɪ.lə.bəl"},{"en":"day off","uz":"dam olish kuni (ishdan ozod kun)","ipa":"ˌdeɪ ˈɒf"},{"en":"meeting","uz":"majlis, uchrashuv (ishda)","ipa":"ˈmiː.tɪŋ"},{"en":"dentist","uz":"tish shifokori","ipa":"ˈden.tɪst"},{"en":"diary","uz":"kundalik, rejalar daftari","ipa":"ˈdaɪə.ri"},{"en":"free","uz":"bo'sh (band emas)","ipa":"friː"},{"en":"nervous","uz":"hayajonlangan, xavotirli","ipa":"ˈnɜː.vəs"},{"en":"pick up","uz":"(mashinada) olib ketmoq, kutib olmoq","ipa":"ˌpɪk ˈʌp"}],"summary":["Present Continuous (am / is / are + -ing) + kelajak vaqti = kelishilgan reja: I'm meeting Aziz tomorrow.","Shaxsiy rejalar uchun odatda Present Simple emas: ❌ I go to Samarkand tomorrow. ✅ I'm going…","tonight, this evening, tomorrow, next week, the day after tomorrow — predlogsiz; on Friday, at six, in July.","Savollar: What are you doing tonight? Are you doing anything on Saturday? — No, I'm free. / Yes, I'm working."]},{"id":"u7-l13","slug":"now-or-plan-present-continuous","title":"Now or plan? Present Continuous","titleUz":"Hozir yoki reja? Present Continuous farqi","goal":"Present Continuous gapi hozir haqidami yoki reja haqidami — buni vaqt so'zlariga qarab aniqlaysiz: I'm working now. / I'm meeting Ali tomorrow.","words":[{"en":"right now","uz":"aynan hozir","ipa":"ˌraɪt ˈnaʊ"},{"en":"at the moment","uz":"hozir, shu paytda","ipa":"ət ðə ˈməʊ.mənt"},{"en":"next week","uz":"kelasi hafta","ipa":"nekst wiːk"},{"en":"next month","uz":"kelasi oy","ipa":"nekst mʌnθ"},{"en":"this weekend","uz":"bu hafta oxiri","ipa":"ðɪs ˌwiːkˈend"},{"en":"later","uz":"keyinroq","ipa":"ˈleɪ.tər"}],"summary":["Shakl bir xil: am / is / are + fe'l-ing.","Hozir: now, right now, at the moment. Reja: tomorrow, tonight, next week, this weekend.","Odat uchun Present Simple: I play tennis every Sunday.","Yangi so'zlar: right now, at the moment, next week, next month, this weekend, later."]},{"id":"u7-l6","slug":"would-like-invitations","title":"would like & invitations","titleUz":"would like, taklif qilish va javob berish","goal":"Odobli istak bildirasiz va taklif qilasiz: I'd like a coffee. Would you like to come to my party? Turli taklif iboralarini (How about…? Why don't we…? Let's…) ishlatasiz, taklifni qabul qilasiz (I'd love to!) yoki odobli rad etasiz (I'm afraid I can't.).","words":[{"en":"would like","uz":"xohlamoq (odobli)","ipa":"wʊd ˈlaɪk"},{"en":"invite","uz":"taklif qilmoq","ipa":"ɪnˈvaɪt"},{"en":"invitation","uz":"taklif, taklifnoma","ipa":"ˌɪn.vɪˈteɪ.ʃən"},{"en":"I'd love to","uz":"jon deb, juda xohlardim","ipa":"aɪd ˈlʌv tuː"},{"en":"sounds great","uz":"zo'r, ajoyib eshitiladi","ipa":"saʊndz ˈɡreɪt"},{"en":"How about…?","uz":"… -sak-chi?","ipa":"haʊ əˈbaʊt"},{"en":"Why don't we…?","uz":"Nega … -maylik? (taklif)","ipa":"waɪ dəʊnt wiː"},{"en":"Let's…","uz":"Keling, … -aylik","ipa":"lets"},{"en":"another time","uz":"boshqa safar","ipa":"əˈnʌð.ə taɪm"},{"en":"I'm afraid…","uz":"afsuski…","ipa":"aɪm əˈfreɪd"}],"summary":["would like = odobli want: I'd like + ot (a coffee), I'd like + to + fe'l (to book a table); -s yo'q.","Do you like…? — umuman (Yes, I do.); Would you like…? — taklif (Yes, please. / I'd love to!).","Taklif: Would you like to…? / Do you want to…? / How about + -ing? / Why don't we + fe'l? / Let's + fe'l.","Qabul: I'd love to! That sounds great! Rad: I'm afraid I can't. I'm working… / Maybe another time."]},{"id":"u7-l12","slug":"invitations-accepting-and-declining","title":"Invitations: accepting and declining","titleUz":"Takliflar: qabul qilish va muloyim rad etish","goal":"Taklifni ingliz tilida odobli qabul qilasiz yoki rad etasiz: Would you like to…? Let's… Shall we…? Why don't we…? — I'd love to! / Sorry, I can't, but…","words":[{"en":"accept","uz":"qabul qilmoq","ipa":"əkˈsept"},{"en":"decline","uz":"rad etmoq","ipa":"dɪˈklaɪn"},{"en":"polite","uz":"odobli","ipa":"pəˈlaɪt"},{"en":"reason","uz":"sabab","ipa":"ˈriː.zən"},{"en":"perhaps","uz":"balki","ipa":"pəˈhæps"},{"en":"join","uz":"qo'shilmoq","ipa":"dʒɔɪn"}],"summary":["Taklif: Would you like to…? / Let's… / Shall we…? / Why don't we…?","Qabul: I'd love to! Good idea! Yes, let's!","Rad: Sorry, I can't. + sabab + Maybe another time?","Yangi so'zlar: accept, decline, polite, reason, perhaps, join."]},{"id":"u7-l10","slug":"making-plans-with-a-friend","title":"Making plans with a friend","titleUz":"Do'st bilan reja tuzish","goal":"Do'stingizni taklif qilasiz, taklifni qabul qilasiz yoki muloyim rad etasiz va vaqtni kelishasiz: Would you like to go to the cinema? I'm meeting Aziz at six. Sorry, I can't.","words":[{"en":"plan","uz":"reja","ipa":"plæn"},{"en":"popcorn","uz":"popkorn","ipa":"ˈpɒp.kɔːn"},{"en":"seat","uz":"o‘rindiq, joy","ipa":"siːt"},{"en":"screen","uz":"ekran","ipa":"skriːn"},{"en":"ticket","uz":"chipta","ipa":"ˈtɪk.ɪt"}],"summary":["Reja: am / is / are + fe'l-ing — I'm meeting Aziz at six.","Taklif: Would you like to…? Qabul: I'd love to! Rad: I'm afraid I can't.","Vaqt: Let's meet at half past six. How about Sunday?","Yangi so'zlar: plan, ticket, popcorn, seat, screen."]},{"id":"u7-l7","slug":"time-timetables","title":"Time & timetables","titleUz":"Soat, jadval: from… to, until, before, after","goal":"Har qanday vaqtni aytasiz (ten to nine, twenty-five past six, 18:30), jadvalni o'qiysiz va so'raysiz (What time does the train leave?), ish va dam olish vaqtini from… to, until, before, after bilan aniq ifodalaysiz.","words":[{"en":"timetable","uz":"jadval (poyezd, dars)","ipa":"ˈtaɪmˌteɪ.bəl"},{"en":"a.m.","uz":"ertalab, tushgacha (00:00–12:00)","ipa":"ˌeɪˈem"},{"en":"p.m.","uz":"tushdan keyin, kechqurun (12:00–24:00)","ipa":"ˌpiːˈem"},{"en":"midday","uz":"tush, soat 12","ipa":"ˌmɪdˈdeɪ"},{"en":"midnight","uz":"yarim tun","ipa":"ˈmɪd.naɪt"},{"en":"until","uz":"…gacha","ipa":"ənˈtɪl"},{"en":"before","uz":"…dan oldin","ipa":"bɪˈfɔː"},{"en":"after","uz":"…dan keyin","ipa":"ˈɑːf.tə"},{"en":"leave","uz":"jo'nab ketmoq, chiqib ketmoq","ipa":"liːv"},{"en":"break","uz":"tanaffus","ipa":"breɪk"}],"summary":["past — o'tdi (ten past eight = 8:10), to — keyingi soatga kam (ten to nine = 8:50). Oddiy usul: eight fifty.","a.m. — tushgacha, p.m. — tushdan keyin; midday — 12:00, midnight — 00:00.","Jadvallar — Present Simple: The train leaves at 7:28. What time does it arrive?","from … to / until, yolg'iz until (…gacha); before / after + ot / -ing: after work, before going to bed."]},{"id":"u7-l8","slug":"questions-how-often-how-long","title":"Questions: How often? How long?…","titleUz":"Savollar: How often, How long, How far…","goal":"How + sifat/ravish savollarini tuzasiz va javob berasiz: How often do you go to the gym? — Three times a week. How long does it take? — It takes 20 minutes. How far is it? — It's 5 kilometres away.","words":[{"en":"how long","uz":"qancha vaqt","ipa":"haʊ ˈlɒŋ"},{"en":"how far","uz":"qancha uzoq (masofa)","ipa":"haʊ ˈfɑː"},{"en":"it takes","uz":"(vaqt) oladi, ketadi","ipa":"ɪt ˈteɪks"},{"en":"kilometre","uz":"kilometr","ipa":"ˈkɪl.əˌmiː.tə"},{"en":"hour","uz":"soat (60 daqiqa)","ipa":"ˈaʊ.ə"},{"en":"journey","uz":"yo'l, safar (bir joydan boshqasiga)","ipa":"ˈdʒɜː.ni"},{"en":"on foot","uz":"piyoda","ipa":"ɒn ˈfʊt"},{"en":"three times","uz":"uch marta","ipa":"θriː ˈtaɪmz"},{"en":"how tall","uz":"bo'yi qancha","ipa":"haʊ ˈtɔːl"},{"en":"away","uz":"narida, uzoqlikda","ipa":"əˈweɪ"}],"summary":["How + sifat/ravish + do/does/is…?: How often, How long, How far, How tall, How fast, How well.","How often? — once / twice / three times a week / month / year, gap oxirida.","How long? — vaqt: It takes (me) + vaqt + to + fe'l; It's two hours long; for a week.","How far? — masofa: It's 5 kilometres away. ❌ How far is? — it shart."]},{"id":"u7-l14","slug":"listening-and-speaking-my-job-and-my-free-time","title":"Listening and speaking: my job and my free time","titleUz":"Tinglash va gapirish: ishim va bo'sh vaqtim","goal":"Ikki suhbatni tinglab, kasb va bo'sh vaqt haqidagi asosiy ma'lumotni topasiz va o'zingiz haqingizda ish va hobbilaringizni aytib berasiz.","words":[{"en":"manager","uz":"menejer, boshliq","ipa":"ˈmæn.ɪ.dʒər"},{"en":"perfect","uz":"ajoyib, juda yaxshi","ipa":"ˈpɜː.fekt"},{"en":"friendly","uz":"mehribon, samimiy","ipa":"ˈfrend.li"},{"en":"spare time","uz":"bo'sh vaqt","ipa":"speə taɪm"},{"en":"part-time","uz":"yarim kunlik","ipa":"ˌpɑːt ˈtaɪm"}],"summary":["Tinglaganda avval kim, qaysi kasb, hobbi nima ekanini toping.","Kasb: I'm an engineer. Hobbi: I love cycling. Tez-tezlik: twice a week.","Taklif va javob: Shall we…? — I'd love to, but I can't.","Yangi so'zlar: manager, friendly, spare time, part-time, perfect."]},{"id":"u7-l15","slug":"reading-and-writing-a-profile-of-me","title":"Reading and writing: a profile of me","titleUz":"O'qish va yozish: o'zim haqimda profil","goal":"Odamlarning ishi va hobbisi haqidagi qisqa profillarni o'qib tushunasiz va o'zingiz haqingizda 5–6 gapdan iborat profil yozasiz.","words":[{"en":"profile","uz":"profil, qisqa tavsif","ipa":"ˈprəʊ.faɪl"},{"en":"company","uz":"kompaniya","ipa":"ˈkʌm.pə.ni"},{"en":"photography","uz":"suratga olish","ipa":"fəˈtɒɡ.rə.fi"},{"en":"both","uz":"ikkalasi ham","ipa":"bəʊθ"},{"en":"full-time","uz":"to'liq kunlik","ipa":"ˌfʊl ˈtaɪm"},{"en":"bookshop","uz":"kitob do'koni","ipa":"ˈbʊk.ʃɒp"}],"summary":["Profil tuzilishi: ism va kasb → ish joyi → hobbi → reja.","also va sometimes odatda fe'ldan oldin: I also work. I sometimes swim.","Hobbi: like / love + fe'l-ing. Reja: I'm + fe'l-ing + vaqt.","Yangi so'zlar: profile, bookshop, both, company, photography, full-time."]},{"id":"u7-l11","slug":"work-and-free-time-final-review","title":"Work and free time: final review","titleUz":"Ish va bo'sh vaqt: yakuniy takror","goal":"7-bo'limni takrorlaysiz: kasblar, like + -ing, ravishlar, play / go / do, rejalar, would like, soat va jadval, How often / How long. Hammasini bitta matnda ko'rasiz.","words":[{"en":"colleague","uz":"hamkasb","ipa":"ˈkɒl.iːɡ"},{"en":"busy","uz":"band","ipa":"ˈbɪz.i"},{"en":"enough","uz":"yetarli","ipa":"ɪˈnʌf"},{"en":"finish","uz":"tugatmoq, tugamoq","ipa":"ˈfɪn.ɪʃ"}],"summary":["like / love / hate / enjoy + -ing; ravish fe'ldan keyin: works hard, speaks well.","play jamoa o'yini, go + -ing, do yakka mashq; reja — am / is / are + -ing.","Would you like to…? — I'd love to. / I'm afraid I can't.","How often…? — twice a week. How long…? — two hours. Vaqt: from… to, until, before, after."]}]},{"id":"u8","n":8,"title":"Food & Shopping","titleUz":"Ovqat va xarid: miqdor, narx, buyurtma","description":"Ovqat, idishlar (a cup of…), a few / a little, narx va pul, kafeda buyurtma, kiyim do'koni, retsept, should, qiyoslash.","canDo":["Kafe va do'konda buyurtma beraman","Miqdorni (a lot of, a little, a few) to'g'ri ishlataman","Narx va pulni so'rayman va aytaman","Retsept va maslahat (should) beraman"],"lessons":[{"id":"u8-l1","slug":"food-containers-a-cup-of","title":"Food & containers: a cup of…","titleUz":"Ovqat va o'lchovlar: a cup of, a bottle of…","goal":"Sanalmaydigan ovqat va ichimliklarni idish yoki bo'lak bilan aytasiz: a cup of tea, a bowl of soup, a loaf of bread, a slice of cake, a bunch of grapes — va ko'plikda ham to'g'ri ishlatasiz: two cartons of milk.","words":[{"en":"a bowl of","uz":"bir kosa …","ipa":"ə ˈbəʊl əv"},{"en":"a plate of","uz":"bir tarelka (likopcha) …","ipa":"ə ˈpleɪt əv"},{"en":"a jar of","uz":"bir (shisha) banka …","ipa":"ə ˈdʒɑː əv"},{"en":"a can of","uz":"bir (temir) banka …","ipa":"ə ˈkæn əv"},{"en":"a carton of","uz":"bir karton quti …","ipa":"ə ˈkɑː.tən əv"},{"en":"a loaf of","uz":"bir buxanka (butun non)","ipa":"ə ˈləʊf əv"},{"en":"a slice of","uz":"bir tilim, yupqa bo'lak …","ipa":"ə ˈslaɪs əv"},{"en":"a bar of","uz":"bir plitka …","ipa":"ə ˈbɑː əv"},{"en":"a bag of","uz":"bir xalta / paket …","ipa":"ə ˈbæɡ əv"},{"en":"a bunch of","uz":"bir shingil / bosh / dasta …","ipa":"ə ˈbʌntʃ əv"}],"summary":["Sanalmaydigan ovqat uchun: a / two + idish + of + ovqat — a cup of tea, a bowl of soup.","Ko'plik -s idishga qo'shiladi: two cups of tea, two loaves of bread (loaf → loaves).","Idishlar: cup (issiq), glass (sovuq), bowl (kosa), plate (tarelka), bottle, can, jar, carton, bag, packet, box.","Bo'laklar: a loaf / slice / piece of bread, a bar of chocolate, a bunch of grapes.","Talaffuz: of kuchsiz — \"əv\": a cup of tea = \"ə kapəv ti:\"."]},{"id":"u8-l2","slug":"a-lot-of-a-few-a-little-no","title":"a lot of, a few, a little, no","titleUz":"Miqdor: a lot of, a few, a little, no","goal":"Miqdorni aniq aytasiz: a lot of (ko'p), a few / a little (bir nechta / ozgina), not many / not much (ko'p emas) va no (umuman yo'q) — qaysi biri sanaladigan, qaysi biri sanalmaydigan ot bilan kelishini adashtirmaysiz.","words":[{"en":"onion","uz":"piyoz","ipa":"ˈʌn.jən"},{"en":"carrot","uz":"sabzi","ipa":"ˈkær.ət"},{"en":"potato","uz":"kartoshka","ipa":"pəˈteɪ.təʊ"},{"en":"tomato","uz":"pomidor","ipa":"təˈmɑː.təʊ"},{"en":"nuts","uz":"yong'oq (har xil)","ipa":"nʌts"},{"en":"pepper","uz":"murch; qalampir","ipa":"ˈpep.ə"},{"en":"cupboard","uz":"shkaf (oshxona javoni)","ipa":"ˈkʌb.əd"},{"en":"empty","uz":"bo'sh","ipa":"ˈemp.ti"},{"en":"enough","uz":"yetarli","ipa":"ɪˈnʌf"},{"en":"only","uz":"faqat, bor-yo'g'i","ipa":"ˈəʊn.li"}],"summary":["a lot of / lots of — ko'p, ikkala tur bilan: a lot of eggs, a lot of milk.","a few + sanaladigan ko'plik (a few eggs), a little + sanalmaydigan (a little milk, a little time).","not many (sanaladigan) / not much (sanalmaydigan) — ko'p emas.","no + ot = not any: There's no milk. Bitta gapda bitta inkor — There isn't no… ❌."]},{"id":"u8-l12","slug":"how-much-how-many-food-questions","title":"How much? How many? Food questions","titleUz":"How much? How many? Ovqat haqida savollar","goal":"Ovqat haqida miqdor savollarini berasiz: How many eggs…? / How much flour…? — va qisqa javob qaytarasiz: A lot. A few. A little. Not many. Not much. None.","words":[{"en":"flour","uz":"un","ipa":"ˈflaʊ.ər"},{"en":"butter","uz":"sariyog'","ipa":"ˈbʌt.ər"},{"en":"cheese","uz":"pishloq","ipa":"tʃiːz"},{"en":"yoghurt","uz":"qatiq, yogurt","ipa":"ˈjɒɡ.ət"},{"en":"oil","uz":"yog' (o'simlik yog'i)","ipa":"ɔɪl"},{"en":"lemon","uz":"limon","ipa":"ˈlem.ən"},{"en":"honey","uz":"asal","ipa":"ˈhʌn.i"}],"summary":["Sanaladigan ko'plik ot bilan How many: How many eggs…?","Sanalmaydigan ot bilan How much: How much flour…?","Qisqa javoblar: a lot, a few / a little, not many / not much, none.","How much is…? — narx; How much milk is there? — miqdor.","Yangi so'zlar: flour, butter, cheese, yoghurt, oil, lemon, honey."]},{"id":"u8-l3","slug":"money-prices","title":"Money & prices","titleUz":"Pul, narx va How much?","goal":"Narxni so'raysiz va aytasiz: How much is this? / How much are these? / How much does it cost? Katta summalarni (fifteen thousand soums, £3.50) to'g'ri o'qiysiz va to'lov iboralarini ishlatasiz: pay by card, pay in cash, change, receipt.","words":[{"en":"cost","uz":"turmoq (narxi …)","ipa":"kɒst"},{"en":"pay","uz":"to'lamoq","ipa":"peɪ"},{"en":"cash","uz":"naqd pul","ipa":"kæʃ"},{"en":"card","uz":"(bank) karta","ipa":"kɑːd"},{"en":"change","uz":"qaytim; mayda pul","ipa":"tʃeɪndʒ"},{"en":"receipt","uz":"chek","ipa":"rɪˈsiːt"},{"en":"discount","uz":"chegirma","ipa":"ˈdɪs.kaʊnt"},{"en":"coin","uz":"tanga","ipa":"kɔɪn"},{"en":"note","uz":"qog'oz pul (kupyura)","ipa":"nəʊt"},{"en":"thousand","uz":"ming","ipa":"ˈθaʊ.zənd"}],"summary":["Birlik: How much is it? / How much does it cost? — It costs…; ko'plik: How much are they? / do they cost?","hundred, thousand son bilan -s olmaydi: fifteen thousand soums; £3.50 = three pounds fifty.","To'lov: pay by card, pay in cash, pay for something; change = qaytim, receipt = chek (\"risi:t\").","Savdolashish: It's a bit expensive. Can you give me a discount?"]},{"id":"u8-l9","slug":"at-the-market-quantities-and-prices","title":"At the market: quantities and prices","titleUz":"Bozorda: miqdor va narx","goal":"Bozorda kerakli miqdorni aytasiz (a kilo of apples, a few tomatoes, a little cheese) va narxni so'raysiz: How much is it? / How much are they?","words":[{"en":"kilo","uz":"kilogramm","ipa":"ˈkiː.ləʊ"},{"en":"price","uz":"narx","ipa":"praɪs"},{"en":"stall","uz":"peshtaxta, rasta","ipa":"stɔːl"},{"en":"weigh","uz":"tortmoq, og'irligini o'lchamoq","ipa":"weɪ"}],"summary":["Miqdor: a kilo of…, a few + sanaladigan, a little + sanalmaydigan.","Narx: How much is it? (birlik), How much are they? (ko'plik).","Yangi so'zlar: kilo, price, stall, weigh."]},{"id":"u8-l4","slug":"at-the-cafe","title":"At the café","titleUz":"Kafeda: buyurtma berish","goal":"Kafeda xushmuomala buyurtma berasiz (I'd like…, Could I have…?, I'll have…), ofitsiantning savollarini tushunib javob berasiz (Are you ready to order? Eat in or take away? Anything else?) va hisobni so'raysiz: Can we have the bill, please?","words":[{"en":"menu","uz":"menyu","ipa":"ˈmen.juː"},{"en":"starter","uz":"birinchi (boshlang'ich) taom","ipa":"ˈstɑː.tə"},{"en":"order","uz":"buyurtma bermoq; buyurtma","ipa":"ˈɔː.də"},{"en":"bill","uz":"hisob (to'lov qog'ozi)","ipa":"bɪl"},{"en":"main course","uz":"asosiy taom","ipa":"ˌmeɪn ˈkɔːs"},{"en":"dessert","uz":"shirinlik (ovqatdan keyin)","ipa":"dɪˈzɜːt"},{"en":"take away","uz":"olib ketish uchun","ipa":"ˌteɪk əˈweɪ"},{"en":"sparkling","uz":"gazli (suv)","ipa":"ˈspɑː.klɪŋ"},{"en":"tip","uz":"choychaqa","ipa":"tɪp"},{"en":"delicious","uz":"juda mazali","ipa":"dɪˈlɪʃ.əs"}],"summary":["Buyurtma: I'd like…, please. / Could I have…? / I'll have… — Give me… qo'pol eshitiladi.","Ofitsiant savollari: Are you ready to order? Anything else? Still or sparkling? Eat in or take away?","Kafeda ichimliklar sanaladi: two coffees, three waters (= cups / glasses of…).","Hisob: Excuse me! Can we have the bill, please? · Let's split the bill. / It's on me."]},{"id":"u8-l5","slug":"shopping-for-clothes","title":"Shopping for clothes","titleUz":"Kiyim do'konida: o'lcham, rang, too big","goal":"Kiyim do'konida gaplashasiz: What size are you? Can I try it on? Have you got this in blue? Muammoni aytasiz: It's too big. / It isn't long enough. / It doesn't fit. va maqtaysiz: It suits you!","words":[{"en":"trousers","uz":"shim","ipa":"ˈtraʊ.zəz"},{"en":"pocket","uz":"cho'ntak","ipa":"ˈpɒk.ɪt"},{"en":"a pair of","uz":"bir juft …","ipa":"ə ˈpeə əv"},{"en":"size","uz":"o'lcham","ipa":"saɪz"},{"en":"try on","uz":"kiyib ko'rmoq","ipa":"ˌtraɪ ˈɒn"},{"en":"fitting room","uz":"kiyinish (kiyib ko'rish) xonasi","ipa":"ˈfɪt.ɪŋ ˌruːm"},{"en":"fit","uz":"(o'lchami) to'g'ri kelmoq","ipa":"fɪt"},{"en":"suit","uz":"yarashmoq; kostyum","ipa":"suːt"},{"en":"tight","uz":"tor, qisib turadigan","ipa":"taɪt"},{"en":"loose","uz":"keng, bo'sh (kiyim)","ipa":"luːs"}],"summary":["trousers, jeans, shorts, glasses — doim ko'plik: These jeans are…, I like them; bitta = a pair of jeans.","Do'konda: What size are you? Can I try it on? Have you got this in blue? Where's the fitting room?","too + sifat (ortiqcha, muammo) / not + sifat + enough (kam): too small = not big enough.","fit = o'lchami to'g'ri kelmoq; suit = yarashmoq: It fits, but it doesn't suit me."]},{"id":"u8-l6","slug":"recipes-first-then-finally","title":"Recipes: first, then, finally","titleUz":"Retsept: first, then, after that, finally","goal":"Oddiy retseptni o'qiysiz va o'zingiz tushuntirasiz: buyruq gaplar (Chop the onions. Don't add oil.), oshxona fe'llari (chop, peel, boil, fry, mix, stir…) va ketma-ketlik so'zlari: First, Then, After that, Finally.","words":[{"en":"chop","uz":"mayda to'g'ramoq","ipa":"tʃɒp"},{"en":"peel","uz":"po'stini archmoq","ipa":"piːl"},{"en":"boil","uz":"qaynatmoq; qaynamoq","ipa":"bɔɪl"},{"en":"fry","uz":"qovurmoq","ipa":"fraɪ"},{"en":"bake","uz":"(duxovkada) pishirmoq","ipa":"beɪk"},{"en":"mix","uz":"aralashtirmoq","ipa":"mɪks"},{"en":"stir","uz":"(qoshiq bilan) aylantirmoq","ipa":"stɜː"},{"en":"add","uz":"qo'shmoq","ipa":"æd"},{"en":"pour","uz":"quymoq","ipa":"pɔː"},{"en":"pan","uz":"tova; kastryulka","ipa":"pæn"}],"summary":["Retseptda buyruq gap: fe'l + … — Chop the onions. Inkor: Don't + fe'l — Don't add oil.","Fe'llar: wash, peel, chop, boil, fry, bake, mix, stir, add, pour; umumiy — cook.","Tartib: First, → Then → Next, → After that, → Finally, (At last emas!).","Vaqt: for ten minutes (davomida), until golden (… bo'lguncha)."]},{"id":"u8-l10","slug":"planning-a-dinner-shopping-list-and-recipe","title":"Planning a dinner: shopping list and recipe","titleUz":"Kechki ovqat rejasi: ro'yxat va retsept","goal":"Kechki ovqatga xaridlar ro'yxatini tuzasiz (We need…, We don't need…), retseptni first, then, finally bilan aytasiz va maslahat berasiz: You should / shouldn't…","words":[{"en":"list","uz":"ro'yxat","ipa":"lɪst"},{"en":"guest","uz":"mehmon","ipa":"ɡest"},{"en":"ingredient","uz":"masalliq, tarkibiy qism","ipa":"ɪnˈɡriː.di.ənt"},{"en":"serve","uz":"(ovqat) tortmoq","ipa":"sɜːv"}],"summary":["Ro'yxat: We need…, We don't need any…","Retsept: First, … Then … Finally, …","Maslahat: You should / shouldn't + oddiy fe'l.","Yangi so'zlar: list, guest, ingredient, serve."]},{"id":"u8-l7","slug":"healthy-habits-should-shouldnt","title":"Healthy habits: should / shouldn't","titleUz":"Sog'lom odatlar: should / shouldn't","goal":"Maslahat berasiz va so'raysiz: You should eat more fruit. You shouldn't skip breakfast. What should I do? — I think you should… Sog'lom va zararli odatlar haqida gapirasiz.","words":[{"en":"healthy","uz":"sog'lom, foydali","ipa":"ˈhel.θi"},{"en":"junk food","uz":"zararli tez ovqat (fast food, chips…)","ipa":"ˈdʒʌŋk ˌfuːd"},{"en":"habit","uz":"odat","ipa":"ˈhæb.ɪt"},{"en":"skip","uz":"tashlab ketmoq, o'tkazib yubormoq","ipa":"skɪp"},{"en":"exercise","uz":"jismoniy mashq; mashq qilmoq","ipa":"ˈek.sə.saɪz"},{"en":"diet","uz":"ovqatlanish tartibi; parhez","ipa":"ˈdaɪ.ət"},{"en":"fresh","uz":"yangi, toza (uzilgan, pishgan)","ipa":"freʃ"},{"en":"fried","uz":"qovurilgan","ipa":"fraɪd"},{"en":"sweets","uz":"shirinliklar, konfetlar","ipa":"swiːts"},{"en":"stay up late","uz":"kechgacha uxlamay o'tirmoq","ipa":"ˌsteɪ ʌp ˈleɪt"}],"summary":["should + fe'lning o'zi — maslahat: You should eat more fruit. (to yo'q, -s yo'q).","Inkor: shouldn't — You shouldn't skip breakfast. Savol: Should I…? / What should I do? — Yes, you should. / No, you shouldn't.","Yumshoq maslahat: I think you should… / I don't think you should… / Maybe you should…","Talaffuz: should = \"shud\" (l o'qilmaydi); should va shouldn't ni n orqali farqlang."]},{"id":"u8-l8","slug":"comparing-better-the-best-as-as","title":"Comparing: better, the best, as… as","titleUz":"Qiyoslash: better, the best, as… as","goal":"Ovqat, narx va joylarni chuqurroq qiyoslaysiz: much cheaper, a bit spicier than me, tenglik va farq: as tasty as / not as fresh as, eng zo'ri: the best plov in town. Ta'm sifatlarini (sweet, sour, salty, spicy, juicy…) bilasiz.","words":[{"en":"tasty","uz":"mazali","ipa":"ˈteɪ.sti"},{"en":"sweet","uz":"shirin","ipa":"swiːt"},{"en":"sour","uz":"nordon","ipa":"ˈsaʊ.ə"},{"en":"salty","uz":"sho'r","ipa":"ˈsɔːl.ti"},{"en":"bitter","uz":"taxir, achchiq (qahvadek)","ipa":"ˈbɪt.ə"},{"en":"spicy","uz":"achchiq (qalampirli)","ipa":"ˈspaɪ.si"},{"en":"juicy","uz":"sersuv, shirali","ipa":"ˈdʒuː.si"},{"en":"ripe","uz":"pishgan (meva)","ipa":"raɪp"},{"en":"crispy","uz":"qarsildoq","ipa":"ˈkrɪs.pi"},{"en":"soft","uz":"yumshoq","ipa":"sɒft"}],"summary":["Imlo: tasty → tastier, hot → hotter, fresh → fresher; uzun: more delicious; istisno: better / the best, worse / the worst.","Farq darajasi: much / a lot / a bit + qiyosiy — much cheaper (very cheaper ❌); than me.","Tenglik: as + sifat + as — as soft as; farq: not as … as — Cola isn't as healthy as juice.","Orttirma: the best … in (joy) / of (guruh): the best plov in Tashkent, the busiest day of the week.","Ta'mlar: sweet, sour, salty, bitter, spicy; sifatlar: juicy, ripe, crispy, soft, tasty."]},{"id":"u8-l13","slug":"as-as-and-the-same-as","title":"as … as and the same as","titleUz":"as … as va the same as: tenglashtirish","goal":"Ikki narsani tenglashtirasiz: as cheap as, the same price as, the same size as — va farqni aytasiz: different from, not the same as. Narx, o'lcham va ovqat haqida gapirganda ishlatasiz.","words":[{"en":"same","uz":"bir xil, o'sha","ipa":"seɪm"},{"en":"different","uz":"boshqacha, farqli","ipa":"ˈdɪf.ər.ənt"},{"en":"similar","uz":"o'xshash","ipa":"ˈsɪm.ɪ.lər"},{"en":"brand","uz":"marka, brend","ipa":"brænd"},{"en":"heavy","uz":"og'ir","ipa":"ˈhev.i"},{"en":"fair","uz":"adolatli, o'rtacha (narx)","ipa":"feə"}],"summary":["Tenglik: as + sifat + as (as cheap as) yoki the same + ot + as (the same price as).","Farq: different from yoki not the same as.","as … as ichida sifat o'zgarmaydi; the same da the tushmaydi.","Yangi so'zlar: same, different, similar, brand, heavy, fair."]},{"id":"u8-l14","slug":"listening-and-speaking-ordering-a-meal","title":"Listening and speaking: ordering a meal","titleUz":"Tinglash va gapirish: ovqat buyurtma qilish","goal":"Restoran suhbatini tinglab, nima buyurtma qilingani va maxsus talablarni topasiz, o'zingiz esa stol band qilib, ovqat tanlab, muloyim buyurtma berasiz.","words":[{"en":"waiter","uz":"ofitsiant","ipa":"ˈweɪ.tər"},{"en":"recommend","uz":"tavsiya qilmoq","ipa":"ˌrek.əˈmend"},{"en":"vegetarian","uz":"vegetarian (go'sht yemaydigan)","ipa":"ˌvedʒ.ɪˈteə.ri.ən"},{"en":"allergic","uz":"allergik","ipa":"əˈlɜː.dʒɪk"},{"en":"special","uz":"maxsus taom (bugungi)","ipa":"ˈspeʃ.əl"},{"en":"book a table","uz":"stol band qilmoq","ipa":"bʊk ə ˈteɪ.bəl"}],"summary":["Stol band qilish: I'd like to book a table for two.","Tavsiya so'rash: What do you recommend?; maxsus talab: I'm vegetarian. I'm allergic to nuts.","Buyurtma: I'd like… / I'll have… / Could I have…, please? — Give me emas.","Yangi so'zlar: waiter, recommend, vegetarian, allergic, special, book a table."]},{"id":"u8-l15","slug":"reading-and-writing-a-menu-and-a-shopping-list","title":"Reading and writing: a menu and a shopping list","titleUz":"O'qish va yozish: menyu va xarid ro'yxati","goal":"Menyu va retseptni o'qib kerakli ma'lumotni (narx, masalliq, tartib) topasiz va o'zingiz xarid ro'yxati hamda qisqa buyurtma xati yozasiz.","words":[{"en":"recipe","uz":"retsept","ipa":"ˈres.ɪ.pi"},{"en":"grilled","uz":"panjarada pishirilgan","ipa":"ɡrɪld"},{"en":"snack","uz":"yengil taom, gazak","ipa":"snæk"},{"en":"sauce","uz":"sous","ipa":"sɔːs"},{"en":"extra","uz":"qo'shimcha","ipa":"ˈek.strə"},{"en":"served with","uz":"... bilan beriladi","ipa":"sɜːvd wɪð"}],"summary":["Menyuda avval narx, nima bilan beriladi (served with) va qo'shimcha (extra) ni qidiring.","Retseptda tartib: First, … Then … After that … Finally, …","Ro'yxat: a kilo of flour, a bottle of oil, 6 eggs.","Buyurtma xati: Hello, I'd like to order… please. Thank you.","Yangi so'zlar: recipe, grilled, snack, sauce, extra, served with."]},{"id":"u8-l11","slug":"food-and-shopping-final-review","title":"Food and shopping: final review","titleUz":"Ovqat va xarid: yakuniy takror","goal":"8-bo'lim mavzularini takrorlaysiz: idish va o'lchovlar, miqdor so'zlari, narx, kafe, kiyim, retsept, should, qiyoslash.","words":[{"en":"bargain","uz":"arzon xarid","ipa":"ˈbɑː.ɡɪn"},{"en":"customer","uz":"xaridor, mijoz","ipa":"ˈkʌs.tə.mər"},{"en":"offer","uz":"taklif qilmoq","ipa":"ˈɒf.ər"}],"summary":["Miqdor: a kilo of, a bottle of, a few + ko'plik, a little + sanalmaydigan.","Narx va buyurtma: How much is/are…? Could I have…? Can I pay by card?","Retsept va maslahat: First, then, finally; should / shouldn't + oddiy fe'l.","Qiyoslash: better than, the best, as … as."]}]},{"id":"u9","n":9,"title":"Stories from the Past","titleUz":"O'tmishdan hikoyalar: Past Simple chuqurroq","description":"Past Simple chuqurroq: ago / last, yangi noto'g'ri fe'llar, Wh-savollar, there was, could, tarjimai hol, hikoya qilish.","canDo":["O'tmishdagi voqealarni hikoya qilaman","Wh-savollarni o'tgan zamonda beraman","Hayot yo'lim haqida gapiraman","Gaplarni and, but, so, because bilan bog'layman"],"lessons":[{"id":"u9-l1","slug":"yesterday-last-week-two-days-ago","title":"Yesterday, last week, two days ago","titleUz":"O'tgan zamon vaqt so'zlari: ago, last, yesterday","goal":"O'tgan voqea qachon bo'lganini aniq ayta olasiz: yesterday afternoon, the day before yesterday, last month, a long time ago, in 2019, this morning, when I was a child — va bu iboralarni to'g'ri joyda, predlogsiz yoki to'g'ri predlog bilan ishlatasiz.","words":[{"en":"the day before yesterday","uz":"kechadan oldingi kun (ikki kun oldin)","ipa":"ðə ˌdeɪ bɪˌfɔː ˈjes.tə.deɪ"},{"en":"yesterday afternoon","uz":"kecha tushdan keyin","ipa":"ˌjes.tə.deɪ ˌɑːf.təˈnuːn"},{"en":"this morning","uz":"bugun ertalab","ipa":"ðɪs ˈmɔː.nɪŋ"},{"en":"last month","uz":"o'tgan oy","ipa":"ˌlɑːst ˈmʌnθ"},{"en":"last summer","uz":"o'tgan yoz","ipa":"ˌlɑːst ˈsʌm.ə"},{"en":"a long time ago","uz":"ancha oldin, uzoq vaqt oldin","ipa":"ə ˌlɒŋ ˈtaɪm əˌɡəʊ"},{"en":"a few minutes ago","uz":"bir necha daqiqa oldin","ipa":"ə ˌfjuː ˈmɪn.ɪts əˌɡəʊ"},{"en":"last weekend","uz":"o'tgan dam olish kunlari","ipa":"ˌlɑːst ˌwiːkˈend"},{"en":"when I was a child","uz":"bolaligimda","ipa":"wen aɪ wəz ə ˈtʃaɪld"},{"en":"cousin","uz":"amakivachcha, xolavachcha, ammavachcha, tog'avachcha (qarindoshingizning farzandi)","ipa":"ˈkʌz.ən"}],"summary":["yesterday morning / afternoon / evening, lekin last night (yesterday night emas); the day before yesterday = kechadan oldingi kun.","last + week / month / summer / Monday — oldida the ham, in / on ham yo'q.","Vaqt miqdori + ago: five minutes ago, a long time ago (❌ before two years). O'tmishdagi voqeadan keyin — later.","Aniq vaqt: in 2019 / May, on Friday / 3 March, at six; davr: when I was a child."]},{"id":"u9-l2","slug":"irregular-verbs-3","title":"Irregular verbs 3","titleUz":"Noto'g'ri fe'llar 3","goal":"Yana 10 ta noto'g'ri fe'lni o'rganasiz: slept, felt, left, spent, sent, lost, brought, taught, told, heard — va ularni to'g'ri talaffuz qilib, tell / say, bring / take kabi chalkash juftliklarni adashtirmay ishlatasiz.","words":[{"en":"sleep – slept","uz":"uxlamoq","ipa":"sliːp – slept"},{"en":"feel – felt","uz":"his qilmoq","ipa":"fiːl – felt"},{"en":"leave – left","uz":"ketmoq; qoldirmoq","ipa":"liːv – left"},{"en":"spend – spent","uz":"sarflamoq; (vaqt) o'tkazmoq","ipa":"spend – spent"},{"en":"send – sent","uz":"yubormoq","ipa":"send – sent"},{"en":"lose – lost","uz":"yo'qotmoq; yutqazmoq","ipa":"luːz – lɒst"},{"en":"bring – brought","uz":"olib kelmoq","ipa":"brɪŋ – brɔːt"},{"en":"teach – taught","uz":"o'rgatmoq, dars bermoq","ipa":"tiːtʃ – tɔːt"},{"en":"tell – told","uz":"aytib bermoq (kimgadir)","ipa":"tel – təʊld"},{"en":"hear – heard","uz":"eshitmoq","ipa":"hɪə – hɜːd"}],"summary":["sleep – slept, feel – felt, leave – left (i: → e + t); spend – spent, send – sent (d → t).","bring – brought, teach – taught (\"o:t\", gh o'qilmaydi); tell – told; lose – lost; hear – heard (\"hö:d\").","tell somebody (told me), lekin say something (said hello). bring — bu yerga, take — u yerga.","Iboralar: left home, left my phone, spent money/a week, sent a message, felt tired, lost the match."]},{"id":"u9-l3","slug":"where-did-you-go-what-did-you-do","title":"Where did you go? What did you do?","titleUz":"O'tgan zamonda Wh-savollar","goal":"O'tgan voqea haqida batafsil so'ray olasiz: Where did you go? What did you do? Who did you meet? How long did you stay? How was it? What happened? — va bunday savollarga qisqa, tabiiy javob berasiz.","words":[{"en":"happen","uz":"sodir bo'lmoq, bo'lmoq","ipa":"ˈhæp.ən"},{"en":"picnic","uz":"piknik","ipa":"ˈpɪk.nɪk"},{"en":"musician","uz":"sozanda, musiqachi","ipa":"mjuˈzɪʃ.ən"},{"en":"everybody","uz":"hamma, barcha","ipa":"ˈev.ri.bɒd.i"},{"en":"stay up","uz":"kech yotmaslik","ipa":"steɪ ʌp"},{"en":"relatives","uz":"qarindoshlar","ipa":"ˈrel.ə.tɪvz"},{"en":"boring","uz":"zerikarli","ipa":"ˈbɔː.rɪŋ"},{"en":"fantastic","uz":"ajoyib, zo'r","ipa":"fænˈtæs.tɪk"},{"en":"sleepy","uz":"uyqusiragan","ipa":"ˈsliː.pi"},{"en":"have fun","uz":"xursandchilik qilmoq, maza qilmoq","ipa":"ˌhæv ˈfʌn"}],"summary":["Savol so'zi + did + ega + V1: Where did you go? What did she buy? How long did you stay?","be bilan did yo'q: Where were you? How was your trip? Why was she late?","Ega so'ralsa — did yo'q, fe'l V2: Who called you? What happened?","Tez nutqda did you = \"didʒu\"; Wh-savol ohangi oxirida pasayadi ↘."]},{"id":"u9-l12","slug":"past-simple-negatives-and-questions-mixed","title":"Past Simple: negatives and questions mixed","titleUz":"Past Simple: inkor va savollar aralash mashq","goal":"O'tgan zamonda inkor (didn't + V1) va savol (Did + ega + V1?) ni oddiy ham, noto'g'ri fe'llar bilan ham xatosiz qurasiz va tayyor gapdagi xatoni topib tuzata olasiz: I didn't see him. Did you buy a ticket?","words":[{"en":"mistake","uz":"xato","ipa":"mɪˈsteɪk"},{"en":"wallet","uz":"hamyon","ipa":"ˈwɒl.ɪt"},{"en":"umbrella","uz":"soyabon","ipa":"ʌmˈbrel.ə"},{"en":"wait","uz":"kutmoq","ipa":"weɪt"},{"en":"answer","uz":"javob bermoq; javob","ipa":"ˈɑːn.sə"},{"en":"correct","uz":"to'g'ri; tuzatmoq","ipa":"kəˈrekt"}],"summary":["Ijobiy gap: V2 (bought, visited). Inkor: didn't + V1. Savol: Did + ega + V1?","Qisqa javob: Yes, I did. / No, I didn't.","did / didn't dan keyin hech qachon V2 qo'ymang: ❌ didn't went, ❌ Did you saw?","was / were bilan did kerak emas: He wasn't at home. Were you late?","Yangi so'zlar: mistake, wallet, umbrella, wait, answer, correct."]},{"id":"u9-l4","slug":"there-was-were-could-couldnt","title":"there was / were, could / couldn't","titleUz":"there was / were va could / couldn't","goal":"O'tmishda nima bor edi / yo'q edi ekanini (there was / there were, there wasn't any…, Was there…?) va nimani qila olardingiz / qila olmadingiz (could / couldn't) aytib bera olasiz: shahringiz, bolaligingiz, biror voqea haqida.","words":[{"en":"playground","uz":"o'yin maydonchasi","ipa":"ˈpleɪ.ɡraʊnd"},{"en":"field","uz":"dala; maydon","ipa":"fiːld"},{"en":"candle","uz":"sham","ipa":"ˈkæn.dəl"},{"en":"fountain","uz":"favvora","ipa":"ˈfaʊn.tɪn"},{"en":"traffic","uz":"yo'l harakati; tirbandlik","ipa":"ˈtræf.ɪk"},{"en":"crowded","uz":"odam gavjum, tiqilinch","ipa":"ˈkraʊ.dɪd"},{"en":"charge","uz":"quvvatlamoq (telefonni)","ipa":"tʃɑːdʒ"},{"en":"noisy","uz":"shovqinli","ipa":"ˈnɔɪ.zi"},{"en":"square","uz":"maydon (shahar maydoni)","ipa":"skweə"},{"en":"power cut","uz":"svet o'chishi (elektr uzilishi)","ipa":"ˈpaʊə ˌkʌt"}],"summary":["There was + birlik / sanalmaydigan ot; There were + ko'plik: There were a lot of people.","Inkor: There wasn't / weren't any… yoki There was / were no…; savol: Was / Were there…? — Yes, there was. / No, there weren't.","\"... bor edi\" ni ❌ had yoki ❌ It was bilan emas, There was / were bilan ayting.","could / couldn't + V1 — o'tmishdagi qobiliyat: I could swim at six. I couldn't sleep. (\"kud\", l o'qilmaydi)."]},{"id":"u9-l13","slug":"could-couldnt-and-was-able-to","title":"could / couldn't and was able to","titleUz":"could / couldn't: o'tmishdagi qobiliyat","goal":"O'tmishda nimani qila olganingiz / qila olmaganingizni aytasiz: umumiy qobiliyat uchun could / couldn't, bitta aniq voqeada muvaffaqiyat uchun was / were able to: I could swim at six. Yesterday I was able to climb the mountain.","words":[{"en":"be able to","uz":"qila olmoq","ipa":"bi ˈeɪ.bəl tuː"},{"en":"carry","uz":"ko'tarib yurmoq, olib yurmoq","ipa":"ˈkær.i"},{"en":"heavy","uz":"og'ir","ipa":"ˈhev.i"},{"en":"lift","uz":"ko'tarmoq","ipa":"lɪft"},{"en":"top","uz":"cho'qqi, tepa","ipa":"tɒp"},{"en":"lock","uz":"qulflamoq; qulf","ipa":"lɒk"}],"summary":["Umumiy qobiliyat: could / couldn't + V1 (I could swim at six).","Bitta aniq voqeada muvaffaqiyat: was / were able to + V1 (I was able to find the key).","Inkorda ikkalasi ham to'g'ri: couldn't = wasn't / weren't able to.","Xato: ❌ They was able to, ❌ wasn't able carry, ❌ couldn't opened.","Yangi so'zlar: carry, heavy, lift, top, lock, be able to."]},{"id":"u9-l5","slug":"life-stories","title":"Life stories","titleUz":"Hayot yo'li: born, grew up, moved…","goal":"O'zingiz yoki boshqa odamning hayot yo'lini gapirib bera olasiz: was born, grew up, left school, got a job, got married, moved to, became, retired — sanalar va at the age of, after that, two years later kabi iboralar bilan.","words":[{"en":"grow up – grew up","uz":"o'smoq, voyaga yetmoq","ipa":"ɡrəʊ ˈʌp – ɡruː ˈʌp"},{"en":"become – became","uz":"… bo'lmoq (kasb, holat)","ipa":"bɪˈkʌm – bɪˈkeɪm"},{"en":"move","uz":"ko'chmoq, ko'chib o'tmoq","ipa":"muːv"},{"en":"get a job","uz":"ishga joylashmoq","ipa":"ˌɡet ə ˈdʒɒb"},{"en":"get married","uz":"turmush qurmoq (uylanmoq / turmushga chiqmoq)","ipa":"ˌɡet ˈmær.id"},{"en":"have a baby","uz":"farzand ko'rmoq","ipa":"ˌhæv ə ˈbeɪ.bi"},{"en":"retire","uz":"nafaqaga chiqmoq","ipa":"rɪˈtaɪə"},{"en":"die","uz":"vafot etmoq, o'lmoq","ipa":"daɪ"},{"en":"childhood","uz":"bolalik","ipa":"ˈtʃaɪld.hʊd"},{"en":"at the age of","uz":"… yoshida","ipa":"ət ði ˈeɪdʒ əv"}],"summary":["Hayot voqealari: was born, grew up, left school, got a job, got married, had a baby, moved to, became, retired, died.","I was born (❌ I born / I am born); savolda: Where were you born? lekin Where did you grow up?","at the age of 17, in 1990, move to + joy, get married to + kishi, become a + kasb.","Voqealarni then, after that, two years later, in the end bilan bog'lang."]},{"id":"u9-l9","slug":"my-weekend-telling-a-friend","title":"My weekend: telling a friend","titleUz":"Dam olish kunim: do'stga hikoya","goal":"Do'stingizga o'tgan dam olish kuningiz haqida gapirib berasiz: I visited my grandmother and we cooked plov. Past Simple (ijobiy, inkor, savol) va vaqt so'zlari (last weekend, on Saturday, in the evening, then) ni real suhbatda ishlatasiz.","words":[{"en":"relax","uz":"dam olmoq, xotirjam bo'lmoq","ipa":"rɪˈlæks"},{"en":"lazy","uz":"dangasa","ipa":"ˈleɪ.zi"},{"en":"wonderful","uz":"ajoyib, a'lo","ipa":"ˈwʌn.də.fəl"}],"summary":["Savol: How was your weekend? / What did you do? Javob: Past Simple + vaqt so'zlari (on Saturday, then, in the evening).","Ijobiy: V2 (went, cooked); inkor va savol: didn't / did + V1.","Yangi so'zlar: relax, lazy, wonderful."]},{"id":"u9-l6","slug":"telling-a-story-and-but-so-because","title":"Telling a story: and, but, so, because","titleUz":"Hikoya qilish: and, but, so, because","goal":"Qisqa gaplarni and, but, so, because bilan bog'lab, izchil hikoya qila olasiz; so (natija) va because (sabab) ni adashtirmaysiz; hikoyani suddenly, luckily, unfortunately, in the end bilan jonli qilasiz.","words":[{"en":"suddenly","uz":"to'satdan, birdan","ipa":"ˈsʌd.ən.li"},{"en":"luckily","uz":"baxtimizga, omad kelib","ipa":"ˈlʌk.ɪ.li"},{"en":"unfortunately","uz":"afsuski","ipa":"ʌnˈfɔː.tʃən.ət.li"},{"en":"in the end","uz":"oxir-oqibat, oxirida","ipa":"ɪn ði ˈend"},{"en":"miss","uz":"(transportdan) qolib ketmoq; sog'inmoq","ipa":"mɪs"},{"en":"worried","uz":"xavotirda, tashvishli","ipa":"ˈwʌr.id"},{"en":"surprised","uz":"hayron, ajablangan","ipa":"səˈpraɪzd"},{"en":"spices","uz":"ziravorlar","ipa":"spaɪ.sɪz"},{"en":"remember","uz":"eslamoq, esda tutmoq","ipa":"rɪˈmem.bə"},{"en":"nobody","uz":"hech kim","ipa":"ˈnəʊ.bə.di"}],"summary":["and — qo'shish, but — qarama-qarshilik, so — natija (shuning uchun), because — sabab (chunki).","Bitta vaziyat ikki xil: I was tired, so I went to bed = I went to bed because I was tired.","because va so bitta gapda birga ishlatilmaydi (❌ Because it rained, so…).","Hikoyani jonlantiring: First, Then, Suddenly, Luckily, Unfortunately, In the end."]},{"id":"u9-l7","slug":"holidays-transport","title":"Holidays & transport","titleUz":"Ta'til va transport: by bus, on foot","goal":"Ta'tilingiz va safaringiz haqida gapirib bera olasiz: by bus / by train / on foot, took a taxi, got on / got off, flew, drove, rode, It took four hours, went sightseeing, stayed at a hotel.","words":[{"en":"camel","uz":"tuya","ipa":"ˈkæm.əl"},{"en":"fly – flew","uz":"uchmoq, samolyotda bormoq","ipa":"flaɪ – fluː"},{"en":"drive – drove","uz":"(mashina) haydamoq, mashinada bormoq","ipa":"draɪv – drəʊv"},{"en":"ride – rode","uz":"minmoq (velosiped, ot, tuya)","ipa":"raɪd – rəʊd"},{"en":"get on","uz":"(avtobus, poyezd, samolyotga) chiqmoq","ipa":"ˌɡet ˈɒn"},{"en":"get off","uz":"(avtobus, poyezddan) tushmoq","ipa":"ˌɡet ˈɒf"},{"en":"go on holiday","uz":"ta'tilga / dam olishga bormoq","ipa":"ˌɡəʊ ɒn ˈhɒl.ə.deɪ"},{"en":"go sightseeing","uz":"diqqatga sazovor joylarni aylanmoq","ipa":"ˌɡəʊ ˈsaɪtˌsiː.ɪŋ"},{"en":"souvenir","uz":"esdalik sovg'asi","ipa":"ˌsuː.vəˈnɪə"},{"en":"comfortable","uz":"qulay, rohat","ipa":"ˈkʌm.fə.tə.bəl"}],"summary":["by bus / car / train / plane / taxi / metro — artiklsiz; piyoda — on foot (❌ by foot, ❌ with bus).","Yangi fe'llar: fly – flew, drive – drove, ride – rode; took a taxi / the train.","get on / off — avtobus, poyezd, samolyot; get in(to) / out of — mashina, taksi.","How did you get there? — It took (us) four hours. Ta'til: went on holiday, went abroad, went sightseeing, stayed at a hotel, bought souvenirs."]},{"id":"u9-l10","slug":"a-trip-last-summer","title":"A trip last summer","titleUz":"O'tgan yozgi sayohat","goal":"O'tgan yozgi sayohatingiz haqida gapirib berasiz: We went to Samarkand by train. There was a beautiful square, but it was crowded, so we couldn't take many photos. Transport, there was / were, could / couldn't va and, but, so, because ni real suhbatda ishlatasiz.","words":[{"en":"beach","uz":"plyaj, sohil","ipa":"biːtʃ"},{"en":"luggage","uz":"yuk, sumkalar","ipa":"ˈlʌɡ.ɪdʒ"},{"en":"view","uz":"manzara","ipa":"vjuː"}],"summary":["Sayohat haqida: Where did you go? How did you get there? — We went by train / on foot.","Tasvir: There was + birlik, There were + ko'plik; could / couldn't + V1.","Bog'lovchilar: and (qo'shish), but (lekin), so (natija), because (sabab).","Yangi so'zlar: beach, luggage, view."]},{"id":"u9-l8","slug":"irregular-verbs-4","title":"Irregular verbs 4","titleUz":"Noto'g'ri fe'llar 4 va o'tgan zamon takrori","goal":"Yana 10 ta noto'g'ri fe'lni o'rganasiz: swam, ran, began, sang, won, broke, forgot, wore, caught, fell — va butun bo'lim bo'yicha Past Simple'ni (ijobiy, inkor, savol, was / were, there was, could) xatosiz ishlatib, hikoya qila olasiz.","words":[{"en":"swim – swam","uz":"suzmoq","ipa":"swɪm – swæm"},{"en":"run – ran","uz":"yugurmoq","ipa":"rʌn – ræn"},{"en":"begin – began","uz":"boshlamoq, boshlanmoq","ipa":"bɪˈɡɪn – bɪˈɡæn"},{"en":"sing – sang","uz":"kuylamoq, qo'shiq aytmoq","ipa":"sɪŋ – sæŋ"},{"en":"cut – cut","uz":"kesmoq; (qo'lni) kesib olmoq","ipa":"kʌt – kʌt"},{"en":"break – broke","uz":"sindirmoq, sinmoq","ipa":"breɪk – brəʊk"},{"en":"forget – forgot","uz":"unutmoq","ipa":"fəˈɡet – fəˈɡɒt"},{"en":"wear – wore","uz":"kiymoq, kiyib yurmoq","ipa":"weə – wɔː"},{"en":"catch – caught","uz":"tutmoq; ulgurmoq; (kasal) yuqtirmoq","ipa":"kætʃ – kɔːt"},{"en":"fall – fell","uz":"yiqilmoq, tushmoq","ipa":"fɔːl – fel"}],"summary":["Yangi fe'llar: swim – swam, run – ran, begin – began, sing – sang, win – won (\"wan\").","break – broke, forget – forgot, wear – wore, catch – caught (\"ko:t\"), fall – fell (felt emas!).","O'zgarmaydiganlar: put, cut, cost, hit — vaqt so'zidan bilinadi.","Oltin qoida: did / didn't / could / couldn't + V1; V2 — ijobiy gapda va Who won? kabi ega-savollarda.","Hikoya: vaqt so'zlari (ago, last, later) + there was / were + and, but, so, because."]},{"id":"u9-l14","slug":"listening-and-speaking-what-did-you-do","title":"Listening and speaking: what did you do?","titleUz":"Tinglash va gapirish: nima qildingiz?","goal":"O'tgan kun haqidagi qisqa suhbatni tinglab tushunasiz (kim, qayerda, nima qildi) va o'zingiz nima qilganingizni ovoz chiqarib aytasiz: What did you do? — I went to a concert with my friends. We had a lovely evening.","words":[{"en":"invite","uz":"taklif qilmoq, chaqirmoq","ipa":"ɪnˈvaɪt"},{"en":"enjoy","uz":"yoqtirmoq, zavqlanmoq","ipa":"ɪnˈdʒɔɪ"},{"en":"lovely","uz":"yoqimli, chiroyli","ipa":"ˈlʌv.li"},{"en":"midnight","uz":"yarim tun","ipa":"ˈmɪd.naɪt"},{"en":"alone","uz":"yolg'iz","ipa":"əˈləʊn"},{"en":"until","uz":"gacha, qadar","ipa":"ənˈtɪl"}],"summary":["Suhbatda qidiring: kim, qachon / qayerda, nima qildi. Javoblar ko'pincha V2 va did / didn't da.","Javob formulasi: qisqa javob + tafsilot (Yes, I did. It was lovely.).","Tez gapirishda did you — \"didya\"; asosiy fe'lni ushlang.","Yangi so'zlar: invite, enjoy, lovely, midnight, alone, until."]},{"id":"u9-l15","slug":"reading-and-writing-a-short-story","title":"Reading and writing: a short story","titleUz":"O'qish va yozish: qisqa hikoya","goal":"O'tgan zamondagi qisqa hikoyani o'qib tushunasiz va o'zingiz hikoya yozasiz: voqealarni one day, at first, then, finally bilan tartiblab, and, but, so, because bilan bog'laysiz.","words":[{"en":"at first","uz":"avval, dastlab","ipa":"æt fɜːst"},{"en":"finally","uz":"oxiri, nihoyat","ipa":"ˈfaɪ.nəl.i"},{"en":"one day","uz":"bir kuni","ipa":"wʌn deɪ"},{"en":"gift","uz":"sovg'a","ipa":"ɡɪft"},{"en":"neighbour","uz":"qo'shni","ipa":"ˈneɪ.bə"},{"en":"knock","uz":"taqillatmoq","ipa":"nɒk"}],"summary":["Hikoya tartibi: One day → At first → Then / After that → Finally.","Bog'lovchilar: and (qo'shish), but (qarama-qarshilik), so (natija), because (sabab).","Hikoya o'tgan zamonda yoziladi: V2, inkorda didn't + V1.","Yangi so'zlar: at first, finally, one day, gift, neighbour, knock."]},{"id":"u9-l11","slug":"stories-from-the-past-final-review","title":"Stories from the past: final review","titleUz":"O'tmishdan hikoyalar: yakuniy takror","goal":"Butun bo'limni takrorlaysiz: ago / last / yesterday, noto'g'ri fe'llar, o'tgan zamon Wh-savollari, there was / were, could / couldn't, hayot hikoyasi, and / but / so / because va transport. Oxirida o'tmish haqida kichik hikoya aytib bera olasiz.","words":[{"en":"journey","uz":"safar, yo'l","ipa":"ˈdʒɜː.ni"},{"en":"adventure","uz":"sarguzasht","ipa":"ədˈven.tʃər"},{"en":"memory","uz":"xotira, esdalik","ipa":"ˈmem.ər.i"}],"summary":["Vaqt: ago (two days ago), last (last week), yesterday.","Savol: Wh + did + ega + V1; ega-savolda: Who won?","there was (birlik) / there were (ko'plik); could / couldn't + V1.","Hikoya: and, but, so, because; transport: by bus, on foot.","Yangi so'zlar: journey, adventure, memory."]}]},{"id":"u10","n":10,"title":"Travel & Health","titleUz":"Sayohat va sog'liq: will, going to, have to, must","description":"Ob-havo, aeroport va vokzal, mehmonxona, Could I…?, will yoki going to, kasallik va maslahat, have to, must.","canDo":["Aeroport va mehmonxonada muammosiz muomala qilaman","Ob-havo haqida gapiraman","Shifokorga nima bezovta qilayotganini aytaman","Qoida va majburiyatlarni (must, have to) ayta olaman"],"lessons":[{"id":"u10-l1","slug":"whats-the-weather-like","title":"What's the weather like?","titleUz":"Ob-havo va fasllar","goal":"Ob-havo haqida erkin so'raysiz va javob berasiz: What's the weather like? — It's cold and foggy. It's minus five. It's raining. Haroratni aytasiz, ob-havo ma'lumotini (forecast) tushunasiz va fasllarni tasvirlaysiz.","words":[{"en":"forecast","uz":"ob-havo ma'lumoti, bashorat","ipa":"ˈfɔː.kɑːst"},{"en":"temperature","uz":"harorat","ipa":"ˈtem.prə.tʃə"},{"en":"degree","uz":"daraja","ipa":"dɪˈɡriː"},{"en":"freezing","uz":"qahraton, juda sovuq","ipa":"ˈfriː.zɪŋ"},{"en":"cool","uz":"salqin","ipa":"kuːl"},{"en":"foggy","uz":"tumanli","ipa":"ˈfɒɡ.i"},{"en":"storm","uz":"bo'ron, dovul","ipa":"stɔːm"},{"en":"snow","uz":"qor; qor yog'moq","ipa":"snəʊ"},{"en":"wet","uz":"ho'l, nam; yomg'irli","ipa":"wet"},{"en":"dry","uz":"quruq","ipa":"draɪ"}],"summary":["What's the weather like? = How's the weather? Javobda like yo'q: It's sunny.","It's + sifat: sunny, cloudy, windy, foggy, stormy (It's fog ❌). Ega It shart.","Hozir: It's raining / snowing. Odat: It rains a lot in April. Does it snow here?","Harorat: hot > warm > cool > cold > freezing; It's twenty degrees. It's minus five.","I'm cold (menga sovuq) ≠ It's cold (havo sovuq). Fasllar: in summer / in the summer."]},{"id":"u10-l2","slug":"at-the-station-airport","title":"At the station & airport","titleUz":"Vokzal va aeroportda","goal":"Vokzalda chipta olasiz (A return ticket to Samarkand, please.), jadval haqida so'raysiz (What time does the train leave? Which platform?) va aeroportda ro'yxatdan o'tish, gate, boarding pass, delayed kabi so'zlarni tushunasiz.","words":[{"en":"platform","uz":"platforma (vokzalda)","ipa":"ˈplæt.fɔːm"},{"en":"return ticket","uz":"borib-kelish chiptasi","ipa":"rɪˈtɜːn ˌtɪk.ɪt"},{"en":"departure","uz":"jo'nash","ipa":"dɪˈpɑː.tʃə"},{"en":"arrival","uz":"yetib kelish","ipa":"əˈraɪ.vəl"},{"en":"check in","uz":"ro'yxatdan o'tmoq","ipa":"ˌtʃek ˈɪn"},{"en":"boarding pass","uz":"bortga chiqish taloni","ipa":"ˈbɔː.dɪŋ pɑːs"},{"en":"gate","uz":"chiqish (aeroportda), darvoza","ipa":"ɡeɪt"},{"en":"delayed","uz":"kechikkan, kechikmoqda","ipa":"dɪˈleɪd"},{"en":"luggage","uz":"yuk, bagaj","ipa":"ˈlʌɡ.ɪdʒ"},{"en":"flight","uz":"reys, parvoz","ipa":"flaɪt"}],"summary":["Chipta: A single / A return (ticket) to Samarkand, please. Yo'nalish — to.","Jadval — Present Simple: What time does the train leave? It leaves at 8:15. Which platform does it leave from?","arrive in + shahar, arrive at + joy (arrive to ❌).","Aeroport: check in → boarding pass → passport control → security → gate → board. The flight is delayed / cancelled.","luggage sanalmaydi: my luggage is, two bags (luggages ❌)."]},{"id":"u10-l13","slug":"tickets-times-and-prices","title":"Tickets, times and prices","titleUz":"Chipta, vaqt va narx: single, return, platform","goal":"Vokzalda chipta, vaqt va narx haqida so'raysiz va javobni tushunasiz: How much is a return ticket? What time does the train leave? Which platform? It's delayed.","words":[{"en":"timetable","uz":"jadval (qatnov)","ipa":"ˈtaɪmˌteɪ.bəl"},{"en":"ticket office","uz":"chipta kassasi","ipa":"ˈtɪk.ɪt ˌɒf.ɪs"},{"en":"fare","uz":"yo'l haqi","ipa":"feə"},{"en":"direct train","uz":"to'g'ridan-to'g'ri poyezd","ipa":"dəˈrekt treɪn"},{"en":"carriage","uz":"vagon","ipa":"ˈkær.ɪdʒ"},{"en":"change trains","uz":"poyezd almashtirmoq","ipa":"tʃeɪndʒ treɪnz"}],"summary":["Narx: How much is a single ticket? / How much are two tickets?","Vaqt va perron: What time does the train leave? Which platform does it leave from? — does dan keyin fe'l oddiy.","Foydali: single, return, delayed, direct train, change trains.","Yangi so'zlar: timetable, ticket office, fare, direct train, carriage, change trains."]},{"id":"u10-l3","slug":"at-the-hotel-could-i","title":"At the hotel: Could I…?","titleUz":"Mehmonxonada: Can I / Could I…?","goal":"Mehmonxonada xona band qilasiz, ruxsat so'raysiz va xushmuomala iltimos qilasiz: Could I have a room for two nights? Could you call a taxi, please? Iltimosga to'g'ri javob berasiz: Yes, of course. / I'm afraid not.","words":[{"en":"reception","uz":"qabulxona, resepshn","ipa":"rɪˈsep.ʃən"},{"en":"reservation","uz":"bron, oldindan band qilish","ipa":"ˌrez.əˈveɪ.ʃən"},{"en":"single room","uz":"bir kishilik xona","ipa":"ˌsɪŋ.ɡəl ˈruːm"},{"en":"double room","uz":"ikki kishilik xona","ipa":"ˌdʌb.əl ˈruːm"},{"en":"key card","uz":"kalit-karta","ipa":"ˈkiː kɑːd"},{"en":"towel","uz":"sochiq","ipa":"ˈtaʊ.əl"},{"en":"lift","uz":"lift","ipa":"lɪft"},{"en":"check out","uz":"mehmonxonadan chiqib ketmoq (xonani topshirmoq)","ipa":"ˌtʃek ˈaʊt"},{"en":"included","uz":"narxga kirgan, qo'shilgan","ipa":"ɪnˈkluː.dɪd"},{"en":"view","uz":"manzara, ko'rinish","ipa":"vjuː"}],"summary":["Ruxsat: Can I…? / Could I + V1…? (Could — muloyimroq): Could I have the key, please?","Iltimos: Could you + V1…, please? — Could you call a taxi? (to va -ing yo'q).","Javob: Yes, of course. / Sure. / No problem. Rad: I'm afraid not. (Yes, you could tabiiy emas → Yes, you can).","could \"kud\" o'qiladi (l jim). Bu yerda u o'tgan zamon emas.","Mehmonxona: reception, reservation, single / double room, key card, towel, lift, check out, included, view."]},{"id":"u10-l9","slug":"booking-a-hotel-room","title":"Booking a hotel room","titleUz":"Mehmonxona xonasini band qilish","goal":"Mehmonxonaga qo'ng'iroq qilib xona band qilasiz: sanalarni va narxni aytasiz, Could I book a room? How much is it per night? kabi savollarni berasiz.","words":[{"en":"available","uz":"bo'sh, mavjud","ipa":"əˈveɪ.lə.bəl"},{"en":"per night","uz":"bir kechasiga","ipa":"pɜː naɪt"},{"en":"guest","uz":"mehmon","ipa":"ɡest"},{"en":"cost","uz":"turmoq (narxi)","ipa":"kɒst"}],"summary":["Xona band qilish: Could I book a room, please? — fe'l oddiy shaklda, to yo'q.","Sana va narx: from the fifth to the eighth of May, eighty dollars per night.","Savollar: Is breakfast included?, Is a room available?","Yangi so'zlar: available, per night, guest, cost."]},{"id":"u10-l4","slug":"will-or-going-to","title":"will or going to?","titleUz":"will yoki going to?","goal":"Kelajak haqida to'g'ri shaklni tanlaysiz: oldindan reja — I'm going to visit Khiva, shu zahoti qaror va taklif — I'll carry your bag, va'da — I'll call you, dalilga asoslangan bashorat — It's going to rain. Shall I…? bilan yordam taklif qilasiz.","words":[{"en":"pack","uz":"(sumka/chamadonga) narsalarni joylamoq","ipa":"pæk"},{"en":"sunglasses","uz":"quyosh ko'zoynagi","ipa":"ˈsʌnˌɡlɑː.sɪz"},{"en":"postcard","uz":"ochiq xat (otkritka)","ipa":"ˈpəʊst.kɑːd"},{"en":"cloud","uz":"bulut","ipa":"klaʊd"},{"en":"tour guide","uz":"gid, ekskursovod","ipa":"ˈtʊə ɡaɪd"},{"en":"hurry up","uz":"shoshilmoq, tezroq bo'lmoq","ipa":"ˌhʌr.i ˈʌp"},{"en":"grey","uz":"kulrang","ipa":"ɡreɪ"},{"en":"map","uz":"xarita","ipa":"mæp"},{"en":"rent","uz":"ijaraga olmoq","ipa":"rent"},{"en":"answer","uz":"javob bermoq; javob","ipa":"ˈɑːn.sə"}],"summary":["going to — oldindan reja: I'm going to visit Khiva. (Chiptalarni oldim.)","will — shu zahoti qaror, taklif, va'da: The bus is late. I'll take a taxi. I promise I'll call.","Bashorat: dalil bor → going to (Look! It's going to rain.); fikr → will (I think you'll like it.).","Taklif savolda: Shall I…? (…aymi?), Shall we…? (…aylikmi?).","O'zbekcha \"olaman\" ni ❌ I take deb tarjima qilmang — kelajak uchun I'll take / I'm going to take."]},{"id":"u10-l5","slug":"whats-the-matter","title":"What's the matter?","titleUz":"Sog'liq: What's the matter? I've got a headache","goal":"Kasalligingizni inglizcha aytasiz (I've got a headache / a cold / a sore throat. My back hurts.), boshqalardan What's the matter? deb so'raysiz va maslahat berasiz: You should see a doctor. Why don't you…? Dorixonada kerakli narsani so'ray olasiz.","words":[{"en":"headache","uz":"bosh og'rig'i","ipa":"ˈhed.eɪk"},{"en":"toothache","uz":"tish og'rig'i","ipa":"ˈtuːθ.eɪk"},{"en":"stomachache","uz":"qorin og'rig'i","ipa":"ˈstʌm.ək.eɪk"},{"en":"a cold","uz":"shamollash","ipa":"ə kəʊld"},{"en":"cough","uz":"yo'tal; yo'talmoq","ipa":"kɒf"},{"en":"sore throat","uz":"tomoq og'rig'i","ipa":"ˌsɔː ˈθrəʊt"},{"en":"have a temperature","uz":"isitmasi bo'lmoq","ipa":"hæv ə ˈtem.prə.tʃə"},{"en":"hurt","uz":"og'rimoq; shikastlamoq","ipa":"hɜːt"},{"en":"medicine","uz":"dori","ipa":"ˈmed.sən"},{"en":"plaster","uz":"plastir","ipa":"ˈplɑː.stə"}],"summary":["So'rash: What's the matter? / What's wrong? / Are you OK? Javob: I don't feel well. I'm ill.","I've got + a headache / cold / cough / sore throat / temperature; (a) toothache, (a) stomachache.","My leg hurts. My eyes hurt. (bitta → hurts, ko'p → hurt). Where does it hurt?","Maslahat: You should + V1, Why don't you + V1? Xayrlashuv: Get well soon!","Talaffuz: ache, stomach — ch = k; cough — \"kof\"; She's got a cold ≠ She's cold."]},{"id":"u10-l12","slug":"giving-advice-should-shouldnt-why-dont-you","title":"Giving advice: should, shouldn't, Why don't you…?","titleUz":"Maslahat berish: should, shouldn't, Why don't you…?","goal":"Sayohat va sog'liq haqida maslahat so'raysiz va berasiz: What should I do? Should I take a coat? You should drink water. You shouldn't stay in the sun. Why don't you lie down?","words":[{"en":"advice","uz":"maslahat (sanalmaydi)","ipa":"ədˈvaɪs"},{"en":"sunscreen","uz":"quyoshdan himoya kremi","ipa":"ˈsʌn.skriːn"},{"en":"fresh air","uz":"toza havo","ipa":"freʃ eə"},{"en":"lie down","uz":"yotmoq, cho'zilmoq","ipa":"laɪ daʊn"},{"en":"bottled water","uz":"shishadagi suv","ipa":"ˈbɒt.əld ˈwɔː.tər"},{"en":"take care","uz":"ehtiyot bo'lmoq, o'zingizni asrang","ipa":"teɪk keə"}],"summary":["Maslahat: You should + V1; qilmaslik kerak: You shouldn't + V1.","Savol: Should I take a coat? va What should I do? — do kerak emas.","Qisqa javob: Yes, you should. / No, you shouldn't. Maslahat: Why don't you lie down?","Yangi so'zlar: advice, sunscreen, fresh air, lie down, bottled water, take care."]},{"id":"u10-l10","slug":"at-the-pharmacy-and-the-doctor","title":"At the pharmacy and the doctor","titleUz":"Dorixona va shifokorda","goal":"Dorixona va shifokorda nima bezovta qilayotganini aytasiz va maslahatni tushunasiz: What's the matter? I've got a fever. You should rest. You shouldn't go to work.","words":[{"en":"pharmacy","uz":"dorixona","ipa":"ˈfɑː.mə.si"},{"en":"fever","uz":"isitma, harorat","ipa":"ˈfiː.vər"},{"en":"tablet","uz":"tabletka","ipa":"ˈtæb.lət"},{"en":"rest","uz":"dam olmoq","ipa":"rest"}],"summary":["Shifokor: What's the matter? — javob: I've got a headache / a fever / a cough.","Maslahat: should + V1, qilmaslik: shouldn't + V1 (to va -s yo'q).","Dorixonada: I need something for a cough. Dorini necha marta ichish: How often do I take it?","Yangi so'zlar: pharmacy, fever, tablet, rest."]},{"id":"u10-l6","slug":"have-to-dont-have-to","title":"have to / don't have to","titleUz":"Majburiyat: have to / don't have to","goal":"Majburiyat haqida gapirasiz: I have to show my passport. She has to wear a uniform. don't have to — \"shart emas\" ekanini bilasiz va so'raysiz: Do I have to fill in this form? O'tgan zamonda: I had to wait for an hour.","words":[{"en":"visa","uz":"viza","ipa":"ˈviː.zə"},{"en":"fill in","uz":"to'ldirmoq (anketa, blanka)","ipa":"ˌfɪl ˈɪn"},{"en":"form","uz":"shakl, anketa, blanka","ipa":"fɔːm"},{"en":"waiting room","uz":"kutish xonasi","ipa":"ˈweɪ.tɪŋ ruːm"},{"en":"queue","uz":"navbat; navbatda turmoq","ipa":"kjuː"},{"en":"on time","uz":"o'z vaqtida","ipa":"ɒn ˈtaɪm"},{"en":"prescription","uz":"retsept","ipa":"prɪˈskrɪp.ʃən"},{"en":"insurance","uz":"sug'urta","ipa":"ɪnˈʃɔː.rəns"},{"en":"document","uz":"hujjat","ipa":"ˈdɒk.jə.mənt"},{"en":"embassy","uz":"elchixona","ipa":"ˈem.bə.si"}],"summary":["have to / has to + V1 — majburiyat (\"-ishim kerak\"): She has to wear a uniform. (has to wears ❌)","don't / doesn't have to — shart emas (mumkin emas EMAS!): You don't have to pay. It's free.","Savol: Do I have to…? Does she have to…? — Yes, you do. / No, she doesn't.","O'tgan zamon: had to / didn't have to / Did you have to…? (had to went ❌).","Talaffuz: \"hafta\", \"hasta\", \"hatta\"."]},{"id":"u10-l7","slug":"must-mustnt-rules-signs","title":"must / mustn't: rules & signs","titleUz":"Qoidalar: must / mustn't","goal":"Qoidalar va belgilarni (signs) tushuntirasiz: You must fasten your seat belt. You mustn't smoke here. mustn't (mumkin emas) va don't have to (shart emas) ni adashtirmaysiz, mustn't ni to'g'ri talaffuz qilasiz.","words":[{"en":"sign","uz":"belgi, yozuv (ko'rsatkich)","ipa":"saɪn"},{"en":"smoke","uz":"chekmoq; tutun","ipa":"sməʊk"},{"en":"fasten","uz":"taqmoq, mahkamlamoq","ipa":"ˈfɑː.sən"},{"en":"seat belt","uz":"xavfsizlik kamari","ipa":"ˈsiːt belt"},{"en":"switch off","uz":"o'chirmoq (telefon, chiroq)","ipa":"ˌswɪtʃ ˈɒf"},{"en":"rule","uz":"qoida","ipa":"ruːl"},{"en":"rubbish","uz":"axlat, chiqindi","ipa":"ˈrʌb.ɪʃ"},{"en":"grass","uz":"o'tloq, maysa","ipa":"ɡrɑːs"},{"en":"be allowed to","uz":"ruxsat berilgan bo'lmoq","ipa":"bi əˈlaʊd tə"},{"en":"danger","uz":"xavf","ipa":"ˈdeɪn.dʒə"}],"summary":["must + V1 — kuchli majburiyat, qoida: You must fasten your seat belt. (must to, musts ❌)","mustn't + V1 — taqiq: You mustn't smoke. Talaffuz: \"masnt\". (don't must ❌)","mustn't (mumkin emas) ≠ don't have to (shart emas): You mustn't touch. / You don't have to pay.","Belgilar: NO SMOKING → mustn't smoke; SWITCH OFF PHONES → must switch off.","must ning o'tgan zamoni yo'q → had to. Savolda odatda Do I have to…?"]},{"id":"u10-l14","slug":"listening-and-speaking-announcements-and-messages","title":"Listening and speaking: announcements and messages","titleUz":"Tinglash va gapirish: e'lonlar va xabarlar","goal":"Vokzal va aeroport e'lonlarini tushunasiz (platforma, vaqt, kechikish) va ovozli xabar qoldirasiz: Hello, this is Anna. Please call me back.","words":[{"en":"announcement","uz":"e'lon (ovozli)","ipa":"əˈnaʊns.mənt"},{"en":"passenger","uz":"yo'lovchi","ipa":"ˈpæs.ɪn.dʒər"},{"en":"attention","uz":"diqqat","ipa":"əˈten.ʃən"},{"en":"voicemail","uz":"ovozli xabar","ipa":"ˈvɔɪs.meɪl"},{"en":"leave a message","uz":"xabar qoldirmoq","ipa":"liːv ə ˈmes.ɪdʒ"},{"en":"call back","uz":"qayta qo'ng'iroq qilmoq","ipa":"kɔːl bæk"}],"summary":["E'londa kalit ma'lumotlarni tuting: reys/poyezd, vaqt, platforma yoki gate, kechikish.","Telefonda: Hello, this is Anna. Xabar: sabab + Please call me back. + Thank you. Bye!","call me back — me o'rtada. Please leave a message — signaldan keyin.","Yangi so'zlar: announcement, passenger, attention, voicemail, leave a message, call back."]},{"id":"u10-l8","slug":"writing-a-message-or-email","title":"Writing a message or email","titleUz":"Xabar va xat yozish","goal":"Do'stingizga norasmiy xat (Hi Anna, Thanks for your email… Write soon! Love, Malika) va mehmonxona yoki maktabga qisqa rasmiyroq xat (Dear Mr Smith, I would like to… Kind regards) yozasiz. Bosh harf, vergul va and, but, because, so bilan bog'langan gaplar yozishni o'rganasiz.","words":[{"en":"reply","uz":"javob; javob bermoq","ipa":"rɪˈplaɪ"},{"en":"subject","uz":"mavzu (xat qatori)","ipa":"ˈsʌb.dʒɪkt"},{"en":"attach","uz":"(faylni) biriktirmoq","ipa":"əˈtætʃ"},{"en":"Dear…","uz":"Hurmatli… (xatda murojaat)","ipa":"dɪə"},{"en":"Best wishes","uz":"Eng yaxshi tilaklar bilan (xat oxirida)","ipa":"ˌbest ˈwɪʃ.ɪz"},{"en":"Kind regards","uz":"Hurmat bilan (xat oxirida)","ipa":"ˌkaɪnd rɪˈɡɑːdz"},{"en":"look forward to","uz":"intiqlik bilan kutmoq","ipa":"lʊk ˈfɔː.wəd tə"},{"en":"let me know","uz":"menga xabar bering","ipa":"ˌlet mi ˈnəʊ"},{"en":"greetings","uz":"salom, ko'rishgan joydan salom (xatda)","ipa":"ˈɡriː.tɪŋz"},{"en":"write back","uz":"javob yozmoq","ipa":"ˌraɪt ˈbæk"}],"summary":["Xat: murojaat → kirish → asosiy qism → yakun → xayrlashuv + ism.","Do'stga: Hi …, / Thanks for your message! / Write soon! / Love, Best wishes,","Rasmiyroq: Dear Sir or Madam, / I would like to… / Could you…? / I look forward to hearing from you. / Kind regards,","look forward to + -ing; bosh harf: I, Monday, July, English, Tashkent.","Bog'lovchilar: and, but, because (sabab), so (natija), also."]},{"id":"u10-l15","slug":"reading-and-writing-a-postcard-and-an-email","title":"Reading and writing: a postcard and an email","titleUz":"O'qish va yozish: otkritka va xat","goal":"Sayohatdan yozilgan otkritka va qisqa xatni o'qib tushunasiz va o'zingiz otkritka yozasiz: joy, ob-havo, nima qildingiz va keyin nima qilasiz.","words":[{"en":"beach","uz":"plyaj","ipa":"biːtʃ"},{"en":"sunset","uz":"quyosh botishi","ipa":"ˈsʌn.set"},{"en":"lovely","uz":"ajoyib, yoqimli","ipa":"ˈlʌv.li"},{"en":"miss","uz":"sog'inmoq","ipa":"mɪs"},{"en":"stamp","uz":"marka (pochta)","ipa":"stæmp"},{"en":"address","uz":"manzil","ipa":"əˈdres"}],"summary":["Otkritka tuzilishi: Dear… → Greetings from… → ob-havo → Yesterday we… → Tomorrow we are going to… → I miss you → Love,","O'tgan voqealar: Yesterday we visited / walked…; reja: Tomorrow we are going to…","Xatda taklif: Why don't you come next summer? Tugatish: Best wishes, / Love,","Yangi so'zlar: beach, sunset, lovely, miss, stamp, address."]},{"id":"u10-l11","slug":"travel-and-health-final-review","title":"Travel and health: final review","titleUz":"Sayohat va sog'liq: yakuniy takror","goal":"Birlikdagi hamma narsani takrorlaysiz: ob-havo, vokzal va aeroport, mehmonxona, will / going to, salomatlik maslahati, have to, must / mustn't va qisqa xabar yozish.","words":[{"en":"journey","uz":"safar, yo'l","ipa":"ˈdʒɜː.ni"},{"en":"souvenir","uz":"esdalik sovg'a","ipa":"ˌsuː.vəˈnɪər"},{"en":"safe","uz":"xavfsiz","ipa":"seɪf"},{"en":"hope","uz":"umid qilmoq","ipa":"həʊp"}],"summary":["will — shu zahotiy qaror va va'da; going to — reja va belgi asosidagi bashorat.","should / shouldn't — maslahat; have to / don't have to — majburiyat / shart emas.","must — shart, mustn't — taqiqlangan; ulardan keyin to qo'yilmaydi.","Mehmonxona va xabar: Could I…? Could you…?, Dear… / Best wishes."]}]},{"id":"u11","n":11,"title":"Experiences","titleUz":"Tajribalar va yakun: Present Perfect va barcha zamonlar","description":"Present Perfect bilan tanishuv, ever / never, been / gone, fe'l + to / -ing, harakat predloglari, phrasal verbs, A1 yakuniy takrori.","canDo":["Hayotimdagi tajribalar haqida (Have you ever…?) gapiraman","Present Perfect va Past Simple farqini bilaman","want to / enjoy -ing kabi birikmalarni to'g'ri ishlataman","Kundalik phrasal verblarni tushunaman"],"lessons":[{"id":"u11-l1","slug":"have-you-ever","title":"Have you ever…?","titleUz":"Present Perfect: Have you ever…?","goal":"Hayotingizdagi tajribalar haqida gapirasiz va so'raysiz: Have you ever been to…? — Yes, I have. / No, I haven't. I've never… Yangi zamon — Present Perfect (have / has + V3) bilan tanishasiz.","words":[{"en":"ever","uz":"hech, qachondir (savolda)","ipa":"ˈevə"},{"en":"many times","uz":"ko'p marta","ipa":"ˈmeni taɪmz"},{"en":"desert","uz":"sahro","ipa":"ˈdez.ət"},{"en":"ocean","uz":"okean","ipa":"ˈəʊʃn"},{"en":"try","uz":"tatib ko'rmoq, sinab ko'rmoq","ipa":"traɪ"},{"en":"ride – rode – ridden","uz":"minmoq (ot, tuya, velosiped)","ipa":"raɪd – rəʊd – ˈrɪdn"},{"en":"foreign","uz":"xorijiy, chet ellik","ipa":"ˈfɒrən"},{"en":"famous","uz":"mashhur","ipa":"ˈfeɪməs"},{"en":"experience","uz":"tajriba, hodisa","ipa":"ɪkˈspɪəriəns"},{"en":"in my life","uz":"hayotimda","ipa":"ɪn maɪ laɪf"}],"summary":["Present Perfect = have / has + V3 — hayotdagi tajriba, qachon bo'lgani muhim emas: I've been to Samarkand.","Savol: Have you ever + V3? → Yes, I have. / No, I haven't. (Yes, I did emas!)","Inkor: I've never + V3 yoki I haven't + V3 — never bilan not birga ishlatilmaydi.","V3: been, seen, eaten, done, met, read, ridden, flown; to'g'ri fe'llarda V3 = -ed.","Necha marta: once, twice, three times, many times — gap oxirida."]},{"id":"u11-l2","slug":"past-participles-been-or-gone","title":"Past participles; been or gone?","titleUz":"3-shakl fe'llar va been / gone","goal":"25 dan ortiq noto'g'ri fe'lning V3 shaklini guruhlab yodlaysiz (written, spoken, lost, broken…), I've lost my keys kabi \"natija hozir\" gaplarini tuzasiz va been to (borib kelgan) bilan gone to (ketgan, hali u yerda) farqini bilasiz.","words":[{"en":"lose – lost – lost","uz":"yo'qotmoq","ipa":"luːz – lɒst – lɒst"},{"en":"find – found – found","uz":"topmoq","ipa":"faɪnd – faʊnd – faʊnd"},{"en":"win – won – won","uz":"yutmoq, g'olib bo'lmoq","ipa":"wɪn – wʌn – wʌn"},{"en":"write – wrote – written","uz":"yozmoq","ipa":"raɪt – rəʊt – ˈrɪtn"},{"en":"speak – spoke – spoken","uz":"gapirmoq","ipa":"spiːk – spəʊk – ˈspəʊkən"},{"en":"break – broke – broken","uz":"sindirmoq","ipa":"breɪk – brəʊk – ˈbrəʊkən"},{"en":"forget – forgot – forgotten","uz":"unutmoq","ipa":"fəˈɡet – fəˈɡɒt – fəˈɡɒtn"},{"en":"drive – drove – driven","uz":"(mashina) haydamoq","ipa":"draɪv – drəʊv – ˈdrɪvn"},{"en":"wear – wore – worn","uz":"kiymoq, taqmoq","ipa":"weə – wɔː – wɔːn"},{"en":"swim – swam – swum","uz":"suzmoq","ipa":"swɪm – swæm – swʌm"}],"summary":["V3 ni guruhlab yodlang: A-A-A (put), A-B-B (bought, lost, found), A-B-C (written, spoken, broken), A-B-A (come).","have + V3, hech qachon have + V2 emas: I've taken (✅), I've took (❌).","Present Perfect natija va yangilik uchun ham: I've lost my keys. We've bought a flat!","has been to = borib kelgan (hozir qaytgan); has gone to = ketgan (hali u yerda)."]},{"id":"u11-l12","slug":"present-perfect-short-answers-and-never-ever","title":"Present Perfect: short answers and never / ever","titleUz":"Present Perfect: qisqa javoblar, ever va never","goal":"Have you ever…? savoliga to'g'ri qisqa javob berasiz (Yes, I have. / No, I haven't.) va ever bilan never o'rnini bilasiz: Have you ever seen snow? — No, never. I've never seen snow.","words":[{"en":"island","uz":"orol","ipa":"ˈaɪlənd"},{"en":"zoo","uz":"hayvonot bog'i","ipa":"zuː"},{"en":"elephant","uz":"fil","ipa":"ˈelɪfənt"},{"en":"snow","uz":"qor","ipa":"snəʊ"},{"en":"boat","uz":"qayiq, kema","ipa":"bəʊt"},{"en":"helicopter","uz":"vertolyot","ipa":"ˈhelɪkɒptə"}],"summary":["Qisqa javob savoldagi yordamchi fe'l bilan: Have you…? → Yes, I have. / No, I haven't.","he / she / it bilan: Has she…? → Yes, she has. / No, she hasn't.","ever — savolda: Have you ever…? never — darak gapda: I've never… (not kerak emas).","Yangi so'zlar: island, zoo, elephant, snow, boat, helicopter."]},{"id":"u11-l3","slug":"present-perfect-or-past-simple","title":"Present Perfect or Past Simple?","titleUz":"Present Perfect yoki Past Simple?","goal":"Ikki zamonni to'g'ri tanlaysiz: vaqt aytilmasa — Present Perfect (I've been to Bukhara), aniq o'tgan vaqt bo'lsa — Past Simple (I went there last summer). Tabiiy suhbat quriladi: Have you ever…? → When did you…? Did you like it?","words":[{"en":"mountain","uz":"tog'","ipa":"ˈmaʊntən"},{"en":"hundreds of","uz":"yuzlab","ipa":"ˈhʌndrədz əv"},{"en":"memory","uz":"esdalik, xotira","ipa":"ˈmeməri"},{"en":"tourist","uz":"turist, sayyoh","ipa":"ˈtʊərɪst"},{"en":"guide","uz":"gid, yo'lboshlovchi","ipa":"ɡaɪd"},{"en":"local","uz":"mahalliy","ipa":"ˈləʊkl"},{"en":"amazing","uz":"ajoyib, hayratlanarli","ipa":"əˈmeɪzɪŋ"},{"en":"unforgettable","uz":"unutilmas","ipa":"ˌʌnfəˈɡetəbl"},{"en":"waterfall","uz":"sharshara","ipa":"ˈwɔːtəfɔːl"},{"en":"festival","uz":"festival, bayram","ipa":"ˈfestɪvl"}],"summary":["Present Perfect — vaqt aytilmaydi: tajriba (I've been to Khiva) yoki yangilik (I've lost my phone).","Past Simple — aniq tugagan vaqt: yesterday, last…, …ago, in 2020, when I was…","When…? savoli doim Past Simple: When did you go? (When have you been ❌)","Suhbat qolipi: Have you ever…? → Yes, I have. → When did you…? Did you like it?"]},{"id":"u11-l13","slug":"how-many-times-once-twice-three-times","title":"How many times? once, twice, three times","titleUz":"Necha marta? once, twice, three times","goal":"Necha marta bo'lganini so'raysiz va aytasiz: How many times have you been to Khiva? — Twice. Hamda so far, again, the first time iboralarini ishlatasiz.","words":[{"en":"a few times","uz":"bir necha marta","ipa":"ə fjuː taɪmz"},{"en":"again","uz":"yana, qayta","ipa":"əˈɡen"},{"en":"so far","uz":"hozirgacha","ipa":"səʊ fɑː"},{"en":"the first time","uz":"birinchi marta","ipa":"ðə fɜːst taɪm"},{"en":"how many times","uz":"necha marta","ipa":"haʊ ˈmeni taɪmz"}],"summary":["Necha marta: once, twice, three times, a few times, many times — gap oxirida.","Savol: How many times + have / has + ega + V3? Javob: Twice.","so far — hozirgacha; again — yana; the first time — birinchi marta.","Yangi so'zlar: a few times, again, so far, the first time, how many times."]},{"id":"u11-l9","slug":"sharing-experiences-have-you-ever","title":"Sharing experiences: have you ever…?","titleUz":"Tajriba almashish: Have you ever…?","goal":"Suhbatdoshingizdan tajribasi haqida so'raysiz (Have you ever…?), o'zingiz haqingizda aytasiz (I've been to… / I've never…) va tafsilotlarni Past Simple bilan davom ettirasiz. been va gone farqini ham bilib olasiz.","words":[{"en":"trip","uz":"sayohat, safar","ipa":"trɪp"},{"en":"lucky","uz":"omadli","ipa":"ˈlʌk.i"},{"en":"adventure","uz":"sarguzasht","ipa":"ədˈven.tʃər"},{"en":"postcard","uz":"otkritka, pochta kartochkasi","ipa":"ˈpəʊstkɑːd"},{"en":"souvenir","uz":"esdalik sovg'a","ipa":"ˌsuːvəˈnɪə"}],"summary":["Tajriba haqida so'rash: Have you ever + V3? — javob Yes, I have. / No, I haven't.","been — borib qaytgan; gone — ketgan, hali qaytmagan.","Tafsilot va aniq vaqt bo'lsa — Past Simple: When did you go? I went in 2023.","Yangi so'zlar: trip, lucky, adventure."]},{"id":"u11-l4","slug":"prepositions-of-movement","title":"Prepositions of movement","titleUz":"Harakat predloglari: into, across, along…","goal":"Harakat yo'nalishini aniq aytasiz: into, out of, up, down, across, along, through, over, under, past, towards, around. Yo'l ko'rsatasiz va sayr haqida gapirasiz: Go along the river, across the bridge and through the park.","words":[{"en":"bridge","uz":"ko'prik","ipa":"brɪdʒ"},{"en":"river","uz":"daryo","ipa":"ˈrɪvə"},{"en":"tunnel","uz":"tunnel","ipa":"ˈtʌnl"},{"en":"path","uz":"so'qmoq, yo'lak","ipa":"pɑːθ"},{"en":"hill","uz":"tepalik","ipa":"hɪl"},{"en":"stairs","uz":"zina","ipa":"steəz"},{"en":"wall","uz":"devor","ipa":"wɔːl"},{"en":"canal","uz":"kanal, ariq","ipa":"kəˈnæl"},{"en":"bakery","uz":"novvoyxona, nonvoyxona","ipa":"ˈbeɪkəri"},{"en":"follow","uz":"ergashmoq, orqasidan bormoq","ipa":"ˈfɒləʊ"}],"summary":["Joy predloglari — qayerda? (in, on); harakat predloglari — qayoqqa? (into, out of, onto, off).","across — kesib o'tib, along — bo'ylab, through — ichidan o'tib, over / under — ustidan / ostidan.","up / down, past, towards, around, from… to — yo'l ko'rsatishda eng kerakli so'zlar.","get on / off the bus, train; get into / out of a car, taxi. go home — predlogsiz."]},{"id":"u11-l5","slug":"want-to-enjoy-ing","title":"want to, enjoy -ing","titleUz":"Fe'l + to yoki -ing: want to, enjoy -ing","goal":"Ikki fe'lni to'g'ri bog'laysiz: want / need / decide / hope + to (I want to learn) va enjoy / finish / practise / don't mind + -ing (I enjoy cooking). I want you to come kabi gaplarni ham tuzasiz va rejalar, orzular haqida gapirasiz.","words":[{"en":"organise","uz":"tashkil qilmoq","ipa":"ˈɔːɡənaɪz"},{"en":"shout","uz":"baqirmoq","ipa":"ʃaʊt"},{"en":"go hiking","uz":"tog'da piyoda sayr qilmoq","ipa":"ɡəʊ ˈhaɪkɪŋ"},{"en":"refuse","uz":"rad qilmoq, rad etmoq","ipa":"rɪˈfjuːz"},{"en":"agree","uz":"rozi bo'lmoq","ipa":"əˈɡriː"},{"en":"offer","uz":"taklif qilmoq","ipa":"ˈɒfə"},{"en":"prefer","uz":"afzal ko'rmoq","ipa":"prɪˈfɜː"},{"en":"report","uz":"hisobot","ipa":"rɪˈpɔːt"},{"en":"practise","uz":"mashq qilmoq","ipa":"ˈpræktɪs"},{"en":"I don't mind","uz":"qarshi emasman, menga farqi yo'q","ipa":"aɪ dəʊnt maɪnd"}],"summary":["want, would like, need, hope, plan, decide, learn, promise, agree, offer + to + V1: I've decided to learn Chinese.","enjoy, finish, stop, practise, (don't) mind, go + V-ing: I enjoy cooking. Let's go shopping.","like, love, hate, start, begin — ikkalasi ham to'g'ri; lekin would like — faqat to.","Boshqa odam haqida: want + kishi + to + V1 — I want you to come (I want that you come ❌)."]},{"id":"u11-l6","slug":"when-before-after-or","title":"when, before, after, or","titleUz":"Gaplarni bog'lash: when, before, after, or","goal":"Ikki gapni vaqt bo'yicha bog'laysiz: When I was a child, I lived in Andijan. After I finished school, I went to university. Kelasi zamonda When I get home, I'll call you (will get emas!) qoidasini bilasiz va or ni savol va inkorda to'g'ri ishlatasiz.","words":[{"en":"army","uz":"armiya","ipa":"ˈɑːmi"},{"en":"graduate","uz":"(oliy o'quv yurtini) bitirmoq","ipa":"ˈɡrædʒueɪt"},{"en":"university","uz":"universitet","ipa":"ˌjuːnɪˈvɜːsəti"},{"en":"business","uz":"biznes, ish","ipa":"ˈbɪznəs"},{"en":"story","uz":"hikoya, voqea","ipa":"ˈstɔːri"},{"en":"grandparents","uz":"bobo va buvi","ipa":"ˈɡrænpeərənts"},{"en":"course","uz":"kurs","ipa":"kɔːs"},{"en":"career","uz":"martaba, kasb yo'li","ipa":"kəˈrɪə"},{"en":"grandchildren","uz":"nevaralar","ipa":"ˈɡræntʃɪldrən"},{"en":"join","uz":"qo'shilmoq, a'zo bo'lmoq","ipa":"dʒɔɪn"}],"summary":["when, before, after ikki gapni vaqt bo'yicha bog'laydi; bu qism boshida bo'lsa — vergul: When I was a child, I…","before / after + gap yoki ot: after I finished school / after school (after of ❌).","Kelajak haqida: when / before / after + Present Simple, asosiy gapda will: When I get home, I'll call you.","or — savolda tanlov (tea or coffee?) va inkorda: I don't eat meat or fish."]},{"id":"u11-l7","slug":"everyday-phrasal-verbs","title":"Everyday phrasal verbs","titleUz":"Kundalik phrasal verbs: get up, put on…","goal":"Kundalik hayotdagi eng kerakli phrasal verbs ni ishlatasiz: wake up, put on, take off, turn on / off, look for, look after, try on, pick up, throw away. Put it on (put on it emas) qoidasini bilasiz va open the light ❌ kabi xatolardan qutulasiz.","words":[{"en":"go out","uz":"(uydan) chiqmoq; sayrga chiqmoq","ipa":"ɡəʊ aʊt"},{"en":"put on","uz":"kiymoq","ipa":"pʊt ɒn"},{"en":"take off","uz":"yechmoq","ipa":"teɪk ɒf"},{"en":"come back","uz":"qaytib kelmoq","ipa":"kʌm bæk"},{"en":"turn off","uz":"o'chirmoq","ipa":"tɜːn ɒf"},{"en":"look for","uz":"qidirmoq","ipa":"lʊk fɔː"},{"en":"look after","uz":"qaramoq, g'amxo'rlik qilmoq","ipa":"lʊk ˈɑːftə"},{"en":"give back","uz":"qaytarib bermoq","ipa":"ɡɪv bæk"},{"en":"switch on","uz":"yoqmoq (chiroq, asbob)","ipa":"swɪtʃ ɒn"},{"en":"throw away","uz":"tashlab yubormoq","ipa":"θrəʊ əˈweɪ"}],"summary":["Phrasal verb = fe'l + kichik so'z, yangi ma'no: look for — qidirmoq, look after — qaramoq.","Har kungi: wake up, get up, put on, take off, turn on / off, go out, come back.","Uy va do'kon: try on, pick up, throw away, give back, fill in.","Olmosh o'rtada: turn it off, put them on (turn off it ❌); lekin look for it.","Chiroq va texnika — turn on / off (open / close the light ❌); put on — harakat, wear — holat."]},{"id":"u11-l10","slug":"mixed-conversations-real-life-situations","title":"Mixed conversations: real-life situations","titleUz":"Aralash suhbatlar: hayotiy vaziyatlar","goal":"Haqiqiy suhbatda zamonlar aralash keladi: kim ekaningiz (Present Simple), hozir nima qilayotganingiz (Continuous), nima bo'lgani (Past Simple, Present Perfect) va rejalaringiz (going to, will). Vokzalda va kafeda shunday suhbat qurasiz.","words":[{"en":"platform","uz":"platforma (vokzalda)","ipa":"ˈplæt.fɔːm"},{"en":"delayed","uz":"kechikkan","ipa":"dɪˈleɪd"},{"en":"seat","uz":"o'rindiq, joy","ipa":"siːt"},{"en":"nervous","uz":"xavotirli","ipa":"ˈnɜː.vəs"},{"en":"free","uz":"bo'sh (joy)","ipa":"friː"},{"en":"Excuse me","uz":"Kechirasiz (murojaat)","ipa":"ɪkˈskjuːs miː"}],"summary":["Bitta suhbatda zamonlar aralashadi: odat/fakt — Simple, hozir — Continuous, o'tmish — Past Simple / Present Perfect, kelajak — going to / will.","Aniq vaqt (ago, yesterday) bo'lsa — Past Simple; tajriba — Present Perfect.","Vokzal iboralari: Is this seat free? It's delayed. Nice to meet you.","Yangi so'zlar: platform, delayed, seat, nervous, free, Excuse me."]},{"id":"u11-l14","slug":"listening-and-speaking-my-experiences","title":"Listening and speaking: my experiences","titleUz":"Tinglash va gapirish: mening tajribalarim","goal":"Tajriba haqidagi qisqa suhbatlarni tinglab tushunasiz va o'zingiz gapirasiz: Have you ever…? — Yes, I have. I went there… — How about you?","words":[{"en":"That sounds fun!","uz":"Qiziq ekan!","ipa":"ðæt saʊndz fʌn"},{"en":"How about you?","uz":"Siz-chi?","ipa":"haʊ əˈbaʊt juː"},{"en":"Me neither","uz":"Men ham (yo'q)","ipa":"miː ˈnaɪðə"},{"en":"by the way","uz":"aytgancha","ipa":"baɪ ðə weɪ"},{"en":"I'd love to","uz":"Xursand bo'lardim","ipa":"aɪd lʌv tuː"},{"en":"take a photo","uz":"rasmga olmoq","ipa":"teɪk ə ˈfəʊtəʊ"}],"summary":["Suhbatda tinglang: savol → qisqa javob → tafsilot (Past Simple).","Yaxshi javob: Yes, I have. + tafsilot + How about you?","Inkorga qo'shilish: Me neither. Qiziqish: That sounds fun!","Yangi iboralar: by the way, I'd love to, take a photo."]},{"id":"u11-l8","slug":"a1-review-all-the-tenses","title":"A1 review: all the tenses","titleUz":"A1 yakuniy takrori: barcha zamonlar","goal":"A1 darajasidagi barcha zamonlarni bitta tizimga solasiz: Present Simple, Present Continuous, Past Simple, going to, will, Present Perfect. Signal so'zlarga qarab zamonni tanlaysiz, yordamchi fe'llarni (do / does / did / am / is / are / will / have / has) adashtirmaysiz va o'zingiz haqida o'tmish, hozir va kelajakni qo'shib gapirasiz.","words":[{"en":"progress","uz":"rivojlanish, o'sish","ipa":"ˈprəʊɡres"},{"en":"goal","uz":"maqsad","ipa":"ɡəʊl"},{"en":"mistake","uz":"xato","ipa":"mɪˈsteɪk"},{"en":"improve","uz":"yaxshilamoq, yaxshilanmoq","ipa":"ɪmˈpruːv"},{"en":"confident","uz":"o'ziga ishongan","ipa":"ˈkɒnfɪdənt"},{"en":"fluent","uz":"erkin, ravon (tilda)","ipa":"ˈfluːənt"},{"en":"level","uz":"daraja","ipa":"ˈlevl"},{"en":"review","uz":"takrorlamoq; takrorlash","ipa":"rɪˈvjuː"},{"en":"achieve","uz":"erishmoq","ipa":"əˈtʃiːv"},{"en":"do your best","uz":"qo'lingizdan kelganini qilmoq","ipa":"duː jɔː best"}],"summary":["Present Simple — odat (I work), Present Continuous — hozir va kelishilgan reja (I'm working).","Past Simple — aniq tugagan vaqt (I worked yesterday), Present Perfect — vaqtsiz tajriba va yangilik (I've worked abroad).","Kelajak: going to — niyat va belgi, will — shu zahoti qaror, taklif, taxmin.","Yordamchi fe'l qoidasi: do / does / did / will + V1, am / is / are + V-ing, have / has + V3.","A1 tugadi! Keyingi qadam — A2: bu zamonlarni yanada erkin va murakkab gaplarda ishlatish."]},{"id":"u11-l15","slug":"reading-and-writing-an-email-about-my-experiences","title":"Reading and writing: an email about my experiences","titleUz":"O'qish va yozish: tajribalarim haqida xat","goal":"Tajribalar haqidagi qisqa xatlarni o'qib tushunasiz va o'zingiz do'stingizga xat yozasiz: salomlashish, tajriba (I've been to…), tafsilot (I went…) va savol (Have you ever…?).","words":[{"en":"Dear…","uz":"Aziz… (xat boshida)","ipa":"dɪə"},{"en":"write back","uz":"javob yozmoq","ipa":"raɪt bæk"},{"en":"Thanks for your email","uz":"Xatingiz uchun rahmat","ipa":"θæŋks fə jɔː ˈiːmeɪl"},{"en":"Best wishes","uz":"Eng yaxshi tilaklar bilan","ipa":"best ˈwɪʃɪz"},{"en":"beach","uz":"plyaj","ipa":"biːtʃ"},{"en":"email","uz":"elektron xat","ipa":"ˈiːmeɪl"}],"summary":["Xat tuzilishi: salom → rahmat → tajriba (Present Perfect) → tafsilot (Past Simple) → savol → xayrlashuv.","Tajriba: I have been to… / I have never…; tafsilot: I went there last summer.","Foydali iboralar: Dear…, Thanks for your email, Please write back, Best wishes."]},{"id":"u11-l11","slug":"elementary-final-review","title":"Elementary: final review","titleUz":"Elementary: yakuniy takror","goal":"Elementary darajasini yakunlaysiz: Present Simple, Present Continuous, Past Simple, going to, will, Present Perfect va modal fe'llar can, have to, must, should — hammasini bitta kichik takrorda mustahkamlaysiz.","words":[{"en":"tense","uz":"zamon (grammatikada)","ipa":"tens"},{"en":"sentence","uz":"gap","ipa":"ˈsen.təns"},{"en":"grammar","uz":"grammatika","ipa":"ˈɡræm.ər"},{"en":"exam","uz":"imtihon","ipa":"ɪɡˈzæm"},{"en":"correct","uz":"to'g'ri (javob, gap)","ipa":"kəˈrekt"}],"summary":["Zamonlar: Simple — odat, Continuous — hozir, Past Simple — aniq o'tmish, Present Perfect — tajriba, going to / will — kelajak.","Modallar: can (qila olish), have to / must (majburiyat), should (maslahat) + oddiy fe'l.","Oltin qoida: yordamchi fe'ldan keyin to'g'ri shakl (V1, V-ing, V3).","Yangi so'zlar: tense, sentence, grammar, exam, correct."]}]}]},{"id":"a2","slug":"pre-intermediate","title":"Pre-Intermediate","cefr":"A2","text":"Kundalik mavzularda gaplasha olaman, lekin xatolarim ko'p.","units":[{"id":"u12","n":12,"title":"Stories from the past","titleUz":"O'tmish hikoyalari: Past Simple, Past Continuous, used to","description":"Past Simple takrori, Past Continuous, used to, when / while va hikoya aytish.","canDo":["Voqealarni ketma-ket hikoya qilaman","Past Simple va Past Continuous ni ajrata olaman","Avvalgi odatlarimni (used to) aytaman","Sabab va qarama-qarshilikni bildiraman"],"lessons":[{"id":"u12-l1","slug":"past-simple-regular-and-irregular","title":"Past Simple: regular and irregular","titleUz":"Past Simple takrori: to'g'ri va noto'g'ri fe'llar","goal":"Past Simple ni mustahkamlaysiz: to'g'ri fe'llarga -ed qo'shish qoidalari (study – studied, stop – stopped), -ed ning uch xil o'qilishi, eng ko'p ishlatiladigan noto'g'ri fe'llar (went, saw, ate, bought, met, left…) va was / were. O'tgan hafta oxiri haqida 6–8 gaplik hikoya yoza olasiz.","words":[{"en":"arrive","uz":"yetib kelmoq","ipa":"əˈraɪv"},{"en":"decide","uz":"qaror qilmoq","ipa":"dɪˈsaɪd"},{"en":"spend – spent","uz":"sarflamoq; (vaqt) o'tkazmoq","ipa":"spend – spent"},{"en":"leave – left","uz":"ketmoq; tark etmoq","ipa":"liːv – left"},{"en":"meet – met","uz":"uchrashmoq, tanishmoq","ipa":"miːt – met"},{"en":"wake up – woke up","uz":"uyg'onmoq","ipa":"weɪk ʌp – wəʊk ʌp"},{"en":"stay","uz":"qolmoq; turmoq (mehmonxonada)","ipa":"steɪ"},{"en":"travel","uz":"sayohat qilmoq","ipa":"ˈtrævl"},{"en":"catch – caught","uz":"ulgurmoq (transport); tutmoq","ipa":"kætʃ – kɔːt"},{"en":"weekend","uz":"hafta oxiri","ipa":"ˌwiːkˈend"}],"summary":["Past Simple tugagan o'tmish uchun: I visited…, we went…. Hamma shaxslarda fe'l bir xil.","To'g'ri fe'llar: +ed (worked), +d (lived), -ied (studied), undosh ikkilanadi (stopped). Noto'g'ri fe'llarni yodlash kerak (go – went, buy – bought).","-ed uch xil o'qiladi: /t/ (worked), /d/ (played), /ɪd/ (wanted) — alohida \"ed\" bo'g'ini faqat t / d dan keyin.","be → was (I, he, she, it) va were (you, we, they). Hech qachon tushirib qoldirmang."]},{"id":"u12-l12","slug":"irregular-past-forms-patterns","title":"Irregular past forms: patterns","titleUz":"Noto'g'ri fe'llar: shakllar va qoliplar (buy – bought, think – thought)","goal":"Noto'g'ri fe'llarni qoliplarga bo'lib yodlaysiz (buy – bought, think – thought; know – knew, fly – flew; sit – sat, win – won), eslab qolish usullarini bilasiz va goed, buyed, thinked kabi xatolardan qochasiz.","words":[{"en":"think – thought","uz":"o'ylamoq","ipa":"θɪŋk – θɔːt"},{"en":"bring – brought","uz":"olib kelmoq","ipa":"brɪŋ – brɔːt"},{"en":"teach – taught","uz":"o'rgatmoq","ipa":"tiːtʃ – tɔːt"},{"en":"know – knew","uz":"bilmoq","ipa":"nəʊ – njuː"},{"en":"fly – flew","uz":"uchmoq","ipa":"flaɪ – fluː"},{"en":"win – won","uz":"yutmoq, g'olib bo'lmoq","ipa":"wɪn – wʌn"},{"en":"sit – sat","uz":"o'tirmoq","ipa":"sɪt – sæt"}],"summary":["Noto'g'ri fe'llar qoliplarga bo'linadi: -ought/-aught (buy, bring, think, teach, catch), -ew (know, grow, throw, fly), unli o'zgarishi (sit – sat, win – won).","Ba'zi fe'llar o'zgarmaydi: put, cut, hit, set, read.","Noto'g'ri fe'lga -ed qo'shmang: goed, buyed, thinked, knowed — xato.","Yangi fe'llar: think, bring, teach, know, fly, win, sit."]},{"id":"u12-l2","slug":"past-simple-questions-and-negatives","title":"Past Simple: questions and negatives","titleUz":"Past Simple: savol va inkor, ago va vaqt iboralari","goal":"Past Simple da didn't bilan inkor gap (I didn't go), Did…? bilan savol (Did you see him?), Wh- savollar (Where did you go?), was / were ning inkor va savol shakllarini tuzasiz va yesterday, last week, two days ago, in 2019 kabi vaqt iboralarini to'g'ri ishlatasiz.","words":[{"en":"ago","uz":"oldin (hozirdan hisoblab)","ipa":"əˈɡəʊ"},{"en":"recently","uz":"yaqinda, ko'p o'tmay","ipa":"ˈriːsntli"},{"en":"last night","uz":"kecha kechqurun","ipa":"lɑːst naɪt"},{"en":"the day before yesterday","uz":"avvalgi kuni (kechadan oldingi kun)","ipa":"ðə deɪ bɪˈfɔː ˈjestədeɪ"},{"en":"a long time ago","uz":"ancha oldin","ipa":"ə lɒŋ taɪm əˈɡəʊ"},{"en":"during","uz":"davomida","ipa":"ˈdjʊərɪŋ"},{"en":"all day","uz":"kun bo'yi","ipa":"ɔːl deɪ"},{"en":"remember","uz":"eslamoq, yodda tutmoq","ipa":"rɪˈmembə"},{"en":"enjoy","uz":"yoqtirmoq, zavqlanmoq","ipa":"ɪnˈdʒɔɪ"},{"en":"miss","uz":"ulgurmaslik, o'tkazib yubormoq","ipa":"mɪs"}],"summary":["Inkor: ega + didn't + V1 (I didn't go). Asosiy fe'l o'tgan shaklga o'tmaydi.","Savol: Did + ega + V1? (Did you see it?). Qisqa javob: Yes, I did. / No, I didn't. Wh-: Where did you go?","be bilan did kerak emas: Was she…? I wasn't… Were you…? We weren't…","Vaqt: yesterday, last week, two days ago, in 2019, on Monday. ago davrdan keyin turadi; last oldida in / on yo'q.","Who / What egasi bo'lsa, did ishlatilmaydi: Who called you?"]},{"id":"u12-l3","slug":"past-continuous","title":"Past Continuous","titleUz":"Past Continuous: was / were + -ing","goal":"Past Continuous (was / were + V-ing) ni tuzasiz va ishlatasiz: o'tmishdagi aniq paytda davom etayotgan ish-harakatni (At eight I was cooking) aytasiz, -ing imlosini bilasiz va Past Simple bilan farqini tushunasiz.","words":[{"en":"crowded","uz":"gavjum, odam ko'p","ipa":"ˈkraʊdɪd"},{"en":"queue","uz":"navbat","ipa":"kjuː"},{"en":"wait for","uz":"kutmoq","ipa":"weɪt fɔː"},{"en":"chat","uz":"suhbatlashmoq, gaplashmoq","ipa":"tʃæt"},{"en":"cross","uz":"kesib o'tmoq","ipa":"krɒs"},{"en":"noise","uz":"shovqin","ipa":"nɔɪz"},{"en":"pour","uz":"quymoq; (yomg'ir) sharros quymoq","ipa":"pɔː"},{"en":"asleep","uz":"uxlab yotgan","ipa":"əˈsliːp"},{"en":"at that moment","uz":"o'sha paytda, shu zahoti","ipa":"æt ðæt ˈməʊmənt"},{"en":"all evening","uz":"kechqurun bo'yi","ipa":"ɔːl ˈiːvnɪŋ"}],"summary":["Past Continuous = was / were + V-ing: o'tmishdagi aniq paytda davom etayotgan ish (At nine I was cooking).","Inkor: wasn't / weren't + V-ing; savol: Was / Were + ega + V-ing? — did ishlatilmaydi.","-ing imlosi: make → making, run → running, lie → lying, study → studying.","Jarayon (was cooking) va tugagan ish (cooked) ni farqlang. Holat fe'llari (know, like, want) Continuous da ishlatilmaydi."]},{"id":"u12-l4","slug":"past-simple-or-past-continuous","title":"Past Simple or Past Continuous?","titleUz":"Past Simple yoki Past Continuous? when va while","goal":"Ikki zamonni bir gapda ishlatasiz: uzoq davom etgan ish (Past Continuous) va uni to'xtatgan qisqa voqea (Past Simple): I was walking home when I saw an accident. when va while ning farqini bilasiz va ikki parallel ishni ham ayta olasiz.","words":[{"en":"accident","uz":"halokat, baxtsiz hodisa","ipa":"ˈæksɪdənt"},{"en":"suddenly","uz":"birdan, to'satdan","ipa":"ˈsʌdənli"},{"en":"ring – rang","uz":"jiringlamoq; qo'ng'iroq qilmoq","ipa":"rɪŋ – ræŋ"},{"en":"fall – fell","uz":"yiqilmoq, tushmoq","ipa":"fɔːl – fel"},{"en":"break down","uz":"buzilmoq (mashina)","ipa":"breɪk daʊn"},{"en":"shout","uz":"baqirmoq","ipa":"ʃaʊt"},{"en":"notice","uz":"payqamoq, sezmoq","ipa":"ˈnəʊtɪs"},{"en":"hurt","uz":"og'rimoq; jarohatlamoq","ipa":"hɜːt"},{"en":"lights went out","uz":"chiroq o'chdi","ipa":"laɪts went aʊt"},{"en":"on my way","uz":"yo'lda ketayotib","ipa":"ɒn maɪ weɪ"}],"summary":["Past Continuous — fon, davom etayotgan ish (was walking); Past Simple — to'satdan bo'lgan qisqa voqea (saw, rang).","Namuna: I was walking home when I saw an accident.","while + uzun ish (While I was cooking…); when + qisqa voqea (…when the phone rang).","Ikkala ish ham bir vaqtda davom etgan bo'lsa — ikkalasi Past Continuous: While I was cooking, he was watching TV.","Gap boshida when / while bo'lsa, vergul qo'yiladi: While I was walking, I saw him."]},{"id":"u12-l13","slug":"when-while-as-soon-as","title":"when, while, as soon as","titleUz":"When, while, as soon as: ikki o'tgan voqeani bog'lash","goal":"Ikki o'tgan voqeani when, while va as soon as bilan bitta gapda bog'laysiz: ketma-ket voqealar (When the bell rang, we left), darhol keyingi voqea (As soon as I got home, I made tea) va bir vaqtda bo'layotgan ishlar (While she was cooking, I was cleaning).","words":[{"en":"as soon as","uz":"-ishi bilan, darhol","ipa":"æz suːn æz"},{"en":"just then","uz":"aynan o'sha payt","ipa":"dʒʌst ðen"},{"en":"at the same time","uz":"bir vaqtning o'zida","ipa":"æt ðə seɪm taɪm"},{"en":"immediately","uz":"darhol","ipa":"ɪˈmiːdiətli"},{"en":"bell","uz":"qo'ng'iroq (maktab, eshik)","ipa":"bel"}],"summary":["when + Past Simple — ketma-ket voqealar; as soon as + Past Simple — darhol keyingi voqea.","while + was / were + V-ing — bir vaqtda davom etgan ish; qisqa voqea esa Past Simple da.","Gap when / while / as soon as bilan boshlansa, ikki qism orasiga vergul qo'ying.","Yangi so'zlar: as soon as, just then, at the same time, immediately, bell."]},{"id":"u12-l9","slug":"what-happened-telling-a-story-to-a-friend","title":"What happened? Telling a story to a friend","titleUz":"Nima bo'ldi? Do'stga hikoya aytib berish","goal":"Do'stingizga kecha yoki o'tgan hafta bo'lgan voqeani qiziqarli aytib berasiz: Guess what happened! bilan boshlaysiz, Past Continuous (fon) va Past Simple (voqea) ni when / while bilan bog'laysiz, so, because, but, then, finally dan foydalanasiz va do'stingizning hikoyasiga No way! What happened next? deb javob berasiz.","words":[{"en":"embarrassed","uz":"xijolat bo'lgan, noqulay","ipa":"ɪmˈbærəst"},{"en":"unbelievable","uz":"ishonib bo'lmaydigan","ipa":"ˌʌnbɪˈliːvəbl"},{"en":"get stuck – got stuck","uz":"tiqilib qolmoq, qotib qolmoq","ipa":"get stʌk – gɒt stʌk"},{"en":"lift","uz":"lift","ipa":"lɪft"},{"en":"scream","uz":"chinqirmoq, qichqirmoq","ipa":"skriːm"},{"en":"No way!","uz":"Yo'q-e! Mumkin emas!","ipa":"nəʊ weɪ"}],"summary":["Hikoyani Guess what happened…! bilan boshlang.","Fon — Past Continuous (was waiting), voqea — Past Simple (saw, rang). Ularni when / while bog'laydi.","because — sabab, so — natija, but — qarama-qarshilik, then / finally — tartib.","Tinglovchi sifatida: Really? No way! What happened next?"]},{"id":"u12-l5","slug":"used-to","title":"Used to","titleUz":"Used to: avval shunday edi","goal":"used to + V1 bilan o'tmishdagi odatlar va holatlarni aytasiz (I used to play chess every day), didn't use to va Did you use to…? shakllarini tuzasiz, used to va Past Simple ni to'g'ri tanlaysiz hamda use to / used to going kabi xatolardan qochasiz.","words":[{"en":"childhood","uz":"bolalik","ipa":"ˈtʃaɪldhʊd"},{"en":"grow up – grew up","uz":"ulg'ayib kamolga yetmoq","ipa":"ɡrəʊ ʌp – ɡruː ʌp"},{"en":"neighbourhood","uz":"mahalla, tuman","ipa":"ˈneɪbəhʊd"},{"en":"in those days","uz":"o'sha kunlarda","ipa":"ɪn ðəʊz deɪz"},{"en":"no longer","uz":"endi ... emas","ipa":"nəʊ ˈlɒŋɡə"},{"en":"change","uz":"o'zgarmoq; o'zgarish","ipa":"tʃeɪndʒ"},{"en":"traditional","uz":"an'anaviy","ipa":"trəˈdɪʃənl"},{"en":"habit","uz":"odat","ipa":"ˈhæbɪt"},{"en":"memory","uz":"xotira; esdalik","ipa":"ˈmeməri"},{"en":"village","uz":"qishloq","ipa":"ˈvɪlɪdʒ"}],"summary":["used to + V1 — o'tgan odat yoki holat, hozir endi bunday emas: I used to play chess.","Inkor va savol: didn't use to, Did you use to…? — used emas, use.","Sanalgan marta, aniq muddat va yakka voqea uchun Past Simple: I went to Paris three times.","use to (darak gapda), used to going, didn't used to — odatiy xatolar."]},{"id":"u12-l6","slug":"because-so-but-although","title":"Because, so, but, although","titleUz":"Because, so, but, although: sabab va qarama-qarshilik","goal":"Gaplarni because (sababi), so (shuning uchun), but (lekin) va although (garchi ... bo'lsa ham) bilan bog'laysiz. Uzun, ma'noli o'tmish gaplarini tuzasiz va because ... so, although ... but kabi odatiy xatolardan qochasiz.","words":[{"en":"reason","uz":"sabab","ipa":"ˈriːzn"},{"en":"result","uz":"natija","ipa":"rɪˈzʌlt"},{"en":"cancel","uz":"bekor qilmoq","ipa":"ˈkænsl"},{"en":"delay","uz":"kechiktirmoq; kechikish","ipa":"dɪˈleɪ"},{"en":"disappointed","uz":"xafa bo'lgan, umidi puchga chiqqan","ipa":"ˌdɪsəˈpɔɪntɪd"},{"en":"exhausted","uz":"juda charchagan","ipa":"ɪɡˈzɔːstɪd"},{"en":"delighted","uz":"juda xursand","ipa":"dɪˈlaɪtɪd"},{"en":"apologise","uz":"uzr so'ramoq","ipa":"əˈpɒlədʒaɪz"},{"en":"lucky","uz":"omadli","ipa":"ˈlʌki"},{"en":"sold out","uz":"sotilib bo'lgan","ipa":"səʊld aʊt"}],"summary":["because — sabab (I stayed home because I was ill); so — natija (I was ill, so I stayed home).","but — gap orasida, oldidan vergul; although — gap boshida yoki o'rtada, keyin to'liq gap.","Bitta gapda because ... so yoki although ... but birga ishlatilmaydi.","Gap boshidagi Because / Although dan keyingi bo'lakdan so'ng vergul qo'yiladi: Although it was cold, we went out."]},{"id":"u12-l14","slug":"listening-and-speaking-my-childhood","title":"Listening and speaking: my childhood","titleUz":"Tinglash va gapirish: mening bolaligim","goal":"Bolalik haqidagi suhbatni tinglab tushunasiz va o'z bolaligingiz haqida 5 gap ayta olasiz: When I was little, I lived in a village. I used to climb trees. My parents were strict, but they were kind.","words":[{"en":"toy","uz":"o'yinchoq","ipa":"tɔɪ"},{"en":"strict","uz":"qattiqqo'l","ipa":"strɪkt"},{"en":"naughty","uz":"shumtaka, yaramas","ipa":"ˈnɔːti"},{"en":"climb","uz":"chiqmoq, ko'tarilmoq","ipa":"klaɪm"},{"en":"cartoon","uz":"multfilm","ipa":"kɑːˈtuːn"}],"summary":["Bolalik haqida: When I was little, I lived…, I used to + V1, I didn't use to + V1, My parents were strict.","Savol: Where did you grow up? Did you use to…? Javob: Yes, I did. / No, I didn't.","Yangi so'zlar: toy, strict, naughty, climb, cartoon.","Gapirishda 5 gap rejasi: qayerda yashadingiz → nima qilardingiz → nima qilmasdingiz → ota-ona → hozir."]},{"id":"u12-l10","slug":"lost-property-reporting-a-lost-bag","title":"Lost property: reporting a lost bag","titleUz":"Yo'qolgan narsa: sumka yo'qolganini xabar qilish","goal":"Yo'qolgan narsalar bo'limida sumkangiz yo'qolganini xabar qilasiz: narsani tasvirlaysiz (rangi, o'lchami, ichida nima bor), qayerda va qachon yo'qolganini Past Simple va Past Continuous bilan aytasiz (I left it on the bus. I was talking on the phone when…) va xodimning savollariga javob berasiz.","words":[{"en":"lost property office","uz":"yo'qolgan narsalar bo'limi","ipa":"lɒst ˈprɒpəti ˈɒfɪs"},{"en":"item","uz":"narsa, buyum","ipa":"ˈaɪtəm"},{"en":"describe","uz":"tasvirlamoq","ipa":"dɪˈskraɪb"},{"en":"leather","uz":"charm","ipa":"ˈleðə"},{"en":"zip","uz":"zanjir (kiyim, sumkada)","ipa":"zɪp"},{"en":"strap","uz":"tasma, qayish","ipa":"stræp"},{"en":"form","uz":"blanka, anketa","ipa":"fɔːm"}],"summary":["Narsani tasvirlang: o'lcham → rang → material → narsa (a big black leather bag), keyin it has a strap / a zip.","Qachon va qayerda: Past Simple — I lost it yesterday. I left it on the bus.","Yo'qotish paytidagi fon: Past Continuous — I was talking on the phone when I got off.","Savollar: What does it look like? When did you lose it? Where did you last see it? What was inside?","Oxirida xodim form (blanka) to'ldirtiradi va qo'ng'iroq qiladi."]},{"id":"u12-l7","slug":"telling-a-story","title":"Telling a story","titleUz":"Hikoya aytish: first, then, after that, finally","goal":"O'tgan voqeani tartib bilan hikoya qilasiz: first, then, after that, next, later, finally, in the end, after / before / as soon as bilan bog'laysiz, hikoyada Past Simple va Past Continuous ni to'g'ri aralashtirasiz va Guess what? What happened next? kabi iboralar bilan suhbatda hikoya aytasiz.","words":[{"en":"at first","uz":"dastlab, avvaliga","ipa":"æt fɜːst"},{"en":"in the end","uz":"oxirida, oxir-oqibat","ipa":"ɪn ði end"},{"en":"meanwhile","uz":"shu orada, shu vaqtda","ipa":"ˈmiːnwaɪl"},{"en":"luckily","uz":"omadga, baxtimizga","ipa":"ˈlʌkɪli"},{"en":"unfortunately","uz":"afsuski","ipa":"ʌnˈfɔːtʃənətli"},{"en":"happen","uz":"sodir bo'lmoq, bo'lmoq","ipa":"ˈhæpən"},{"en":"realise","uz":"anglab yetmoq","ipa":"ˈriːəlaɪz"},{"en":"as soon as","uz":"...ishi bilan","ipa":"æz suːn æz"},{"en":"shocked","uz":"hayratda, dovdirab qolgan","ipa":"ʃɒkt"},{"en":"go on","uz":"davom etmoq, yuz bermoq","ipa":"ɡəʊ ɒn"}],"summary":["Hikoya = boshlanish (fon: Past Continuous, was / were), voqealar (Past Simple), yakun.","Ketma-ketlik so'zlari: First, Then, Next / After that, Later, Suddenly, Finally / In the end. Boshida vergul (Then dan tashqari).","after, before, as soon as + Past Simple bilan voqealarni bitta gapda bog'laymiz.","Hikoyada zamonni almashtirmang — boshdan oxirigacha o'tgan zamon.","Og'zaki: Guess what! / What happened next? / No way!"]},{"id":"u12-l15","slug":"reading-and-writing-a-short-story","title":"Reading and writing: a short story","titleUz":"O'qish va yozish: qisqa hikoya","goal":"O'tgan voqea haqidagi qisqa hikoyani o'qib tushunasiz va o'zingiz 5–7 gaplik hikoya yozasiz: First, we took the bus. Then we walked. While we were walking, it started to rain. Finally, the sun came out.","words":[{"en":"surprise","uz":"syurpriz, kutilmagan narsa","ipa":"səˈpraɪz"},{"en":"hide – hid","uz":"yashirinmoq; yashirmoq","ipa":"haɪd – hɪd"},{"en":"gift","uz":"sovg'a","ipa":"ɡɪft"},{"en":"candle","uz":"sham","ipa":"ˈkændl"},{"en":"guest","uz":"mehmon","ipa":"ɡest"}],"summary":["Hikoya tartibi: First, … Then … While/When … After that, … Finally, …","Voqealar Past Simple da (went, took, made), fon esa Past Continuous da (we were walking).","Yozgach tekshiring: o'tgan zamon, tartib so'zlari, bosh harf va nuqta.","Yangi so'zlar: surprise, hide – hid, gift, candle, guest."]},{"id":"u12-l8","slug":"unit-review-the-past","title":"Unit review: the past","titleUz":"Bosqich takrori: o'tgan zamon","goal":"12-bosqichdagi hamma narsani takrorlaysiz: Past Simple (to'g'ri / noto'g'ri fe'llar, savol va inkor), Past Continuous, when / while, used to, because / so / but / although va hikoya aytish. Oxirida o'tgan hafta oxiri yoki sayohat haqida bog'langan hikoya yoza va aytib bera olasiz.","words":[{"en":"journey","uz":"yo'l, safar","ipa":"ˈdʒɜːni"},{"en":"adventure","uz":"sarguzasht","ipa":"ədˈventʃə"},{"en":"souvenir","uz":"esdalik (sovg'a)","ipa":"ˌsuːvəˈnɪə"},{"en":"memorable","uz":"esda qoladigan","ipa":"ˈmemərəbl"},{"en":"experience","uz":"tajriba; boshdan kechirmoq","ipa":"ɪkˈspɪəriəns"},{"en":"argue","uz":"tortishmoq, janjallashmoq","ipa":"ˈɑːɡjuː"},{"en":"promise","uz":"va'da bermoq; va'da","ipa":"ˈprɒmɪs"},{"en":"whole","uz":"butun, tamom","ipa":"həʊl"},{"en":"brave","uz":"jasur","ipa":"breɪv"},{"en":"strange","uz":"g'alati","ipa":"streɪndʒ"}],"summary":["Past Simple: I went / worked; inkor didn't + V1; savol Did + ega + V1?; be → was / were. Vaqt: yesterday, last week, two days ago, in 2019.","Past Continuous (was / were + V-ing) — jarayon; Past Simple — qisqa voqea: I was walking when I saw…; while + uzun ish.","used to + V1 — o'tgan odat va holat; sanalgan marta va aniq muddat uchun Past Simple.","because (sabab), so (natija), but / although (qarama-qarshilik) — bir gapda because ... so va although ... but yo'q.","Hikoya: fon (Continuous) → voqealar (First, Then, After that, Finally) → yakun. Zamon boshdan oxirigacha o'tgan."]},{"id":"u12-l11","slug":"stories-from-the-past-final-review","title":"Stories from the past: final review","titleUz":"O'tmish hikoyalari: yakuniy takror","goal":"Butun bosqichni takrorlaysiz: Past Simple (to'g'ri/noto'g'ri fe'llar, savol, inkor, ago), Past Continuous, when / while, used to, because / so / but / although va hikoya tartibi (first, then, after that, finally) — va ularni bitta kichik hikoyada birga ishlatasiz.","words":[{"en":"terrified","uz":"dahshatga tushgan, juda qo'rqqan","ipa":"ˈterɪfaɪd"},{"en":"relieved","uz":"yengil tortgan","ipa":"rɪˈliːvd"},{"en":"all of a sudden","uz":"to'satdan, birdan","ipa":"ɔːl əv ə ˈsʌdn"},{"en":"at last","uz":"nihoyat, oxiri","ipa":"æt lɑːst"},{"en":"in the middle of","uz":"o'rtasida","ipa":"ɪn ðə ˈmɪdl əv"}],"summary":["Past Simple: V2; savol — Did you…?, inkor — didn't + V1; ago — o'tgan vaqt.","Past Continuous (was / were + -ing) — fon; Past Simple — voqea; when / while bog'laydi.","used to + V1 — avvalgi odat.","because — sabab, so — natija, but / although — qarama-qarshilik.","Tartib: First, then, after that, finally — hikoya shunday quriladi."]}]},{"id":"u13","n":13,"title":"Plans and the future","titleUz":"Rejalar va kelajak: going to, will, may / might, shart gap","description":"Going to, will, Present Continuous rejalar uchun, may / might va birinchi shart gap.","canDo":["Reja va qarorlarni (going to, will) farqlab aytaman","Ehtimolni (may, might) bildiraman","First conditional gap tuzaman","Uchrashuv va rejalar belgilayman"],"lessons":[{"id":"u13-l1","slug":"going-to","title":"Going to","titleUz":"Going to: rejalar va aniq belgilar","goal":"be going to + fe'l yordamida kelajak rejalaringiz (I'm going to study medicine) va hozirgi belgilarga asoslangan taxminlarni (Look at the clouds! It's going to rain) ayta olasiz, inkor va savol gaplar tuzasiz.","words":[{"en":"plan","uz":"reja; rejalashtirmoq","ipa":"plæn"},{"en":"decide","uz":"qaror qilmoq","ipa":"dɪˈsaɪd"},{"en":"book","uz":"oldindan band qilmoq","ipa":"bʊk"},{"en":"pack","uz":"(yukni) joylamoq","ipa":"pæk"},{"en":"save money","uz":"pul yig'moq","ipa":"seɪv ˈmʌni"},{"en":"take an exam","uz":"imtihon topshirmoq","ipa":"teɪk ən ɪɡˈzæm"},{"en":"move","uz":"ko'chib o'tmoq","ipa":"muːv"},{"en":"get married","uz":"turmush qurmoq; uylanmoq","ipa":"ɡet ˈmærid"},{"en":"next year","uz":"kelasi yil","ipa":"nekst jɪə"},{"en":"careful","uz":"ehtiyotkor","ipa":"ˈkeəfl"}],"summary":["am / is / are + going to + V1 — oldindan qilingan reja yoki niyat: I'm going to study.","Inkor: isn't / aren't / 'm not going to. Savol: Are you going to…? — do / does kerak emas.","Hozir ko'rinib turgan dalil bo'lsa ham going to: Look at the clouds! It's going to rain.","gonna — faqat og'zaki shakl; yozuvda going to."]},{"id":"u13-l2","slug":"will-and-wont","title":"Will and won't","titleUz":"Will / won't: qaror, va'da, taxmin","goal":"will / won't bilan gap qurasiz va uni uchta holatda ishlatasiz: shu zahoti qaror (I'll answer it), va'da va taklif (I'll help you) hamda fikrga asoslangan taxmin (I think it will be hot).","words":[{"en":"promise","uz":"va'da bermoq; va'da","ipa":"ˈprɒmɪs"},{"en":"probably","uz":"ehtimol, ko'pincha","ipa":"ˈprɒbəbli"},{"en":"definitely","uz":"albatta, shubhasiz","ipa":"ˈdefɪnətli"},{"en":"perhaps","uz":"balki","ipa":"pəˈhæps"},{"en":"secret","uz":"sir","ipa":"ˈsiːkrət"},{"en":"future","uz":"kelajak","ipa":"ˈfjuːtʃə"},{"en":"robot","uz":"robot","ipa":"ˈrəʊbɒt"},{"en":"carry","uz":"ko'tarib yurmoq, olib bormoq","ipa":"ˈkæri"},{"en":"on time","uz":"o'z vaqtida","ipa":"ɒn taɪm"},{"en":"right away","uz":"darhol","ipa":"raɪt əˈweɪ"}],"summary":["will + V1 barcha egalar bilan: I / he / they will go. Inkor: won't. Savol: Will you…? Hech qachon will to go, wills.","Shu zahoti qaror, va'da va taklif: The phone is ringing — I'll answer it. I won't tell anyone.","Fikr va taxmin: I think / I'm sure / probably / definitely + will.","Inkor fikr: I don't think it will rain (I think it won't emas)."]},{"id":"u13-l3","slug":"will-or-going-to","title":"Will or going to?","titleUz":"Will yoki going to? Shall bilan taklif","goal":"will va going to farqini bilib, vaziyatga qarab to'g'ri birini tanlaysiz hamda Shall I…? va Shall we…? bilan yordam taklif qilasiz va birgalikda ish qilishni taklif etasiz.","words":[{"en":"decision","uz":"qaror","ipa":"dɪˈsɪʒn"},{"en":"offer","uz":"taklif qilmoq (yordam)","ipa":"ˈɒfə"},{"en":"suggest","uz":"taklif qilmoq, maslahat bermoq","ipa":"səˈdʒest"},{"en":"instead","uz":"o'rniga","ipa":"ɪnˈsted"},{"en":"already","uz":"allaqachon","ipa":"ɔːlˈredi"},{"en":"Good idea!","uz":"Yaxshi fikr!","ipa":"ɡʊd aɪˈdɪə"},{"en":"No problem","uz":"Hech gap emas","ipa":"nəʊ ˈprɒbləm"},{"en":"It depends","uz":"Bunga bog'liq","ipa":"ɪt dɪˈpendz"},{"en":"umbrella","uz":"soyabon","ipa":"ʌmˈbrelə"},{"en":"guide","uz":"gid, yo'lboshchi","ipa":"ɡaɪd"}],"summary":["going to — oldindan qilingan reja yoki hozir ko'rinib turgan dalil; will — shu zahoti qaror, fikr, va'da, taklif.","Savol bering: bu reja / dalilmi yoki hozirgina o'ylab topdimmi? Shunga qarab tanlang.","will va going to bir gapda birga kelmaydi: will going to ❌.","Shall I…? — yordam taklifi; Shall we…? — birgalikda ish taklifi. Faqat I / we bilan, dan keyin V1."]},{"id":"u13-l12","slug":"future-time-expressions","title":"Future time expressions","titleUz":"Kelasi zamon iboralari: tomorrow, next week, in two days, soon","goal":"Kelajak vaqtini to'g'ri aytasiz: tomorrow morning, next Friday, in two days, by Friday, soon, later, in 2027 — va ularni going to, will hamda Present Continuous bilan qo'llab, in / at / on ni adashtirmaysiz.","words":[{"en":"soon","uz":"tez orada","ipa":"suːn"},{"en":"later","uz":"keyinroq","ipa":"ˈleɪ.tər"},{"en":"the day after tomorrow","uz":"indinga","ipa":"ðə deɪ ˈɑːf.tə təˈmɒr.əʊ"},{"en":"by (a time)","uz":"… gacha (kech qolmasdan)","ipa":"baɪ"},{"en":"in a week","uz":"bir haftadan keyin","ipa":"ɪn ə wiːk"}],"summary":["tomorrow, tonight, this evening, next week oldida predlog yo'q. Hozirdan muddat uchun in two days / in a week, yil oldidan in 2027.","by Friday — juma kunigacha (oxirgi muddat); in — shu muddatdan keyin.","Vaqt iborasi odatda gap oxirida; boshida bo'lsa, vergul qo'yiladi. Kelajak shakllari: going to, will, Present Continuous.","Yangi so'zlar: soon, later, the day after tomorrow, by, in a week."]},{"id":"u13-l4","slug":"present-continuous-for-plans","title":"Present Continuous for plans","titleUz":"Present Continuous: kelishilgan rejalar","goal":"Present Continuous ni kelajak uchun ishlatasiz: kelishib qo'yilgan uchrashuv va rejalarni (I'm meeting Laylo at six) aytasiz, uni going to va Present Simple (jadval) bilan chalkashtirmaysiz.","words":[{"en":"arrange","uz":"kelishmoq, uyushtirmoq","ipa":"əˈreɪndʒ"},{"en":"appointment","uz":"qabul, belgilangan uchrashuv","ipa":"əˈpɔɪntmənt"},{"en":"dentist","uz":"tish shifokori","ipa":"ˈdentɪst"},{"en":"wedding","uz":"to'y","ipa":"ˈwedɪŋ"},{"en":"flight","uz":"reys, parvoz","ipa":"flaɪt"},{"en":"pick up","uz":"olib ketmoq (mashinada)","ipa":"pɪk ʌp"},{"en":"diary","uz":"kundalik; reja daftari","ipa":"ˈdaɪəri"},{"en":"busy","uz":"band","ipa":"ˈbɪzi"},{"en":"free","uz":"bo'sh (vaqti bor)","ipa":"friː"},{"en":"stay with","uz":"birovnikida qolmoq","ipa":"steɪ wɪð"}],"summary":["am / is / are + V-ing + vaqt iborasi = kelishilgan yaqin reja: I'm meeting Laylo at six.","Rasmiy jadval va dasturda Present Simple: The train leaves at 8:15.","Taxmin va ob-havo uchun Present Continuous emas, going to / will: It's going to rain.","Savol va inkor oddiy Present Continuous kabi: Are you coming? I'm not working on Sunday."]},{"id":"u13-l5","slug":"may-and-might","title":"May and might","titleUz":"May / might: ehtimol","goal":"Kelajak haqida ishonchingiz komil bo'lmaganda may / might + fe'l bilan ehtimolni ifodalaysiz (It might rain. I may go to Samarkand), will bilan farqini bilasiz va maybe / may be ni adashtirmaysiz.","words":[{"en":"maybe","uz":"balki","ipa":"ˈmeɪbi"},{"en":"chance","uz":"imkoniyat, ehtimol","ipa":"tʃɑːns"},{"en":"hope","uz":"umid qilmoq","ipa":"həʊp"},{"en":"forecast","uz":"(ob-havo) bashorati","ipa":"ˈfɔːkɑːst"},{"en":"storm","uz":"bo'ron","ipa":"stɔːm"},{"en":"cancel","uz":"bekor qilmoq","ipa":"ˈkænsl"},{"en":"delay","uz":"kechikish; kechiktirmoq","ipa":"dɪˈleɪ"},{"en":"traffic jam","uz":"tirbandlik","ipa":"ˈtræfɪk dʒæm"},{"en":"not sure","uz":"ishonchi komil emas","ipa":"nɒt ʃɔː"},{"en":"enough","uz":"yetarli","ipa":"ɪˈnʌf"}],"summary":["may / might + V1 = ehtimol, ishonch past: It might rain. I may go. Hamma egalar bilan bir xil, to va -s yo'q.","Inkor: may not / might not (mayn't yo'q). Savol uchun: Do you think it will…?","Aniq narsa — will / won't, noaniq — may / might.","Maybe gap boshida (Maybe he is late), may be fe'l sifatida (He may be late). May I…? — xushmuomala ruxsat so'rash."]},{"id":"u13-l6","slug":"first-conditional","title":"First conditional","titleUz":"Birinchi shart gap: if + Present, will","goal":"If + Present Simple, … will + V1 qolipi bilan kelajakdagi real shart va natija haqida gapirasiz (If it rains, we'll stay at home), va'da, ogohlantirish hamda maslahat berasiz va unless ni (ixtiyoriy) tushunasiz.","words":[{"en":"pass (an exam)","uz":"(imtihondan) o'tmoq","ipa":"pɑːs"},{"en":"fail","uz":"yiqilmoq; o'ta olmamoq","ipa":"feɪl"},{"en":"miss","uz":"o'tkazib yubormoq (transport)","ipa":"mɪs"},{"en":"catch","uz":"ulgurmoq; tutmoq (transport)","ipa":"kætʃ"},{"en":"borrow","uz":"qarzga olmoq","ipa":"ˈbɒrəʊ"},{"en":"lend","uz":"qarzga bermoq","ipa":"lend"},{"en":"in time","uz":"o'z vaqtida (ulgurib)","ipa":"ɪn taɪm"},{"en":"warn","uz":"ogohlantirmoq","ipa":"wɔːn"},{"en":"wake up","uz":"uyg'onmoq","ipa":"weɪk ʌp"},{"en":"hurry up","uz":"shoshilmoq","ipa":"ˈhʌri ʌp"}],"summary":["If + Present Simple, will + V1 — kelajakdagi real shart va natija: If it rains, we'll stay home.","If-qismda will yo'q: If it rains ✅, If it will rain ❌. Inkor: don't / doesn't.","If-qism boshida bo'lsa — vergul; oxirida bo'lsa — vergulsiz. Natijada can, may, might yoki buyruq ham kelishi mumkin.","Unless = if … not: Unless you hurry, you'll be late. Unless dan keyin inkor kerak emas."]},{"id":"u13-l13","slug":"unless-as-soon-as-when","title":"Unless, as soon as, when","titleUz":"Unless, when va as soon as: shart gapning davomi","goal":"unless (agar … bo'lmasa) ni ishlatasiz va when, as soon as, before, after, until dan keyin kelajak uchun ham Present Simple qo'yasiz: I'll call you when I arrive — when I will arrive emas.","words":[{"en":"unless","uz":"agar … bo'lmasa","ipa":"ənˈles"},{"en":"as soon as","uz":"… bilanoq","ipa":"æz suːn æz"},{"en":"until","uz":"… gacha","ipa":"ənˈtɪl"},{"en":"arrive","uz":"yetib kelmoq","ipa":"əˈraɪv"},{"en":"forget","uz":"unutmoq","ipa":"fəˈɡet"},{"en":"finish","uz":"tugatmoq","ipa":"ˈfɪn.ɪʃ"}],"summary":["unless = if … not. Undan keyin darak shakl: Unless you hurry, you'll be late.","when, as soon as, before, after, until dan keyin kelajak uchun ham Present Simple: I'll call you when I arrive.","if — ehtimol; when — aniq bo'ladigan voqea.","Yangi so'zlar: unless, as soon as, until, arrive, forget, finish."]},{"id":"u13-l9","slug":"making-weekend-plans-with-friends","title":"Making weekend plans with friends","titleUz":"Do'stlar bilan dam olish rejalarini tuzish","goal":"Do'stlaringiz bilan dam olish kunlari rejasini tuza olasiz: nima qilmoqchi ekaningizni aytasiz (going to), kelishilgan rejani aytasiz (I'm meeting…), taklif qilasiz va taklifni qabul qilasiz yoki rad etasiz.","words":[{"en":"hang out","uz":"vaqt o'tkazmoq, aylanib yurmoq","ipa":"hæŋ aʊt"},{"en":"stay in","uz":"uyda qolmoq","ipa":"steɪ ɪn"},{"en":"barbecue","uz":"barbekyu, ochiq havoda kabob","ipa":"ˈbɑː.bɪ.kjuː"},{"en":"lazy","uz":"dangasa","ipa":"ˈleɪ.zi"},{"en":"join","uz":"qo'shilmoq","ipa":"dʒɔɪn"},{"en":"match","uz":"o'yin, musobaqa","ipa":"mætʃ"}],"summary":["Niyat va reja: am / is / are + going to + V1 (I'm going to stay in).","Vaqti va joyi kelishilgan reja: Present Continuous (We're meeting at twelve).","Taklif: Why don't you join us? / Would you like to…? / How about going…?","Qabul: That sounds great! / I'd love to! Rad etish: I'd love to, but… Maybe another time?"]},{"id":"u13-l7","slug":"making-plans","title":"Making plans","titleUz":"Reja tuzish: taklif, qabul va rad etish","goal":"Do'stlaringizga taklif qilasiz (Would you like to come…? Why don't we…?), taklifni qabul qilasiz yoki xushmuomalalik bilan rad etasiz (I'd love to, but…) hamda vaqt va joyni kelishib olasiz.","words":[{"en":"invite","uz":"taklif qilmoq (mehmonga)","ipa":"ɪnˈvaɪt"},{"en":"invitation","uz":"taklifnoma; taklif","ipa":"ˌɪnvɪˈteɪʃn"},{"en":"accept","uz":"qabul qilmoq","ipa":"əkˈsept"},{"en":"decline","uz":"rad etmoq (xushmuomala)","ipa":"dɪˈklaɪn"},{"en":"I'd love to","uz":"Xursand bo'lardim","ipa":"aɪd lʌv tuː"},{"en":"I'm afraid","uz":"Afsuski","ipa":"aɪm əˈfreɪd"},{"en":"another time","uz":"boshqa safar","ipa":"əˈnʌðə taɪm"},{"en":"look forward to","uz":"intizorlik bilan kutmoq","ipa":"lʊk ˈfɔːwəd tuː"},{"en":"meet up","uz":"uchrashmoq","ipa":"miːt ʌp"},{"en":"sounds great","uz":"zo'r bo'larkan","ipa":"saʊndz ɡreɪt"}],"summary":["Taklif: Would you like to + V1?, Why don't we + V1?, How about + V-ing?, Let's + V1.","Qabul: I'd love to! / That sounds great! / Good idea!","Rad etish: minnatdorchilik + I'd love to, but… / I'm afraid I can't + sabab + boshqa taklif.","Kelishuv: What time / Where shall we meet? va tasdiqlash: So we're meeting at seven."]},{"id":"u13-l14","slug":"listening-and-speaking-making-and-answering-an-invitation","title":"Listening and speaking: making and answering an invitation","titleUz":"Tinglash va gapirish: taklif qilish va javob berish","goal":"Taklifni tinglab tushunasiz, o'zingiz taklif qilasiz, qabul qilasiz yoki xushmuomalalik bilan rad etasiz va vaqt hamda joyni kelishib olasiz: Would you like to come over on Saturday? — I'd love to!","words":[{"en":"come over","uz":"mehmonga kelmoq","ipa":"kʌm ˈəʊ.vər"},{"en":"make it","uz":"kelib ulgurmoq, kela olmoq","ipa":"meɪk ɪt"},{"en":"get together","uz":"yig'ilmoq, uchrashmoq","ipa":"ɡet təˈɡeð.ər"},{"en":"count me in","uz":"men ham borman","ipa":"kaʊnt miː ɪn"},{"en":"text","uz":"SMS yozmoq, xabar yozmoq","ipa":"tekst"}],"summary":["Taklif: Would you like to come over…? / Why don't we get together…?","Qabul: I'd love to! / Sounds great! / Count me in! Rad etish: Thanks for asking, but I can't make it. How about…?","Vaqt va joy: What time shall we meet? Where shall we meet? Tasdiq: I'll text you when I leave.","Yangi iboralar: come over, make it, get together, count me in, text."]},{"id":"u13-l10","slug":"planning-a-trip-what-might-happen","title":"Planning a trip: what might happen?","titleUz":"Sayohatni rejalashtirish: nima bo'lishi mumkin?","goal":"Sayohatni rejalashtirganda nima bo'lishi mumkinligini ayta olasiz: will / won't (ishonch), may / might (ehtimol) va birinchi shart gap (If it rains, we'll…) bilan.","words":[{"en":"passport","uz":"pasport","ipa":"ˈpɑːs.pɔːt"},{"en":"luggage","uz":"yuk, bagaj","ipa":"ˈlʌɡ.ɪdʒ"},{"en":"souvenir","uz":"esdalik sovg'a","ipa":"ˌsuː.vəˈnɪər"},{"en":"sunscreen","uz":"quyoshdan himoya kremi","ipa":"ˈsʌn.skriːn"},{"en":"lost","uz":"yo'qolgan, adashgan","ipa":"lɒst"},{"en":"sightseeing","uz":"diqqatga sazovor joylarni ko'rish","ipa":"ˈsaɪtˌsiː.ɪŋ"}],"summary":["Ishonch: will / won't + V1. Ehtimol: may / might + V1 (It might rain).","Ehtimol emas: may not / might not (mayn't yo'q).","Birinchi shart gap: If + Present Simple, will + V1 (If it rains, we'll stay in).","If dan keyin will ishlatilmaydi."]},{"id":"u13-l15","slug":"reading-and-writing-an-invitation-and-a-reply","title":"Reading and writing: an invitation and a reply","titleUz":"O'qish va yozish: taklifnoma va javob xati","goal":"Qisqa taklifnoma va javob xatini o'qib tushunasiz hamda o'zingiz 4–6 gapli taklifnoma va javob yozasiz: I'm having a party on Saturday. Would you like to come? Please write back by Thursday.","words":[{"en":"reply","uz":"javob; javob bermoq","ipa":"rɪˈplaɪ"},{"en":"write back","uz":"javob yozmoq","ipa":"raɪt bæk"},{"en":"address","uz":"manzil","ipa":"əˈdres"},{"en":"details","uz":"tafsilotlar","ipa":"ˈdiː.teɪlz"},{"en":"lovely","uz":"ajoyib, yoqimli","ipa":"ˈlʌv.li"},{"en":"best wishes","uz":"eng yaxshi tilaklar bilan","ipa":"best ˈwɪʃ.ɪz"}],"summary":["Taklifnoma: salom → nima, qachon, qayerda → tafsilot → Would you like to come? Please write back by… → xayrlashuv.","Javob xati: minnatdorchilik, I'd love to come yoki I'm afraid I can't make it (+ sabab), tilak.","Yozishda: I'm having a party, Please write back by Friday, I'll text you as soon as I leave.","Yangi so'zlar: reply, write back, address, details, lovely, best wishes."]},{"id":"u13-l8","slug":"unit-review-the-future","title":"Unit review: the future","titleUz":"Bosqich takrori: kelajak","goal":"Bosqichdagi barcha mavzuni takrorlaysiz: going to, will / won't, will yoki going to + shall, Present Continuous (reja), may / might, birinchi shart gap va taklif qilish / qabul qilish / rad etish. Kelajak haqida erkin va to'g'ri gapira olasiz.","words":[{"en":"expect","uz":"kutmoq, umid qilmoq","ipa":"ɪkˈspekt"},{"en":"prepare","uz":"tayyorlamoq; tayyorlanmoq","ipa":"prɪˈpeə"},{"en":"schedule","uz":"jadval, reja","ipa":"ˈʃedjuːl"},{"en":"deadline","uz":"oxirgi muddat","ipa":"ˈdedlaɪn"},{"en":"celebrate","uz":"nishonlamoq","ipa":"ˈselɪbreɪt"},{"en":"graduate","uz":"(universitetni) bitirmoq","ipa":"ˈɡrædʒueɪt"},{"en":"surprise","uz":"syurpriz; hayratga solmoq","ipa":"səˈpraɪz"},{"en":"arrive","uz":"yetib kelmoq","ipa":"əˈraɪv"},{"en":"apply for","uz":"(ishga) topshirmoq, murojaat qilmoq","ipa":"əˈplaɪ fɔː"},{"en":"get ready","uz":"tayyorlanmoq","ipa":"ɡet ˈredi"}],"summary":["going to + V1 — reja yoki dalil; will + V1 — shu zahoti qaror, va'da, fikr; Shall I / we…? — taklif.","Kelishilgan shaxsiy reja — Present Continuous (I'm meeting Laylo at six); jadval — Present Simple.","Ehtimol: may / might + V1 (It might rain); inkor: may not / might not.","Birinchi shart gap: If + Present Simple, will + V1; if-qismda will yo'q. Unless = if … not.","Taklif: Would you like to…? Why don't we…? How about…ing? Rad etish: I'd love to, but… / I'm afraid I can't."]},{"id":"u13-l11","slug":"plans-and-the-future-final-review","title":"Plans and the future: final review","titleUz":"Rejalar va kelajak: yakuniy takror","goal":"Bosqichni yakunlaysiz: going to, will / won't, will yoki going to, Present Continuous (reja), may / might, birinchi shart gap va reja tuzish iboralarini bir joyda takrorlab, kelajak haqida erkin gapirasiz.","words":[{"en":"goal","uz":"maqsad","ipa":"ɡəʊl"},{"en":"dream","uz":"orzu","ipa":"driːm"},{"en":"success","uz":"muvaffaqiyat","ipa":"səkˈses"},{"en":"someday","uz":"bir kun, kelajakda biror vaqt","ipa":"ˈsʌm.deɪ"},{"en":"come true","uz":"ro'yobga chiqmoq","ipa":"kʌm truː"},{"en":"change","uz":"o'zgartirmoq, o'zgarmoq","ipa":"tʃeɪndʒ"}],"summary":["Reja: going to + V1; kelishilgan reja: Present Continuous; shu zahoti qaror va va'da: will / won't.","Ehtimol: may / might + V1; ehtimol emas: may not / might not.","Birinchi shart gap: If + Present Simple, will + V1.","Taklif: Would you like to…? Why don't we…? How about…ing? Rad etish: I'd love to, but… Maybe another time?"]}]},{"id":"u14","n":14,"title":"Comparing things","titleUz":"Taqqoslash: qiyosiy va orttirma daraja, as … as, too / enough","description":"Qiyosiy va orttirma daraja, as ... as, too / enough, ravishlar va tasvirlash.","canDo":["Narsa va odamlarni solishtiraman","Eng yaxshi/yomonini (superlative) aytaman","too va enough ni to'g'ri ishlataman","Ikki shahar yoki odamni taqqoslab yozaman"],"lessons":[{"id":"u14-l1","slug":"comparatives","title":"Comparatives","titleUz":"Qiyosiy daraja: -er va more","goal":"Ikki narsani solishtirishni o'rganasiz: qisqa sifatlarga -er (taller, bigger, easier), uzun sifatlarga more (more expensive) qo'shasiz, good → better, bad → worse kabi noto'g'ri shakllarni bilasiz va than bilan to'g'ri gap tuzasiz. more bigger kabi xatolardan qochasiz.","words":[{"en":"expensive","uz":"qimmat","ipa":"ɪkˈspensɪv"},{"en":"cheap","uz":"arzon","ipa":"tʃiːp"},{"en":"comfortable","uz":"qulay","ipa":"ˈkʌmftəbl"},{"en":"popular","uz":"mashhur, ommabop","ipa":"ˈpɒpjələ"},{"en":"dangerous","uz":"xavfli","ipa":"ˈdeɪndʒərəs"},{"en":"noisy","uz":"shovqinli","ipa":"ˈnɔɪzi"},{"en":"modern","uz":"zamonaviy","ipa":"ˈmɒdn"},{"en":"healthy","uz":"sog'lom; foydali","ipa":"ˈhelθi"},{"en":"difficult","uz":"qiyin","ipa":"ˈdɪfɪkəlt"},{"en":"heavy","uz":"og'ir","ipa":"ˈhevi"}],"summary":["Qisqa sifat + -er (taller, cheaper); -e bilan tugasa -r (nicer); big → bigger; easy → easier.","Uzun sifat: more + sifat (more expensive, more comfortable).","Noto'g'ri shakllar: good → better, bad → worse, far → further.","Solishtirishda than ishlatiladi: taller than me. then — boshqa so'z (keyin).","Ikki marta qiyoslamang: ❌ more bigger. Kuchaytirish uchun: much / a lot / a bit + qiyosiy (❌ very bigger)."]},{"id":"u14-l2","slug":"superlatives","title":"Superlatives","titleUz":"Orttirma daraja: the -est, the most","goal":"Uch va undan ortiq narsa ichidan eng ... ekanini aytishni o'rganasiz: the tallest, the biggest, the most beautiful. the best, the worst kabi noto'g'ri shakllarni, one of the + -est + ko'plik qolipini va in / of ning farqini bilib olasiz. the ni tushirib qoldirish xatosidan qochasiz.","words":[{"en":"delicious","uz":"mazali","ipa":"dɪˈlɪʃəs"},{"en":"wonderful","uz":"ajoyib","ipa":"ˈwʌndəfl"},{"en":"terrible","uz":"dahshatli, juda yomon","ipa":"ˈterəbl"},{"en":"ancient","uz":"qadimiy","ipa":"ˈeɪnʃənt"},{"en":"famous","uz":"mashhur","ipa":"ˈfeɪməs"},{"en":"huge","uz":"ulkan","ipa":"hjuːdʒ"},{"en":"tiny","uz":"juda kichkina","ipa":"ˈtaɪni"},{"en":"exciting","uz":"hayajonli, qiziqarli","ipa":"ɪkˈsaɪtɪŋ"},{"en":"boring","uz":"zerikarli","ipa":"ˈbɔːrɪŋ"},{"en":"useful","uz":"foydali","ipa":"ˈjuːsfl"}],"summary":["Orttirma daraja uch va undan ortiq narsa ichidan \"eng ...\" ni bildiradi va doim the bilan keladi: the tallest, the most famous.","Qisqa sifat: the + -est (the biggest, the easiest). Uzun sifat: the most + sifat. ❌ the most big, ❌ the expensivest.","Noto'g'ri shakllar: good → the best, bad → the worst, far → the furthest.","Joy / guruh bilan in (in the world, in my class), ko'plik / vaqt bilan of (of the year, of my life).","one of the + orttirma + ko'plik ot: one of the oldest cities. ...the best ... I've ever ... — tajriba haqida."]},{"id":"u14-l12","slug":"comparatives-spelling-and-irregular-forms","title":"Comparatives: spelling and irregular forms","titleUz":"Qiyosiy daraja: imlo va noto'g'ri shakllar (good – better – best)","goal":"Qiyosiy va orttirma darajaning imlosini (big → bigger, happy → happier, nice → nicer), ikki bo'g'inli sifatlarda -er yoki more tanlashni va noto'g'ri shakllarni (good – better – best, bad – worse – worst, far – further – furthest) xatosiz yozasiz.","words":[{"en":"narrow","uz":"tor (yo'l, ko'cha)","ipa":"ˈnær.əʊ"},{"en":"wide","uz":"keng, enli","ipa":"waɪd"},{"en":"simple","uz":"oddiy, sodda","ipa":"ˈsɪm.pəl"},{"en":"tidy","uz":"ozoda, tartibli","ipa":"ˈtaɪ.di"},{"en":"sad","uz":"xafa, g'amgin","ipa":"sæd"},{"en":"thin","uz":"ingichka, yupqa, ozg'in","ipa":"θɪn"}],"summary":["1 bo'g'inli sifat: -er / -est. -y bilan tugaydigan 2 bo'g'inli: -ier / -iest. Boshqa uzun sifatlar: more / the most.","Imlo: nice → nicer, big → bigger, happy → happier, new → newer (w, x, y ikkilanmaydi).","-ed, -ing, -ful, -ous bilan tugaydigan sifatlar doim more oladi: more boring, more tired.","Noto'g'ri shakllar: good – better – best, bad – worse – worst, far – further – furthest.","Yangi so'zlar: narrow, wide, simple, tidy, sad, thin."]},{"id":"u14-l3","slug":"as-as","title":"As ... as","titleUz":"as ... as va the same as","goal":"Ikki narsa teng ekanini aytasiz (as tall as), teng emas ekanini aytasiz (not as expensive as), the same as, different from, similar to va like ni to'g'ri ishlatasiz. same with, different with, as tall than kabi xatolardan qochasiz.","words":[{"en":"similar","uz":"o'xshash","ipa":"ˈsɪmələ"},{"en":"different","uz":"boshqacha, farqli","ipa":"ˈdɪfrənt"},{"en":"the same","uz":"bir xil","ipa":"ðə seɪm"},{"en":"alike","uz":"bir-biriga o'xshash","ipa":"əˈlaɪk"},{"en":"twin","uz":"egizak","ipa":"twɪn"},{"en":"opposite","uz":"teskari, qarama-qarshi","ipa":"ˈɒpəzɪt"},{"en":"in common","uz":"umumiy (narsa)","ipa":"ɪn ˈkɒmən"},{"en":"compare","uz":"solishtirmoq","ipa":"kəmˈpeə"},{"en":"difference","uz":"farq","ipa":"ˈdɪfrəns"},{"en":"equal","uz":"teng","ipa":"ˈiːkwəl"}],"summary":["as + sifat + as — tenglik: Aziz is as tall as Kamol. Sifat o'zgarmaydi: ❌ as taller as.","not as + sifat + as — \"...chalik emas\": Bukhara isn't as big as Tashkent. (= Tashkent is bigger.)","the same as, different from, similar to — ❌ same with, different with, similar with.","look like — o'xshamoq: You look like your mother. alike — The two sisters are alike.","Foydali iboralar: as soon as possible, as much as you like, twice as ... as."]},{"id":"u14-l13","slug":"stronger-comparisons-much-a-lot-a-bit-far","title":"Stronger comparisons: much, a lot, a bit, far","titleUz":"Kuchaytirilgan taqqoslash: much, a lot, a bit, far","goal":"Farq katta (much bigger, a lot cheaper, far better) yoki kichik (a bit older, slightly cheaper) ekanini aytasiz, even bilan \"yana ham\" deysiz va than bilan as … as ni adashtirmaysiz.","words":[{"en":"slightly","uz":"biroz, sal","ipa":"ˈslaɪt.li"},{"en":"nearly","uz":"deyarli","ipa":"ˈnɪə.li"},{"en":"even","uz":"hatto, yanada","ipa":"ˈiː.vən"},{"en":"by far","uz":"ancha farq bilan, shubhasiz","ipa":"baɪ fɑː"},{"en":"exactly","uz":"aynan, xuddi","ipa":"ɪɡˈzækt.li"}],"summary":["Katta farq: much / a lot / far + qiyosiy (much bigger). Kichik farq: a bit / slightly (a bit cheaper).","❌ very bigger. ✅ much bigger. Uzun sifat bilan: much more expensive.","even — \"yana ham\": even better. by far the + orttirma: by far the best.","than — farq bor (taller than). as … as — tenglik (as tall as). not nearly as … as — ancha kam.","Yangi so'zlar: slightly, nearly, even, by far, exactly."]},{"id":"u14-l4","slug":"too-and-enough","title":"Too and enough","titleUz":"Too va enough, too much / too many","goal":"too (me'yoridan ortiq, muammo) va enough (yetarli) so'zlarini to'g'ri o'rinda ishlatasiz: too hot, big enough, enough money, too much sugar, too many people, too tired to study. too much hot, enough big, too many money kabi xatolarni tuzatasiz.","words":[{"en":"spicy","uz":"achchiq (ziravorli)","ipa":"ˈspaɪsi"},{"en":"salty","uz":"sho'r","ipa":"ˈsɔːlti"},{"en":"tight","uz":"tor (kiyim)","ipa":"taɪt"},{"en":"loose","uz":"keng (kiyim)","ipa":"luːs"},{"en":"crowded","uz":"gavjum, odam ko'p","ipa":"ˈkraʊdɪd"},{"en":"afford","uz":"(puli) yetmoq, ega bo'la olmoq","ipa":"əˈfɔːd"},{"en":"plenty of","uz":"yetarli darajada ko'p","ipa":"ˈplenti əv"},{"en":"enough","uz":"yetarli","ipa":"ɪˈnʌf"},{"en":"exhausted","uz":"juda charchagan","ipa":"ɪɡˈzɔːstɪd"},{"en":"cramped","uz":"tor, siqiq (joy)","ipa":"kræmpt"}],"summary":["too + sifat — me'yoridan ortiq, muammo: too hot, too small. very esa shunchaki \"juda\" (muammo yo'q).","sifat + enough (big enough), lekin enough + ot (enough money). ❌ enough big.","too much + sanalmaydigan ot (sugar, time, traffic); too many + sanaladigan ko'plik ot (people, cars). ❌ too much hot.","too / enough + to + fe'l: too tired to study, old enough to drive. too young = not old enough."]},{"id":"u14-l5","slug":"adverbs-of-manner","title":"Adverbs of manner","titleUz":"Ravish: quickly, well, hard","goal":"Fe'l qanday bajarilishini ravish bilan aytasiz: quickly, carefully, badly. good (sifat) va well (ravish) farqini bilasiz, hard, fast, late, early kabi shakli o'zgarmaydigan ravishlarni, hardly va lately ning boshqa ma'nosini eslab qolasiz va ravishning qiyosiy darajasini tuzasiz (faster, harder, more carefully).","words":[{"en":"quickly","uz":"tez, tezda","ipa":"ˈkwɪkli"},{"en":"slowly","uz":"sekin","ipa":"ˈsləʊli"},{"en":"carefully","uz":"ehtiyotkorlik bilan, diqqat bilan","ipa":"ˈkeəfəli"},{"en":"badly","uz":"yomon","ipa":"ˈbædli"},{"en":"loudly","uz":"baland ovozda","ipa":"ˈlaʊdli"},{"en":"quietly","uz":"jimgina, past ovozda","ipa":"ˈkwaɪətli"},{"en":"easily","uz":"oson, osongina","ipa":"ˈiːzɪli"},{"en":"happily","uz":"xursandlik bilan","ipa":"ˈhæpɪli"},{"en":"hard","uz":"qattiq, jiddiy (ravish)","ipa":"hɑːd"},{"en":"early","uz":"erta","ipa":"ˈɜːli"}],"summary":["Ravish fe'lning qanday bajarilishini bildiradi: odatda sifat + -ly (slowly, carefully); -y → -ily (happily, easily).","good — sifat, well — ravish: She is a good singer. She sings well. ❌ speaks good.","hard, fast, late, early — sifat va ravish bir xil. hardly = deyarli ... emas, lately = yaqinda.","Tartib: fe'l + to'ldiruvchi + ravish: He speaks English well. ❌ speaks well English. be / look / taste / feel dan keyin sifat.","Qiyosiy: faster, harder, better, worse; -ly ravishlar uchun more: more slowly, more carefully."]},{"id":"u14-l6","slug":"describing-people","title":"Describing people","titleUz":"Odamlarni tasvirlash: tashqi ko'rinish va xarakter","goal":"Odamning tashqi ko'rinishi (tall, slim, curly hair, blue eyes) va xarakteri (friendly, shy, generous) ni tasvirlaysiz. is / has / looks like, What does he look like? va What is he like? farqini bilasiz va sifatlarni to'g'ri tartibda qo'yasiz (a nice young man).","words":[{"en":"slim","uz":"ozg'in, nozik tanli","ipa":"slɪm"},{"en":"curly","uz":"jingalak","ipa":"ˈkɜːli"},{"en":"bald","uz":"kal","ipa":"bɔːld"},{"en":"middle-aged","uz":"o'rta yoshli","ipa":"ˌmɪdl ˈeɪdʒd"},{"en":"good-looking","uz":"chiroyli, xushsurat","ipa":"ˌɡʊd ˈlʊkɪŋ"},{"en":"generous","uz":"saxovatli","ipa":"ˈdʒenərəs"},{"en":"shy","uz":"uyatchan","ipa":"ʃaɪ"},{"en":"lazy","uz":"dangasa","ipa":"ˈleɪzi"},{"en":"polite","uz":"odobli, xushmuomala","ipa":"pəˈlaɪt"},{"en":"honest","uz":"halol, rostgo'y","ipa":"ˈɒnɪst"}],"summary":["Bo'y, tana, yosh uchun be: He is tall and slim. Soch, ko'z, soqol uchun have: She has long curly hair. ❌ She is long hair.","What does he look like? — tashqi ko'rinish. What is he like? — xarakter. What does he like? — qiziqishlari.","look + sifat (You look tired), look like + ot (He looks like his father).","Sifatlar tartibi: fikr → o'lcham → yosh → rang → kelib chiqish → ot: a lovely young woman. Tavsif uchun with: a man with a beard.","Xarakter sifatlari: friendly, shy, generous, lazy, honest, polite, funny."]},{"id":"u14-l14","slug":"listening-and-speaking-choosing-between-two-things","title":"Listening and speaking: choosing between two things","titleUz":"Tinglash va gapirish: ikki narsadan birini tanlash","goal":"Ikki narsadan birini tanlash haqidagi suhbatni tinglab tushunasiz va o'zingiz tanlaysiz, sabab aytasiz: I prefer the black one because it's faster. In my opinion, it's the better choice.","words":[{"en":"decide","uz":"qaror qilmoq","ipa":"dɪˈsaɪd"},{"en":"opinion","uz":"fikr, nuqtai nazar","ipa":"əˈpɪn.jən"},{"en":"agree","uz":"rozi bo'lmoq","ipa":"əˈɡriː"},{"en":"choice","uz":"tanlov","ipa":"tʃɔɪs"},{"en":"reason","uz":"sabab","ipa":"ˈriː.zən"},{"en":"it depends","uz":"bunga bog'liq","ipa":"ɪt dɪˈpendz"}],"summary":["Tanlovni tartib bilan ayting: farq (A is cheaper, but B is better) → tanlov (I prefer B) → sabab (because …).","Foydali iboralar: I can't decide. In my opinion, … It depends. I agree.","Qiyoslashda: much faster, a bit more expensive, not as good as. ❌ more better, ❌ I am prefer.","Yangi so'zlar: decide, opinion, agree, choice, reason, it depends."]},{"id":"u14-l9","slug":"choosing-a-phone-comparing-products","title":"Choosing a phone: comparing products","titleUz":"Telefon tanlash: mahsulotlarni solishtirish","goal":"Do'konda ikki telefonni (yoki boshqa mahsulotni) solishtirishni o'rganasiz: qiyosiy va orttirma daraja, as ... as va too / enough yordamida narx, ekran, batareya va sifat haqida gapirasiz va tanlovingizni tushuntirasiz.","words":[{"en":"battery","uz":"batareya","ipa":"ˈbætəri"},{"en":"screen","uz":"ekran","ipa":"skriːn"},{"en":"brand","uz":"brend, marka","ipa":"brænd"},{"en":"charger","uz":"zaryadlagich","ipa":"ˈtʃɑːdʒə"},{"en":"discount","uz":"chegirma","ipa":"ˈdɪskaʊnt"},{"en":"lightweight","uz":"yengil (vazni kam)","ipa":"ˈlaɪtweɪt"}],"summary":["Ikki mahsulot: qiyosiy + than (The Nova is bigger than the Zed). Uch va ko'p: the + orttirma (the cheapest).","as ... as teng, not as ... as kamroq: The Zed isn't as good as the Nova.","too + sifat — muammo (too small); sifat + enough — yetarli (big enough).","Yangi so'zlar: battery, screen, brand, charger, discount, lightweight."]},{"id":"u14-l7","slug":"comparing-places","title":"Comparing places","titleUz":"Shaharlarni solishtirish: o'qish va yozish","goal":"Ikki shahar yoki joyni solishtirib o'qiysiz va yozasiz. but, however, while, whereas, both ... and, on the other hand kabi bog'lovchilarni ishlatasiz, shahar haqida gapirish uchun kerakli so'zlarni (traffic, climate, public transport, cost of living) bilib olasiz va 8–10 gapli kichik taqqoslash matnini yozasiz.","words":[{"en":"traffic","uz":"tirbandlik (transport oqimi)","ipa":"ˈtræfɪk"},{"en":"climate","uz":"iqlim","ipa":"ˈklaɪmət"},{"en":"public transport","uz":"jamoat transporti","ipa":"ˌpʌblɪk ˈtrænspɔːt"},{"en":"neighbourhood","uz":"mahalla, atrof","ipa":"ˈneɪbəhʊd"},{"en":"cost of living","uz":"yashash xarajatlari","ipa":"ˌkɒst əv ˈlɪvɪŋ"},{"en":"nightlife","uz":"tungi hayot","ipa":"ˈnaɪtlaɪf"},{"en":"suburb","uz":"shahar chekkasi","ipa":"ˈsʌbɜːb"},{"en":"sights","uz":"diqqatga sazovor joylar","ipa":"saɪts"},{"en":"safe","uz":"xavfsiz","ipa":"seɪf"},{"en":"lively","uz":"jonli, quvnoq","ipa":"ˈlaɪvli"}],"summary":["Farqni ko'rsatish: but, while / whereas (gap ichida), However, va On the other hand, (yangi gapda, vergul bilan). O'xshashlik: both ... and, too, also.","Miqdor: more + ot; sanaladigan ot uchun fewer, sanalmaydigan uchun less: fewer cars, less traffic.","Taqqoslash matni: kirish (ikki joy), asosiy qism (2–3 mavzu), xulosa (In my opinion... / I prefer...).","Xatolar: ❌ more bigger from, ❌ Both of cities, ❌ The people is. To'g'ri: bigger than, Both cities, The people are."]},{"id":"u14-l10","slug":"two-flats-to-rent-which-is-better","title":"Two flats to rent: which is better?","titleUz":"Ikki ijara uyi: qaysi biri yaxshi?","goal":"Ijaraga olinadigan ikki uyni narx, o'lcham va joylashuv bo'yicha solishtirasiz va nega bittasini tanlaganingizni inglizcha tushuntira olasiz: than, the most, as ... as, too, enough, both, however.","words":[{"en":"rent","uz":"ijara (haqi); ijaraga olmoq","ipa":"rent"},{"en":"landlord","uz":"uy egasi","ipa":"ˈlændlɔːd"},{"en":"bedroom","uz":"yotoqxona","ipa":"ˈbedruːm"},{"en":"balcony","uz":"balkon","ipa":"ˈbælkəni"},{"en":"furnished","uz":"mebelli","ipa":"ˈfɜːnɪʃt"},{"en":"bills","uz":"kommunal to'lovlar, hisoblar","ipa":"bɪlz"}],"summary":["Uylarni solishtirish: cheaper, more expensive, closer, bigger + than; uchtadan biri: the cheapest / the biggest.","too muammoni bildiradi (too far), enough sifatdan keyin keladi (big enough). too ... enough birga ishlatilmaydi.","Both + ko'plik: Both flats are nice. Qarama-qarshilik uchun: but, however.","Yangi so'zlar: rent, landlord, bedroom, balcony, furnished, bills."]},{"id":"u14-l15","slug":"reading-and-writing-describing-my-city","title":"Reading and writing: describing my city","titleUz":"O'qish va yozish: shahrimni tasvirlash","goal":"Shahar haqidagi qisqa matnlarni o'qib tushunasiz va o'z shahringiz haqida 5–7 gapli tavsif yozasiz: It is smaller than Tashkent, but it is quieter. In my opinion, it is the most beautiful city in Uzbekistan.","words":[{"en":"population","uz":"aholi","ipa":"ˌpɒp.jəˈleɪ.ʃən"},{"en":"historic","uz":"tarixiy","ipa":"hɪˈstɒr.ɪk"},{"en":"pollution","uz":"ifloslanish","ipa":"pəˈluː.ʃən"},{"en":"tourist","uz":"sayyoh","ipa":"ˈtʊə.rɪst"},{"en":"festival","uz":"festival, bayram","ipa":"ˈfes.tɪ.vəl"},{"en":"countryside","uz":"qishloq joy, tabiat","ipa":"ˈkʌn.tri.saɪd"}],"summary":["Shahar tavsifi: joy → boshqa shahar bilan solishtirish → eng yaxshi joy → ob-havo/transport → odamlar → fikr.","Qolip: smaller than …, one of the oldest cities in …, the most beautiful city in …, In my opinion, …","Ehtiyot bo'ling: ❌ more small, ❌ one of the oldest city, ❌ most beautiful city of Uzbekistan.","Yangi so'zlar: population, historic, pollution, tourist, festival, countryside."]},{"id":"u14-l8","slug":"unit-review-comparing","title":"Unit review: comparing","titleUz":"Bosqich takrori: taqqoslash","goal":"Butun bosqichni takrorlaysiz: qiyosiy va orttirma daraja, as ... as, too / enough, ravishlar, odamlarni tasvirlash va shaharlarni solishtirish. Aralash mashqlar orqali xatolaringizni topasiz va taqqoslash haqida erkin gapirishga tayyor bo'lasiz.","words":[{"en":"both","uz":"ikkalasi ham","ipa":"bəʊθ"},{"en":"whereas","uz":"holbuki, esa","ipa":"weərˈæz"},{"en":"however","uz":"biroq","ipa":"haʊˈevə"},{"en":"prefer","uz":"afzal ko'rmoq","ipa":"prɪˈfɜː"},{"en":"especially","uz":"ayniqsa","ipa":"ɪˈspeʃəli"},{"en":"although","uz":"garchi","ipa":"ɔːlˈðəʊ"},{"en":"instead","uz":"o'rniga","ipa":"ɪnˈsted"},{"en":"choose","uz":"tanlamoq","ipa":"tʃuːz"},{"en":"advantage","uz":"afzallik","ipa":"ədˈvɑːntɪdʒ"},{"en":"disadvantage","uz":"kamchilik","ipa":"ˌdɪsədˈvɑːntɪdʒ"}],"summary":["Qiyosiy: -er / more + than; orttirma: the -est / the most; good → better → the best, bad → worse → the worst.","as ... as (teng), not as ... as (kam), the same as, different from, similar to, look like.","too + sifat (muammo), sifat + enough, enough + ot, too much / too many.","Ravish: -ly, well (≠ good), hard / fast / early / late; qiyosiy: faster, more carefully. Tartib: fe'l + to'ldiruvchi + ravish.","Odamlarni tasvirlash: is tall, has curly hair, looks tired, What is he like? Shaharlarni solishtirish: while, whereas, however, both."]},{"id":"u14-l11","slug":"comparing-things-final-review","title":"Comparing things: final review","titleUz":"Taqqoslash: yakuniy takror","goal":"Bosqichni yakuniy takrorlaysiz: qiyosiy va orttirma daraja, as ... as / the same as, too / enough, ravishlar va odamlar hamda joylarni tasvirlash. Aralash mashqlar sizni taqqoslash haqida ishonchli gapirishga tayyorlaydi.","words":[{"en":"quality","uz":"sifat (sifatlilik)","ipa":"ˈkwɒləti"},{"en":"size","uz":"o'lcham","ipa":"saɪz"},{"en":"speed","uz":"tezlik","ipa":"spiːd"},{"en":"weight","uz":"og'irlik, vazn","ipa":"weɪt"},{"en":"cost","uz":"turmoq (narxi); narx","ipa":"kɒst"},{"en":"confident","uz":"o'ziga ishongan","ipa":"ˈkɒnfɪdənt"}],"summary":["Qiyosiy (-er / more + than) ikki narsa uchun; orttirma (the -est / the most) uch va undan ko'p uchun. good → better → the best.","as ... as, not as ... as, the same as, different from.","too + sifat (muammo), sifat + enough (yetarli).","Ravish: slowly, carefully, well, hard, fast. Tasvir: is tall, has curly hair, looks like, What is he like?","Yangi so'zlar: quality, size, speed, weight, cost, confident."]}]},{"id":"u15","n":15,"title":"Rules, advice and requests","titleUz":"Qoidalar, maslahat va iltimoslar: must, should, can / could","description":"Must, have to, should, can / could, muloyim iltimoslar, yo'l ko'rsatish va shifokorda.","canDo":["Majburiyat va maslahatni (must, have to, should) ayta olaman","Odobli iltimos va takliflar bildiraman","Yo'l ko'rsataman va shifokorda nima bezovta qilishini aytaman","Belgilar va qoidalarni tushunaman"],"lessons":[{"id":"u15-l1","slug":"must-and-have-to","title":"Must and have to","titleUz":"Must, have to, mustn't, don't have to","goal":"Majburiyatni must va have to bilan ifodalaysiz, ularning farqini bilasiz, eng muhimi — mustn't (\"mumkin emas\") bilan don't have to (\"shart emas\") ni adashtirmaysiz va I must to go, he musts kabi xatolardan qochasiz.","words":[{"en":"rule","uz":"qoida","ipa":"ruːl"},{"en":"obey","uz":"bo'ysunmoq, rioya qilmoq","ipa":"əˈbeɪ"},{"en":"necessary","uz":"zarur, kerakli","ipa":"ˈnesəsəri"},{"en":"forbidden","uz":"taqiqlangan","ipa":"fəˈbɪdn"},{"en":"compulsory","uz":"majburiy","ipa":"kəmˈpʌlsəri"},{"en":"deadline","uz":"oxirgi muddat","ipa":"ˈdedlaɪn"},{"en":"uniform","uz":"forma (kiyim)","ipa":"ˈjuːnɪfɔːm"},{"en":"fine","uz":"jarima","ipa":"faɪn"},{"en":"seat belt","uz":"xavfsizlik kamari","ipa":"ˈsiːt belt"},{"en":"on time","uz":"o'z vaqtida","ipa":"ɒn taɪm"}],"summary":["must va have to — majburiyat. must dan keyin to yo'q, -s yo'q: He must go. have to: He has to go.","mustn't = taqiq (You mustn't smoke here). don't have to = shart emas (You don't have to come).","must ning o'tgan va kelasi zamoni yo'q: had to, will have to.","have to da savol va inkor do / does / did bilan: Do I have to…? She doesn't have to…"]},{"id":"u15-l12","slug":"must-not-or-do-not-have-to","title":"Must not or do not have to?","titleUz":"Mustn't yoki don't have to? Farqini bilish","goal":"Mustn't (taqiq) bilan don't have to (shart emas) ni adashtirmaysiz, o'tgan zamonda had to / didn't have to dan foydalanasiz, needn't ni bilasiz va qoidalar hamda belgilarni to'g'ri tushuntirasiz.","words":[{"en":"optional","uz":"ixtiyoriy","ipa":"ˈɒp.ʃən.əl"},{"en":"ban","uz":"taqiqlamoq; taqiq","ipa":"bæn"},{"en":"enter","uz":"kirmoq","ipa":"ˈen.tə"},{"en":"in advance","uz":"oldindan","ipa":"ɪn ədˈvɑːns"},{"en":"unnecessary","uz":"keraksiz","ipa":"ʌnˈnes.ə.ser.i"}],"summary":["mustn't = taqiq (qilib bo'lmaydi). don't have to / needn't = shart emas (xohlasangiz qilasiz).","Tez sinov: qilsam muammo bo'ladimi? Ha — mustn't. Yo'q — don't have to.","O'tgan zamon: had to (kerak edi), didn't have to (shart emas edi), Did … have to …?","needn't + V1 (to yo'q): You needn't wait. Yangi so'zlar: optional, ban, enter, in advance, unnecessary."]},{"id":"u15-l2","slug":"should-and-shouldnt","title":"Should and shouldn't","titleUz":"Should / shouldn't: maslahat berish","goal":"should va shouldn't bilan maslahat berasiz va maslahat so'raysiz (What should I do?), I think you should… va If I were you, I'd… kabi tabiiy iboralarni ishlatasiz hamda should to go, an advice kabi xatolardan qochasiz.","words":[{"en":"advice","uz":"maslahat","ipa":"ədˈvaɪs"},{"en":"suggest","uz":"taklif qilmoq","ipa":"səˈdʒest"},{"en":"recommend","uz":"tavsiya qilmoq","ipa":"ˌrekəˈmend"},{"en":"sensible","uz":"oqilona, aqlli","ipa":"ˈsensəbl"},{"en":"stressed","uz":"stressda, asabiy","ipa":"strest"},{"en":"relax","uz":"dam olmoq, tinchlanmoq","ipa":"rɪˈlæks"},{"en":"habit","uz":"odat","ipa":"ˈhæbɪt"},{"en":"give up","uz":"voz kechmoq, tashlamoq","ipa":"ɡɪv ʌp"},{"en":"take a break","uz":"tanaffus qilmoq","ipa":"teɪk ə breɪk"},{"en":"enough","uz":"yetarli","ipa":"ɪˈnʌf"}],"summary":["should + V1 = maslahat: You should rest. shouldn't = \"…masligi kerak\": You shouldn't worry.","Savol: Should I…? / What should I do? — to, -s va do/does kerak emas.","Maslahat iboralari: I think you should…, I don't think you should…, If I were you, I'd…","advice — sanalmaydi: some advice, a piece of advice (an advice ❌, advices ❌)."]},{"id":"u15-l3","slug":"can-could-be-able-to","title":"Can, could, be able to","titleUz":"Can, could, be able to: qobiliyat va ruxsat","goal":"Qobiliyatni hozir, o'tmishda va kelajakda to'g'ri ifodalaysiz (can, could, was able to, will be able to), ruxsat so'raysiz (Can I…? Could I…?) va I will can, I can to swim kabi xatolardan qochasiz.","words":[{"en":"ability","uz":"qobiliyat","ipa":"əˈbɪləti"},{"en":"skill","uz":"malaka, ko'nikma","ipa":"skɪl"},{"en":"talent","uz":"iste'dod","ipa":"ˈtælənt"},{"en":"manage to","uz":"uddalamoq, ulgurmoq","ipa":"ˈmænɪdʒ tuː"},{"en":"permission","uz":"ruxsat","ipa":"pəˈmɪʃn"},{"en":"allowed","uz":"ruxsat etilgan","ipa":"əˈlaʊd"},{"en":"possible","uz":"mumkin, imkoni bor","ipa":"ˈpɒsəbl"},{"en":"impossible","uz":"imkonsiz","ipa":"ɪmˈpɒsəbl"},{"en":"be good at","uz":"…da yaxshi bo'lmoq","ipa":"bi ɡʊd æt"},{"en":"by myself","uz":"o'zim, yolg'iz o'zim","ipa":"baɪ maɪˈself"}],"summary":["can — hozirgi qobiliyat va ruxsat; could — o'tmishdagi umumiy qobiliyat va muloyim iltimos (Could I…?).","Bitta aniq voqea, uddalagan (musbat) → was / were able to yoki managed to: I was able to catch the bus.","Kelajak va Present Perfect uchun be able to: I will be able to…, I haven't been able to… (will can ❌).","Hamma modal fe'llardan keyin to yo'q va -s yo'q: I can swim (I can to swim ❌)."]},{"id":"u15-l4","slug":"polite-requests-and-offers","title":"Polite requests and offers","titleUz":"Muloyim iltimos va taklif: Could you…? Would you like…?","goal":"Iltimosni muloyim aytasiz (Could you…? Can I…? Would you…?), takliflar berasiz (Would you like…? Shall I…? I'll…), ularga to'g'ri javob qaytarasiz va Give me water! kabi qo'pol eshitiladigan gaplardan qochasiz.","words":[{"en":"request","uz":"iltimos, so'rov","ipa":"rɪˈkwest"},{"en":"offer","uz":"taklif qilmoq; taklif","ipa":"ˈɒfə"},{"en":"polite","uz":"muloyim, odobli","ipa":"pəˈlaɪt"},{"en":"favour","uz":"yaxshilik, xizmat","ipa":"ˈfeɪvə"},{"en":"borrow","uz":"so'rab olmoq","ipa":"ˈbɒrəʊ"},{"en":"lend","uz":"so'rab bermoq, qarzga bermoq","ipa":"lend"},{"en":"pass","uz":"uzatmoq","ipa":"pɑːs"},{"en":"accept","uz":"qabul qilmoq","ipa":"əkˈsept"},{"en":"decline","uz":"(muloyimlik bilan) rad etmoq","ipa":"dɪˈklaɪn"},{"en":"certainly","uz":"albatta","ipa":"ˈsɜːtnli"}],"summary":["Buyruq (Give me…) qo'pol eshitiladi. Muloyim: Could you…? va I'd like…; I want… ishlatmang.","Iltimos: Can / Could / Would you + V1? Ruxsat: Can / Could / May I + V1?","Taklif: Would you like + ot / to + fe'l?, Shall I + V1?, I'll + V1. (Do you like…? taklif emas!)","borrow = men olaman; lend = men beraman. Rad etganda ham muloyim bo'ling: Sorry, I can't… / No, thanks."]},{"id":"u15-l13","slug":"offers-and-suggestions","title":"Offers and suggestions","titleUz":"Takliflar: Shall I…? Let me… Why don't we…?","goal":"Yordam taklif qilasiz (Shall I…? Let me…), birgalikdagi rejani taklif qilasiz (Why don't we…? How about…?) va taklifga muloyim ravishda rozi bo'lasiz yoki rad etasiz.","words":[{"en":"carry","uz":"ko'tarmoq, olib yurmoq","ipa":"ˈkær.i"},{"en":"suggestion","uz":"taklif, fikr","ipa":"səˈdʒes.tʃən"},{"en":"I can manage","uz":"o'zim eplayman","ipa":"aɪ kæn ˈmæn.ɪdʒ"},{"en":"I'd rather not","uz":"xohlamas edim","ipa":"aɪd ˈrɑː.ðə nɒt"},{"en":"give someone a lift","uz":"mashinada olib bormoq","ipa":"gɪv ˈsʌm.wʌn ə lɪft"}],"summary":["Yordam taklifi: Shall I…? Can I…? Let me… + V1 (to yo'q). Shall faqat I va we bilan.","Taklif: Why don't we + V1?, How about + -ing?, Let's + V1, Shall we + V1?","Javob: Yes, please. / That would be great. — No, thanks. I can manage. / Sorry, I'd rather not.","Yangi so'zlar: carry, suggestion, I can manage, I'd rather not, give someone a lift."]},{"id":"u15-l9","slug":"a-friend-has-a-problem-giving-advice","title":"A friend has a problem: giving advice","titleUz":"Do'stning muammosi: maslahat berish","goal":"Do'stingiz muammosini aytganda unga should / shouldn't va Why don't you…? bilan muloyim maslahat bera olasiz va maslahat so'ray olasiz.","words":[{"en":"problem","uz":"muammo","ipa":"ˈprɒb.ləm"},{"en":"worried","uz":"xavotirli","ipa":"ˈwʌr.id"},{"en":"solution","uz":"yechim","ipa":"səˈluː.ʃn"},{"en":"decide","uz":"qaror qilmoq","ipa":"dɪˈsaɪd"},{"en":"mistake","uz":"xato","ipa":"mɪˈsteɪk"},{"en":"lonely","uz":"yolg'iz, o'zini yolg'iz his qilgan","ipa":"ˈləʊn.li"}],"summary":["Maslahat: You should + V1; qilmaslik haqida: You shouldn't + V1. To va -s yo'q.","Do'stona taklif: Why don't you + V1? — bu sabab so'rash emas.","Maslahat so'rash: What should I do?","advice sanalmaydi: some advice, a piece of advice."]},{"id":"u15-l5","slug":"giving-directions","title":"Giving directions","titleUz":"Yo'l ko'rsatish va tushuntirish","goal":"Yo'lni so'raysiz (How do I get to…? Is there a … near here?), yo'l ko'rsatasiz (turn left, go straight on, take the second turning), joylashuvni aytasiz (opposite, next to, between) va xaritadagi yo'nalishni inglizcha tushuntirasiz.","words":[{"en":"straight","uz":"to'g'ri (yo'nalish)","ipa":"streɪt"},{"en":"corner","uz":"burchak, ko'cha burchagi","ipa":"ˈkɔːnə"},{"en":"traffic lights","uz":"svetofor","ipa":"ˈtræfɪk laɪts"},{"en":"roundabout","uz":"aylana (yo'l)","ipa":"ˈraʊndəbaʊt"},{"en":"cross","uz":"kesib o'tmoq","ipa":"krɒs"},{"en":"bridge","uz":"ko'prik","ipa":"brɪdʒ"},{"en":"opposite","uz":"qarshisida","ipa":"ˈɒpəzɪt"},{"en":"between","uz":"o'rtasida","ipa":"bɪˈtwiːn"},{"en":"go past","uz":"yonidan o'tib ketmoq","ipa":"ɡəʊ pɑːst"},{"en":"turning","uz":"burilish (ko'cha)","ipa":"ˈtɜːnɪŋ"}],"summary":["Yo'lni so'rash: Excuse me, how do I get to…?, Is there a … near here?, Is it far?","Yo'nalish: Go straight on. Turn left / right. Take the second turning. Cross the road. Go past…","Joylashuv: next to, opposite, between … and …, behind, in front of, on the corner.","On the left / right (in emas). Yo'l tushuntirishda buyruq shakli qo'pol emas, tabiiy."]},{"id":"u15-l6","slug":"at-the-doctors","title":"At the doctor's","titleUz":"Shifokorda: kasallik va maslahat","goal":"Shifokorga yoki dorixonaga murojaat qilasiz: o'z holatingizni (I've got a headache, My back hurts, I feel dizzy) tushuntirasiz, What's the matter? kabi savollarga javob berasiz va should / shouldn't bilan oddiy kundalik maslahatlarni tushunasiz.","words":[{"en":"symptom","uz":"belgi (kasallik belgisi)","ipa":"ˈsɪmptəm"},{"en":"headache","uz":"bosh og'rig'i","ipa":"ˈhedeɪk"},{"en":"sore throat","uz":"tomoq og'rig'i","ipa":"sɔː θrəʊt"},{"en":"cough","uz":"yo'tal","ipa":"kɒf"},{"en":"temperature","uz":"isitma, harorat","ipa":"ˈtemprətʃə"},{"en":"appointment","uz":"qabulga yozilish, uchrashuv","ipa":"əˈpɔɪntmənt"},{"en":"ill","uz":"kasal","ipa":"ɪl"},{"en":"hurt","uz":"og'rimoq; lat yedirmoq","ipa":"hɜːt"},{"en":"pharmacy","uz":"dorixona","ipa":"ˈfɑːməsi"},{"en":"rest","uz":"dam; dam olmoq","ipa":"rest"}],"summary":["Savollar: What's the matter? Where does it hurt? When did it start?","Belgilar: I've got a headache / a cold / a cough / a sore throat. Og'riq: My back hurts. (I have headache ❌ — artikl kerak.)","Kundalik maslahat: You should rest / drink plenty of water / see a doctor. You shouldn't go to work.","I feel ill / bad (feel myself ❌). Qabul: I'd like to make an appointment. Jiddiy belgi bo'lsa — darhol shifokorga boring."]},{"id":"u15-l14","slug":"listening-and-speaking-at-the-doctors","title":"Listening and speaking: at the doctor's","titleUz":"Tinglash va gapirish: shifokorda","goal":"Shifokorning savollari va maslahatini tinglab tushunasiz, o'z shikoyatingizni aytasiz (I've got a stomach ache) va Could you repeat that, please? deb so'raysiz.","words":[{"en":"stomach ache","uz":"qorin og'rig'i","ipa":"ˈstʌm.ək eɪk"},{"en":"fever","uz":"isitma","ipa":"ˈfiː.və"},{"en":"medicine","uz":"dori","ipa":"ˈmed.sən"},{"en":"tablet","uz":"tabletka","ipa":"ˈtæb.lət"},{"en":"twice a day","uz":"kuniga ikki marta","ipa":"twaɪs ə deɪ"}],"summary":["Shikoyat: I've got a stomach ache. / My back hurts. / I feel sick. Shifokor: Where does it hurt? Do you have a fever?","Maslahat: You should… / You shouldn't…. Dori: once / twice / three times a day.","Tushunmasangiz: Could you repeat that, please? Could you speak more slowly?","Yangi so'zlar: stomach ache, fever, medicine, tablet, twice a day."]},{"id":"u15-l7","slug":"rules-and-signs","title":"Rules and signs","titleUz":"Qoidalar va belgilar: need to / needn't","goal":"need to (kerak) va don't need to / needn't (kerak emas) ni to'g'ri ishlatasiz, maktab, ish va yo'ldagi qoidalarni must / mustn't / have to bilan aytasiz hamda ingliz tilidagi eng keng tarqalgan belgi va yozuvlarni (No parking, Keep off the grass, Out of order) tushunasiz.","words":[{"en":"sign","uz":"belgi, yozuv","ipa":"saɪn"},{"en":"warning","uz":"ogohlantirish","ipa":"ˈwɔːnɪŋ"},{"en":"entrance","uz":"kirish joyi","ipa":"ˈentrəns"},{"en":"exit","uz":"chiqish joyi","ipa":"ˈeksɪt"},{"en":"queue","uz":"navbat","ipa":"kjuː"},{"en":"pedestrian","uz":"piyoda","ipa":"pəˈdestriən"},{"en":"speed limit","uz":"tezlik chegarasi","ipa":"ˈspiːd ˌlɪmɪt"},{"en":"out of order","uz":"ishlamaydi, buzilgan","ipa":"aʊt əv ˈɔːdə"},{"en":"give way","uz":"yo'l bermoq","ipa":"ɡɪv weɪ"},{"en":"keep off","uz":"yaqinlashmaslik, bosmaslik","ipa":"kiːp ɒf"}],"summary":["need to + V1 = kerak (She needs to go). Inkor va savol: don't / doesn't need to, Do I need to…?","Shart emas: don't need to, needn't (to yo'q!), don't have to. Taqiq: mustn't.","Qoidalar: must, mustn't, have to (Students must wear a uniform. You mustn't run.).","Belgilar: No parking, No smoking, Keep off the grass, Out of order, Give way, Exit — qisqa, ko'pincha taqiq."]},{"id":"u15-l10","slug":"rules-at-university-and-at-work","title":"Rules at university and at work","titleUz":"Universitet va ishdagi qoidalar","goal":"Universitet va ishdagi qoidalarni must / mustn't, have to / don't have to, need to / needn't va can / can't bilan tushuntira olasiz.","words":[{"en":"lecture","uz":"ma'ruza","ipa":"ˈlek.tʃər"},{"en":"attend","uz":"qatnashmoq","ipa":"əˈtend"},{"en":"library","uz":"kutubxona","ipa":"ˈlaɪ.brər.i"},{"en":"staff","uz":"xodimlar","ipa":"stɑːf"},{"en":"absent","uz":"yo'q, qatnashmagan","ipa":"ˈæb.sənt"},{"en":"assignment","uz":"topshiriq","ipa":"əˈsaɪn.mənt"}],"summary":["must / have to — majburiyat; mustn't — taqiq (qilmang!).","don't have to / don't need to / needn't — shart emas. needn't dan keyin to yo'q.","can — ruxsat bor; can't — ruxsat yo'q: You can't park here.","Savol: Do I have to…? Do you need to…? (Does she have to…?)"]},{"id":"u15-l15","slug":"reading-and-writing-signs-notices-and-advice","title":"Reading and writing: signs, notices and advice","titleUz":"O'qish va yozish: belgilar, e'lonlar va maslahat xati","goal":"Belgilar va e'lonlarni o'qib tushunasiz, do'stning maslahat xatini o'qiysiz va o'zingiz should / must / could bilan 4–6 gapli qisqa maslahat xati yozasiz.","words":[{"en":"notice","uz":"e'lon","ipa":"ˈnəʊ.tɪs"},{"en":"no entry","uz":"kirish mumkin emas","ipa":"nəʊ ˈen.tri"},{"en":"wet floor","uz":"ho'l pol","ipa":"wet flɔː"},{"en":"staff only","uz":"faqat xodimlar uchun","ipa":"stɑːf ˈəʊn.li"},{"en":"reply","uz":"javob bermoq; javob","ipa":"rɪˈplaɪ"}],"summary":["Belgilar qisqa: No entry = You mustn't go in. Free entry = You don't have to pay. Staff only = faqat xodimlar.","Maslahat xati: salom va hamdardlik, I think you should…, You could also…, You shouldn't…, yakun.","Hamma modal fe'ldan keyin to yo'q: You should rest, You could ask, You mustn't give up.","Yangi so'zlar: notice, no entry, wet floor, staff only, reply."]},{"id":"u15-l8","slug":"unit-review-modal-verbs","title":"Unit review: modal verbs","titleUz":"Bosqich takrori: modal fe'llar","goal":"Bosqichning barcha mavzularini takrorlaysiz: must / have to / mustn't / don't have to, should, can / could / be able to, muloyim iltimos va takliflar, yo'l ko'rsatish, shifokorda va belgilar (need to / needn't). Modal fe'llarni to'g'ri shaklda ishlatib, 8–10 gaplik mini-hikoya tuza olasiz.","words":[{"en":"obligation","uz":"majburiyat","ipa":"ˌɒblɪˈɡeɪʃn"},{"en":"regulation","uz":"qoida, nizom","ipa":"ˌreɡjuˈleɪʃn"},{"en":"essential","uz":"juda zarur","ipa":"ɪˈsenʃl"},{"en":"instructions","uz":"yo'riqnoma","ipa":"ɪnˈstrʌkʃnz"},{"en":"emergency","uz":"favqulodda holat","ipa":"ɪˈmɜːdʒənsi"},{"en":"rude","uz":"qo'pol, odobsiz","ipa":"ruːd"},{"en":"careful","uz":"ehtiyotkor","ipa":"ˈkeəfl"},{"en":"helpful","uz":"foydali; yordam beradigan","ipa":"ˈhelpfl"},{"en":"remind","uz":"eslatmoq","ipa":"rɪˈmaɪnd"},{"en":"ahead","uz":"oldinda; oldinga","ipa":"əˈhed"}],"summary":["must / have to — majburiyat, mustn't — taqiq, don't have to / don't need to / needn't — shart emas.","should — maslahat; can / could / was able to / will be able to — qobiliyat va ruxsat.","Muloyim iltimos: Could you…? Can I…?; taklif: Would you like…? Shall I…? I'll…","Yo'l ko'rsatish: go straight on, turn left, opposite, next to, between. Shifokorda: I've got a…, My… hurts, You should…","Eng ko'p xatolar: must to, he musts, should to, will can, an advice, I have headache."]},{"id":"u15-l11","slug":"rules-advice-and-requests-final-review","title":"Rules, advice and requests: final review","titleUz":"Qoidalar, maslahat va iltimoslar: yakuniy takror","goal":"Bosqichdagi hamma narsani takrorlaysiz: must / have to, should, can / could / be able to, muloyim iltimos va takliflar, yo'l ko'rsatish, shifokorda va belgilar. Bir kunlik vaziyatda to'g'ri ibora tanlay olasiz.","words":[{"en":"reception","uz":"qabulxona, registratura","ipa":"rɪˈsep.ʃn"},{"en":"prescription","uz":"retsept","ipa":"prɪˈskrɪp.ʃn"},{"en":"pavement","uz":"trotuar","ipa":"ˈpeɪv.mənt"},{"en":"switch off","uz":"o'chirmoq","ipa":"swɪtʃ ɒf"},{"en":"quiet","uz":"tinch, jim","ipa":"ˈkwaɪ.ət"},{"en":"receipt","uz":"chek","ipa":"rɪˈsiːt"}],"summary":["must / have to — majburiyat, mustn't — taqiq, don't have to / needn't — shart emas.","should — maslahat; can / could / be able to — qobiliyat va ruxsat.","Muloyim iltimos: Could you…? Can I…?; taklif: Would you like…? Shall I…?","Yo'l: How do I get to…? Turn left. It's next to… Shifokorda: I've got a…, My… hurts.","Modal fe'ldan keyin 1-shakl: must go, should rest, needn't wait."]}]},{"id":"u16","n":16,"title":"Experiences and the world around us","titleUz":"Tajriba va dunyo: Present Perfect, who / which, majhul nisbat","description":"Present Perfect va Past Simple, for / since, who / which / that, majhul nisbat, frazali fe'llar va xat yozish.","canDo":["Present Perfect va Past Simple ni to'g'ri tanlayman","for va since bilan davomiylikni ayta olaman","who / which / that bilan gapni murakkablashtiraman","Rasmiy va norasmiy email yozaman"],"lessons":[{"id":"u16-l1","slug":"present-perfect-or-past-simple","title":"Present Perfect or Past Simple?","titleUz":"Present Perfect yoki Past Simple?","goal":"Present Perfect (I've been to Khiva) va Past Simple (I went to Khiva last year) farqini tushunasiz, ever, never, just, already, yet so'zlarini to'g'ri joyga qo'yasiz va I have seen him yesterday kabi mashhur xatodan qochasiz.","words":[{"en":"experience","uz":"tajriba","ipa":"ɪkˈspɪə.ri.əns"},{"en":"adventure","uz":"sarguzasht","ipa":"ədˈven.tʃər"},{"en":"abroad","uz":"chet elda, chet elga","ipa":"əˈbrɔːd"},{"en":"recently","uz":"yaqinda, so'nggi paytlarda","ipa":"ˈriː.sənt.li"},{"en":"so far","uz":"hozirgacha, shu paytgacha","ipa":"səʊ fɑː"},{"en":"once","uz":"bir marta","ipa":"wʌns"},{"en":"twice","uz":"ikki marta","ipa":"twaɪs"},{"en":"journey","uz":"yo'l, safar","ipa":"ˈdʒɜː.ni"},{"en":"souvenir","uz":"esdalik sovg'a","ipa":"ˌsuː.vəˈnɪər"},{"en":"lucky","uz":"omadli","ipa":"ˈlʌk.i"}],"summary":["Present Perfect (have / has + V3): tajriba, yangilik, hozirga aloqasi bor ish — vaqt aytilmaydi.","Past Simple: aniq tugagan vaqt — yesterday, last week, in 2020, two days ago. When bilan savol ham Past Simple.","ever, never, just, already, yet — Present Perfect so'zlari: Have you ever…? I've never… She's just… We've already… Not yet.","Xato: ~~I have seen him yesterday~~. To'g'risi: I saw him yesterday.","Suhbat: Have you ever been to…? — Yes, I have. I went there last…"]},{"id":"u16-l12","slug":"present-perfect-ever-never-already-yet-just","title":"Present Perfect: ever, never, already, yet, just","titleUz":"Present Perfect: ever, never, already, yet, just","goal":"ever, never, already, yet, just so'zlarini gapda to'g'ri joyga qo'yasiz (I've never been to Japan. She's already left. They haven't arrived yet.) va have been bilan have gone farqini ajratasiz.","words":[{"en":"arrive","uz":"yetib kelmoq","ipa":"əˈraɪv"},{"en":"pack","uz":"(sumka) yig'moq","ipa":"pæk"},{"en":"book","uz":"band qilmoq, buyurtma bermoq","ipa":"bʊk"},{"en":"miss","uz":"o'tkazib yubormoq (poyezd, avtobus)","ipa":"mɪs"},{"en":"decide","uz":"qaror qilmoq","ipa":"dɪˈsaɪd"}],"summary":["ever, never, already, just — have va V3 orasida; yet — gap oxirida (inkor va savolda).","ever — savolda (Have you ever…?); never — darak gapda, haven't never deb bo'lmaydi.","Darak gapda yet yo'q: I've already finished ✅. Inkorda: I haven't finished yet ✅.","have been — borib qaytgan (tajriba); have gone — ketgan, hozir yo'q.","Yangi so'zlar: arrive, pack, book, miss, decide."]},{"id":"u16-l2","slug":"for-and-since","title":"For and since","titleUz":"For va since: how long?","goal":"How long have you lived here? savoliga for (for ten years) va since (since 2015) bilan javob berasiz va I live here since 2020 degan mashhur xatoni qilmaysiz.","words":[{"en":"move house","uz":"ko'chib o'tmoq","ipa":"muːv haʊs"},{"en":"neighbour","uz":"qo'shni","ipa":"ˈneɪ.bər"},{"en":"colleague","uz":"hamkasb","ipa":"ˈkɒl.iːɡ"},{"en":"member","uz":"a'zo","ipa":"ˈmem.bər"},{"en":"grow up","uz":"katta bo'lmoq, ulg'ayib voyaga yetmoq","ipa":"ɡrəʊ ʌp"},{"en":"own","uz":"egalik qilmoq","ipa":"əʊn"},{"en":"friendship","uz":"do'stlik","ipa":"ˈfrend.ʃɪp"},{"en":"for ages","uz":"juda uzoq vaqt, anchadan beri","ipa":"fɔːr ˈeɪ.dʒɪz"},{"en":"club","uz":"klub","ipa":"klʌb"},{"en":"since then","uz":"o'shandan beri","ipa":"sɪns ðen"}],"summary":["Davom etayotgan holat uchun: How long have you lived here? (Present Perfect), hozirgi zamon emas.","for + muddat (two years, ten minutes, ages); since + boshlanish nuqtasi (2019, Monday, I was ten).","Xatolar: I live here since 2020 ❌ → I have lived here since 2020 ✅. since two years ❌ → for two years.","ago Present Perfect bilan ishlatilmaydi: I moved here two years ago yoki I've lived here for two years.","Past Simple + for = tugagan davr: I lived in Bukhara for two years (endi yashamayman)."]},{"id":"u16-l3","slug":"relative-clauses","title":"Relative clauses","titleUz":"Who, which, that, where: ta'riflash","goal":"who, which, that, where yordamida gapni bog'laysiz (The man who lives next door is a doctor), narsa va odamlarni ta'riflaysiz va A dentist is a person who… kabi ta'rif berasiz. The book what I read xatosidan qochasiz.","words":[{"en":"dentist","uz":"tish shifokori","ipa":"ˈden.tɪst"},{"en":"tourist","uz":"sayyoh","ipa":"ˈtʊə.rɪst"},{"en":"mechanic","uz":"avtomexanik, mexanik","ipa":"məˈkæn.ɪk"},{"en":"bakery","uz":"novvoyxona, non do'koni","ipa":"ˈbeɪ.kər.i"},{"en":"pharmacy","uz":"dorixona","ipa":"ˈfɑː.mə.si"},{"en":"stadium","uz":"stadion","ipa":"ˈsteɪ.di.əm"},{"en":"tool","uz":"asbob, qurol","ipa":"tuːl"},{"en":"kettle","uz":"choynak (elektr)","ipa":"ˈket.əl"},{"en":"cousin","uz":"amakivachcha, xolavachcha","ipa":"ˈkʌz.ən"},{"en":"guest","uz":"mehmon","ipa":"ɡest"}],"summary":["who — odamlar, which — narsalar, that — odam yoki narsa, where — joylar.","Defining gapda vergul yo'q: The man who lives next door is a dentist. Ot oldin, tushuntirish keyin keladi.","Xatolar: ~~the book what I read~~ → the book (that) I read; ~~the man who he lives~~ → the man who lives.","To'ldiruvchi bo'lsa that / which ni tushirish mumkin: The film (that) we saw was long.","Ta'rif: A … is a person who / a thing that / a place where …"]},{"id":"u16-l4","slug":"the-passive","title":"The passive","titleUz":"Majhul nisbat: is made, was built","goal":"Present Simple va Past Simple majhul nisbatini tuzasiz (Cars are made in factories. The cake was baked by my mother), by ni faqat kerak bo'lganda qo'shasiz va I born, was happened kabi xatolardan qochasiz.","words":[{"en":"factory","uz":"zavod, fabrika","ipa":"ˈfæk.tər.i"},{"en":"produce","uz":"ishlab chiqarmoq","ipa":"prəˈdjuːs"},{"en":"build – built – built","uz":"qurmoq","ipa":"bɪld – bɪlt – bɪlt"},{"en":"invent","uz":"ixtiro qilmoq","ipa":"ɪnˈvent"},{"en":"repair","uz":"ta'mirlamoq","ipa":"rɪˈpeər"},{"en":"steal – stole – stolen","uz":"o'g'irlamoq","ipa":"stiːl – stəʊl – ˈstəʊ.lən"},{"en":"invite","uz":"taklif qilmoq","ipa":"ɪnˈvaɪt"},{"en":"deliver","uz":"yetkazib bermoq","ipa":"dɪˈlɪv.ər"},{"en":"damage","uz":"shikast yetkazmoq, zarar bermoq","ipa":"ˈdæm.ɪdʒ"},{"en":"discover","uz":"kashf qilmoq, topmoq","ipa":"dɪˈskʌv.ər"}],"summary":["Passive = be + V3. Present: Cars are made in factories. Past: The window was broken.","Savol va inkorda faqat be o'zgaradi: Is plov cooked here? The window wasn't broken. do / did kerak emas.","by + kim faqat ish bajaruvchi muhim bo'lsa: The cake was baked by my mother. Aks holda yozmang.","Xatolar: Cars made… (be yo'q), was broke (V2), was happened (o'timsiz fe'l), I born (to'g'risi: I was born)."]},{"id":"u16-l13","slug":"the-passive-past-and-questions","title":"The passive: past and questions","titleUz":"Majhul nisbat: o'tgan zamon va savollar","goal":"O'tgan zamon majhul nisbatida savol (When was the phone invented?) va inkor (The window wasn't broken) tuzasiz, by bilan ish bajaruvchini ko'rsatasiz va gapni active ↔ passive ga aylantirasiz.","words":[{"en":"paint","uz":"rasm chizmoq, bo'yamoq","ipa":"peɪnt"},{"en":"design","uz":"loyihalamoq, dizayn qilmoq","ipa":"dɪˈzaɪn"},{"en":"destroy","uz":"vayron qilmoq","ipa":"dɪˈstrɔɪ"},{"en":"publish","uz":"nashr qilmoq","ipa":"ˈpʌb.lɪʃ"},{"en":"translate","uz":"tarjima qilmoq","ipa":"trænzˈleɪt"}],"summary":["Active → passive: to'ldiruvchi ega bo'ladi + was / were + V3 (+ by + kim, kerak bo'lsa).","Savol: Was / Were + ega + V3? Was the window broken? Wh-: When was the phone invented? — did kerak emas.","Inkor: wasn't / weren't + V3. Tartibsiz fe'llarda V2 emas, V3: written, broken, taken, sent.","by faqat ish bajaruvchi muhim bo'lsa: painted by Leonardo. somebody / people bilan yozilmaydi.","Yangi so'zlar: paint, design, destroy, publish, translate."]},{"id":"u16-l5","slug":"phrasal-verbs","title":"Phrasal verbs","titleUz":"Frazali fe'llar: get up, look for, turn on","goal":"10 ta eng ko'p ishlatiladigan frazali fe'lni (get up, turn on/off, look for, put on, take off, give up, find out, come back, wake up, sit down) o'rganasiz va ulardan ajraladiganlari (turn it on) bilan ajralmaydiganlarini (look for it) farqlaysiz.","words":[{"en":"get up","uz":"o'rnidan turmoq","ipa":"ɡet ʌp"},{"en":"turn on / turn off","uz":"yoqmoq / o'chirmoq","ipa":"tɜːn ɒn / tɜːn ɒf"},{"en":"look for","uz":"qidirmoq","ipa":"lʊk fɔː"},{"en":"put on","uz":"kiymoq","ipa":"pʊt ɒn"},{"en":"take off","uz":"yechmoq","ipa":"teɪk ɒf"},{"en":"give up","uz":"taslim bo'lmoq, tashlamoq","ipa":"ɡɪv ʌp"},{"en":"find out","uz":"bilib olmoq, aniqlamoq","ipa":"faɪnd aʊt"},{"en":"come back","uz":"qaytib kelmoq","ipa":"kʌm bæk"},{"en":"wake up","uz":"uyg'onmoq","ipa":"weɪk ʌp"},{"en":"sit down","uz":"o'tirmoq","ipa":"sɪt daʊn"}],"summary":["Frazali fe'l = fe'l + kichik so'z; ma'nosi o'zgaradi: look → look for, give → give up.","To'ldiruvchisiz: wake up, get up, sit down, come back. To'ldiruvchili: turn on/off, put on, take off, look for, give up, find out.","Ajraladigan fe'llarda olmosh o'rtada: turn it on, put them on, take it off. ❌ turn on it.","Ajralmaydigan: look for it, find out the answer.","wake up (uyg'onmoq) ≠ get up (o'rnidan turmoq); put on (kiymoq) ≠ wear (kiyib yurmoq)."]},{"id":"u16-l9","slug":"travel-experiences-have-you-ever","title":"Travel experiences: have you ever…?","titleUz":"Sayohat tajribasi: Have you ever…?","goal":"Sayohat haqida suhbatda Have you ever…? deb so'raysiz, Yes, I have / No, I haven't deb javob berasiz, keyin esa Past Simple bilan tafsilot (qachon, qayerda) aytasiz. Shuningdek, for va since bilan qancha vaqtdan beri yashayotganingizni aytasiz.","words":[{"en":"passport","uz":"pasport","ipa":"ˈpɑːspɔːt"},{"en":"flight","uz":"parvoz, reys","ipa":"flaɪt"},{"en":"luggage","uz":"yuk, bagaj","ipa":"ˈlʌɡɪdʒ"},{"en":"tour","uz":"ekskursiya, sayohat","ipa":"tʊə"},{"en":"view","uz":"manzara, ko'rinish","ipa":"vjuː"},{"en":"beach","uz":"plyaj, qirg'oq","ipa":"biːtʃ"}],"summary":["Tajribani so'rash: Have you ever + V3? Javob: Yes, I have. / No, I haven't.","Hech qachon bo'lmagan ish: I have never + V3.","Tafsilot (qachon, qayerda) so'ralsa yoki aniq vaqt bor bo'lsa — Past Simple.","Davom etayotgan holat: for + muddat, since + boshlanish nuqtasi."]},{"id":"u16-l6","slug":"question-tags","title":"Question tags","titleUz":"Tasdiq savollari: isn't it? don't you?","goal":"Gap oxiriga to'g'ri question tag qo'shasiz (It's cold, isn't it? You like plov, don't you?), short answer (Yes, I do. No, I can't.) bilan javob berasiz va har gapga isn't it? qo'shish xatosidan qochasiz.","words":[{"en":"probably","uz":"ehtimol, katta ehtimol bilan","ipa":"ˈprɒb.ə.bli"},{"en":"definitely","uz":"shubhasiz, albatta","ipa":"ˈdef.ɪ.nət.li"},{"en":"obviously","uz":"ravshanki, shubhasiz","ipa":"ˈɒb.vi.əs.li"},{"en":"exactly","uz":"aynan, aniq","ipa":"ɪɡˈzækt.li"},{"en":"actually","uz":"aslida, haqiqatan","ipa":"ˈæk.tʃu.ə.li"},{"en":"perhaps","uz":"balki","ipa":"pəˈhæps"},{"en":"certainly","uz":"albatta, shubhasiz","ipa":"ˈsɜː.tən.li"},{"en":"anyway","uz":"baribir, har holda","ipa":"ˈen.i.weɪ"},{"en":"honestly","uz":"rostini aytsam","ipa":"ˈɒn.ɪst.li"},{"en":"apparently","uz":"ko'rinishidan, aytishlaricha","ipa":"əˈpær.ənt.li"}],"summary":["Darak gap (+) → inkor tag (−): She likes tea, doesn't she? Inkor gap (−) → darak tag (+): He can't swim, can he?","Tag gapdagi yordamchi fe'lni takrorlaydi; yo'q bo'lsa do / does / did. Tagda ot emas, olmosh (he, she, they, there).","Alohida: I'm late, aren't I? Let's go, shall we? Open the window, will you?","Qisqa javob: Yes / No + olmosh + yordamchi fe'l. Yes/No haqiqatga qarab aytiladi: You don't like coffee, do you? — Yes, I do.","isn't it? ni har gapga qo'shmang: tag gapga moslashadi."]},{"id":"u16-l10","slug":"explaining-what-something-is","title":"Explaining what something is","titleUz":"Narsa nima ekanini tushuntirish","goal":"Inglizcha so'zni bilmasangiz ham, uni who / which / that / where bilan ta'riflab tushuntira olasiz (It's a thing that…, It's a place where…) va majhul nisbat bilan qayerda, nimadan yasalganini aytasiz (It is made of…).","words":[{"en":"describe","uz":"ta'riflamoq","ipa":"dɪˈskraɪb"},{"en":"device","uz":"qurilma, asbob","ipa":"dɪˈvaɪs"},{"en":"container","uz":"idish, quti","ipa":"kənˈteɪnə"},{"en":"machine","uz":"mashina, apparat","ipa":"məˈʃiːn"},{"en":"material","uz":"material, xomashyo","ipa":"məˈtɪəriəl"},{"en":"useful","uz":"foydali","ipa":"ˈjuːsfl"}],"summary":["Odam → who (yoki that); narsa → that / which; joy → where. what bunday ishlatilmaydi.","So'zni bilmasangiz tushuntiring: It's a thing that…, It's a person who…, It's a place where…","Majhul nisbat: is / are / was / were + V3 (is made of wood, was built in 1990)."]},{"id":"u16-l14","slug":"listening-and-speaking-talking-about-experiences","title":"Listening and speaking: talking about experiences","titleUz":"Tinglash va gapirish: tajribalar haqida suhbat","goal":"Sayohat va yangi tajribalar haqidagi suhbatni tinglab tushunasiz va o'zingiz aytib berasiz: I've been to Khiva twice. I went there last spring. It was amazing!","words":[{"en":"amazing","uz":"ajoyib, hayratlanarli","ipa":"əˈmeɪ.zɪŋ"},{"en":"unforgettable","uz":"unutilmas","ipa":"ˌʌn.fəˈɡet.ə.bəl"},{"en":"disappointing","uz":"ko'ngilsiz, umidni puchga chiqaruvchi","ipa":"ˌdɪs.əˈpɔɪn.tɪŋ"},{"en":"exhausting","uz":"charchatuvchi","ipa":"ɪɡˈzɔː.stɪŋ"},{"en":"worth visiting","uz":"borishga arziydi","ipa":"wɜːθ ˈvɪz.ɪ.tɪŋ"},{"en":"highlight","uz":"eng yorqin lahza, eng yaxshi qism","ipa":"ˈhaɪ.laɪt"}],"summary":["Suhbat tartibi: Have you ever…? (tajriba) → When / Who with / How long…? (Past Simple) → What was it like? (fikr).","Fikr bildirish: amazing, unforgettable, disappointing, exhausting; maqtash: It's worth visiting.","What was it like? — «qanday edi?», Did you like it? emas.","Suhbatni davom ettiring: And you? Have you ever tried it?"]},{"id":"u16-l7","slug":"writing-an-email","title":"Writing an email","titleUz":"Elektron xat yozish: do'stga va rasmiy","goal":"Elektron xatning tuzilishini bilasiz (mavzu, salomlashish, asosiy qism, xayrlashuv), do'stingizga norasmiy, notanish odamga esa muloyim rasmiy xat yozasiz (I am writing to ask… Could you please…? Yours sincerely) va ikkala uslubni aralashtirmaysiz.","words":[{"en":"subject","uz":"mavzu (xatning)","ipa":"ˈsʌbdʒɪkt"},{"en":"greeting","uz":"salomlashish","ipa":"ˈɡriːtɪŋ"},{"en":"sincerely","uz":"hurmat bilan (xat oxirida)","ipa":"sɪnˈsɪəli"},{"en":"apologise","uz":"uzr so'ramoq","ipa":"əˈpɒlədʒaɪz"},{"en":"confirm","uz":"tasdiqlamoq","ipa":"kənˈfɜːm"},{"en":"request","uz":"iltimos, so'rov","ipa":"rɪˈkwest"},{"en":"available","uz":"bo'sh, mavjud","ipa":"əˈveɪləbl"},{"en":"keep in touch","uz":"aloqada bo'lmoq","ipa":"kiːp ɪn tʌtʃ"},{"en":"look forward to","uz":"intizorlik bilan kutmoq","ipa":"lʊk ˈfɔːwəd tuː"},{"en":"message","uz":"xabar","ipa":"ˈmesɪdʒ"}],"summary":["Xat tuzilishi: mavzu → salomlashish → asosiy qism → yakun → xayrlashuv.","Norasmiy: Hi, Thanks for your email, Write soon, Best wishes — qisqartmalar mumkin.","Rasmiy: Dear Mr / Ms…, I am writing to…, Could you please…?, I look forward to hearing from you, Yours sincerely / faithfully.","Ismi ma'lum → sincerely; ismi noma'lum (Sir or Madam) → faithfully.","Uslublarni aralashtirmang va rasmiy xatda buyruq o'rniga Could you please…? ishlating."]},{"id":"u16-l15","slug":"reading-and-writing-a-blog-post-about-a-trip","title":"Reading and writing: a blog post about a trip","titleUz":"O'qish va yozish: sayohat haqida blog yozuvi","goal":"Sayohat haqidagi qisqa blog yozuvini o'qib tushunasiz va o'zingiz 6–8 gapli yozuv yozasiz: I went there last weekend. The old city was built long ago. I have never seen such a beautiful place.","words":[{"en":"blog","uz":"blog, internet kundalik","ipa":"blɒɡ"},{"en":"comment","uz":"izoh, fikr","ipa":"ˈkɒm.ent"},{"en":"reader","uz":"o'quvchi","ipa":"ˈriː.dər"},{"en":"recommend","uz":"tavsiya qilmoq","ipa":"ˌrek.əˈmend"},{"en":"courtyard","uz":"hovli","ipa":"ˈkɔːt.jɑːd"}],"summary":["Blog tuzilishi: boshlanish → voqealar → joy haqida → fikr → o'quvchiga savol.","Voqealar — Past Simple (We stayed…), tajriba — Present Perfect (I have never seen…), joy tarixi — passive (was built).","Aniq vaqt bor gapda have ishlatmang: Last week I visited… ✅.","Yangi so'zlar: blog, comment, reader, recommend, courtyard."]},{"id":"u16-l8","slug":"unit-review-experiences","title":"Unit review: experiences","titleUz":"Bosqich takrori: tajriba va dunyo","goal":"Bosqichni mustahkamlaysiz: Present Perfect va Past Simple, for / since, who / which / that / where, majhul nisbat, frazali fe'llar, question tag va xat yozish — hammasini bitta matn va aralash mashqlarda ishlatasiz.","words":[{"en":"article","uz":"maqola","ipa":"ˈɑːtɪkl"},{"en":"century","uz":"asr","ipa":"ˈsentʃəri"},{"en":"invention","uz":"ixtiro","ipa":"ɪnˈvenʃn"},{"en":"popular","uz":"mashhur, ommabop","ipa":"ˈpɒpjələ"},{"en":"traditional","uz":"an'anaviy","ipa":"trəˈdɪʃənl"},{"en":"modern","uz":"zamonaviy","ipa":"ˈmɒdn"},{"en":"local","uz":"mahalliy","ipa":"ˈləʊkl"},{"en":"nearby","uz":"yaqin atrofda","ipa":"ˌnɪəˈbaɪ"},{"en":"wonder","uz":"hayratlanarli narsa; hayron bo'lmoq","ipa":"ˈwʌndə"},{"en":"similar","uz":"o'xshash","ipa":"ˈsɪmələ"}],"summary":["Present Perfect — tajriba va natija (vaqtsiz); Past Simple — aniq tugagan vaqt.","for + muddat, since + boshlanish; ago faqat Past Simple bilan.","who / which / that / where otdan keyin tushuntirish beradi; what ishlatilmaydi.","Passive: be + V3; frazali fe'llarda olmosh o'rtada (turn it on).","Question tag gapdagi yordamchi fe'lga qarab o'zgaradi; xat uslubi bir xil bo'lsin."]},{"id":"u16-l11","slug":"experiences-and-the-world-final-review","title":"Experiences and the world: final review","titleUz":"Tajriba va dunyo: yakuniy takror","goal":"Bosqichning hammasini bir joyda takrorlaysiz: Present Perfect va Past Simple, for / since, who / which / that / where, majhul nisbat, frazali fe'llar, question tag va do'stga xat yozish — va ularni qisqa xat va savollarda ishlatasiz.","words":[{"en":"festival","uz":"festival, bayram","ipa":"ˈfestɪvl"},{"en":"tradition","uz":"an'ana","ipa":"trəˈdɪʃn"},{"en":"culture","uz":"madaniyat","ipa":"ˈkʌltʃə"},{"en":"celebrate","uz":"nishonlamoq","ipa":"ˈselɪbreɪt"},{"en":"guidebook","uz":"yo'l ko'rsatkich kitob","ipa":"ˈɡaɪdbʊk"},{"en":"attraction","uz":"diqqatga sazovor joy","ipa":"əˈtrækʃn"}],"summary":["Tajriba — Present Perfect; aniq vaqt (yesterday, ago, in 2020) — Past Simple.","for + muddat, since + boshlanish nuqtasi.","who (odam), which / that (narsa), where (joy); passive: be + V3.","Frazali fe'lda olmosh o'rtada (turn it off); question tag qarama-qarshi bo'ladi.","Do'stga xat norasmiy: Hi, … Best wishes; rasmiy xat: Dear …, Yours sincerely."]}]},{"id":"u17","n":17,"title":"Work, money and everyday life","titleUz":"Ish, pul va kundalik hayot: suhbatlar va yozish","description":"Fe'l qoliplari, kasblar, pul va xaridlar, texnologiya, sayohat, restoran va A2 yakuniy takrori.","canDo":["Ish suhbatida o'zimni tanishtiraman","Do'konda, mehmonxonada va restoranda muammosiz muomala qilaman","Qisqa CV va xabar yozaman","Texnologiya haqida gapiraman"],"lessons":[{"id":"u17-l1","slug":"like-doing-or-want-to-do","title":"Like doing or want to do?","titleUz":"Fe'l qolipi: like doing, want to do","goal":"Ikki fe'l ketma-ket kelganda -ing yoki to + V1 ni to'g'ri tanlaysiz: enjoy swimming, want to go, would like to ask. Shuningdek Let's…, Why don't we…?, How about…? bilan taklif qilishni o'rganasiz va I like swim, I want go, enjoy to kabi xatolardan qutulasiz.","words":[{"en":"enjoy","uz":"zavqlanmoq, yoqtirmoq","ipa":"ɪnˈdʒɔɪ"},{"en":"hate","uz":"yomon ko'rmoq","ipa":"heɪt"},{"en":"hope","uz":"umid qilmoq","ipa":"həʊp"},{"en":"decide","uz":"qaror qilmoq","ipa":"dɪˈsaɪd"},{"en":"plan","uz":"rejalashtirmoq","ipa":"plæn"},{"en":"prefer","uz":"afzal ko'rmoq","ipa":"prɪˈfɜː"},{"en":"finish","uz":"tugatmoq","ipa":"ˈfɪnɪʃ"},{"en":"practise","uz":"mashq qilmoq","ipa":"ˈpræktɪs"},{"en":"refuse","uz":"rad etmoq, ko'nmaslik","ipa":"rɪˈfjuːz"},{"en":"promise","uz":"va'da bermoq","ipa":"ˈprɒmɪs"}],"summary":["enjoy, finish, stop, practise + -ing: I enjoy swimming. Hech qachon enjoy to swim emas.","want, need, hope, decide, plan, promise + to + V1: I want to go. \"to\" ni tushirib qoldirmang.","like, love, hate, prefer + -ing — umumiy yoqtirish; would like to + V1 — hozirgi yoki yaqin istak va muloyim iltimos.","Taklif: Let's / Why don't we / Shall we + V1, How about + -ing."]},{"id":"u17-l12","slug":"verb-patterns-stop-remember-try","title":"Verb patterns: stop, remember, try","titleUz":"Fe'l qoliplari: stop, remember, try + -ing yoki to","goal":"stop, remember, forget, try dan keyin -ing va to + V1 ning ma'no farqini bilasiz (stop smoking ≠ stop to smoke) va like / love / hate / enjoy / finish / mind + -ing, want / hope / plan / decide / need + to qoliplarini aralashtirmaysiz.","words":[{"en":"remember","uz":"eslamoq, esda tutmoq","ipa":"rɪˈmem.bə"},{"en":"forget","uz":"unutmoq","ipa":"fəˈɡet"},{"en":"try","uz":"urinmoq; sinab ko'rmoq","ipa":"traɪ"},{"en":"stop","uz":"to'xtamoq; to'xtatmoq","ipa":"stɒp"},{"en":"mind","uz":"qarshi bo'lmoq, ko'ngliga olmoq","ipa":"maɪnd"},{"en":"give up","uz":"taslim bo'lmoq, tashlamoq","ipa":"ɡɪv ˈʌp"}],"summary":["like, love, hate, enjoy, finish, mind + -ing; want, hope, plan, decide, need + to + V1.","stop + -ing = tashlamoq; stop + to + V1 = boshqa ish uchun to'xtamoq.","remember / forget + to + V1 = kerakli ishni esda tutmoq / unutmoq; remember + -ing = o'tgan voqeani eslamoq.","try + -ing = sinab ko'rmoq; try + to + V1 = urinmoq.","Yangi so'zlar: remember, forget, try, stop, mind, give up."]},{"id":"u17-l2","slug":"jobs-and-interviews","title":"Jobs and interviews","titleUz":"Kasblar va ish suhbati","goal":"Kasblar nomini artikl bilan to'g'ri aytasiz (I'm an engineer), work as / for / in farqini bilasiz, I've worked here for five years kabi tajribangiz haqida gapirasiz va ish suhbatida o'zingizni tanishtirish, kuchli tomonlaringizni aytish hamda oddiy savollarga javob berishni o'rganasiz.","words":[{"en":"apply","uz":"ishga murojaat qilmoq","ipa":"əˈplaɪ"},{"en":"interview","uz":"ish suhbati","ipa":"ˈɪntəvjuː"},{"en":"experience","uz":"tajriba","ipa":"ɪkˈspɪəriəns"},{"en":"salary","uz":"oylik maosh","ipa":"ˈsæləri"},{"en":"colleague","uz":"hamkasb","ipa":"ˈkɒliːɡ"},{"en":"manager","uz":"menejer, boshliq","ipa":"ˈmænɪdʒə"},{"en":"skill","uz":"ko'nikma","ipa":"skɪl"},{"en":"part-time","uz":"yarim kunlik","ipa":"ˌpɑːt ˈtaɪm"},{"en":"full-time","uz":"to'liq kunlik","ipa":"ˌfʊl ˈtaɪm"},{"en":"reliable","uz":"ishonchli","ipa":"rɪˈlaɪəbl"}],"summary":["Kasb oldidan a / an: I'm a nurse, She's an engineer. Ko'plikda artikl yo'q.","work as (lavozim), work for (kompaniya), work in / at (joy).","Hozirgacha davom etayotgan ish: have / has + V3 + for / since: I've worked here for 3 years.","Kuchli tomonlar: I'm + sifat, I'm good at + -ing, I can + V1.","Suhbatda muloyim va aniq bo'ling: I'd like to…, Thank you for your time."]},{"id":"u17-l3","slug":"money-and-shopping","title":"Money and shopping","titleUz":"Pul va xaridlar: narx, chegirma, qaytarish","goal":"Do'konda va bozorda narxni so'raysiz (How much is it? How much are these?), narxlarni to'g'ri aytasiz, chegirma so'raysiz, naqd yoki karta bilan to'laysiz, tovarni qaytarasiz va muammo bo'lsa muloyim shikoyat qilasiz. How much costs? kabi xatolardan qochasiz.","words":[{"en":"price","uz":"narx","ipa":"praɪs"},{"en":"discount","uz":"chegirma","ipa":"ˈdɪskaʊnt"},{"en":"receipt","uz":"chek","ipa":"rɪˈsiːt"},{"en":"change","uz":"qaytim; maydalangan pul","ipa":"tʃeɪndʒ"},{"en":"refund","uz":"pulni qaytarish","ipa":"ˈriːfʌnd"},{"en":"cash","uz":"naqd pul","ipa":"kæʃ"},{"en":"bargain","uz":"arzon va foydali xarid","ipa":"ˈbɑːɡɪn"},{"en":"cheap","uz":"arzon","ipa":"tʃiːp"},{"en":"expensive","uz":"qimmat","ipa":"ɪkˈspensɪv"},{"en":"afford","uz":"imkoni bo'lmoq (pul jihatdan)","ipa":"əˈfɔːd"}],"summary":["Narx so'rash: How much is / are…? yoki How much does / do… cost? — hech qachon How much costs? emas.","Narxlar: forty-five thousand so'm — thousand / hundred / million son bilan -s olmaydi.","To'lov: pay by card / in cash, Keep the change, Could I have a receipt?","Qaytarish: I bought this yesterday, but it doesn't work. Could I have a refund / exchange it?","Shikoyatda muloyim bo'ling: Excuse me, I'm sorry, but…, Could you…?"]},{"id":"u17-l13","slug":"quantity-words","title":"Quantity words","titleUz":"Miqdor so'zlari: a lot of, much, many, a few, a little, enough","goal":"Sanaladigan va sanalmaydigan otlar bilan a lot of, much, many, a few, a little, enough ni to'g'ri tanlaysiz, How much / How many savollarini tuzasiz va xarid hamda pul haqida I don't have much money, There are a few apples kabi gaplar aytasiz.","words":[{"en":"budget","uz":"byudjet","ipa":"ˈbʌdʒ.ɪt"},{"en":"plenty of","uz":"yetarlicha ko'p","ipa":"ˈplen.ti əv"},{"en":"a few","uz":"bir nechta","ipa":"ə ˈfjuː"},{"en":"a little","uz":"ozgina","ipa":"ə ˈlɪt.əl"},{"en":"enough","uz":"yetarli","ipa":"ɪˈnʌf"},{"en":"queue","uz":"navbat","ipa":"kjuː"}],"summary":["Sanaladigan ot: many, a few, few. Sanalmaydigan ot: much, a little, little. Ikkalasi bilan: a lot of, enough, plenty of.","Savol va inkor: How many / How much, not many / not much. Darak gapda a lot of.","a few / a little — bor (ijobiy); few / little — deyarli yo'q.","enough + ot (enough money), sifat + enough (big enough); ortiqcha: too much / too many.","Yangi so'zlar: budget, plenty of, a few, a little, enough, queue."]},{"id":"u17-l4","slug":"technology","title":"Technology","titleUz":"Texnologiya va internet","goal":"Telefon, kompyuter va internet haqidagi kundalik so'zlarni bilasiz (battery, screen, password, download, log in), texnik muammoni tushuntirasiz, qadam-baqadam ko'rsatma berasiz (First… Then… Don't forget to…), qisqa onlayn xabarlar yozasiz va telefon suhbatini olib borasiz (Who's calling? Hold on. I'll call you back.).","words":[{"en":"battery","uz":"batareya","ipa":"ˈbætəri"},{"en":"screen","uz":"ekran","ipa":"skriːn"},{"en":"password","uz":"parol","ipa":"ˈpɑːswɜːd"},{"en":"charger","uz":"zaryadlovchi","ipa":"ˈtʃɑːdʒə"},{"en":"download","uz":"yuklab olmoq","ipa":"ˌdaʊnˈləʊd"},{"en":"website","uz":"veb-sayt","ipa":"ˈwebsaɪt"},{"en":"online","uz":"onlayn, internetda","ipa":"ˌɒnˈlaɪn"},{"en":"update","uz":"yangilamoq","ipa":"ˌʌpˈdeɪt"},{"en":"log in","uz":"tizimga kirmoq","ipa":"lɒɡ ɪn"},{"en":"delete","uz":"o'chirib tashlamoq","ipa":"dɪˈliːt"}],"summary":["Asosiy so'zlar: battery, screen, charger, password, download, log in, update, delete.","Frazali fe'llarda olmosh o'rtada: turn it off, plug it in; ot bilan ikkala tartib mumkin.","Ko'rsatma: buyruq (V1) + first, then, next, finally; inkorda Don't + V1.","try + -ing — sinab ko'rmoq (Try restarting it); qisqartmalar (BTW, ASAP, thx) faqat norasmiy yozuvda.","Telefonda: Can I speak to…? Who's calling? This is… Hold on. I'll call you back."]},{"id":"u17-l5","slug":"travel-and-hotels","title":"Travel and hotels","titleUz":"Sayohat va mehmonxona","goal":"Mehmonxonada xona bron qilasiz, check-in / check-out qilasiz, kerakli narsalarni muloyim so'raysiz (Could I have…? Is there…?), vokzal va aeroportda chipta olasiz, perron va reysni so'raysiz hamda luggage kabi sanalmaydigan so'zlarni to'g'ri ishlatasiz.","words":[{"en":"reservation","uz":"bron qilish","ipa":"ˌrezəˈveɪʃn"},{"en":"luggage","uz":"yuk, bagaj","ipa":"ˈlʌɡɪdʒ"},{"en":"boarding pass","uz":"bort talonchasi","ipa":"ˈbɔːdɪŋ pɑːs"},{"en":"platform","uz":"perron","ipa":"ˈplætfɔːm"},{"en":"delay","uz":"kechikish; kechiktirmoq","ipa":"dɪˈleɪ"},{"en":"return ticket","uz":"borib-kelish chiptasi","ipa":"rɪˈtɜːn ˈtɪkɪt"},{"en":"check in","uz":"ro'yxatdan o'tmoq","ipa":"tʃek ɪn"},{"en":"check out","uz":"hisob-kitob qilib chiqib ketmoq","ipa":"tʃek aʊt"},{"en":"available","uz":"bo'sh, mavjud","ipa":"əˈveɪləbl"},{"en":"included","uz":"narxga kiritilgan","ipa":"ɪnˈkluːdɪd"}],"summary":["Bron: I'd like to book a… room for… nights. Savol: Is breakfast included? Do you have any rooms available?","Muloyim iltimos: Could I have…? / Could you…?; borligini so'rash: Is there… / Are there any…?","Jadval — Present Simple: What time does the train leave? (does + V1).","luggage, baggage — sanalmaydigan ot: My luggage is heavy, hech qachon luggages.","Aeroport ketma-ketligi: check-in → boarding pass → passport control → gate."]},{"id":"u17-l6","slug":"restaurants-and-food","title":"Restaurants and food","titleUz":"Restoran va ovqat buyurtma qilish","goal":"Restoran va choyxonada buyurtma berasiz (I'll have… / Could I have…?), menyuni tushunasiz, allergiya va ehtiyojlaringizni aytasiz, hisob so'raysiz va sanaladigan hamda sanalmaydigan ovqat nomlarini (some, any, much, many, a bowl of) to'g'ri ishlatasiz.","words":[{"en":"menu","uz":"menyu","ipa":"ˈmenjuː"},{"en":"starter","uz":"gazak, birinchi bo'lim","ipa":"ˈstɑːtə"},{"en":"dessert","uz":"shirinlik","ipa":"dɪˈzɜːt"},{"en":"bill","uz":"hisob (restoranda)","ipa":"bɪl"},{"en":"tip","uz":"choy puli","ipa":"tɪp"},{"en":"allergic","uz":"allergiyasi bor","ipa":"əˈlɜːdʒɪk"},{"en":"vegetarian","uz":"vegetarian","ipa":"ˌvedʒəˈteəriən"},{"en":"spicy","uz":"achchiq, ziravorli","ipa":"ˈspaɪsi"},{"en":"recommend","uz":"tavsiya qilmoq","ipa":"ˌrekəˈmend"},{"en":"delicious","uz":"mazali","ipa":"dɪˈlɪʃəs"}],"summary":["Buyurtma: I'll have… / Could I have…? / I'd like…, please. — I want emas.","Ogohlantirish: I'm allergic to…, I'm a vegetarian, without onions, Is there any … in it?","Sanalmaydigan ovqatlar: some / any / much + o'lchov: a cup of tea, a bowl of soup, a piece of bread.","Taklifda some (Would you like some tea?), inkor va savolda any.","Hisob: Could we have the bill, please? Is service included? Maqtash: It was delicious!"]},{"id":"u17-l14","slug":"listening-and-speaking-a-job-interview","title":"Listening and speaking: a job interview","titleUz":"Tinglash va gapirish: ish suhbati","goal":"Ish suhbatidagi savollarni tinglab tushunasiz va ularga o'zingiz javob berasiz: Tell me about yourself. What are your strengths? Why do you want this job? Can you start next month?","words":[{"en":"strength","uz":"kuchli tomon","ipa":"streŋθ"},{"en":"weakness","uz":"zaif tomon","ipa":"ˈwiːk.nəs"},{"en":"shift","uz":"smena","ipa":"ʃɪft"},{"en":"trainee","uz":"stajyor","ipa":"ˌtreɪˈniː"},{"en":"on time","uz":"vaqtida","ipa":"ɒn ˈtaɪm"},{"en":"career","uz":"kasbiy yo'l, karyera","ipa":"kəˈrɪə"}],"summary":["Suhbat savollari: Tell me about yourself. Why do you want this job? What are your strengths? Can you start next month?","Javob tartibi: qisqa javob + sabab yoki misol; kuchli tomon uchun I'm + sifat, I'm good at + -ing.","Tushunmasangiz: Sorry, could you repeat that, please? Oxirida: Thank you for your time.","Yangi so'zlar: strength, weakness, shift, trainee, on time, career."]},{"id":"u17-l9","slug":"returning-an-item-to-a-shop","title":"Returning an item to a shop","titleUz":"Do'konga narsani qaytarish","goal":"Do'konga borib, narsani qaytarish yoki almashtirishni muloyim so'raysiz: nima bo'lganini tushuntirasiz (It's too small. It doesn't work.), chekni ko'rsatasiz va refund yoki exchange so'raysiz. Kerak bo'lsa, shikoyatni qo'pol emas, muloyim aytasiz.","words":[{"en":"faulty","uz":"nuqsonli, ishlamaydigan","ipa":"ˈfɔːlti"},{"en":"damaged","uz":"shikastlangan","ipa":"ˈdæmɪdʒd"},{"en":"complaint","uz":"shikoyat","ipa":"kəmˈpleɪnt"},{"en":"size","uz":"o'lcham","ipa":"saɪz"},{"en":"fit","uz":"mos kelmoq (o'lcham)","ipa":"fɪt"},{"en":"exchange","uz":"almashtirmoq","ipa":"ɪksˈtʃeɪndʒ"}],"summary":["Qaytarishda 3 qadam: muammoni ayting → chekni ko'rsating → muloyim so'rang.","Foydali iboralar: I'd like to return this. Could I have a refund? Can I exchange it for…?","Muammo: it's too small, it doesn't work, it's damaged, it's faulty.","Muloyim bo'ling: Excuse me, I'm sorry, but…, Could you…, please?"]},{"id":"u17-l10","slug":"booking-a-table-by-phone","title":"Booking a table by phone","titleUz":"Telefonda stol band qilish","goal":"Restoranga telefon qilib stol band qilasiz: sana, vaqt va odamlar sonini aytasiz, o'rin haqida (by the window, outside, quiet) muloyim iltimos qilasiz va bronni tasdiqlaysiz.","words":[{"en":"book","uz":"band qilmoq","ipa":"bʊk"},{"en":"reserve","uz":"oldindan band qilmoq","ipa":"rɪˈzɜːv"},{"en":"quiet","uz":"tinch","ipa":"ˈkwaɪət"},{"en":"corner","uz":"burchak","ipa":"ˈkɔːnə"},{"en":"terrace","uz":"terrasa, ochiq maydoncha","ipa":"ˈterəs"},{"en":"confirm","uz":"tasdiqlamoq","ipa":"kənˈfɜːm"}],"summary":["Bron qilish: I'd like to book a table for four on Friday at eight.","Predloglar: on + kun, at + soat, for + odamlar soni.","Iltimoslar: Could we have a table by the window / in a quiet corner / outside?","Oxirida bronni tasdiqlang: So that's a table for…"]},{"id":"u17-l7","slug":"writing-cv-and-short-messages","title":"Writing: CV and short messages","titleUz":"Rezyume va qisqa xat yozish","goal":"Inglizcha CV (rezyume) tuzasiz, ish uchun qisqa cover message yozasiz (I am writing to apply for…), shuningdek qisqa xabar, eslatma va taklifnomalar yozib, ularga muloyim javob berasiz (I'd love to come. Sorry, I can't.). Rasmiy va norasmiy uslubni farqlaysiz.","words":[{"en":"qualification","uz":"malaka, diplom","ipa":"ˌkwɒlɪfɪˈkeɪʃn"},{"en":"reference","uz":"tavsiyanoma","ipa":"ˈrefrəns"},{"en":"responsible","uz":"mas'ul","ipa":"rɪˈspɒnsəbl"},{"en":"manage","uz":"boshqarmoq","ipa":"ˈmænɪdʒ"},{"en":"organise","uz":"tashkil qilmoq","ipa":"ˈɔːɡənaɪz"},{"en":"attach","uz":"biriktirmoq","ipa":"əˈtætʃ"},{"en":"invitation","uz":"taklifnoma","ipa":"ˌɪnvɪˈteɪʃn"},{"en":"reply","uz":"javob bermoq; javob","ipa":"rɪˈplaɪ"},{"en":"regards","uz":"hurmat bilan (xat oxirida)","ipa":"rɪˈɡɑːdz"},{"en":"deadline","uz":"oxirgi muddat","ipa":"ˈdedlaɪn"}],"summary":["CV bo'limlari: Personal details, Profile, Work experience, Education, Skills, References — eng yangi ish birinchi.","CV da qisqa iboralar: Organised events. Responsible for managing… ; \"I\" siz.","Cover message: Dear… / I am writing to apply for… / I have attached my CV. / I look forward to hearing from you. / Yours sincerely.","Taklifnoma: Would you like to come to…? Please reply by… Javob: I'd love to! / Sorry, I can't. I have to…","Norasmiy va rasmiy uslubni aralashtirmang: Hi… See you! va Dear… Best regards."]},{"id":"u17-l15","slug":"reading-and-writing-an-email-to-a-hotel","title":"Reading and writing: an email to a hotel","titleUz":"O'qish va yozish: mehmonxonaga xat","goal":"Mehmonxonaga yozilgan qisqa xatni o'qib tushunasiz va o'zingiz 5–7 gapli xat yozasiz: sanalarni ayting, narxni so'rang va muloyim iltimos qiling (I would like to book… Could you tell me…?).","words":[{"en":"stay","uz":"qolmoq, turmoq (mehmonxonada)","ipa":"steɪ"},{"en":"arrive","uz":"yetib kelmoq","ipa":"əˈraɪv"},{"en":"view","uz":"manzara","ipa":"vjuː"},{"en":"dates","uz":"sanalar","ipa":"deɪts"},{"en":"facilities","uz":"qulayliklar, xizmatlar","ipa":"fəˈsɪl.ə.tiz"},{"en":"car park","uz":"avtoturargoh","ipa":"ˈkɑː pɑːk"}],"summary":["Xat tartibi: salomlashish → maqsad → sanalar → savollar → javob so'rash → xayrlashuv.","Muloyim: I would like to book… / Could you tell me…? / Is breakfast included?","Dear Sir or Madam → Yours faithfully; ism ma'lum bo'lsa — Best regards.","I am writing to ask… (maqsad) va I look forward to hearing… (to + -ing).","Yangi so'zlar: stay, arrive, view, dates, facilities, car park."]},{"id":"u17-l8","slug":"a2-final-review","title":"A2 final review","titleUz":"A2 yakuniy takrori: hamma zamonlar va modal fe'llar","goal":"Pre-Intermediate darajasini yakunlaysiz: o'tgan zamon (Past Simple, Past Continuous, used to), kelajak (going to, will, might, if), taqqoslash, modal fe'llar (must, should, can, could), Present Perfect, passive va fe'l qoliplari — hammasini bitta matn va aralash mashqlarda qo'llaysiz.","words":[{"en":"improve","uz":"yaxshilanmoq, yaxshilamoq","ipa":"ɪmˈpruːv"},{"en":"progress","uz":"taraqqiyot, o'sish","ipa":"ˈprəʊɡres"},{"en":"achieve","uz":"erishmoq","ipa":"əˈtʃiːv"},{"en":"confidence","uz":"o'ziga ishonch","ipa":"ˈkɒnfɪdəns"},{"en":"fluent","uz":"ravon","ipa":"ˈfluːənt"},{"en":"vocabulary","uz":"lug'at boyligi","ipa":"vəˈkæbjələri"},{"en":"mistake","uz":"xato","ipa":"mɪˈsteɪk"},{"en":"memorise","uz":"yodlamoq","ipa":"ˈmeməraɪz"},{"en":"keep going","uz":"davom etmoq, to'xtamaslik","ipa":"kiːp ˈɡəʊɪŋ"},{"en":"nervous","uz":"hayajonlangan, asabiy","ipa":"ˈnɜːvəs"}],"summary":["Past Simple (tugagan), Past Continuous (jarayon), used to (eski odat), Present Perfect (tajriba, natija, for / since).","Kelajak: going to (reja), will (qaror), Present Continuous (kelishilgan), might (ehtimol), if + Present, will.","Taqqoslash: -er / more … than, the -est / the most, as … as, too / enough.","Modal fe'llar: must, mustn't, don't have to, should, can, could; muloyim iltimos — Could you…? Would you like…?","Passive (be + V3), who / which / that / where, fe'l qoliplari (enjoy -ing, want to)."]},{"id":"u17-l11","slug":"pre-intermediate-final-review","title":"Pre-Intermediate: final review","titleUz":"Pre-Intermediate: yakuniy takror","goal":"Butun Pre-Intermediate darajani qisqa takrorlaysiz: o'tgan zamon, kelajak, taqqoslash, modal fe'llar, Present Perfect, passive, relative clauses va kundalik vaziyatlar. Qaysi mavzu kuchli, qaysi biri takrorni talab qilishini bilib olasiz.","words":[{"en":"revise","uz":"takrorlamoq","ipa":"rɪˈvaɪz"},{"en":"level","uz":"daraja","ipa":"ˈlevl"},{"en":"grammar","uz":"grammatika","ipa":"ˈɡræmə"},{"en":"pronunciation","uz":"talaffuz","ipa":"prəˌnʌnsiˈeɪʃn"},{"en":"exam","uz":"imtihon","ipa":"ɪɡˈzæm"},{"en":"certificate","uz":"sertifikat","ipa":"səˈtɪfɪkət"}],"summary":["O'tgan zamon: Past Simple (V2), Past Continuous (was/were + -ing), used to.","Kelajak: going to (reja), will (qaror), if + Present, will + V1.","Taqqoslash va modal fe'llar: cheaper than, the cheapest; must, should, could.","Present Perfect, passive, relative clauses: have + V3, was + V3, who / which / that.","Kundalik gaplarda muloyim bo'ling: Could I…, please? I'd like to…"]}]}]},{"id":"b1","slug":"intermediate","title":"Intermediate","cefr":"B1","text":"Ko'p narsani tushunaman, fikrimni ayta olaman.","units":[{"id":"u18","n":18,"title":"Life stories and experiences","titleUz":"Hayot hikoyalari va tajriba: Present Perfect va uning shakllari","description":"Present Perfect (tajriba, natija, for / since), Present Perfect Continuous, Past Simple bilan farqi, o'zgarishlar va hayot voqealari.","canDo":["Hayotim va tajribam haqida Present Perfect bilan gapiraman (I've been to…, I've never…)","For, since va How long bilan davomiylikni ayta olaman","Present Perfect, Present Perfect Continuous va Past Simple ni to'g'ri tanlayman","Eski do'stga email yozaman va o'z hayotim haqida qisqa hikoya qilaman"],"lessons":[{"id":"u18-l1","slug":"present-perfect-experiences-and-results","title":"Present Perfect: experiences and results","titleUz":"Present Perfect: tajriba va natija (ever, never, already, yet, just)","goal":"Present Perfect ni uchta vazifada ishlatasiz: hayotiy tajriba (I've run a marathon), hozirgi natija (I've lost my passport) va yangilik (They've just won). Savol, inkor va qisqa javoblarni to'g'ri tuzasiz hamda This is the first time I've… va the best … I've ever… qoliplarini bilib olasiz.","words":[{"en":"look up to","uz":"hurmat qilmoq, havas qilmoq","ipa":"lʊk ʌp tuː"},{"en":"succeed","uz":"muvaffaqiyat qozonmoq","ipa":"səkˈsiːd"},{"en":"role model","uz":"namuna bo'ladigan inson","ipa":"rəʊl ˈmɒd.əl"},{"en":"challenge","uz":"qiyin sinov, qiyinchilik","ipa":"ˈtʃæl.ɪndʒ"},{"en":"competition","uz":"musobaqa, tanlov","ipa":"ˌkɒm.pəˈtɪʃ.ən"},{"en":"award","uz":"mukofot, sovrin","ipa":"əˈwɔːd"},{"en":"volunteer","uz":"ko'ngilli (kishi); ko'ngilli bo'lmoq","ipa":"ˌvɒl.ənˈtɪə"},{"en":"proud","uz":"faxrlangan, g'ururlangan","ipa":"praʊd"},{"en":"get a degree","uz":"diplom olmoq","ipa":"ɡet ə dɪˈɡriː"},{"en":"take part in","uz":"qatnashmoq","ipa":"teɪk pɑːt ɪn"}],"summary":["Present Perfect = have / has + V3. Inkor: haven't / hasn't + V3. Savol: Have / Has + ega + V3?","Uch vazifa: hayotiy tajriba (I've run a marathon), hozirgi natija (I've lost my keys), yangilik (She has just won). Aniq o'tgan vaqt aytilmaydi.","Tajriba so'zlari: ever (savolda), never, before, once / twice / three times, so far. Darak gapda ever ishlatilmaydi.","Qoliplar: This is the first time I've… va the best … I've ever…","today, this week, this year kabi tugamagan davrlar bilan ham Present Perfect ishlatiladi. Tartibsiz fe'llarda V3 ni yodlang: written, eaten, seen, been."]},{"id":"u18-l12","slug":"been-or-gone-just-already-yet","title":"Been or gone? Just, already, yet","titleUz":"Been yoki gone? Just, already va yet bilan ishlash","goal":"just, already, yet va still so'zlarini gapda to'g'ri joyga qo'yasiz, have been bilan have gone farqini ajratasiz va o'z hayotingiz haqida aniq gaplar tuzasiz.","words":[{"en":"look around","uz":"aylanib ko'rmoq","ipa":"lʊk əˈraʊnd"},{"en":"get back","uz":"qaytib kelmoq","ipa":"ɡet bæk"},{"en":"save up","uz":"jamg'arib bormoq","ipa":"seɪv ʌp"},{"en":"take over","uz":"o'z zimmasiga olmoq","ipa":"teɪk ˈəʊ.və"},{"en":"work on","uz":"ustida ishlamoq","ipa":"wɜːk ɒn"}],"summary":["just va already — have / has bilan V3 orasida; yet — gap oxirida (inkor va savol).","still — haven't dan oldin: I still haven't finished. (sabrsizlik). Savolda already — hayrat.","have been — borib qaytgan (tajriba); have gone — ketgan, hozir yo'q.","Yangi so'zlar: look around, get back, save up, take over, work on."]},{"id":"u18-l2","slug":"present-perfect-with-for-and-since","title":"Present Perfect with for and since","titleUz":"For va since: How long…? savollari","goal":"How long…? savoliga Present Perfect + for (muddat) yoki since (boshlanish nuqtasi) bilan javob berasiz, I live here since 2015 kabi o'zbekcha xatodan qochasiz va since dan keyin gap (since I was a child) ishlatasiz.","words":[{"en":"relative","uz":"qarindosh","ipa":"ˈrel.ə.tɪv"},{"en":"acquaintance","uz":"tanish (yaqin do'st emas)","ipa":"əˈkweɪn.təns"},{"en":"get along","uz":"chiqishmoq, til topishmoq","ipa":"ɡet əˈlɒŋ"},{"en":"supportive","uz":"qo'llab-quvvatlovchi","ipa":"səˈpɔː.tɪv"},{"en":"community","uz":"jamoa, mahalla (jamiyat)","ipa":"kəˈmjuː.nə.ti"},{"en":"take after","uz":"o'xshamoq (oila a'zosiga)","ipa":"teɪk ˈɑːf.tə"},{"en":"collect","uz":"yig'moq, to'plamoq","ipa":"kəˈlekt"},{"en":"get to know","uz":"tanishib bormoq, yaxshi bilib olmoq","ipa":"ɡet tə nəʊ"},{"en":"stay in touch","uz":"aloqada bo'lmoq","ipa":"steɪ ɪn tʌtʃ"},{"en":"lose touch","uz":"aloqani yo'qotmoq","ipa":"luːz tʌtʃ"}],"summary":["How long have you…? — davom etayotgan holat haqida savol. Javobda ham Present Perfect ishlatamiz.","for + muddat (for two years, for ages); since + boshlanish nuqtasi (since 2019, since Monday).","O'zbekchadagi «yashayman, bilaman» ni inglizchaga o'tkazmang: ~~I live here since 2015~~ → I have lived here since 2015.","since + gap bo'lsa, gap Past Simple da: since I was a child, since I moved here.","Past Simple + for — tugagan davr (I lived there for five years); Present Perfect + for — hozir ham davom etmoqda."]},{"id":"u18-l3","slug":"present-perfect-continuous","title":"Present Perfect Continuous","titleUz":"Present Perfect Continuous: davom etayotgan jarayon","goal":"Present Perfect Continuous (I've been working) ni to'g'ri tuzasiz, uni Present Perfect Simple (I've finished) dan ajratasiz — jarayon yoki natija — hamda How long…?, What have you been doing? savollariga javob berasiz.","words":[{"en":"fed up","uz":"bezor bo'lgan, toliqqan","ipa":"fed ʌp"},{"en":"sort out","uz":"tartibga solmoq, hal qilmoq","ipa":"sɔːt aʊt"},{"en":"tidy up","uz":"tartibga keltirmoq, yig'ishtirmoq","ipa":"ˈtaɪ.di ʌp"},{"en":"clear out","uz":"tozalab tashlamoq (keraksiz narsalardan)","ipa":"klɪər aʊt"},{"en":"wait around","uz":"bekor kutib turmoq","ipa":"weɪt əˈraʊnd"},{"en":"search","uz":"qidirmoq (diqqat bilan)","ipa":"sɜːtʃ"},{"en":"lately","uz":"so'nggi paytlarda","ipa":"ˈleɪt.li"},{"en":"keep up","uz":"davom ettirmoq, ortda qolmaslik","ipa":"kiːp ʌp"},{"en":"decorate","uz":"bezamoq; ta'mirlab bo'yamoq","ipa":"ˈdek.ə.reɪt"},{"en":"work out","uz":"sport bilan shug'ullanmoq; yechim topmoq","ipa":"wɜːk aʊt"}],"summary":["Present Perfect Continuous = have / has + been + V-ing. Savol: Have you been waiting long? Inkor: I haven't been sleeping well.","Ikki vazifa: hozir ham davom etayotgan jarayon (I've been learning English for a year) va hozirgina tugagan harakat, natijasi ko'rinib turibdi (I've been running).","Continuous — jarayon va davomiylik (how long?); Simple — natija va son (how many?): I've been reading all day / I've read three chapters.","know, like, want, need, have (egalik), be kabi holat fe'llari Continuous bo'lmaydi: ~~I have been knowing~~ → I have known.","Foydali so'zlar: how long, for, since, all day, lately, recently. Savol: What have you been doing?"]},{"id":"u18-l4","slug":"present-perfect-or-past-simple","title":"Present Perfect or Past Simple?","titleUz":"Present Perfect yoki Past Simple? Simple yoki Continuous?","goal":"O'tgan voqea haqida gapirganda to'rt shakldan birini ongli tanlaysiz: Past Simple, Present Perfect, Present Perfect Continuous yoki Past Continuous. Bir hikoyada ularni bir-biriga bog'lay olasiz va I have seen him yesterday kabi xatolardan qochasiz.","words":[{"en":"bring back","uz":"esga solmoq, qaytarmoq","ipa":"brɪŋ bæk"},{"en":"come across","uz":"tasodifan topib olmoq","ipa":"kʌm əˈkrɒs"},{"en":"look through","uz":"ko'zdan kechirmoq, varaqlamoq","ipa":"lʊk θruː"},{"en":"occur","uz":"sodir bo'lmoq","ipa":"əˈkɜː"},{"en":"forgetful","uz":"esi past, unutuvchan","ipa":"fəˈɡet.fəl"},{"en":"keep in mind","uz":"yodda tutmoq","ipa":"kiːp ɪn maɪnd"},{"en":"gradually","uz":"asta-sekin","ipa":"ˈɡrædʒ.u.ə.li"},{"en":"recent","uz":"yaqindagi, so'nggi","ipa":"ˈriː.sənt"},{"en":"take place","uz":"bo'lib o'tmoq","ipa":"teɪk pleɪs"},{"en":"mention","uz":"tilga olmoq, eslatib o'tmoq","ipa":"ˈmen.ʃən"}],"summary":["Past Simple — tugagan voqea, aniq payt: yesterday, last year, two days ago, in 2019, when…?","Present Perfect — hozirga aloqasi bor: tajriba, natija, yangilik; ever, never, already, yet, just, so far, for, since.","Suhbatda: Present Perfect (yangilik) → Past Simple (tafsilot). Xato: ~~I have seen him yesterday~~ → I saw him yesterday.","Continuous — jarayon (I've been reading all day, I was reading when…); Simple — natija va son (I've read three chapters).","Savol-testi: aniq tugagan vaqt? → Past Simple. Hozirgacha davom etadimi? → Present Perfect (Continuous). Natija / son / tajriba? → Present Perfect Simple."]},{"id":"u18-l13","slug":"how-long-ago-and-time-words","title":"How long, ago and time words","titleUz":"How long, ago va vaqt so'zlari: to'g'ri zamonni tanlash","goal":"How long…? va How long ago…? savollarini farqlaysiz, ago, for, since, so far, lately kabi vaqt so'zlariga qarab Present Perfect yoki Past Simple ni tanlaysiz.","words":[{"en":"work part-time","uz":"yarim kunlik ishlamoq","ipa":"wɜːk ˌpɑːtˈtaɪm"},{"en":"not any more","uz":"endi emas","ipa":"nɒt ˈen.i mɔː"},{"en":"these days","uz":"hozirgi kunlarda","ipa":"ðiːz deɪz"},{"en":"all my life","uz":"butun umr bo'yi","ipa":"ɔːl maɪ laɪf"},{"en":"over the years","uz":"yillar davomida","ipa":"ˈəʊ.və ðə jɪəz"}],"summary":["How long have you…? — hozirgacha davom etgan davr (Present Perfect). How long ago did you…? — o'tmishdagi payt (Past Simple).","ago, yesterday, last week, in 2019 → Past Simple. for, since, lately, so far, today → Present Perfect.","I lived there for two years — endi yashamaydi; I have lived there for two years — hali ham yashaydi.","Yangi iboralar: work part-time, not any more, these days, all my life, over the years."]},{"id":"u18-l9","slug":"meeting-someone-new-talking-about-your-life","title":"Meeting someone new: talking about your life","titleUz":"Yangi tanish bilan suhbat: hayotingiz haqida gapirish","goal":"Yangi tanish bilan suhbatni boshlaysiz, qayerdansiz, qancha vaqtdan beri yashaysiz, nima ish qilasiz haqida gapirasiz va Have you ever…? savollari bilan suhbatni davom ettirasiz.","words":[{"en":"originally","uz":"asli, dastlab","ipa":"əˈrɪdʒ.ən.əl.i"},{"en":"be raised","uz":"tarbiyalanib o'smoq","ipa":"bi reɪzd"},{"en":"accent","uz":"talaffuz (urg'u), sheva","ipa":"ˈæk.sənt"},{"en":"immigrant","uz":"muhojir","ipa":"ˈɪm.ɪ.ɡrənt"},{"en":"roots","uz":"ildizlar, kelib chiqish","ipa":"ruːts"}],"summary":["Tanishuv: Nice to meet you. Where are you from? What do you do? What about you?","Qancha vaqtdan beri: How long have you lived here? — I've lived here for three years / since 2022.","Tajriba: Have you ever lived abroad? Aloqa: Let's keep in touch.","Yangi so'zlar: originally, be raised, accent, immigrant, roots."]},{"id":"u18-l5","slug":"life-events-and-milestones","title":"Life events and milestones","titleUz":"Hayot voqealari: get married, move house, graduate, retire","goal":"Hayotdagi asosiy voqealarni (graduate, get engaged, get married, move house, get a promotion, retire) to'g'ri fe'l va predlog bilan aytasiz hamda ularni Past Simple (I graduated in 2018) va Present Perfect (I've been married for five years) bilan to'g'ri bog'laysiz.","words":[{"en":"milestone","uz":"hayotdagi muhim bosqich","ipa":"ˈmaɪl.stəʊn"},{"en":"be born","uz":"tug'ilmoq","ipa":"bi bɔːn"},{"en":"leave school","uz":"maktabni bitirmoq","ipa":"liːv skuːl"},{"en":"get engaged","uz":"unashtirilmoq","ipa":"ɡet ɪnˈɡeɪdʒd"},{"en":"start a family","uz":"oila qurmoq (farzand ko'rmoq)","ipa":"stɑːt ə ˈfæm.əl.i"},{"en":"honeymoon","uz":"asal oyi","ipa":"ˈhʌn.i.muːn"},{"en":"get a promotion","uz":"lavozimi ko'tarilmoq","ipa":"ɡet ə prəˈməʊ.ʃən"},{"en":"move out","uz":"ko'chib chiqmoq","ipa":"muːv aʊt"},{"en":"settle down","uz":"joylashib, osoyishta hayot kechirmoq","ipa":"ˈset.əl daʊn"},{"en":"retirement","uz":"nafaqa, nafaqaga chiqish davri","ipa":"rɪˈtaɪə.mənt"}],"summary":["Hayot voqealari: grow up, graduate, get engaged, get married, move house, get a promotion, retire, settle down.","Predloglarni unutmang: graduate from, move to, retire at the age of, married to, apply for.","be born — doim passive Past Simple: I was born in 1995.","Voqea aniq vaqtda bo'lsa — Past Simple (We got married in 2019). Qancha vaqtdan beri deyilsa — holat: We've been married for six years.","I have got married for five years — xato. get married muddat (for) bilan ishlatilmaydi."]},{"id":"u18-l6","slug":"changes-used-to-be-used-to-get-used-to","title":"Changes: used to, be used to, get used to","titleUz":"O'zgarishlar: used to, be used to va get used to","goal":"used to + fe'l (I used to play chess), be used to + -ing (I'm used to getting up early) va get used to + -ing (I'm getting used to the cold) ni bir-biridan ajratasiz va hayotdagi o'zgarishlar haqida gapira olasiz.","words":[{"en":"unfamiliar","uz":"notanish","ipa":"ˌʌn.fəˈmɪl.i.ər"},{"en":"lie in","uz":"uzoqroq uxlamoq","ipa":"laɪ ɪn"},{"en":"lifestyle","uz":"hayot tarzi","ipa":"ˈlaɪf.staɪl"},{"en":"adapt","uz":"moslashmoq","ipa":"əˈdæpt"},{"en":"adjust","uz":"ko'nikib olmoq, moslashmoq","ipa":"əˈdʒʌst"},{"en":"custom","uz":"urf-odat","ipa":"ˈkʌs.təm"},{"en":"nowadays","uz":"hozirgi kunlarda","ipa":"ˈnaʊ.ə.deɪz"},{"en":"settle in","uz":"joylashib olmoq, o'rganib qolmoq","ipa":"ˈset.əl ɪn"},{"en":"culture shock","uz":"madaniy shok","ipa":"ˈkʌl.tʃə ʃɒk"},{"en":"grow out of","uz":"katta bo'lgach tashlamoq (odatni)","ipa":"ɡrəʊ aʊt ɒv"}],"summary":["used to + fe'l: ilgari shunday bo'lgan, hozir yo'q. Inkor/savol: didn't use to, Did you use to…?","be used to + -ing / ot: ko'nikkan holat. I'm used to getting up early.","get used to + -ing / ot: ko'nikish jarayoni. I'm getting used to the cold.","be used to va get used to dagi to — predlog, shuning uchun fe'l -ing shaklida: ~~I'm used to get up~~ → I'm used to getting up.","would ilgarigi takrorlangan harakatlarda ishlatiladi, lekin holatda (have, be, like) faqat used to."]},{"id":"u18-l14","slug":"listening-and-speaking-an-interview-about-a-life","title":"Listening and speaking: an interview about a life","titleUz":"Tinglash va gapirish: hayot haqida intervyu","goal":"Hayot haqidagi intervyuni tinglab asosiy ma'lumotni topasiz (kim, qachon, qancha vaqt), o'z hayotingiz haqida 3 qadamli javob berasiz va Could you say that again? deb so'raysiz.","words":[{"en":"obstacle","uz":"to'siq","ipa":"ˈɒb.stə.kəl"},{"en":"achievement","uz":"yutuq","ipa":"əˈtʃiːv.mənt"},{"en":"defeat","uz":"mag'lubiyat","ipa":"dɪˈfiːt"},{"en":"hire","uz":"ishga olmoq","ipa":"ˈhaɪ.ə"},{"en":"again and again","uz":"qayta-qayta","ipa":"əˈɡen ənd əˈɡen"}],"summary":["Intervyuda raqam + years / ago / since va zamonlarga e'tibor bering: ago — o'tmish, for / since — hozirgacha.","Javob 3 qadamda: javob, tafsilot, misol. Masalan: I've lived here for four years. I moved here after university.","Eshitmasangiz: Sorry, could you say that again, please?","Yangi so'zlar: obstacle, achievement, defeat, hire, again and again."]},{"id":"u18-l10","slug":"catching-up-with-a-friend-by-phone","title":"Catching up with a friend by phone","titleUz":"Do'stga telefonda yangiliklarni aytish","goal":"Uzoq vaqt ko'rmagan do'stingiz bilan telefonda gaplashasiz: How have you been? What have you been up to? deb so'raysiz, yangiliklaringizni aytasiz va xursandchilik bildirasiz.","words":[{"en":"catch up","uz":"yangiliklarni almashmoq","ipa":"kætʃ ʌp"},{"en":"ages","uz":"uzoq vaqt (so'zlashuv)","ipa":"ˈeɪ.dʒɪz"},{"en":"bump into","uz":"tasodifan uchrashib qolmoq","ipa":"bʌmp ˈɪn.tuː"},{"en":"congratulations","uz":"tabriklayman","ipa":"kənˌɡrætʃ.əˈleɪ.ʃənz"},{"en":"pass on","uz":"yetkazmoq, aytib qo'ymoq","ipa":"pɑːs ɒn"}],"summary":["Salomlashish: It's been ages! How have you been? What have you been up to?","Yangilik: Guess what? I've got some news. Javob: That's great news! Congratulations! / I'm sorry to hear that.","news — sanalmaydigan ot: good news, a piece of news, a news emas.","Yangi so'zlar: catch up, ages, bump into, congratulations, pass on."]},{"id":"u18-l7","slug":"writing-a-short-biography","title":"Writing a short biography","titleUz":"Yozish: qisqa tarjimai hol","goal":"Odam hayoti haqida 8-10 gapli qisqa tarjimai hol (biography) yozasiz: Past Simple bilan o'tmishni, Present Perfect bilan hozirgacha davom etayotgan narsalarni aytasiz va gaplarni later, afterwards, at the age of, since then kabi so'zlar bilan bog'laysiz.","words":[{"en":"biography","uz":"tarjimai hol","ipa":"baɪˈɒɡ.rə.fi"},{"en":"early life","uz":"hayotining dastlabki yillari","ipa":"ˈɜː.li laɪf"},{"en":"reputation","uz":"obro', nom","ipa":"ˌrep.jəˈteɪ.ʃən"},{"en":"dedicated","uz":"fidoyi, o'zini bag'ishlagan","ipa":"ˈded.ɪ.keɪ.tɪd"},{"en":"inspire","uz":"ilhomlantirmoq","ipa":"ɪnˈspaɪə"},{"en":"eventually","uz":"oxir-oqibat","ipa":"ɪˈven.tʃu.ə.li"},{"en":"afterwards","uz":"keyin, undan so'ng","ipa":"ˈɑːf.tə.wədz"},{"en":"throughout","uz":"davomida, butun","ipa":"θruːˈaʊt"},{"en":"fame","uz":"shuhrat","ipa":"feɪm"},{"en":"well-known","uz":"taniqli","ipa":"wel nəʊn"}],"summary":["Biografiya tartibi: tug'ilish, bolalik, o'qish, ish va yutuqlar, hozir.","Boshlanishi: Name was born in (joy) in (yil). Tugagan voqealar — Past Simple.","Hozirgacha davom etgan narsalar — Present Perfect: has lived … since 2015, has written five books so far.","Bog'lash: at the age of, when he was ten, later, afterwards, eventually, since then.","Yozgandan keyin tekshiring: aniq yil bo'lsa Past Simple, since / for bo'lsa Present Perfect."]},{"id":"u18-l15","slug":"reading-and-writing-an-email-to-an-old-friend","title":"Reading and writing: an email to an old friend","titleUz":"O'qish va yozish: eski do'stga xat","goal":"Eski do'stdan kelgan norasmiy emailni o'qib tushunasiz va o'zingiz yangiliklar, savol va reja bilan 7-8 gapdan iborat email yozasiz (Sorry I haven't written for so long…).","words":[{"en":"grow apart","uz":"uzoqlashib qolmoq","ipa":"ɡrəʊ əˈpɑːt"},{"en":"all the best","uz":"hammasi yaxshi bo'lsin (xat oxirida)","ipa":"ɔːl ðə best"},{"en":"give my love to","uz":"salom aytmoq (yaqin odamga)","ipa":"ɡɪv maɪ lʌv tuː"},{"en":"last time","uz":"oxirgi marta","ipa":"lɑːst taɪm"},{"en":"reunion","uz":"uchrashuv (eski do'stlar yig'ini)","ipa":"riːˈjuː.ni.ən"}],"summary":["Norasmiy email: salom, sabab/hol, yangiliklar, savol/taklif, yakun (Hi Sara… Best wishes, Emma).","Foydali iboralar: Sorry I haven't written for so long. By the way… Anyway… Write back soon!","look forward to + -ing: I'm looking forward to hearing from you. Yangiliklarda for / since, used to ishlating.","Yangi so'zlar: grow apart, all the best, give my love to, last time, reunion."]},{"id":"u18-l8","slug":"unit-review-experiences","title":"Unit review: experiences","titleUz":"Bosqich takrori: tajriba va Present Perfect","goal":"Bosqichdagi hamma narsani yangi misollarda takrorlaysiz: Present Perfect (ever, never, already, yet, just), for / since, Present Perfect Continuous, Present Perfect yoki Past Simple, used to / be used to / get used to, hayot voqealari va tarjimai hol yozish.","words":[{"en":"lesson","uz":"saboq, dars","ipa":"ˈles.ən"},{"en":"opportunity","uz":"imkoniyat","ipa":"ˌɒp.əˈtʃuː.nə.ti"},{"en":"priority","uz":"ustuvor vazifa","ipa":"praɪˈɒr.ə.ti"},{"en":"sacrifice","uz":"qurbon qilmoq, voz kechmoq","ipa":"ˈsæk.rɪ.faɪs"},{"en":"lifetime","uz":"butun umr","ipa":"ˈlaɪf.taɪm"},{"en":"failure","uz":"muvaffaqiyatsizlik","ipa":"ˈfeɪl.jə"},{"en":"regret","uz":"afsuslanmoq","ipa":"rɪˈɡret"},{"en":"ambition","uz":"orzu-maqsad, intilish","ipa":"æmˈbɪʃ.ən"},{"en":"turning point","uz":"burilish nuqtasi","ipa":"ˈtɜː.nɪŋ pɔɪnt"},{"en":"support","uz":"qo'llab-quvvatlamoq; yordam","ipa":"səˈpɔːt"}],"summary":["Present Perfect (have / has + V3): tajriba va yangilik. ever, never, already, yet, just; been — borib kelgan, gone — hali qaytmagan.","for + muddat, since + boshlanish nuqtasi. How long have you…? Davom etayotgan faoliyat: have been + V-ing.","Aniq o'tgan vaqt (yesterday, ago, in 2018, when) bo'lsa — Past Simple. Hozirgacha davom etsa — Present Perfect.","used to + fe'l (ilgari), be / get used to + -ing (ko'nikish). Hayot voqealari: graduate from, get married, retire at the age of…","Tarjimai hol: was born, Past Simple voqealar, at the age of, later, eventually, since then."]},{"id":"u18-l11","slug":"life-stories-final-review","title":"Life stories: final review","titleUz":"Hayot hikoyalari: yakuniy takror","goal":"Bosqichdagi barcha mavzularni takrorlaysiz: Present Perfect, for / since, Present Perfect Continuous, Present Perfect yoki Past Simple, used to va hayot voqealari haqida qisqa hikoya aytasiz.","words":[{"en":"nostalgic","uz":"o'tmishni sog'ingan","ipa":"nɒˈstæl.dʒɪk"},{"en":"treasure","uz":"qadrlamoq, aziz ko'rmoq","ipa":"ˈtreʒ.ə"},{"en":"carry on","uz":"davom etmoq","ipa":"ˈkær.i ɒn"},{"en":"look back","uz":"o'tmishga nazar tashlamoq","ipa":"lʊk bæk"},{"en":"move on","uz":"oldinga yurmoq, o'tmishni ortda qoldirmoq","ipa":"muːv ɒn"}],"summary":["Present Perfect — tajriba, natija, hozirgacha davom etgan davr; Past Simple — aniq o'tgan vaqt (ago, in 2019, last year).","for — davomiylik, since — boshlanish nuqtasi; ikkalasi Present Perfect (yoki Continuous) bilan. been — borib qaytgan, gone — hozir yo'q.","used to — ilgarigi odat; be / get used to + -ing — ko'nikmoq.","Yangi so'zlar: nostalgic, treasure, carry on, look back, move on."]}]},{"id":"u19","n":19,"title":"Telling stories and reporting","titleUz":"Hikoya aytish va gapni ko'chirish: Past Perfect, reported speech","description":"Past Perfect, hikoya zamonlari, ko'chirma gap (bayon, savol, iltimos), reporting fe'llari va yangiliklar.","canDo":["O'tmishdagi voqealarni to'g'ri tartibda (Past Perfect, Past Simple, Past Continuous) hikoya qilaman","Boshqalarning gapini, savolini va buyrug'ini ko'chirma gap bilan aytib beraman","Politsiyaga voqea haqida xabar beraman va muloyim shikoyat qilaman","Qisqa hikoya yoki yangilik maqolasini bog'lovchilar bilan yozaman"],"lessons":[{"id":"u19-l1","slug":"past-perfect-what-had-happened-before","title":"Past Perfect: what had happened before","titleUz":"Past Perfect: o'tmishdan oldin nima bo'lgan edi","goal":"Past Perfect (had + V3) ni yasaysiz va o'tmishdagi ikki voqeadan oldin bo'lganini to'g'ri ifodalaysiz: When I arrived, the film had already started. Inkor, savol va never, already, just, yet bilan ishlata olasiz.","words":[{"en":"burst into tears","uz":"yig'lab yubormoq","ipa":"bɜːst ˈɪn.tuː tɪəz"},{"en":"spot","uz":"ko'rib qolmoq, payqab qolmoq","ipa":"spɒt"},{"en":"run out of","uz":"...i tugab qolmoq","ipa":"rʌn aʊt əv"},{"en":"recognise","uz":"tanimoq","ipa":"ˈrek.əɡ.naɪz"},{"en":"disappear","uz":"g'oyib bo'lmoq","ipa":"ˌdɪs.əˈpɪər"},{"en":"get lost","uz":"adashib qolmoq","ipa":"ɡet lɒst"},{"en":"misplace","uz":"qayoqqadir qo'yib yo'qotmoq","ipa":"ˌmɪsˈpleɪs"},{"en":"set off","uz":"yo'lga chiqmoq","ipa":"set ɒf"},{"en":"leave behind","uz":"qoldirib ketmoq","ipa":"liːv bɪˈhaɪnd"},{"en":"double-check","uz":"yana bir bor tekshirmoq","ipa":"ˌdʌb.əl ˈtʃek"}],"summary":["Past Perfect = had + V3 (had finished, had gone). Hamma shaxs uchun bir xil: I had, she had, they had.","U o'tmishdagi ikki voqeadan oldin bo'lganini ko'rsatadi: When I arrived, the train had left.","Inkor: hadn't + V3. Savol: Had + ega + V3? Qisqa javob: Yes, I had. / No, I hadn't.","already, just, never ... before, yet, ever — had dan keyin keladi: She had already left.","Xatolar: ~~I had went~~ (to'g'risi had gone); Past Perfect ni yolg'iz va aniq vaqt bilan ishlatmang."]},{"id":"u19-l12","slug":"past-perfect-or-past-simple-before-after-by-the-time","title":"Past Perfect or Past Simple? Before, after, by the time","titleUz":"Past Perfect yoki Past Simple? Before, after, by the time","goal":"O'tmishdagi ikki voqeadan qaysi biri oldin bo'lganini ko'rsatasiz: oldingisiga Past Perfect, keyingisiga Past Simple ishlatasiz va before, after, by the time, as soon as so'zlarini to'g'ri qo'llaysiz (By the time we arrived, the film had started.).","words":[{"en":"by the time","uz":"...ga kelib, ...gacha (vaqtga kelib)","ipa":"baɪ ðə taɪm"},{"en":"by then","uz":"o'sha vaqtga kelib","ipa":"baɪ ðen"},{"en":"turn up","uz":"kelib qolmoq, paydo bo'lmoq","ipa":"tɜːn ʌp"},{"en":"turn out","uz":"bo'lib chiqmoq","ipa":"tɜːn aʊt"},{"en":"not long after","uz":"...dan ko'p o'tmay","ipa":"nɒt lɒŋ ˈɑːf.tər"}],"summary":["Oldin bo'lgan ish — Past Perfect (had left), keyin bo'lgan ish — Past Simple (arrived).","before / after tartibni o'zi ko'rsatadi: ikkalasi Past Simple bo'lishi ham mumkin. Ketma-ket ishlarni ikkala bo'lakda ham Past Perfect qilmang.","By the time + Past Simple, asosiy gap — Past Perfect: By the time we arrived, the shop had closed.","as soon as (...ishi bilan), by then (o'sha vaqtga kelib), turn out, realise — hikoyada foydali."]},{"id":"u19-l2","slug":"narrative-tenses-together","title":"Narrative tenses together","titleUz":"Hikoya zamonlari birga: Past Simple, Continuous, Perfect","goal":"Hikoya aytganda Past Simple (asosiy voqealar), Past Continuous (fon va to'xtatilgan ish) va Past Perfect (oldin bo'lgan voqea) ni birga ishlatasiz va when / while bilan to'g'ri gap tuzasiz.","words":[{"en":"gasp","uz":"hayratdan ah tortmoq","ipa":"ɡɑːsp"},{"en":"glance","uz":"bir qarab olmoq","ipa":"ɡlɑːns"},{"en":"whisper","uz":"pichirlamoq","ipa":"ˈwɪs.pər"},{"en":"wander","uz":"kezib yurmoq","ipa":"ˈwɒn.dər"},{"en":"stare","uz":"tikilib qaramoq","ipa":"steər"},{"en":"crowd","uz":"olomon","ipa":"kraʊd"},{"en":"thunder","uz":"momaqaldiroq","ipa":"ˈθʌn.dər"},{"en":"silence","uz":"sukunat","ipa":"ˈsaɪ.ləns"},{"en":"escape","uz":"qochib qutulmoq","ipa":"ɪˈskeɪp"},{"en":"chase","uz":"quvmoq","ipa":"tʃeɪs"}],"summary":["Past Simple — asosiy voqealar birin-ketin: He opened the door and went in.","Past Continuous — fon va to'xtatilgan uzun ish: I was walking home when I saw an accident.","Past Perfect — voqeadan oldin bo'lgan ish: She was upset because she had lost her phone.","while + Continuous, when + qisqa voqea. Ikki parallel ish: While I was cooking, he was watching TV.","Stative fe'llar (know, like, want, be) Continuous bo'lmaydi: I knew, emas ~~I was knowing~~."]},{"id":"u19-l3","slug":"reported-speech-statements","title":"Reported speech: statements","titleUz":"Reported speech: darak gaplar (say, tell, zamon siljishi)","goal":"Birovning gapini reported speech da aytasiz: say va tell ni farqlaysiz, zamonni bir pog'ona orqaga siljitasiz (am - was, will - would), olmosh va vaqt so'zlarini (tomorrow - the next day) to'g'ri almashtirasiz.","words":[{"en":"explain","uz":"tushuntirmoq","ipa":"ɪkˈspleɪn"},{"en":"remark","uz":"fikr bildirmoq, izoh bermoq","ipa":"rɪˈmɑːk"},{"en":"complain","uz":"shikoyat qilmoq","ipa":"kəmˈpleɪn"},{"en":"boast","uz":"maqtanmoq","ipa":"bəʊst"},{"en":"insist","uz":"turib olmoq","ipa":"ɪnˈsɪst"},{"en":"inform","uz":"xabardor qilmoq","ipa":"ɪnˈfɔːm"},{"en":"rumour","uz":"mish-mish","ipa":"ˈruː.mər"},{"en":"assure","uz":"ishontirmoq, kafolat bermoq","ipa":"əˈʃɔːr"},{"en":"gossip","uz":"g'iybat, mish-mish","ipa":"ˈɡɒs.ɪp"},{"en":"declare","uz":"e'lon qilmoq, rasman bildirmoq","ipa":"dɪˈkleər"}],"summary":["Reported speech: tirnoq yo'q, oddiy gap tartibi, odatda zamon bir pog'ona orqaga: \"I'm tired.\" → She said she was tired.","Zamon siljishi: Present Simple → Past Simple; Present Perfect va Past Simple → Past Perfect; will → would, can → could, must → had to.","Vaqt va joy: now → then, tomorrow → the next day, yesterday → the day before, here → there, this → that.","say + gap (kishisiz); tell + kishi: He told me…. Xato: ~~He said me~~, ~~He told to me~~.","Aytilgan gap hamon haqiqat bo'lsa yoki says hozirgi zamonda bo'lsa, siljitish shart emas."]},{"id":"u19-l4","slug":"reported-questions-requests-and-orders","title":"Reported questions, requests and orders","titleUz":"Ko'chirma savollar, iltimos va buyruqlar","goal":"Birovning savolini (She asked me where I lived), iltimosini (asked me to help) va buyrug'ini (told me not to be late) reported speech da to'g'ri yetkazasiz. Do / did ishlatmaysiz, so'roq gap tartibini darak tartibiga aylantirasiz.","words":[{"en":"ask for","uz":"so'ramoq, talab qilmoq (narsani)","ipa":"ɑːsk fɔː"},{"en":"beg","uz":"yalinmoq, ko'p iltimos qilmoq","ipa":"beɡ"},{"en":"instruction","uz":"ko'rsatma","ipa":"ɪnˈstrʌk.ʃən"},{"en":"forbid","uz":"taqiqlamoq","ipa":"fəˈbɪd"},{"en":"advise","uz":"maslahat bermoq","ipa":"ədˈvaɪz"},{"en":"manners","uz":"odob, xulq-atvor qoidalari","ipa":"ˈmæn.əz"},{"en":"impolite","uz":"odobsiz, muloyim emas","ipa":"ˌɪm.pəˈlaɪt"},{"en":"urgent","uz":"shoshilinch","ipa":"ˈɜː.dʒənt"},{"en":"enquire","uz":"so'ramoq, surishtirmoq","ipa":"ɪnˈkwaɪər"},{"en":"demand","uz":"qat'iy talab qilmoq","ipa":"dɪˈmɑːnd"}],"summary":["Ko'chirma savolda savol belgisi yo'q, do / does / did yo'q, tartib: ega + fe'l: She asked where I lived.","Yes / No savol → if / whether: He asked if I was ready. Zamon bir pog'ona orqaga suriladi.","Iltimos va buyruq: asked / told + kishi + to + V1: She asked me to wait. Inkor: not to: He told me not to worry.","Savol so'zi ega bo'lsa tartib o'zgarmaydi: She asked who had called.","Xatolar: ~~asked me where did I live~~, ~~told me don't worry~~, ~~asked me that~~."]},{"id":"u19-l13","slug":"reporting-verbs-suggest-promise-admit-deny","title":"Reporting verbs: suggest, promise, admit, deny","titleUz":"Reporting fe'llari: suggest, promise, admit, deny, warn","goal":"Gapni say o'rniga aniqroq fe'l bilan ko'chirasiz: promise to do, offer to do, refuse to do, admit / deny / suggest doing, warn somebody (not) to do (He denied breaking the window. She warned us not to touch it.).","words":[{"en":"hint","uz":"ishora qilmoq, shama qilmoq","ipa":"hɪnt"},{"en":"accuse","uz":"ayblamoq","ipa":"əˈkjuːz"},{"en":"admit","uz":"tan olmoq","ipa":"ədˈmɪt"},{"en":"deny","uz":"inkor qilmoq","ipa":"dɪˈnaɪ"},{"en":"own up","uz":"aybini tan olmoq","ipa":"əʊn ʌp"},{"en":"grumble","uz":"noliy-noliy aytmoq, g'ulduramoq","ipa":"ˈɡrʌm.bəl"},{"en":"swear","uz":"qasam ichmoq","ipa":"sweər"}],"summary":["promise, offer, refuse + to + fe'l: He promised to call me.","admit, deny, suggest + -ing: She denied taking the money. He suggested going by train.","warn + kim + (not) to + fe'l: She warned us not to touch it. suggested me to — xato.","Hammasidan keyin that + gap ham kelishi mumkin: He admitted that he had lied."]},{"id":"u19-l9","slug":"reporting-an-incident","title":"Reporting an incident","titleUz":"Voqea haqida xabar berish: yo'l hodisasi, o'g'rilik","goal":"Politsiyaga yo'l hodisasi yoki o'g'rilik haqida xabar berasiz: nima, qachon va qayerda bo'lganini aytasiz, odam va narsani tasvirlaysiz va boshqalar sizga nima deganini ko'chirasiz (He told me he had lost control.).","words":[{"en":"witness","uz":"guvoh","ipa":"ˈwɪt.nəs"},{"en":"injured","uz":"jarohatlangan","ipa":"ˈɪn.dʒəd"},{"en":"crash","uz":"to'qnashmoq; to'qnashuv","ipa":"kræʃ"},{"en":"theft","uz":"o'g'irlik","ipa":"θeft"},{"en":"break in","uz":"bostirib kirmoq","ipa":"breɪk ɪn"},{"en":"make a statement","uz":"ko'rsatma bermoq","ipa":"meɪk ə ˈsteɪt.mənt"}],"summary":["Xabar berish: I'd like to report a theft / a road accident. So'ng: what, when, where.","Nima bo'lgani — Past Simple, fon — Past Continuous, undan oldingi ish — Past Perfect (I had locked it).","Boshqalarning gapi: told me that he had lost control; said (that)… bilan me ishlatilmaydi.","Foydali so'zlar: witness, injured, crash, steal – stole – stolen, damage, make a statement."]},{"id":"u19-l5","slug":"news-and-media","title":"News and media","titleUz":"Yangiliklar va ommaviy axborot: so'zlar va sarlavhalar","goal":"Yangiliklar va ommaviy axborot lug'atini (headline, journalist, source, reliable, rumour…) o'rganasiz, sarlavhalarning qisqa uslubini tushunasiz va xabarning ishonchli yoki ishonchsiz ekanini ayta olasiz.","words":[{"en":"headline","uz":"sarlavha","ipa":"ˈhed.laɪn"},{"en":"newspaper","uz":"gazeta","ipa":"ˈnjuːzˌpeɪ.pər"},{"en":"editor","uz":"muharrir","ipa":"ˈed.ɪ.tər"},{"en":"broadcast","uz":"efirga uzatmoq; teleko'rsatuv","ipa":"ˈbrɔːd.kɑːst"},{"en":"source","uz":"manba","ipa":"sɔːs"},{"en":"fake","uz":"soxta, yolg'on","ipa":"feɪk"},{"en":"coverage","uz":"yoritish (ommaviy axborotda)","ipa":"ˈkʌv.ər.ɪdʒ"},{"en":"bias","uz":"tarafkashlik","ipa":"ˈbaɪ.əs"},{"en":"viewer","uz":"tomoshabin","ipa":"ˈvjuː.ər"},{"en":"breaking news","uz":"shoshilinch xabar","ipa":"ˈbreɪ.kɪŋ njuːz"}],"summary":["Asosiy so'zlar: headline (sarlavha), journalist, article, source (manba), witness (guvoh), publish (chop etmoq), broadcast (efirga uzatmoq).","Sarlavha uslubi: artikl tushiriladi, o'tgan voqea uchun Present Simple (Thieves steal painting), kelasi zamon uchun to + fe'l (Shop to open), majhul nisbat uchun faqat V3 (Man rescued).","News — sanalmaydigan ot: ~~a news~~ emas, some news yoki a piece of news; breaking news — shoshilinch xabar.","Ishonchlilik: reliable (ishonchli), rumour (mish-mish), fake news, according to + manba. Ulashishdan oldin manbani tekshiring."]},{"id":"u19-l6","slug":"linking-a-story-suddenly-meanwhile-in-the-end","title":"Linking a story: suddenly, meanwhile, in the end","titleUz":"Hikoyada bog'lovchilar: suddenly, meanwhile, eventually, in the end","goal":"Hikoyani bog'lovchi so'zlar bilan tartibli va qiziqarli aytasiz: at first, then, suddenly, meanwhile, as soon as, eventually, in the end va in the end / at the end farqini bilasiz.","words":[{"en":"after a while","uz":"bir ozdan keyin","ipa":"ˈɑːf.tər ə waɪl"},{"en":"after that","uz":"shundan keyin","ipa":"ˈɑːf.tər ðæt"},{"en":"from then on","uz":"o'shandan boshlab","ipa":"frɒm ðen ɒn"},{"en":"later on","uz":"keyinroq","ipa":"ˈleɪ.tər ɒn"},{"en":"to begin with","uz":"avvalo, boshida","ipa":"tə bɪˈɡɪn wɪð"},{"en":"soon afterwards","uz":"oradan ko'p o'tmay","ipa":"suːn ˈɑːf.tə.wədz"},{"en":"fortunately","uz":"yaxshiyamki","ipa":"ˈfɔː.tʃən.ət.li"},{"en":"by chance","uz":"tasodifan","ipa":"baɪ tʃɑːns"},{"en":"before long","uz":"tez orada","ipa":"bɪˈfɔː lɒŋ"},{"en":"to my surprise","uz":"hayratimga","ipa":"tə maɪ səˈpraɪz"}],"summary":["Tartib: at first (boshida), then / after that / later / afterwards (keyin), finally / in the end / eventually (oxirida). Gap boshida bog'lovchidan keyin vergul qo'yiladi.","To'satdan: suddenly, all of a sudden, just then + Past Simple. Fon uchun Past Continuous: I was walking when suddenly…","Bir vaqtda: meanwhile yangi gapni boshlaydi; bitta gap ichida while ishlating.","In the end (natija) va at the end of + ot (oxirida) boshqa-boshqa. Eventually = oxir-oqibat, «mumkin» emas!","Fortunately / unfortunately (omad / omadsizlik), as soon as + Past Simple (...ishi bilanoq)."]},{"id":"u19-l14","slug":"listening-and-speaking-a-news-report","title":"Listening and speaking: a news report","titleUz":"Tinglash va gapirish: yangiliklar ma'ruzasi","goal":"Qisqa yangiliklar ma'ruzasini tinglab asosiy ma'lumotni (kim, nima, qayerda, qachon) tushunasiz va uni According to…, X said that…, X warned people not to… bilan do'stingizga qayta aytib berasiz.","words":[{"en":"bulletin","uz":"yangiliklar xabarnomasi","ipa":"ˈbʊl.ə.tɪn"},{"en":"flood","uz":"toshqin","ipa":"flʌd"},{"en":"rescue","uz":"qutqaruv; qutqarmoq","ipa":"ˈres.kjuː"},{"en":"according to","uz":"...ning aytishicha","ipa":"əˈkɔː.dɪŋ tuː"},{"en":"emergency services","uz":"favqulodda xizmatlar","ipa":"ɪˈmɜː.dʒən.si ˈsɜː.vɪ.sɪz"}],"summary":["Yangilikni ikki marta tinglang: avval umumiy ma'no, keyin raqam, vaqt va manba.","Manba: According to the police, … / The mayor said that…","Qayta aytganda zamon siljiydi (will → would), warned people not to…, promised that….","Keyingi yangilikka Meanwhile bilan o'ting. Sekin va aniq gapiring."]},{"id":"u19-l10","slug":"making-a-complaint","title":"Making a complaint","titleUz":"Shikoyat qilish: mahsulot yoki xizmatdan norozilik","goal":"Do'konda yoki mehmonxonada muloyim, lekin qat'iy shikoyat qilasiz: muammoni tushuntirasiz (I bought it last week, but it doesn't work), refund yoki replacement so'raysiz va sizga aytilgan gapni ko'chirasiz (The assistant told me that I could return it).","words":[{"en":"defective","uz":"nuqsonli, yaroqsiz","ipa":"dɪˈfek.tɪv"},{"en":"compensation","uz":"tovon, kompensatsiya","ipa":"ˌkɒm.penˈseɪ.ʃən"},{"en":"let down","uz":"umidini oqlamay xafa qilmoq","ipa":"let daʊn"},{"en":"replacement","uz":"almashtirish; o'rniga beriladigan yangi narsa","ipa":"rɪˈpleɪs.mənt"},{"en":"unacceptable","uz":"qabul qilib bo'lmaydigan","ipa":"ˌʌn.əkˈsep.tə.bəl"}],"summary":["Shikoyat tartibi: Excuse me, I'd like to make a complaint. → muammo → Could I have a refund / replacement, please?","Muloyim bo'ling: I'm afraid…, Could I…?, I'd like…. Qat'iy, lekin qo'pol emas: I'm afraid that's not acceptable.","Muammoni Past Simple (I bought it last week) va Past Perfect (I had tried to fix it) bilan ayting.","Sizga aytilgan gap: The assistant told me that I could return it."]},{"id":"u19-l7","slug":"writing-a-story","title":"Writing a story","titleUz":"Yozish: qiziqarli hikoya","goal":"Hikoyani boshi, o'rtasi va oxiri bilan tuzasiz, tasvirni jonli qilasiz, to'g'ridan-to'g'ri nutqni to'g'ri yozasiz (\"I'm tired,\" said Tom.) va tayyor hikoyani o'zingiz tekshirasiz.","words":[{"en":"plot","uz":"syujet, voqealar zanjiri","ipa":"plɒt"},{"en":"character","uz":"qahramon, personaj","ipa":"ˈkær.ək.tər"},{"en":"setting","uz":"voqea joyi va vaqti","ipa":"ˈset.ɪŋ"},{"en":"ending","uz":"yakun, oxiri","ipa":"ˈen.dɪŋ"},{"en":"narrator","uz":"hikoyachi","ipa":"nəˈreɪ.tər"},{"en":"vivid","uz":"jonli, yorqin","ipa":"ˈvɪv.ɪd"},{"en":"dialogue","uz":"dialog, suhbat","ipa":"ˈdaɪ.ə.lɒɡ"},{"en":"draft","uz":"qoralama","ipa":"drɑːft"},{"en":"edit","uz":"tahrir qilmoq","ipa":"ˈed.ɪt"},{"en":"creative","uz":"ijodkor, ijodiy","ipa":"kriˈeɪ.tɪv"}],"summary":["Hikoya uch qismdan iborat: beginning (joy, vaqt, qahramonlar), middle (muammo, voqealar), ending (yechim, his-tuyg'u). Yozishdan oldin reja tuzing.","Jonli yozing: «u qo'rqdi» o'rniga aniq harakat va tasvir bering (her hands were shaking). Aniq fe'l ko'p sifatdan yaxshi.","To'g'ridan-to'g'ri nutq: \"I'm tired,\" said Tom. Vergul tirnoq ichida, fe'l kichik harfda; olmosh bilan he said.","Zamonlar: asosiy voqealar Past Simple, fon Past Continuous, oldingi voqea Past Perfect. Bog'lovchilar: at first, suddenly, meanwhile, in the end.","Yozib bo'lgach draft ni o'qing va edit qiling: zamonlar, tinish belgilari, gap boshlanishlari."]},{"id":"u19-l15","slug":"reading-and-writing-a-news-article","title":"Reading and writing: a news article","titleUz":"O'qish va yozish: yangilik maqolasi","goal":"Qisqa yangilik maqolasini o'qib tuzilishini tushunasiz (sarlavha, asosiy gap, tafsilot, iqtibos) va o'zingiz 6–8 gapli maqola yozasiz: announced that…, said that…, promised to… va meanwhile, eventually bilan.","words":[{"en":"spokesperson","uz":"vakil, matbuot kotibi","ipa":"ˈspəʊks.pɜː.sən"},{"en":"announce","uz":"e'lon qilmoq","ipa":"əˈnaʊns"},{"en":"quote","uz":"iqtibos; iqtibos keltirmoq","ipa":"kwəʊt"},{"en":"council","uz":"kengash (shahar)","ipa":"ˈkaʊn.səl"},{"en":"organiser","uz":"tashkilotchi","ipa":"ˈɔː.ɡən.aɪ.zər"}],"summary":["Maqola tuzilishi: sarlavha → birinchi gap (kim, nima, qachon) → tafsilot → iqtibos → keyin nima bo'ladi.","Fe'llar: announced that…, said that…, told reporters that…, promised that… (will → would).","Iqtibos qo'shtirnoqda aynan beriladi: \"…,\" the spokesperson said.","Hikoyani bog'lang: at first, meanwhile, eventually."]},{"id":"u19-l8","slug":"unit-review-stories-and-reporting","title":"Unit review: stories and reporting","titleUz":"Bosqich takrori: hikoya va ko'chirma gap","goal":"Bosqichni takrorlaysiz: Past Perfect va hikoya zamonlari, reported speech (darak, savol, iltimos), hikoya bog'lovchilari va yangilik tili. Hammasini yangi misollarda ishlatib ko'rasiz.","words":[{"en":"disaster","uz":"falokat","ipa":"dɪˈzɑː.stər"},{"en":"claim","uz":"da'vo qilmoq, ta'kidlamoq","ipa":"kleɪm"},{"en":"earthquake","uz":"zilzila","ipa":"ˈɜːθ.kweɪk"},{"en":"incident","uz":"hodisa, voqea","ipa":"ˈɪn.sɪ.dənt"},{"en":"tragedy","uz":"fojea","ipa":"ˈtrædʒ.ə.di"},{"en":"survive","uz":"omon qolmoq","ipa":"səˈvaɪv"},{"en":"victim","uz":"jabrlanuvchi","ipa":"ˈvɪk.tɪm"},{"en":"official","uz":"rasmiy shaxs; rasmiy","ipa":"əˈfɪʃ.əl"},{"en":"recall","uz":"eslamoq, yodga olmoq","ipa":"rɪˈkɔːl"},{"en":"unexpected","uz":"kutilmagan","ipa":"ˌʌn.ɪkˈspek.tɪd"}],"summary":["Past Perfect (had + V3) boshqa o'tgan voqeadan oldingi ishni bildiradi; asosiy voqealar Past Simple, fon Past Continuous.","Reported statements: zamon bir pog'ona orqaga (am → was, will → would, can → could, went → had gone); say + ob'ektsiz, tell + kimga.","Reported questions: darak tartib, do/did tushadi, savol belgisi yo'q; yes/no savolda if / whether. Iltimos: ask / tell + kimga + (not) to + fe'l.","Hikoya bog'lovchilari: at first, suddenly, meanwhile, as soon as, in the end. Yangilik tili: headline, source, reliable, rumour, according to.","Yozishdan keyin tekshiring: zamonlar, nutq tinish belgilari va bog'lovchilar."]},{"id":"u19-l11","slug":"stories-and-reporting-final-review","title":"Stories and reporting: final review","titleUz":"Hikoya va ko'chirma gap: yakuniy takror","goal":"Butun bosqichni takrorlaysiz: Past Perfect, hikoya zamonlari, ko'chirma gap (darak, savol, buyruq), reporting fe'llari va hikoya bog'lovchilari (suddenly, meanwhile, eventually).","words":[{"en":"exclaim","uz":"hayajon bilan aytmoq","ipa":"ɪkˈskleɪm"},{"en":"reveal","uz":"oshkor qilmoq","ipa":"rɪˈviːl"},{"en":"murmur","uz":"pichirlab aytmoq, g'o'ldiramoq","ipa":"ˈmɜː.mər"},{"en":"recount","uz":"hikoya qilib bermoq","ipa":"rɪˈkaʊnt"},{"en":"congratulate","uz":"tabriklamoq","ipa":"kənˈɡrætʃ.ə.leɪt"}],"summary":["Hikoya: Past Simple (voqea), Past Continuous (fon), Past Perfect (oldingi ish).","Ko'chirma gap: zamon bir qadam o'tmishga (is → was, will → would); savolda if / whether va oddiy tartib; buyruqda to / not to.","Reporting fe'llari: promise to, deny / admit / suggest -ing, warn somebody (not) to.","Bog'lovchilar: suddenly, meanwhile, eventually."]}]},{"id":"u20","n":20,"title":"Possibilities and imagination","titleUz":"Imkoniyatlar va tasavvur: shart gaplar, wish, taxmin","description":"Second va third conditional, wish, taxmin modal fe'llari (must, might, can't), maslahat va pushaymonlik.","canDo":["If I were… va if I had… bilan xayoliy va o'tgan zamon vaziyatlarini aytaman","I wish bilan orzu va pushaymonligimni bildiraman","must, might, can't bilan taxmin qilaman va should have bilan o'tgan ishlarni baholayman","Do'stga muloyim maslahat beraman va uzr so'rayman"],"lessons":[{"id":"u20-l1","slug":"second-conditional-imaginary-situations","title":"Second conditional: imaginary situations","titleUz":"Second conditional: xayoliy vaziyatlar (If I were…, I would…)","goal":"Second conditional (If I won the lottery, I would travel the world) yordamida hozirgi va kelajakdagi xayoliy yoki ehtimoli kam vaziyatlar haqida gapirasiz, If I were you bilan maslahat berasiz va if dan keyin would qo'yish xatosidan qochasiz.","words":[{"en":"imagine","uz":"tasavvur qilmoq","ipa":"ɪˈmædʒ.ɪn"},{"en":"lottery","uz":"lotereya","ipa":"ˈlɒt.ər.i"},{"en":"millionaire","uz":"millioner","ipa":"ˌmɪl.jəˈneər"},{"en":"inherit","uz":"meros qilib olmoq","ipa":"ɪnˈher.ɪt"},{"en":"quit","uz":"tashlab ketmoq, to'xtatmoq","ipa":"kwɪt"},{"en":"fortune","uz":"boylik, katta pul","ipa":"ˈfɔː.tʃuːn"},{"en":"unlikely","uz":"ehtimoldan yiroq","ipa":"ʌnˈlaɪk.li"},{"en":"mansion","uz":"saroy, katta hashamatli uy","ipa":"ˈmæn.ʃən"},{"en":"invest","uz":"sarmoya kiritmoq","ipa":"ɪnˈvest"},{"en":"luxury","uz":"hashamat, dabdabali","ipa":"ˈlʌk.ʃər.i"}],"summary":["Second conditional: If + Past Simple, would + V1 — hozirgi va kelajakdagi xayoliy yoki ehtimoli kam vaziyat.","Past Simple bu yerda o'tgan zamon emas: u gapning xayoliy ekanini ko'rsatadi. If I had a car, I would…","were hamma shaxs uchun mumkin: If I were rich… Maslahat qolipi: If I were you, I would…","Xato: ~~If I would have~~. If dan keyin would (va will) qo'yilmaydi. To'g'risi: If I had…","Savol: What would you do if…? Qisqa javob: Yes, I would. / No, I wouldn't. Ba'zan would o'rniga could yoki might ishlatiladi."]},{"id":"u20-l12","slug":"i-wish-present-and-past","title":"I wish… (present and past)","titleUz":"I wish…: hozirgi va o'tgan zamon orzu-pushaymonligi","goal":"I wish bilan hozirgi hayotingizdan norozilikni (I wish I had more time.) va o'tgan zamon pushaymonligini (I wish I had studied harder.) aytasiz, hamda wish bilan hope ni adashtirmaysiz.","words":[{"en":"homesick","uz":"vatanini sog'ingan","ipa":"ˈhəʊm.sɪk"},{"en":"pity","uz":"afsus, achinarli hol","ipa":"ˈpɪt.i"},{"en":"envy","uz":"hasad qilmoq, havas qilmoq","ipa":"ˈen.vi"},{"en":"overseas","uz":"xorijda, chet elda","ipa":"ˌəʊ.vəˈsiːz"},{"en":"stubborn","uz":"qaysar, o'jar","ipa":"ˈstʌb.ən"}],"summary":["I wish + Past Simple / could / were — hozirgi vaziyat yoqmaydi: I wish I had a car. I wish I could swim. I wish I were taller.","I wish + had + V3 — o'tgan zamon pushaymonligi: I wish I had studied harder. I wish I hadn't said that.","wish dan keyin am, can, have emas, \"orqaga\" shakl keladi; I wish I would have… — xato.","hope — bo'lishi mumkin ish (I hope you pass), wish — o'zgartirib bo'lmaydigan narsa.","Yangi so'zlar: homesick, pity, envy, overseas, stubborn."]},{"id":"u20-l2","slug":"first-or-second-conditional-unless-as-long-as","title":"First or second conditional? Unless, as long as","titleUz":"First yoki second conditional? Unless, as long as, provided","goal":"First va second conditional ni to'g'ri tanlaysiz (real yoki xayoliy), unless, as long as, provided (that) so'zlarini ishlatasiz va unless bilan qo'shimcha inkor qo'yish xatosidan qochasiz.","words":[{"en":"condition","uz":"shart, holat","ipa":"kənˈdɪʃ.ən"},{"en":"likely","uz":"ehtimol, mumkin","ipa":"ˈlaɪk.li"},{"en":"risk","uz":"xavf, tavakkal","ipa":"rɪsk"},{"en":"warranty","uz":"kafolat muddati","ipa":"ˈwɒr.ən.ti"},{"en":"fee","uz":"to'lov, haq","ipa":"fiː"},{"en":"guarantee","uz":"kafolat","ipa":"ˌɡær.ənˈtiː"},{"en":"penalty","uz":"jarima","ipa":"ˈpen.əl.ti"},{"en":"eligible","uz":"huquqi bor, munosib","ipa":"ˈel.ɪ.dʒə.bəl"},{"en":"otherwise","uz":"aks holda","ipa":"ˈʌð.ə.waɪz"},{"en":"depend on","uz":"…ga bog'liq bo'lmoq","ipa":"dɪˈpend ɒn"}],"summary":["First conditional (If I get…, I will…) — real, mumkin. Second conditional (If I got…, I would…) — ehtimoli kam yoki xayoliy. Tanlov sizning fikringizga bog'liq.","Unless = if … not. Undan keyin darak fe'l keladi: Unless you hurry… (~~Unless you don't hurry~~ — xato).","as long as, provided (that), providing (that) = faqat shu shart bajarilsa. Ulardan keyin Present Simple: as long as I have time.","if, unless, as long as dan keyin will qo'yilmaydi. In case esa «oldindan tayyorgarlik» ma'nosini beradi, if ga teng emas."]},{"id":"u20-l3","slug":"third-conditional-past-regrets","title":"Third conditional: past regrets","titleUz":"Third conditional: o'tgan zamon pushaymonligi","goal":"Third conditional (If I had left earlier, I wouldn't have missed the bus) yordamida o'tmishda bo'lmagan narsa haqida pushaymonlik yoki yengillik bildirasiz va If I would have known kabi xatodan qochasiz.","words":[{"en":"injure","uz":"jarohatlamoq","ipa":"ˈɪn.dʒər"},{"en":"furious","uz":"g'azabdan qutirgan","ipa":"ˈfjʊə.ri.əs"},{"en":"blame","uz":"ayblamoq","ipa":"bleɪm"},{"en":"fault","uz":"ayb, nuqson","ipa":"fɔːlt"},{"en":"guilty","uz":"aybdor, vijdoni qiynalgan","ipa":"ˈɡɪl.ti"},{"en":"ashamed","uz":"uyalgan, xijolat bo'lgan","ipa":"əˈʃeɪmd"},{"en":"misunderstand","uz":"noto'g'ri tushunmoq","ipa":"ˌmɪs.ʌn.dəˈstænd"},{"en":"consequence","uz":"oqibat","ipa":"ˈkɒn.sɪ.kwəns"},{"en":"unfair","uz":"adolatsiz","ipa":"ʌnˈfeər"},{"en":"ignore","uz":"e'tiborsiz qoldirmoq","ipa":"ɪɡˈnɔːr"}],"summary":["Third conditional: If + had + V3, would have + V3 — o'tmishda bo'lmagan narsa haqida (pushaymonlik, yengillik, tanqid).","Inkor: If I hadn't…, I wouldn't have…. Natijada would o'rniga could have (qila olardim) va might have (ehtimol) ham mumkin.","Xato: ~~If I would have known~~. If dan keyin had + V3: If I had known…","Vaqtni farqlang: hozir/kelajak — second (If I had a car, I would drive); o'tgan zamon — third (If I had had a car, I would have driven).","Savol: What would you have done if you had…? Qisqa javob: Yes, I would. / No, I wouldn't."]},{"id":"u20-l4","slug":"modals-of-deduction-must-might-cant","title":"Modals of deduction: must, might, can't","titleUz":"Taxmin modallari: must, might, can't (must have been)","goal":"must, might / may / could, can't yordamida hozirgi va o'tgan zamon haqida taxmin qilasiz (He must be at work. She can't have seen it. They might have left) va mustn't bilan can't ni adashtirmaysiz.","words":[{"en":"obvious","uz":"aniq, ravshan","ipa":"ˈɒb.vi.əs"},{"en":"evidence","uz":"dalil","ipa":"ˈev.ɪ.dəns"},{"en":"certain","uz":"ishonchi komil","ipa":"ˈsɜː.tən"},{"en":"suspect","uz":"gumon qilmoq","ipa":"səˈspekt"},{"en":"clue","uz":"ishora, iz","ipa":"kluː"},{"en":"mystery","uz":"sir, jumboq","ipa":"ˈmɪs.tər.i"},{"en":"guess","uz":"taxmin qilmoq","ipa":"ɡes"},{"en":"presumably","uz":"ehtimol, shunday bo'lsa kerak","ipa":"prɪˈzjuː.mə.bli"},{"en":"possibly","uz":"ehtimol, balki","ipa":"ˈpɒs.ə.bli"},{"en":"conclusion","uz":"xulosa","ipa":"kənˈkluː.ʒən"}],"summary":["Hozirgi taxmin: must be (deyarli aniq, ha), might / may / could be (ehtimol), can't be (deyarli aniq, yo'q). Davom etayotgan ish: must be working.","O'tgan taxmin: modal + have + V3 — must have gone, might have forgotten, can't have seen.","Taxmin inkori — can't, mustn't emas! Mustn't — taqiq (You mustn't park here).","Ehtimol-inkor uchun might not / may not: She might not be at home. Modaldan keyin to qo'yilmaydi."]},{"id":"u20-l13","slug":"modals-in-the-past-should-have-could-have","title":"Modals in the past: should have, could have","titleUz":"O'tgan zamon modallari: should have, could have, needn't have","goal":"should have, could have, needn't have bilan o'tgan zamondagi ishlarni baholaysiz (You should have called me. We could have won. You needn't have waited.) va ularni third conditional bilan bog'laysiz.","words":[{"en":"waste","uz":"behuda sarflamoq, isrof qilmoq","ipa":"weɪst"},{"en":"oversleep","uz":"uxlab qolmoq","ipa":"ˌəʊ.vəˈsliːp"},{"en":"rush","uz":"shoshilmoq","ipa":"rʌʃ"},{"en":"neglect","uz":"e'tiborsiz qoldirmoq","ipa":"nɪˈɡlekt"},{"en":"overlook","uz":"ko'rmay qolmoq, e'tibor bermay o'tib ketmoq","ipa":"ˌəʊ.vəˈlʊk"}],"summary":["should have + V3 — qilish kerak edi (qilinmagan); shouldn't have + V3 — qilmaslik kerak edi (qilingan).","could have + V3 — o'tgan zamonda imkoniyat bor edi; needn't have + V3 — qilingan, lekin keraksiz bo'lgan.","have o'zgarmaydi, ortidan V3: should have gone, could have called. should has va could have went — xato.","Third conditional bilan bir fikr: If I had left earlier, I would have caught it = I should have left earlier.","Yangi so'zlar: waste, oversleep, rush, neglect, overlook."]},{"id":"u20-l9","slug":"giving-advice-to-a-friend","title":"Giving advice to a friend","titleUz":"Do'stga maslahat berish: muammoli vaziyat","goal":"Do'stingiz muammo haqida gapirganda muloyim va aniq maslahat berasiz (If I were you, I'd talk to her. Why don't you…?) va maslahatga javob berasiz (That's a good idea. I'll think about it.).","words":[{"en":"upset","uz":"xafa, ranjigan","ipa":"ʌpˈset"},{"en":"reassure","uz":"tinchlantirmoq, ishontirmoq","ipa":"ˌriː.əˈʃɔːr"},{"en":"calm down","uz":"tinchlanmoq","ipa":"kɑːm daʊn"},{"en":"sympathetic","uz":"hamdard, tushunadigan","ipa":"ˌsɪm.pəˈθet.ɪk"},{"en":"talk it over","uz":"(masalani) muhokama qilib olmoq","ipa":"tɔːk ɪt ˈəʊ.və"}],"summary":["Avval tinglang va hamdardlik bildiring: That sounds difficult. I'm sorry to hear that.","Maslahat: If I were you, I'd…, Why don't you…?, You could…, I think you should…","Maslahatga javob: That's a good idea. I'll think about it. yoki I'm not sure that would work.","Yangi so'zlar: upset, reassure, calm down, sympathetic, talk it over."]},{"id":"u20-l5","slug":"dreams-ambitions-and-feelings","title":"Dreams, ambitions and feelings","titleUz":"Orzu, intilish va his-tuyg'ular lug'ati","goal":"Orzu, maqsad va his-tuyg'ularni ifodalovchi B1 so'zlarini (ambition, achieve, determined, jealous, grateful…) to'g'ri old qo'shimchalar bilan ishlatasiz va -ed / -ing sifatlarini (disappointed / disappointing) adashtirmaysiz.","words":[{"en":"ambitious","uz":"intiluvchan, maqsadli","ipa":"æmˈbɪʃ.əs"},{"en":"pursue","uz":"intilmoq, ortidan bormoq","ipa":"pəˈsjuː"},{"en":"determined","uz":"qat'iyatli","ipa":"dɪˈtɜː.mɪnd"},{"en":"realistic","uz":"real, haqiqatga yaqin","ipa":"ˌrɪə.lɪˈstɪk"},{"en":"determination","uz":"qat'iyat, iroda","ipa":"dɪˌtɜː.mɪˈneɪ.ʃən"},{"en":"jealous","uz":"hasad qiluvchi","ipa":"ˈdʒel.əs"},{"en":"grateful","uz":"minnatdor","ipa":"ˈɡreɪt.fəl"},{"en":"anxious","uz":"xavotirli","ipa":"ˈæŋk.ʃəs"},{"en":"imagination","uz":"tasavvur, xayol","ipa":"ɪˌmædʒ.ɪˈneɪ.ʃən"},{"en":"thrilled","uz":"juda xursand, hayajonlangan","ipa":"θrɪld"}],"summary":["ambition, achieve, determined, realistic, come true — orzu va maqsad haqida gapirish uchun asosiy so'zlar.","dream of + -ing, determined to + fe'l: old qo'shimcha va keyingi shaklni birga yodlang.","Odam his qilsa -ed (disappointed, excited), narsa shunday ta'sir qilsa -ing (disappointing, exciting).","His sifatlarining o'z old qo'shimchasi bor: jealous of, proud of, anxious about, grateful to … for …, disappointed with."]},{"id":"u20-l6","slug":"advice-and-suggestions-should-ought-to-had-better","title":"Advice and suggestions: should, ought to, had better","titleUz":"Maslahat va taklif: should, ought to, had better, If I were you","goal":"should, ought to, had better va If I were you yordamida kuchli va yumshoq maslahat berasiz, suggest / recommend / advise fe'llarini to'g'ri qolipda ishlatasiz va should to go, an advice kabi xatolardan qochasiz.","words":[{"en":"recommendation","uz":"tavsiya","ipa":"ˌrek.ə.menˈdeɪ.ʃən"},{"en":"urge","uz":"qattiq maslahat bermoq, undamoq","ipa":"ɜːdʒ"},{"en":"wise","uz":"dono, oqilona","ipa":"waɪz"},{"en":"avoid","uz":"chetlab o'tmoq, qochmoq","ipa":"əˈvɔɪd"},{"en":"solve","uz":"hal qilmoq","ipa":"sɒlv"},{"en":"cope with","uz":"uddalamoq, bardosh bermoq","ipa":"kəʊp wɪð"},{"en":"deal with","uz":"bilan shug'ullanmoq, hal etmoq","ipa":"diːl wɪð"},{"en":"bear in mind","uz":"yodda tutmoq, hisobga olmoq","ipa":"beər ɪn maɪnd"},{"en":"think twice","uz":"yaxshilab o'ylab ko'rmoq","ipa":"θɪŋk twaɪs"},{"en":"take your time","uz":"shoshilmaslik, vaqt olmoq","ipa":"teɪk jɔː taɪm"}],"summary":["should / ought to — oddiy maslahat; had better — kuchli ogohlantirish (aks holda muammo). Uchalasidan keyin ham fe'l V1 (ought dan keyin to).","Xatolar: should to go, had better to go, had better don't — bularning hammasi noto'g'ri. Inkor: shouldn't, had better not.","Yumshoq maslahat: If I were you, I'd…, Why don't you…?, How about + -ing?, I suggest + -ing / you + V1.","suggest + you to go bo'lmaydi; advise + odam + to + V1. advice — sanalmaydigan ot: some advice, a piece of advice."]},{"id":"u20-l14","slug":"listening-and-speaking-a-dilemma","title":"Listening and speaking: a dilemma","titleUz":"Tinglash va gapirish: qiyin tanlov","goal":"Qiyin tanlov haqidagi suhbatni tinglab tushunasiz, ikkala variantning yaxshi va yomon tomonlarini aytasiz (If I took the job, I would…) va o'z qaroringizni sabab bilan bayon qilasiz.","words":[{"en":"dilemma","uz":"qiyin tanlov, ikkilanish","ipa":"dɪˈlem.ə"},{"en":"consult","uz":"maslahatlashmoq","ipa":"kənˈsʌlt"},{"en":"reasonable","uz":"o'rinli, mantiqli","ipa":"ˈriː.zən.ə.bəl"},{"en":"option","uz":"variant, imkoniyat","ipa":"ˈɒp.ʃən"},{"en":"cautious","uz":"ehtiyotkor, hushyor","ipa":"ˈkɔː.ʃəs"}],"summary":["Muammoni ayting: I have a real dilemma. Variantlar: If I took…, I would… On the other hand, …","depend on — doim on: It depends on the situation. Qaror: In the end, I've decided to…","Tinglashda avval umumiy ma'noni tushuning: muammo nima, ikkita variant qanday, qaror qanday.","Yangi so'zlar: dilemma, consult, reasonable, option, cautious."]},{"id":"u20-l10","slug":"apologising-and-expressing-regret","title":"Apologising and expressing regret","titleUz":"Uzr so'rash va pushaymonlik bildirish","goal":"Xato qilganingizda to'g'ri uzr so'raysiz (I'm so sorry. It was my fault. I didn't mean to…), pushaymonligingizni bildirasiz (I wish I hadn't said that.) va birovning uzrini qabul qilasiz.","words":[{"en":"apology","uz":"uzr","ipa":"əˈpɒl.ə.dʒi"},{"en":"sincere","uz":"samimiy","ipa":"sɪnˈsɪər"},{"en":"confess","uz":"tan olmoq, bo'yniga olmoq","ipa":"kənˈfes"},{"en":"forgive","uz":"kechirmoq","ipa":"fəˈɡɪv"},{"en":"excuse","uz":"bahona, uzr","ipa":"ɪkˈskjuːs"}],"summary":["Yaxshi uzr: I'm so sorry. It was my fault. + qisqa sabab + tuzatish: Can I make it up to you?","sorry for / apologise for + -ing; I regret + -ing; I didn't mean to…","Pushaymonlik: I should have… / I shouldn't have… / I wish I hadn't…","Uzrni qabul qilish: Don't worry about it. / That's OK. / No harm done.","Yangi so'zlar: apology, sincere, confess, forgive, excuse."]},{"id":"u20-l7","slug":"writing-a-letter-of-advice","title":"Writing a letter of advice","titleUz":"Yozish: maslahat xati","goal":"Do'stingizning muammosiga maslahat xati yozasiz: to'g'ri boshlanish va yakunlash qoliplarini, Firstly / Secondly / However / In conclusion kabi bog'lovchilarni va maslahat qoliplarini (If I were you, I'd…) ishlatasiz.","words":[{"en":"trust","uz":"ishonmoq, ishonch","ipa":"trʌst"},{"en":"loyal","uz":"sodiq, ishonchli","ipa":"ˈlɔɪ.əl"},{"en":"criticise","uz":"tanqid qilmoq","ipa":"ˈkrɪt.ɪ.saɪz"},{"en":"encourage","uz":"dalda bermoq, ruhlantirmoq","ipa":"ɪnˈkʌr.ɪdʒ"},{"en":"get over","uz":"tuzalib ketmoq, yengib o'tmoq","ipa":"ɡet ˈəʊ.vər"},{"en":"relationship","uz":"munosabat","ipa":"rɪˈleɪ.ʃən.ʃɪp"},{"en":"cheer up","uz":"ko'ngli ko'tarilmoq","ipa":"tʃɪər ʌp"},{"en":"fall out","uz":"janjallashib qolmoq","ipa":"fɔːl aʊt"},{"en":"in conclusion","uz":"xulosa qilib aytganda","ipa":"ɪn kənˈkluː.ʒən"},{"en":"on the other hand","uz":"boshqa tomondan","ipa":"ɒn ði ˈʌð.ə hænd"}],"summary":["Maslahat xati: salomlashish → kirish (rahmat, hamdardlik) → 2–3 maslahat → xotima → xayrlashish. Salomdan keyin vergul: Dear Aziz,.","Kirish va xotima iboralari: Thanks for your letter, I'm sorry to hear that…, Write soon, Let me know how it goes, I'm looking forward to hearing from you.","Bog'lovchilar: Firstly, Secondly, Also, However, On the other hand, In conclusion; gap boshida bo'lsa, vergul qo'ying.","Tekshiring: should + V1, had better + V1, suggest you go, some advice, how it goes (so'z tartibi)."]},{"id":"u20-l15","slug":"reading-and-writing-a-problem-page","title":"Reading and writing: a problem page","titleUz":"O'qish va yozish: maslahat ustuni","goal":"Gazeta yoki saytdagi maslahat ustuni (problem page) maktubini o'qib tushunasiz va o'zingiz 6–8 gapdan iborat maslahat javobi yozasiz (hamdardlik, maslahat, dalda).","words":[{"en":"struggle","uz":"qiynalmoq, kurashmoq","ipa":"ˈstrʌɡ.əl"},{"en":"bother","uz":"bezovta qilmoq, xalaqit bermoq","ipa":"ˈbɒð.ər"},{"en":"mature","uz":"ulg'aygan, pishgan","ipa":"məˈtʃʊər"},{"en":"pressure","uz":"bosim","ipa":"ˈpreʃ.ə"},{"en":"stand up for","uz":"himoya qilmoq, yonini olmoq","ipa":"stænd ʌp fɔːr"}],"summary":["Problem page — o'quvchi muammosini yozadi, mutaxassis maslahat beradi. Avval asosiy muammoni toping.","Javob tuzilmasi: salom, hamdardlik, maslahat, sabab, dalda.","Foydali iboralar: If I were you, I would… / You could… / Why don't you…? / In that way, … / Good luck!","Yangi so'zlar: struggle, bother, mature, pressure, stand up for."]},{"id":"u20-l8","slug":"unit-review-conditionals-and-modals","title":"Unit review: conditionals and modals","titleUz":"Bosqich takrori: shart gaplar va modallar","goal":"Bosqichdagi barcha mavzuni yangi misollarda takrorlaysiz: first / second / third conditional, unless, wish, must / might / can't, should have va maslahat qoliplari. Bunda o'n ta foydali so'zni ham o'rganasiz.","words":[{"en":"pay off","uz":"samara bermoq","ipa":"peɪ ɒf"},{"en":"effort","uz":"harakat, kuch","ipa":"ˈef.ət"},{"en":"courage","uz":"jasorat","ipa":"ˈkʌr.ɪdʒ"},{"en":"go through","uz":"boshdan kechirmoq","ipa":"ɡəʊ θruː"},{"en":"hold on","uz":"kutmoq, biroz sabr qilmoq","ipa":"həʊld ɒn"},{"en":"acknowledge","uz":"tan olmoq, e'tirof etmoq","ipa":"əkˈnɒl.ɪdʒ"},{"en":"hesitate","uz":"ikkilanmoq","ipa":"ˈhez.ɪ.teɪt"},{"en":"convince","uz":"ishontirmoq","ipa":"kənˈvɪns"},{"en":"make up your mind","uz":"qaror qilmoq","ipa":"meɪk ʌp jɔː maɪnd"},{"en":"turn down","uz":"rad etmoq","ipa":"tɜːn daʊn"}],"summary":["Shart gaplar: first (If + Present, will), second (If + Past, would), third (If + Past Perfect, would have + V3). unless = if … not.","wish + Past Simple — hozirgi orzu, wish + Past Perfect — o'tgan pushaymon.","Taxmin: must (ishonchli ha), might (ehtimol), can't (ishonchli yo'q); o'tgan zamonda: must have + V3. Tanqid: should have + V3.","Maslahat: should, ought to, had better, If I were you; fe'ldan oldin to faqat ought dan keyin keladi."]},{"id":"u20-l11","slug":"possibilities-final-review","title":"Possibilities: final review","titleUz":"Imkoniyatlar: yakuniy takror","goal":"Bosqichdagi barcha mavzularni takrorlaysiz: conditionals, wish, must / might / can't, should have, should / ought to / had better va ularni yangi gaplarda to'g'ri ishlatasiz.","words":[{"en":"possibility","uz":"imkoniyat, ehtimol","ipa":"ˌpɒs.əˈbɪl.ə.ti"},{"en":"prospect","uz":"istiqbol, kutilayotgan imkoniyat","ipa":"ˈprɒs.pekt"},{"en":"uncertain","uz":"noaniq","ipa":"ʌnˈsɜː.tən"},{"en":"outcome","uz":"natija, oqibat","ipa":"ˈaʊt.kʌm"},{"en":"suppose","uz":"faraz qilmoq, deb o'ylamoq","ipa":"səˈpəʊz"}],"summary":["First: if + Present, will. Second: if + Past Simple, would. Third: if + had + V3, would have + V3. unless = if not.","wish + Past Simple / could (hozir), wish + had + V3 (o'tgan). I wish I would have — xato.","must / might / can't + fe'l (hozir), + have + V3 (o'tgan); should / shouldn't / could / needn't have + V3.","Maslahat: should, ought to, had better (to siz), If I were you…","Yangi so'zlar: possibility, prospect, uncertain, outcome, suppose."]}]},{"id":"u21","n":21,"title":"People, places and things","titleUz":"Odamlar, joylar va narsalar: majhul nisbat, nisbiy gaplar, artikl","description":"Passive voice, nisbiy gaplar (who, which, whose), artikl va miqdor so'zlari, savol dumlari va xushmuomala savollar.","canDo":["Majhul nisbatda gapiraman va yozaman (is made, was built, has been closed, will be opened)","Odamlar, joylar va narsalarni who, which, where, whose bilan aniq tasvirlayman","Shahar yoki mahallani tasvirlayman va turistik ofisda muloyim savol beraman","Mehmonxona yoki sayohat haqida qisqa sharh yozaman"],"lessons":[{"id":"u21-l1","slug":"the-passive-present-and-past","title":"The passive: present and past","titleUz":"Majhul nisbat: hozirgi va o'tgan zamon (is made, was built)","goal":"Majhul nisbat (passive) ni hozirgi va o'tgan zamonda tuzasiz: Rice is grown here. The bridge was built in 1998. Qachon by kerakligini bilasiz, passive savol va inkor gaplar tuzasiz va The accident was happened kabi xatodan qochasiz.","words":[{"en":"manufacture","uz":"ishlab chiqarmoq (sanoatda)","ipa":"ˌmæn.jəˈfæk.tʃə"},{"en":"export","uz":"eksport qilmoq","ipa":"ɪkˈspɔːt"},{"en":"construct","uz":"qurmoq","ipa":"kənˈstrʌkt"},{"en":"assemble","uz":"yig'moq, yig'ib qurmoq","ipa":"əˈsem.bəl"},{"en":"release","uz":"chiqarmoq, e'lon qilmoq","ipa":"rɪˈliːs"},{"en":"steal","uz":"o'g'irlamoq","ipa":"stiːl"},{"en":"transport","uz":"tashimoq","ipa":"trænˈspɔːt"},{"en":"harvest","uz":"hosilni yig'ib olmoq","ipa":"ˈhɑː.vɪst"},{"en":"raw material","uz":"xomashyo","ipa":"rɔː məˈtɪə.ri.əl"},{"en":"product","uz":"mahsulot","ipa":"ˈprɒd.ʌkt"}],"summary":["Passive = be + V3. Ish yoki natija muhim bo'lsa, ish qiluvchi noma'lum yoki ahamiyatsiz bo'lsa ishlatamiz.","Hozirgi zamon: am / is / are + V3 (Cars are made here). O'tgan zamon: was / were + V3 (The bridge was built in 1998).","Inkor: isn't / wasn't + V3. Savol: Is / Was + ega + V3? va Where was it made? — savolda do / did kerak emas.","By faqat ish qiluvchi muhim bo'lsa aytiladi: written by a young girl.","O'timsiz fe'llar passive bo'lmaydi: ~~The accident was happened~~ → The accident happened."]},{"id":"u21-l12","slug":"the-passive-perfect-future-and-modals","title":"The passive: perfect, future and modals","titleUz":"Majhul nisbat: has been built, will be done, can be seen","goal":"Majhul nisbatni Present Perfect (has been repaired), kelasi zamon (will be opened) va modal fe'llar (can be seen, must be finished) bilan yasaysiz, inkor va savol shaklini bilasiz.","words":[{"en":"renovate","uz":"yangilamoq, ta'mirlab yangilamoq","ipa":"ˈrenəveɪt"},{"en":"replace","uz":"almashtirmoq","ipa":"rɪˈpleɪs"},{"en":"demolish","uz":"buzib tashlamoq","ipa":"dɪˈmɒl.ɪʃ"},{"en":"protect","uz":"himoya qilmoq","ipa":"prəˈtekt"},{"en":"approve","uz":"ma'qullamoq, tasdiqlamoq","ipa":"əˈpruːv"}],"summary":["Majhul nisbat formulasi: to be + V3. Present Perfect: has / have been + V3.","Kelasi zamon: will be + V3. Modallar: can / must / should be + V3.","Inkor va savolda yordamchi fe'l o'rni o'zgaradi: hasn't been done, Has it been done?, can't be seen.","Xatolar: has repaired (xato) → has been repaired (to'g'ri); can booked (xato) → can be booked (to'g'ri).","Yangi so'zlar: renovate, replace, demolish, protect, approve."]},{"id":"u21-l2","slug":"defining-relative-clauses","title":"Defining relative clauses","titleUz":"Aniqlovchi nisbiy gaplar: who, which, that, where, whose","goal":"Odam, narsa va joyni aniqlab gapirasiz: The man who lives next door is a doctor. This is the café where we met. Who, which, that, where, whose ni to'g'ri tanlaysiz, that ni tushirib qoldirishni bilasiz va The man who he lives kabi xatodan qochasiz.","words":[{"en":"employer","uz":"ish beruvchi","ipa":"ɪmˈplɔɪ.ə"},{"en":"tenant","uz":"ijarachi","ipa":"ˈten.ənt"},{"en":"stranger","uz":"notanish odam","ipa":"ˈstreɪn.dʒə"},{"en":"supplier","uz":"yetkazib beruvchi","ipa":"səˈplaɪ.ə"},{"en":"owner","uz":"egasi","ipa":"ˈəʊ.nə"},{"en":"gadget","uz":"qurilma, asbob-uskuna","ipa":"ˈɡædʒ.ɪt"},{"en":"appliance","uz":"maishiy texnika","ipa":"əˈplaɪ.əns"},{"en":"inhabitant","uz":"aholi, yashovchi","ipa":"ɪnˈhæb.ɪ.tənt"},{"en":"instrument","uz":"cholg'u asbobi","ipa":"ˈɪn.strə.mənt"},{"en":"shareholder","uz":"aksiyador","ipa":"ˈʃeəˌhəʊl.də"}],"summary":["Aniqlovchi nisbiy gap «qaysi?» savoliga javob beradi va vergulsiz yoziladi: The man who lives next door is a doctor.","who — odam; which — narsa; that — ikkalasi; where — joy; whose — kimning (whose + ot, artiklsiz).","Nisbiy so'z to'ldiruvchi bo'lsa tushirsa bo'ladi: The film (that) we saw. Ega bo'lsa (keyin fe'l) tushirib bo'lmaydi.","Predlog odatda oxirda turadi: the house we live in, the girl I talked to.","Xatolar: ~~who he lives~~, ~~the film what~~, ~~where ... there~~. Olmoshni takrorlamang, what ishlatmang."]},{"id":"u21-l3","slug":"non-defining-relative-clauses","title":"Non-defining relative clauses","titleUz":"Qo'shimcha ma'lumot beruvchi nisbiy gaplar (vergul bilan)","goal":"Odam yoki joy haqida qo'shimcha ma'lumot berasiz: My brother, who lives in London, is a doctor. Samarkand, which is a very old city, is famous for the Registan. Vergullarni to'g'ri qo'yasiz, bu yerda that ishlatilmasligini va which butun gapga ham tegishli bo'la olishini bilasiz.","words":[{"en":"author","uz":"muallif, yozuvchi","ipa":"ˈɔː.θə"},{"en":"founder","uz":"asoschi","ipa":"ˈfaʊn.də"},{"en":"scientist","uz":"olim","ipa":"ˈsaɪ.ən.tɪst"},{"en":"celebrity","uz":"mashhur shaxs, yulduz","ipa":"səˈleb.rə.ti"},{"en":"talented","uz":"iqtidorli, qobiliyatli","ipa":"ˈtæl.ən.tɪd"},{"en":"wealthy","uz":"boy, badavlat","ipa":"ˈwel.θi"},{"en":"deserve","uz":"loyiq bo'lmoq","ipa":"dɪˈzɜːv"},{"en":"respected","uz":"hurmatli, obro'li","ipa":"rɪˈspek.tɪd"},{"en":"outgoing","uz":"kirishimli, ochiq","ipa":"ˈaʊtˌɡəʊ.ɪŋ"},{"en":"formerly","uz":"ilgari, avvallari","ipa":"ˈfɔː.mə.li"}],"summary":["Qo'shimcha nisbiy gap ma'lumot qo'shadi, usiz ham gap to'liq. U ikki vergul orasida yoziladi: Mr Karimov, who lives next door, is a doctor.","Odam → who, narsa → which, joy → where, egalik → whose. Bu yerda that ishlatilmaydi.","Nisbiy so'zni tushirib bo'lmaydi: Bukhara, which I visited last year, is beautiful.","Vergul ma'noni o'zgartiradi: my brother who lives in London (bir nechtasidan biri) va my brother, who lives in London (yagona).",", which butun oldingi gap haqida fikr bildiradi: The train was late, which made me angry."]},{"id":"u21-l4","slug":"articles-and-determiners","title":"Articles and determiners","titleUz":"Artikl va aniqlovchilar: a, the, artikl yo'q; some, any, much, many","goal":"a / an / the va artiklsiz holatlarni to'g'ri tanlaysiz, sanaladigan va sanalmaydigan otlarni farqlaysiz va some, any, much, many, a few, a little, enough so'zlarini ishlatasiz. an advice va informations kabi xatolardan qochasiz.","words":[{"en":"scenery","uz":"manzara, tabiat ko'rinishi","ipa":"ˈsiː.nər.i"},{"en":"information","uz":"ma'lumot","ipa":"ˌɪn.fəˈmeɪ.ʃən"},{"en":"behaviour","uz":"xulq-atvor","ipa":"bɪˈheɪ.vjə"},{"en":"equipment","uz":"jihoz, uskunalar","ipa":"ɪˈkwɪp.mənt"},{"en":"machinery","uz":"mashina-uskunalar","ipa":"məˈʃiː.nər.i"},{"en":"housing","uz":"uy-joy","ipa":"ˈhaʊ.zɪŋ"},{"en":"research","uz":"tadqiqot","ipa":"rɪˈsɜːtʃ"},{"en":"knowledge","uz":"bilim","ipa":"ˈnɒl.ɪdʒ"},{"en":"a great deal of","uz":"juda ko'p","ipa":"ə ɡreɪt diːl əv"},{"en":"several","uz":"bir nechta","ipa":"ˈsev.ər.əl"}],"summary":["a / an — birinchi marta, bitta, kasb; tovushga qarang: an hour, a university. the — ikkalamiz bilgan, ikkinchi marta, yagona, oliy daraja.","Artiklsiz: umumiy ko'plik va sanalmaydigan otlar (Books are expensive), ovqat nomlari, tillar, go to school / work / bed.","Sanalmaydigan otlar: advice, information, furniture, equipment, luggage, news, progress, research, knowledge. Ko'plik shakli yo'q, a piece of bilan sanaladi.","Sanaladigan ko'plik: many, a few, few, several. Sanalmaydigan: much, a little, little. Ikkalasi bilan: some, any, a lot of, plenty of, enough.","some — darak gap va taklif; any — savol va inkor. a few / a little — yetarli; few / little — kam."]},{"id":"u21-l13","slug":"all-both-either-neither-each-every","title":"All, both, either, neither, each, every","titleUz":"All, both, either, neither, each va every","goal":"all, both, either, neither, each, every so'zlarini to'g'ri ishlatasiz: ikkita narsa uchun both / either / neither, uchta va undan ko'p uchun all, each va every dan keyin esa birlik otni qo'yasiz.","words":[{"en":"identical","uz":"bir xil, aynan o'xshash","ipa":"aɪˈden.tɪ.kəl"},{"en":"participant","uz":"ishtirokchi","ipa":"pɑːˈtɪs.ɪ.pənt"},{"en":"mutual","uz":"o'zaro, umumiy","ipa":"ˈmjuː.tʃu.əl"},{"en":"suitable","uz":"mos, munosib","ipa":"ˈsuːtəbl"},{"en":"separate","uz":"alohida","ipa":"ˈseprət"}],"summary":["both — ikkita (both cities); all — uch va undan ko'p yoki sanalmaydigan ot (all the rooms, all day).","either — ikkitadan biri; neither — ikkalasi ham emas. neither o'zi inkor: not qo'shilmaydi.","each va every + birlik ot + birlik fe'l: Every room has…, Each of the rooms has….","every of (xato) → every one of yoki each of (to'g'ri).","Yangi so'zlar: identical, participant, mutual, suitable, separate."]},{"id":"u21-l9","slug":"describing-a-place","title":"Describing a place","titleUz":"Joyni tasvirlash: shahar yoki mahalla","goal":"Do'stingizga o'z shahringiz yoki mahallangizni tasvirlab berasiz: What's it like? ga javob berasiz, who / which / where bilan aniqlik kiritasiz, joyning kamchilik va yutuqlarini aytasiz (It's famous for…, It's surrounded by…).","words":[{"en":"surroundings","uz":"atrof, atrofdagi joylar","ipa":"səˈraʊn.dɪŋz"},{"en":"spacious","uz":"keng, joyi ko'p","ipa":"ˈspeɪ.ʃəs"},{"en":"picturesque","uz":"rasmdek go'zal, manzarali","ipa":"ˌpɪk.tʃəˈresk"},{"en":"scenic","uz":"manzarali","ipa":"ˈsiː.nɪk"},{"en":"peaceful","uz":"tinch, osoyishta","ipa":"ˈpiːsfl"},{"en":"charming","uz":"maftunkor, yoqimli","ipa":"ˈtʃɑː.mɪŋ"}],"summary":["What's it like? — tasvir so'raydi: javob sifat bilan: It's lively and friendly.","Foydali iboralar: famous for, surrounded by, within walking distance, a lovely view of.","Tasvirni boyiting: where (joy), which (narsa), vergul bilan qo'shimcha ma'lumot, majhul nisbat.","Yangi so'zlar: surroundings, spacious, picturesque, scenic, peaceful, charming."]},{"id":"u21-l5","slug":"cities-buildings-and-tourism","title":"Cities, buildings and tourism","titleUz":"Shahar, binolar va turizm: so'zlar va so'z yasalishi","goal":"Shahar, bino va turizm haqidagi B1 so'zlarini (suburb, landmark, sightseeing, accommodation…) ishlatasiz va suffikslar yordamida yangi so'z yasaysiz (attract → attraction, tour → tourist, tradition → traditional).","words":[{"en":"skyline","uz":"shahar silueti","ipa":"ˈskaɪ.laɪn"},{"en":"district","uz":"tuman, mavze","ipa":"ˈdɪs.trɪkt"},{"en":"skyscraper","uz":"osmono'par bino","ipa":"ˈskaɪˌskreɪ.pə"},{"en":"landmark","uz":"mashhur belgi, diqqatga sazovor bino","ipa":"ˈlænd.mɑːk"},{"en":"outskirts","uz":"shahar chekkasi","ipa":"ˈaʊt.skɜːts"},{"en":"accommodation","uz":"turar joy","ipa":"əˌkɒm.əˈdeɪ.ʃən"},{"en":"residential","uz":"turar-joy (rayoni)","ipa":"ˌrez.ɪˈden.ʃəl"},{"en":"destination","uz":"borilgan manzil, yo'nalish","ipa":"ˌdes.tɪˈneɪ.ʃən"},{"en":"bustling","uz":"gavjum, jonli","ipa":"ˈbʌs.lɪŋ"},{"en":"guided tour","uz":"gid hamrohligidagi sayohat","ipa":"ˈɡaɪ.dɪd tʊə"}],"summary":["Shahar so'zlari: suburb (chekka hudud), district (mavze), skyscraper (osmono'par bino), landmark (mashhur belgi).","Turizm: attraction, destination, go sightseeing (predlogsiz!), accommodation (sanalmaydi: good accommodation).","Suffikslar: -ion (attraction), -ist (tourist), -or/-er (visitor), -ous (famous), -ful (beautiful), -al (traditional), -able (comfortable).","historic — tarixda muhim; historical — tarixga oid. crowded — sifat (gavjum), crowd — ot (olomon)."]},{"id":"u21-l6","slug":"question-tags-and-polite-questions","title":"Question tags and polite questions","titleUz":"Question tags va xushmuomala savollar (Could you tell me…?)","goal":"Question tag (It's lovely, isn't it?) tuzasiz va ma'nosini tushunasiz; begona odamdan Could you tell me where the station is? kabi xushmuomala savol bilan ma'lumot so'raysiz va so'z tartibi xatosidan qochasiz.","words":[{"en":"directions","uz":"yo'l-yo'riq, yo'nalish","ipa":"dɪˈrek.ʃənz"},{"en":"assistance","uz":"yordam","ipa":"əˈsɪs.təns"},{"en":"complimentary","uz":"bepul (hurmat belgisi sifatida)","ipa":"ˌkɒm.plɪˈmen.tər.i"},{"en":"valid","uz":"amal qiladigan, yaroqli","ipa":"ˈvæl.ɪd"},{"en":"booking","uz":"band qilish, buyurtma","ipa":"ˈbʊk.ɪŋ"},{"en":"kindly","uz":"marhamat qilib","ipa":"ˈkaɪnd.li"},{"en":"in person","uz":"shaxsan","ipa":"ɪn ˈpɜː.sən"},{"en":"at your convenience","uz":"o'zingizga qulay paytda","ipa":"æt jɔː kənˈviː.ni.əns"},{"en":"opening hours","uz":"ish vaqti","ipa":"ˈəʊ.pən.ɪŋ ˌaʊəz"},{"en":"get in touch","uz":"bog'lanmoq","ipa":"ɡet ɪn tʌtʃ"}],"summary":["Question tag: darak gap → inkor tag, inkor gap → darak tag. Tag gapdagi yordamchi fe'l bilan: It's nice, isn't it? They live here, don't they?","Maxsus: I am → aren't I?, Let's → shall we?, There is → isn't there?. Ega doim olmosh bo'ladi.","Pasayuvchi ohang — tasdiqlatish, ko'tariluvchi ohang — haqiqiy savol. Javob faktga qarab: No, I don't / Yes, I do.","Xushmuomala savol: Could you tell me where the station is? — so'roq so'zidan keyin gap tartibi, do / does / did yo'q.","Ha/yo'q savolda if yoki whether: Do you know if the museum is open? Boshida Excuse me deng."]},{"id":"u21-l14","slug":"listening-and-speaking-describing-a-place","title":"Listening and speaking: describing a place","titleUz":"Tinglash va gapirish: joyni tasvirlab berish","goal":"Joy haqidagi qisqa hikoyani tinglab tushunasiz (qayerda? qanday? nima bilan mashhur?), question tag bilan hamsuhbatni jalb qilasiz (It's beautiful, isn't it?) va o'z shahringizni 6-8 gapda ovoz chiqarib tasvirlaysiz.","words":[{"en":"atmosphere","uz":"muhit, kayfiyat","ipa":"ˈæt.məs.fɪə"},{"en":"typical","uz":"xos, odatiy","ipa":"ˈtɪpɪkl"},{"en":"region","uz":"viloyat, hudud","ipa":"ˈriːdʒən"},{"en":"impressive","uz":"ta'sirli, ulug'vor","ipa":"ɪmˈpresɪv"},{"en":"valley","uz":"vodiy","ipa":"ˈvæli"}],"summary":["Tinglashda avval umumiy ma'noni oling: qayerda, qanday, nima bilan mashhur.","Tasvir iboralari: located in, known for, surrounded by, You should definitely visit….","Question tag hamsuhbatni jalb qiladi: It's lovely, isn't it? — darak gapdan keyin inkor tag.","Xushmuomala savol: Could you tell me where … is? (darak tartibi).","Yangi so'zlar: atmosphere, typical, region, impressive, valley."]},{"id":"u21-l10","slug":"asking-for-information","title":"Asking for information","titleUz":"Ma'lumot so'rash: turistik ofis va telefon orqali","goal":"Turistik ofisda va telefonda Could you tell me…?, Do you know if…?, Is it possible to…? bilan muloyim savol berasiz, javobni tasdiqlaysiz (So the tour starts at ten, doesn't it?) va Could you repeat that? deb qayta so'raysiz.","words":[{"en":"brochure","uz":"buklet, risola","ipa":"ˈbrəʊʃə"},{"en":"enquiry","uz":"so'rov, ma'lumot so'rash","ipa":"ɪnˈkwaɪri"},{"en":"deposit","uz":"avans, garov puli","ipa":"dɪˈpɒzɪt"},{"en":"availability","uz":"bo'sh joy borligi","ipa":"əˌveɪ.ləˈbɪl.ə.ti"},{"en":"itinerary","uz":"sayohat rejasi","ipa":"aɪˈtɪn.ər.i"}],"summary":["Muloyim savol: Could you tell me… / Do you know… / Is it possible to…? va darak tartibi.","Misol: Could you tell me where the office is? — where is the office (xato).","Ha/yo'q savolda if (yoki whether): Do you know if the museum is open?","Telefonda: Could you repeat that, please? va Could you speak more slowly? — uyalmang.","Tasdiqlash uchun question tag: So the tour starts at ten, doesn't it?","Yangi so'zlar: brochure, enquiry, deposit, availability, itinerary."]},{"id":"u21-l7","slug":"writing-a-travel-review","title":"Writing a travel review","titleUz":"Yozish: sayohat sharhi","goal":"Sayohat sharhini (shahar, tur yoki restoran) tuzilgan holda yozasiz: sarlavha, qisqa kirish, yaxshi va yomon tomonlar, tavsiya. Although / despite, however va kuchli sifatlardan foydalanasiz.","words":[{"en":"stunning","uz":"juda go'zal, hayratlanarli","ipa":"ˈstʌn.ɪŋ"},{"en":"spotless","uz":"juda toza","ipa":"ˈspɒt.ləs"},{"en":"overpriced","uz":"narxiga arzimaydigan, haddan tashqari qimmat","ipa":"ˌəʊ.vəˈpraɪst"},{"en":"authentic","uz":"haqiqiy, asl","ipa":"ɔːˈθen.tɪk"},{"en":"cosy","uz":"shinam","ipa":"ˈkəʊ.zi"},{"en":"mediocre","uz":"o'rtamiyona","ipa":"ˌmiː.diˈəʊ.kə"},{"en":"worthwhile","uz":"arziydigan, foydali","ipa":"ˌwɜːθˈwaɪl"},{"en":"rating","uz":"baho, reyting","ipa":"ˈreɪ.tɪŋ"},{"en":"value for money","uz":"narxiga arziydigan","ipa":"ˌvæl.juː fə ˈmʌn.i"},{"en":"off the beaten track","uz":"sayyohlar kam boradigan joyda","ipa":"ɒf ðə ˌbiː.tən ˈtræk"}],"summary":["Sharh tuzilishi: sarlavha, kirish, yaxshi tomonlar, yomon tomonlar, tavsiya. Voqealar Past Simple da, umumiy faktlar Present Simple da.","Kuchli sifatlar: stunning, spotless, cosy (yaxshi); tiny, overpriced, disappointing (yomon); value for money.","Although + gap (but yo'q!), despite / in spite of + ot yoki -ing, However, — yangi gap boshida.","Bu bosqich grammatikasi sharhni boyitadi: passive (was built) va which / who / where bilan nisbiy gaplar.","Tavsiya: I would definitely recommend it to anyone who …, Overall, …"]},{"id":"u21-l15","slug":"reading-and-writing-a-hotel-review","title":"Reading and writing: a hotel review","titleUz":"O'qish va yozish: mehmonxona sharhi","goal":"Mehmonxona sharhini o'qib, undan fikr va faktlarni ajratasiz, o'zingiz esa 6-8 gapdan iborat sharh yozasiz: sarlavha, umumiy fikr, yaxshi va yomon tomonlar, tavsiya; although, however, but bilan fikrlarni bog'laysiz.","words":[{"en":"cleanliness","uz":"tozalik","ipa":"ˈkliːn.li.nəs"},{"en":"outdated","uz":"eskirgan","ipa":"ˌaʊtˈdeɪ.tɪd"},{"en":"satisfied","uz":"mamnun","ipa":"ˈsæt.ɪs.faɪd"},{"en":"amenities","uz":"qulayliklar","ipa":"əˈmiː.nə.tiz"},{"en":"hospitality","uz":"mehmondo'stlik","ipa":"ˌhɒs.pɪˈtæl.ə.ti"},{"en":"courteous","uz":"xushmuomala","ipa":"ˈkɜː.ti.əs"}],"summary":["Sharh tuzilishi: kirish, yaxshi tomon, muammo, qarama-qarshilik, tavsiya.","Although + gap, asosiy gap (but yo'q); However, — alohida gap boshida, vergul bilan.","Fe'l egaga mos bo'lsin (the rooms were). Shovqin, xona, xizmat haqida aniq so'zlar ishlating: spotless, comfortable, noisy.","Tavsiya: I would (definitely) recommend it. / I'm afraid I can't recommend it.","Yangi so'zlar: cleanliness, outdated, satisfied, amenities, hospitality, courteous."]},{"id":"u21-l8","slug":"unit-review-passive-and-relative-clauses","title":"Unit review: passive and relative clauses","titleUz":"Bosqich takrori: majhul nisbat va nisbiy gaplar","goal":"Bosqichni takrorlaysiz: passive (is made, was built, has been done, will be opened), who / which / whose / where bilan nisbiy gaplar, artikl va miqdor so'zlari, question tags va xushmuomala savollarni yangi misollarda tekshirasiz.","words":[{"en":"resident","uz":"yashovchi, mahalliy aholi vakili","ipa":"ˈrez.ɪ.dənt"},{"en":"architect","uz":"me'mor","ipa":"ˈɑː.kɪ.tekt"},{"en":"medieval","uz":"o'rta asrlarga oid","ipa":"ˌmed.iˈiː.vəl"},{"en":"settlement","uz":"aholi punkti, qishloq","ipa":"ˈset.əl.mənt"},{"en":"legacy","uz":"meros, qoldiq","ipa":"ˈleɡ.ə.si"},{"en":"heritage","uz":"madaniy meros","ipa":"ˈher.ɪ.tɪdʒ"},{"en":"monument","uz":"yodgorlik","ipa":"ˈmɒn.jə.mənt"},{"en":"craftsman","uz":"hunarmand","ipa":"ˈkrɑːfts.mən"},{"en":"ceremony","uz":"marosim","ipa":"ˈser.ɪ.mə.ni"},{"en":"ruins","uz":"xarobalar, vayronalar","ipa":"ˈruː.ɪnz"}],"summary":["Passive: be + V3 — is made, was built, has been repaired, will be opened, can be seen. by faqat kerak bo'lganda.","Nisbiy gap: odam — who, narsa — which, joy — where, egalik — whose. Qo'shimcha ma'lumot vergul bilan va that siz.","Artikl: birinchi marta a / an, keyin the, umumiy ko'plik va sanalmaydiganlarda artikl yo'q. all, both, either, neither, each, every ni to'g'ri tanlang.","Question tag va xushmuomala savol: It's nice, isn't it? Could you tell me where the bank is?","Sharh yozishda: although, despite, however va kuchli sifatlar (stunning, overpriced) ishlating."]},{"id":"u21-l11","slug":"people-and-places-final-review","title":"People and places: final review","titleUz":"Odamlar va joylar: yakuniy takror","goal":"Bosqichdagi hamma mavzuni takrorlaysiz: majhul nisbat, nisbiy gaplar, artikl va miqdor so'zlari, question tags, muloyim savollar va sharh yozish iboralari.","words":[{"en":"convenient","uz":"qulay (joylashgan)","ipa":"kənˈviːniənt"},{"en":"landscape","uz":"manzara, tabiat","ipa":"ˈlændskeɪp"},{"en":"economy","uz":"iqtisodiyot","ipa":"ɪˈkɒn.ə.mi"},{"en":"cultural","uz":"madaniy","ipa":"ˈkʌltʃrəl"},{"en":"infrastructure","uz":"infratuzilma","ipa":"ˈɪn.frəˌstrʌk.tʃə"}],"summary":["Majhul nisbat: to be + V3 (is made, was built, has been closed, will be opened, can be seen).","Nisbiy gaplar: who, which, that, where, whose; vergulli gapda that yo'q va olmosh qayta qo'yilmaydi.","Artikl: a / an / the / —; sanalmaydigan otlar bilan some. both, either, neither — ikkita; all — ko'p; each, every + birlik.","Question tags va muloyim savollar (Could you tell me where … is?) — darak tartibi.","Sharhda: although (but yo'q), however,, the only problem was…."]}]},{"id":"u22","n":22,"title":"Work, study and technology","titleUz":"Ish, o'qish va texnologiya: gerund / infinitive, kelasi zamonlar, phrasal verbs","description":"Gerund va infinitive, maqsad bildirish, Future Continuous / Perfect, taqqoslash, phrasal verbs, rasmiy xat.","canDo":["Fe'l bilan gerund yoki infinitive ni to'g'ri tanlayman (enjoy working, decide to apply)","Kelajak rejalarim va bashoratlarimni will, going to, Future Continuous va Future Perfect bilan ayta olaman","Ish suhbatida o'zim haqimda gapiraman va texnik muammoni tushuntiraman","Rasmiy elektron xat va qo'shimcha xat yozaman"],"lessons":[{"id":"u22-l1","slug":"gerund-or-infinitive","title":"Gerund or infinitive?","titleUz":"Gerund yoki infinitive? Fe'l qoliplari","goal":"Fe'ldan keyin -ing (gerund) yoki to + fe'l (infinitive) kelishini bilasiz: I enjoy working, I decided to study. stop, remember, try, forget ma'noni qanday o'zgartirishini tushunasiz va I want that you help me kabi xatolardan qochasiz.","words":[{"en":"pretend","uz":"o'zini ... qilib ko'rsatmoq","ipa":"prɪˈtend"},{"en":"tend","uz":"moyil bo'lmoq, odatda ... qilmoq","ipa":"tend"},{"en":"consider","uz":"o'ylab ko'rmoq","ipa":"kənˈsɪd.ər"},{"en":"involve","uz":"o'z ichiga olmoq, talab qilmoq","ipa":"ɪnˈvɒlv"},{"en":"threaten","uz":"po'pisa qilmoq","ipa":"ˈθret.ən"},{"en":"resist","uz":"o'zini tiymoq, qarshilik qilmoq","ipa":"rɪˈzɪst"},{"en":"propose","uz":"taklif qilmoq, niyat qilmoq","ipa":"prəˈpəʊz"},{"en":"postpone","uz":"keyinga qoldirmoq","ipa":"pəʊstˈpəʊn"},{"en":"persuade","uz":"ko'ndirmoq","ipa":"pəˈsweɪd"},{"en":"keep on","uz":"davom ettirmoq, to'xtamasdan qilmoq","ipa":"kiːp ɒn"}],"summary":["Gerund (-ing) dan keyin: enjoy, avoid, finish, suggest, consider, keep, mind, give up.","to + fe'l dan keyin: want, decide, hope, plan, manage, refuse, promise, afford, agree. want / ask / tell + kim + to + fe'l: I want you to help me.","Predlogdan keyin doim -ing: interested in learning, good at explaining, before sending, look forward to meeting.","stop, remember, forget, try: -ing — o'tgan ish yoki usul, to — bajarilishi kerak bo'lgan ish yoki harakat.","would like / would love dan keyin faqat to: I'd like to apply."]},{"id":"u22-l12","slug":"purpose-to-in-order-to-so-that-for","title":"Purpose: to, in order to, so that, for","titleUz":"Maqsad: to, in order to, so that, for","goal":"Nima uchun? degan savolga to'g'ri javob berasiz: to / in order to + fe'l (I use an app to learn words), so that + gap (so that I can relax) va for + ot yoki -ing (a tool for cutting paper) ni adashtirmaysiz.","words":[{"en":"purpose","uz":"maqsad, vazifa","ipa":"ˈpɜː.pəs"},{"en":"boost","uz":"oshirmoq, kuchaytirmoq","ipa":"buːst"},{"en":"prevent","uz":"oldini olmoq, to'sqinlik qilmoq","ipa":"prɪˈvent"},{"en":"recharge","uz":"quvvatlamoq","ipa":"ˌriːˈtʃɑːdʒ"},{"en":"enhance","uz":"yaxshilamoq, kuchaytirmoq","ipa":"ɪnˈhɑːns"}],"summary":["Odam biror ish qilsa, maqsadni to + fe'l bilan aytamiz: I use an app to learn words. for study deb bo'lmaydi.","in order to / so as to — rasmiyroq. Inkor maqsad: in order not to / so as not to + fe'l.","so that dan keyin to'liq gap keladi (can, could, will, would): so that I can relax.","for + ot (for bread) yoki narsaning vazifasi: for + -ing (a tool for cutting). What is it for?"]},{"id":"u22-l2","slug":"future-forms-will-going-to-present-tenses","title":"Future forms: will, going to, present tenses","titleUz":"Kelasi zamon shakllari: will, going to, Present Continuous / Simple","goal":"Kelajak haqida gapirganda to'rt shakldan birini to'g'ri tanlaysiz: will (shu zahoti qaror, taxmin), going to (reja, dalilga asoslangan taxmin), Present Continuous (kelishilgan uchrashuv) va Present Simple (jadval). when / as soon as dan keyin will ishlatmaysiz.","words":[{"en":"register","uz":"ro'yxatdan o'tmoq","ipa":"ˈredʒ.ɪ.stər"},{"en":"intend","uz":"niyat qilmoq","ipa":"ɪnˈtend"},{"en":"reschedule","uz":"boshqa vaqtga ko'chirmoq","ipa":"ˌriːˈʃed.juːl"},{"en":"reminder","uz":"eslatma","ipa":"rɪˈmaɪn.dər"},{"en":"install","uz":"o'rnatmoq","ipa":"ɪnˈstɔːl"},{"en":"agenda","uz":"kun tartibi","ipa":"əˈdʒen.də"},{"en":"launch","uz":"ishga tushirmoq","ipa":"lɔːntʃ"},{"en":"venue","uz":"tadbir o'tkaziladigan joy","ipa":"ˈven.juː"},{"en":"tolerate","uz":"chidamoq, toqat qilmoq","ipa":"ˈtɒl.ə.reɪt"},{"en":"call off","uz":"bekor qilmoq","ipa":"kɔːl ɒf"}],"summary":["will — shu zahoti qaror, taklif, va'da va fikringizga asoslangan taxmin: I'll help you. I think it will be fine.","be going to — oldindan qilingan reja yoki hozirgi dalilga asoslangan taxmin: I'm going to apply. It's going to rain.","Present Continuous — kelishilgan uchrashuv va tadbirlar (vaqt belgisi bilan): I'm meeting Dilnoza at six.","Present Simple — jadval va kalendar: The train leaves at nine.","when, as soon as, before, until dan keyin will yo'q — Present Simple: I'll call you when I arrive."]},{"id":"u22-l3","slug":"future-continuous-and-future-perfect","title":"Future Continuous and Future Perfect","titleUz":"Future Continuous va Future Perfect: kelajakdagi jarayon va natija","goal":"Kelajakdagi jarayon (This time tomorrow I'll be flying) va kelajakdagi biror vaqtgacha tugagan natija (By Friday I'll have finished) ni ayta olasiz; by va by the time dan to'g'ri foydalanasiz.","words":[{"en":"target","uz":"maqsad, mo'ljal (reja)","ipa":"ˈtɑː.ɡɪt"},{"en":"submit","uz":"topshirmoq, yubormoq","ipa":"səbˈmɪt"},{"en":"outline","uz":"qisqacha reja","ipa":"ˈaʊt.laɪn"},{"en":"finalise","uz":"yakuniy shaklga keltirmoq","ipa":"ˈfaɪ.nəl.aɪz"},{"en":"accomplish","uz":"amalga oshirmoq, bajarmoq","ipa":"əˈkʌm.plɪʃ"},{"en":"ultimately","uz":"oxir-oqibat, pirovardida","ipa":"ˈʌl.tɪ.mət.li"},{"en":"sooner or later","uz":"ertami-kechmi","ipa":"ˌsuː.nər ɔː ˈleɪ.tər"},{"en":"complete","uz":"tugatmoq, to'ldirmoq","ipa":"kəmˈpliːt"},{"en":"in the meantime","uz":"shu orada, ayni paytda","ipa":"ɪn ðə ˈmiːn.taɪm"},{"en":"on schedule","uz":"jadval bo'yicha, o'z vaqtida","ipa":"ɒn ˈʃed.juːl"}],"summary":["Future Continuous (will be + -ing): kelajakdagi aniq paytda davom etayotgan ish — This time tomorrow I'll be flying.","Will you be + -ing? — boshqaning rejalari haqida muloyim savol: Will you be using the car tonight?","Future Perfect (will have + V3): kelajakdagi paytgacha tugagan natija — By Friday I'll have finished.","by — muddat (kechikmay), until — to'xtamay davom etish: I'll finish by six. I'll work until six.","by the time, when, until dan keyin Present Simple: By the time you arrive, I'll have left."]},{"id":"u22-l4","slug":"comparing-in-depth","title":"Comparing in depth","titleUz":"Taqqoslash chuqurroq: the more… the more, much / far, as… as","goal":"Taqqoslashni aniqroq qilasiz: the more you practise, the better you get, much / far / slightly bilan farqni kuchaytirasiz yoki kamaytirasiz, as … as, not as … as, twice as … as, the same as, different from va less / fewer ni to'g'ri ishlatasiz.","words":[{"en":"efficient","uz":"samarali","ipa":"ɪˈfɪʃ.ənt"},{"en":"durable","uz":"chidamli, uzoq xizmat qiladigan","ipa":"ˈdjʊə.rə.bəl"},{"en":"affordable","uz":"hamyonbop, arzon","ipa":"əˈfɔː.də.bəl"},{"en":"demanding","uz":"ko'p kuch talab qiladigan","ipa":"dɪˈmɑːn.dɪŋ"},{"en":"flexible","uz":"moslashuvchan","ipa":"ˈflek.sə.bəl"},{"en":"noticeably","uz":"sezilarli darajada, ko'zga tashlanib","ipa":"ˈnəʊ.tɪ.sə.bli"},{"en":"considerably","uz":"sezilarli darajada","ipa":"kənˈsɪd.ər.ə.bli"},{"en":"increasingly","uz":"tobora, borgan sari","ipa":"ɪnˈkriː.sɪŋ.li"},{"en":"steadily","uz":"izchil, bir maromda","ipa":"ˈsted.ɪ.li"},{"en":"compared with","uz":"...ga nisbatan","ipa":"kəmˈpeəd wɪð"}],"summary":["The + qiyosiy daraja, the + qiyosiy daraja: The more you practise, the better you get. Ikkala qismda ham the bor.","Farqni kuchaytirish: much, a lot, far + qiyosiy daraja; kamaytirish: a bit, a little, slightly. very bigger va more better — xato.","as … as (teng), not as … as (teng emas), twice as … as, the same as, different from, similar to.","less + sanalmaydigan ot, fewer + sanaladigan ko'plik: less time, fewer meetings.","by far the best, one of the most …, I've ever …, harder and harder — tabiiy qoliplar."]},{"id":"u22-l13","slug":"predictions-and-certainty","title":"Predictions and certainty","titleUz":"Bashorat va ishonch darajasi: probably, definitely, I doubt","goal":"Kelajak haqida qanchalik ishonchingizni aytasiz: will definitely / will probably / might / probably won't, I doubt…, be likely / unlikely to… va so'zlarni gapda to'g'ri joyga qo'yasiz.","words":[{"en":"predict","uz":"bashorat qilmoq","ipa":"prɪˈdɪkt"},{"en":"bound to","uz":"albatta ... bo'ladi (muqarrar)","ipa":"baʊnd tuː"},{"en":"doubt","uz":"shubhalanmoq","ipa":"daʊt"},{"en":"surely","uz":"albatta, shubhasiz","ipa":"ˈʃɔː.li"},{"en":"inevitable","uz":"muqarrar, oldini olib bo'lmaydigan","ipa":"ɪˈnev.ɪ.tə.bəl"},{"en":"assume","uz":"deb o'ylamoq, taxmin qilmoq","ipa":"əˈsjuːm"}],"summary":["Ishonch shkalasi: will definitely (100) > will probably (80) > might / may / could (50) > probably won't > definitely won't.","probably va definitely darakda will dan keyin, inkorda won't dan oldin turadi: probably won't, definitely won't.","I doubt + darak gap (I doubt he will come). I don't think … will ham keng ishlatiladi.","be likely to (ehtimol) va be unlikely to (dargumon) + fe'l: Prices are likely to rise."]},{"id":"u22-l9","slug":"a-job-interview","title":"A job interview","titleUz":"Ish suhbati: o'zingiz va rejalaringiz haqida","goal":"Ish suhbatida o'zingiz haqingizda aytasiz (I'm good at solving problems), kuchli va zaif tomonlaringizni tushuntirasiz, Where do you see yourself in five years? savoliga rejangiz bilan javob berasiz va oxirida o'zingiz savol berasiz.","words":[{"en":"enthusiastic","uz":"ishtiyoqli, g'ayratli","ipa":"ɪnˌθjuː.ziˈæs.tɪk"},{"en":"awkward","uz":"noqulay","ipa":"ˈɔː.kwəd"},{"en":"teamwork","uz":"jamoaviy ish, hamkorlik","ipa":"ˈtiːm.wɜːk"},{"en":"motivated","uz":"intiluvchan, o'z ishiga rag'batli","ipa":"ˈməʊ.tɪ.veɪ.tɪd"},{"en":"adaptable","uz":"moslashuvchan","ipa":"əˈdæp.tə.bəl"}],"summary":["Tell me about yourself: hozirgi ishingiz, tajribangiz va nega bu ish haqida 30-60 soniya ayting.","Kuchli tomon: I'm good at…ing, My biggest strength is…. Zaif tomon: kamchilik + qanday yaxshilayotganingiz.","Kelajak rejasi: I'll be leading a team, By then I will have finished…; ishonch: probably / definitely.","Oxirida o'zingiz savol bering: What would my typical day be like? va I'm available to start…"]},{"id":"u22-l5","slug":"work-careers-and-education","title":"Work, careers and education","titleUz":"Ish, kasb va ta'lim: lug'at va birikmalar","goal":"job, work, career so'zlarini farqlaysiz, ish va o'qishga oid tayyor birikmalarni (meet a deadline, sit an exam, apply for a job) to'g'ri fe'l bilan aytasiz, work as / for / at kabi predloglarni adashtirmaysiz va o'z kasbiy yo'lingiz haqida gapira olasiz.","words":[{"en":"supervisor","uz":"bevosita rahbar, nazoratchi","ipa":"ˈsuː.pə.vaɪ.zə"},{"en":"employee","uz":"xodim, ishchi","ipa":"ɪmˈplɔɪ.iː"},{"en":"promotion","uz":"lavozimga ko'tarilish","ipa":"prəˈməʊ.ʃən"},{"en":"wage","uz":"ish haqi (soatbay yoki haftalik)","ipa":"weɪdʒ"},{"en":"training","uz":"o'qitish, kasbiy tayyorgarlik","ipa":"ˈtreɪ.nɪŋ"},{"en":"internship","uz":"amaliyot","ipa":"ˈɪn.tɜːn.ʃɪp"},{"en":"freelance","uz":"frilanser; frilanser sifatida","ipa":"ˈfriː.lɑːns"},{"en":"scholarship","uz":"stipendiya (grant)","ipa":"ˈskɒl.ə.ʃɪp"},{"en":"workload","uz":"ish yuki","ipa":"ˈwɜːk.ləʊd"},{"en":"resign","uz":"ishdan o'z xohishi bilan ketmoq","ipa":"rɪˈzaɪn"}],"summary":["job — aniq ish joyi (sanaladi); work — mehnat (sanalmaydi: a lot of work); career — uzoq kasbiy yo'l.","employ → employer, employee, employment, unemployed: bitta o'zakdan bir oila.","Tayyor birikmalar: meet a deadline, earn a salary, gain experience, apply for a job, get a promotion, sit / take an exam, pass / fail, submit an essay.","Predloglar: work as (kasb), work for (kompaniya), work at (joy), in charge of, responsible for, good at, graduate from.","Xato: ~~I gave an exam~~, ~~many works~~, ~~I work like a teacher~~. To'g'risi: I took an exam, a lot of work, I work as a teacher."]},{"id":"u22-l6","slug":"phrasal-verbs","title":"Phrasal verbs","titleUz":"Phrasal verbs: ajraladigan va ajralmaydigan","goal":"Ish, o'qish va texnologiyada eng ko'p ishlatiladigan phrasal verbs (set up, fill in, hand in, back up, look into) ni bilasiz, ularni ajraladigan va ajralmaydigan turlarga ajratasiz va olmoshni to'g'ri joyga qo'yasiz: fill it in, lekin look after it.","words":[{"en":"set up","uz":"o'rnatmoq, sozlamoq, ochmoq","ipa":"set ʌp"},{"en":"hand in","uz":"topshirmoq (ish, hujjat)","ipa":"hænd ɪn"},{"en":"figure out","uz":"tushunib yetmoq, yechimini topmoq","ipa":"ˈfɪɡ.ər aʊt"},{"en":"back up","uz":"zaxira nusxasini olmoq","ipa":"bæk ʌp"},{"en":"sign up","uz":"ro'yxatdan o'tmoq, yozilmoq","ipa":"saɪn ʌp"},{"en":"look into","uz":"tekshirib ko'rmoq","ipa":"lʊk ˈɪn.tuː"},{"en":"put off","uz":"kechiktirmoq, qoldirmoq","ipa":"pʊt ɒf"},{"en":"come up with","uz":"o'ylab topmoq","ipa":"kʌm ʌp wɪð"},{"en":"drop out","uz":"o'qishni tashlamoq","ipa":"drɒp aʊt"},{"en":"carry out","uz":"o'tkazmoq, bajarmoq","ipa":"ˈkær.i aʊt"}],"summary":["Phrasal verb = fe'l + particle, ma'nosi yangi: back up, fill in, look into. Butun birikmani yodlang.","Ajraladigan (fill in, hand in, set up, back up, put off, turn down): ot ikki joyda tura oladi, olmosh faqat o'rtada: fill it in.","Ajralmaydigan (look after, look into, come across, get over): ob'ekt doim oxirida: look after them.","Uch qismli (look forward to, put up with, come up with, catch up with) bo'linmaydi; look forward to dan keyin -ing.","Ob'ektsiz phrasal verbs: log in, sign up, drop out, break down, carry on."]},{"id":"u22-l14","slug":"listening-and-speaking-technology-in-our-lives","title":"Listening and speaking: technology in our lives","titleUz":"Tinglash va gapirish: hayotimizdagi texnologiya","goal":"Texnologiya haqidagi suhbatni tinglab tushunasiz (asosiy fikr va tafsilotlar), o'z fikringizni ayta olasiz (I rely on my phone for almost everything) va I'm not sure I agree deb muloyim e'tiroz bildirasiz.","words":[{"en":"browse","uz":"internetda ko'zdan kechirmoq","ipa":"braʊz"},{"en":"privacy","uz":"shaxsiy hayot, maxfiylik","ipa":"ˈprɪv.ə.si"},{"en":"addicted","uz":"qaram, o'rganib qolgan","ipa":"əˈdɪk.tɪd"},{"en":"stream","uz":"onlayn tomosha qilmoq yoki tinglamoq","ipa":"striːm"},{"en":"notification","uz":"xabarnoma","ipa":"ˌnəʊ.tɪ.fɪˈkeɪ.ʃən"}],"summary":["Tinglashda avval asosiy fikrni (kim, nima haqida), keyin tafsilotlarni (raqam, sabab) toping.","Fikr bildirish: In my opinion…, I rely on… for…; rozilik: I completely agree; qisman: You have a point, but…","Muloyim e'tiroz: I'm not sure I agree. To'g'ridan-to'g'ri You're wrong demang.","Gapirganda fikrni sabab bilan yoqlang (because, so that, to) va the more…, the better… ni ishlating."]},{"id":"u22-l10","slug":"solving-a-problem-at-work-or-with-technology","title":"Solving a problem at work or with technology","titleUz":"Ishdagi yoki texnik muammoni hal qilish","goal":"Texnik yordamga murojaat qilasiz (My laptop keeps crashing), muammoni aniq tushuntirasiz, yechim so'raysiz va ishda muddatni o'zgartirish uchun muloyim iltimos qilasiz (Would it be possible to…?).","words":[{"en":"freeze","uz":"qotib qolmoq (ekran, dastur)","ipa":"friːz"},{"en":"reboot","uz":"qayta ishga tushirmoq","ipa":"ˌriːˈbuːt"},{"en":"backup","uz":"zaxira nusxa","ipa":"ˈbæk.ʌp"},{"en":"glitch","uz":"kichik nosozlik","ipa":"ɡlɪtʃ"},{"en":"error","uz":"xato","ipa":"ˈer.ər"}],"summary":["Muammoni tushuntirish: I'm having a problem with…, It keeps crashing, It started after…, I've already tried…ing.","keep + -ing takrorlanuvchi holat; try + -ing sinab ko'rish. It says there is an error — xato xabari.","Yordam va vaqt so'rash: Would it be possible to…?, I'm afraid I won't…, Could you give me a hand?","Va'da: I'll look into it, I'll let you know, I'll definitely send it on Monday."]},{"id":"u22-l7","slug":"writing-a-formal-email","title":"Writing a formal email","titleUz":"Yozish: rasmiy elektron xat","goal":"Rasmiy elektron xatning tuzilishini (sarlavha, murojaat, maqsad, so'rov, xulosa, xayrlashuv) bilasiz, Dear Mr Brown… Yours sincerely va Dear Sir or Madam… Yours faithfully ni adashtirmaysiz va I am writing to enquire about… I would be grateful if you could… kabi tayyor iboralar bilan o'zingiz xat yoza olasiz.","words":[{"en":"enclose","uz":"ilova qilmoq (xat bilan birga)","ipa":"ɪnˈkləʊz"},{"en":"regarding","uz":"...ga oid, ...ga taalluqli","ipa":"rɪˈɡɑː.dɪŋ"},{"en":"reluctant","uz":"istaksiz, ikkilangan","ipa":"rɪˈlʌk.tənt"},{"en":"inconvenience","uz":"noqulaylik","ipa":"ˌɪn.kənˈviː.ni.əns"},{"en":"forward","uz":"jo'natmoq (olingan xatni)","ipa":"ˈfɔː.wəd"},{"en":"appreciate","uz":"qadrlamoq, minnatdor bo'lmoq","ipa":"əˈpriː.ʃi.eɪt"},{"en":"proceed","uz":"davom etmoq, o'tmoq","ipa":"prəˈsiːd"},{"en":"assist","uz":"yordam bermoq (rasmiy)","ipa":"əˈsɪst"},{"en":"accommodate","uz":"joylashtirmoq; moslashmoq","ipa":"əˈkɒm.ə.deɪt"},{"en":"response","uz":"javob","ipa":"rɪˈspɒns"}],"summary":["Rasmiy xat: Subject → Dear… → maqsad → asosiy qism → yakun → Yours… → ism. Har qism qisqa abzats.","Dear Mr Brown… Yours sincerely (ism ma'lum); Dear Sir or Madam… Yours faithfully (ism noma'lum).","Tayyor iboralar: I am writing to enquire about… Could you please…? I would be grateful if you could… Please find attached… I look forward to hearing from you.","Rasmiy so'zlar: get → receive, need → require, help → assist, tell → inform, start → begin, I want → I would like.","Qisqartmalarsiz yozing: I am, I would, cannot. look forward to dan keyin -ing."]},{"id":"u22-l15","slug":"reading-and-writing-a-job-advert-and-cover-email","title":"Reading and writing: a job advert and cover email","titleUz":"O'qish va yozish: e'lon va qo'shimcha xat","goal":"Ish e'lonini o'qib, talablar va shartlarni topasiz, so'ng e'longa mos qo'shimcha xat (cover email) yozasiz: nega nomzod ekaningizni, tajribangizni va qachon boshlay olishingizni aytasiz.","words":[{"en":"vacancy","uz":"bo'sh ish o'rni","ipa":"ˈveɪ.kən.si"},{"en":"requirement","uz":"talab","ipa":"rɪˈkwaɪə.mənt"},{"en":"applicant","uz":"nomzod, ariza beruvchi","ipa":"ˈæp.lɪ.kənt"},{"en":"relevant","uz":"tegishli, mos","ipa":"ˈrel.ə.vənt"},{"en":"qualified","uz":"malakali, layoqatli","ipa":"ˈkwɒl.ɪ.faɪd"}],"summary":["E'longa qarab lavozim, talablar va muddatni toping. Tajriba an advantage bo'lsa, bu majburiy emas.","Cover email: Dear…, I am writing to apply for…, tajriba, qiziqish, I am available to start…, I look forward to hearing from you.","Ism ma'lum: Yours sincerely; ism noma'lum (Dear Sir or Madam): Yours faithfully.","To'g'ri qoliplar: good at + -ing, interested in + -ing, look forward to + -ing, to apply for."]},{"id":"u22-l8","slug":"unit-review-work-and-technology","title":"Unit review: work and technology","titleUz":"Bosqich takrori: ish va texnologiya","goal":"Bosqichdagi asosiy qoidalarni yangi misollar bilan takrorlaysiz: gerund / infinitive, maqsad iboralari, kelasi zamon shakllari, Future Continuous / Perfect, taqqoslash, phrasal verbs va rasmiy xat iboralari. Texnologiya va ish mavzusidagi 10 ta eng foydali so'zni o'rganasiz.","words":[{"en":"digital","uz":"raqamli","ipa":"ˈdɪdʒ.ɪ.təl"},{"en":"software","uz":"dasturiy ta'minot","ipa":"ˈsɒft.weər"},{"en":"productivity","uz":"ish unumdorligi","ipa":"ˌprɒd.ʌkˈtɪv.ə.ti"},{"en":"security","uz":"xavfsizlik","ipa":"sɪˈkjʊə.rə.ti"},{"en":"access","uz":"kirish huquqi, ruxsat","ipa":"ˈæk.ses"},{"en":"data","uz":"ma'lumotlar","ipa":"ˈdeɪ.tə"},{"en":"remote","uz":"masofaviy","ipa":"rɪˈməʊt"},{"en":"workplace","uz":"ish joyi","ipa":"ˈwɜːk.pleɪs"},{"en":"hybrid","uz":"aralash (ofis va uydan)","ipa":"ˈhaɪ.brɪd"},{"en":"network","uz":"tarmoq","ipa":"ˈnet.wɜːk"}],"summary":["-ing: enjoy, avoid, finish, suggest, predloglardan keyin. to + fe'l: want, decide, plan, manage, promise. stop doing / stop to do ma'nosi farq qiladi.","Maqsad: to, in order to, so that + gap, for + ot / -ing. Kelasi zamon: will, going to, Present Continuous (reja), Present Simple (jadval).","will be + -ing (o'sha payt jarayonda), will have + V3 (o'sha paytgacha tugagan).","Taqqoslash: the more… the more, much / far + comparative, as… as, not as… as, twice as… as.","Phrasal verbs'da olmosh o'rtada (fill it in); ajralmaydiganlarda oxirida (look after them). Rasmiy xat: Yours sincerely / faithfully, qisqartmasiz."]},{"id":"u22-l11","slug":"work-study-and-technology-final-review","title":"Work, study and technology: final review","titleUz":"Ish, o'qish va texnologiya: yakuniy takror","goal":"Butun bosqichni takrorlaysiz: gerund / infinitive, maqsad, kelasi zamon shakllari, Future Continuous / Perfect, taqqoslash, bashorat, phrasal verbs va rasmiy xat iboralari. Yangi misollarda bilimingizni tekshirasiz.","words":[{"en":"seminar","uz":"seminar, amaliy mashg'ulot","ipa":"ˈsem.ɪ.nɑː"},{"en":"tutor","uz":"repetitor, shaxsiy ustoz","ipa":"ˈtjuː.tər"},{"en":"overtime","uz":"qo'shimcha ish vaqti","ipa":"ˈəʊ.və.taɪm"},{"en":"fragile","uz":"mo'rt, sinuvchan","ipa":"ˈfrædʒ.aɪl"},{"en":"lecturer","uz":"universitet o'qituvchisi","ipa":"ˈlek.tʃər.ər"}],"summary":["enjoy / avoid / suggest + -ing, want / decide / hope + to, predlogdan keyin -ing; maqsad: to / in order to / so that.","Kelasi zamon: will (qaror, taxmin), going to (reja), Present Continuous (kelishilgan); will be -ing (jarayon), will have V3 (natija).","Taqqoslash: the more…, the more…, much / far, as…as. Ishonch: definitely, probably, I doubt, likely.","Phrasal verbs: olmosh o'rtada (fill it in); rasmiy xat: Dear…, I am writing to…, Yours sincerely / faithfully."]}]},{"id":"u23","n":23,"title":"Ideas, opinions and communication","titleUz":"G'oyalar, fikrlar va muloqot: munozara, bog'lovchilar, B1 yakuni","description":"Fikr bildirish va asoslash, taqqoslash, bog'lovchi so'zlar, qiyin mavzular bo'yicha munozara, taqdimot, esse va B1 yakuniy takrori.","canDo":["Fikrimni asoslab aytaman va boshqalarning fikriga muloyim e'tiroz bildiraman","however, therefore, in addition kabi so'zlar bilan fikrlarimni bog'layman","Afzallik va kamchiliklarni taqqoslab, xulosa chiqaraman","Qisqa nutq yoki fikr bildiruvchi esse tayyorlayman"],"lessons":[{"id":"u23-l1","slug":"giving-and-defending-opinions","title":"Giving and defending opinions","titleUz":"Fikr bildirish va himoya qilish: I think, In my view, I'm convinced","goal":"Fikringizni I think, In my opinion, I'm convinced that… kabi iboralar bilan bildirasiz, sabab va misol bilan himoya qilasiz, rozi bo'lasiz va xushmuomala e'tiroz bildirasiz, hamda I don't think… qolipini va I am agree kabi xatolarni to'g'ri ishlatasiz.","words":[{"en":"presume","uz":"taxmin qilmoq, o'ylamoq","ipa":"prɪˈzjuːm"},{"en":"point of view","uz":"nuqtai nazar","ipa":"ˌpɔɪnt əv ˈvjuː"},{"en":"convinced","uz":"ishongan, aniq ishonchi komil","ipa":"kənˈvɪnst"},{"en":"justify","uz":"oqlamoq, asoslab bermoq","ipa":"ˈdʒʌs.tɪ.faɪ"},{"en":"argument","uz":"dalil; bahs","ipa":"ˈɑː.ɡjə.mənt"},{"en":"point out","uz":"ta'kidlab o'tmoq, ko'rsatib o'tmoq","ipa":"ˌpɔɪnt ˈaʊt"},{"en":"compete","uz":"raqobatlashmoq","ipa":"kəmˈpiːt"},{"en":"reasoning","uz":"fikrlash tarzi, mulohaza","ipa":"ˈriː.zən.ɪŋ"},{"en":"statement","uz":"bayonot, fikr","ipa":"ˈsteɪt.mənt"},{"en":"debate","uz":"munozara","ipa":"dɪˈbeɪt"}],"summary":["Fikr bildirish: I think (yumshoq), In my opinion / In my view (o'rtacha), I'm convinced that (qat'iy). Ikkisini birga qo'ymang va ~~According to me~~ demang.","Fikrni himoya qilish: fikr → sabab → misol → xulosa (The main reason is that… For example… That is why…).","Rozilik va e'tiroz: I agree with you, You've got a point, but…, I'm afraid I disagree. Xato: ~~I am agree~~.","I don't think + gap — inkor think ga qo'yiladi: I don't think it's true. Qisqa javob: I think so / I don't think so.","Yumshatish: perhaps, I tend to think, to some extent, it seems that."]},{"id":"u23-l12","slug":"linking-ideas-however-therefore-in-addition","title":"Linking ideas: however, therefore, in addition","titleUz":"Fikrlarni bog'lash: however, therefore, in addition, on the other hand","goal":"Fikrlaringizni bog'lovchi so'zlar bilan tartibli aytasiz: qo'shish (in addition, moreover), qarama-qarshilik (however, on the other hand, although), natija (therefore, as a result) va tartib (firstly, finally). Tinish belgilarini ham to'g'ri qo'yasiz.","words":[{"en":"in contrast","uz":"aksincha, farqli o'laroq","ipa":"ɪn ˈkɒn.trɑːst"},{"en":"therefore","uz":"shuning uchun","ipa":"ˈðeə.fɔːr"},{"en":"moreover","uz":"bundan tashqari","ipa":"mɔːrˈəʊ.vər"},{"en":"as a result","uz":"natijada","ipa":"æz ə rɪˈzʌlt"},{"en":"nevertheless","uz":"shunga qaramay","ipa":"ˌnev.ə.ðəˈles"}],"summary":["Qo'shish: in addition, moreover. Qarama-qarshilik: however, on the other hand, whereas, although. Natija: therefore, as a result, so.","However, Therefore, In addition gap boshida turadi va vergul bilan ajratiladi. Ikki gapni faqat vergul bilan however orqali bog'lamang.","Although bilan but birga ishlatilmaydi: Although it was late, we stayed.","Tartib va xulosa: firstly, secondly, finally, in conclusion. Yangi so'zlar: however, therefore, moreover, whereas, nevertheless."]},{"id":"u23-l2","slug":"advantages-and-disadvantages","title":"Advantages and disadvantages","titleUz":"Afzallik va kamchiliklar: taqqoslash va xulosa","goal":"Biror narsaning afzallik va kamchiliklarini (advantage, disadvantage, benefit, drawback) aytasiz, while, whereas, although, despite bilan qarama-qarshilikni ifodalaysiz, taqqoslash shakllarini kengaytirasiz va overall, on balance bilan xulosa qilasiz.","words":[{"en":"pros and cons","uz":"afzallik va kamchiliklar","ipa":"ˌprəʊz ən ˈkɒnz"},{"en":"downside","uz":"salbiy tomon","ipa":"ˈdaʊn.saɪd"},{"en":"benefit","uz":"foyda","ipa":"ˈben.ɪ.fɪt"},{"en":"drawback","uz":"kamchilik, salbiy tomon","ipa":"ˈdrɔː.bæk"},{"en":"side effect","uz":"yon ta'sir","ipa":"ˈsaɪd ɪˌfekt"},{"en":"weigh up","uz":"taqqoslab ko'rmoq, o'ylab ko'rmoq","ipa":"ˌweɪ ˈʌp"},{"en":"long-term","uz":"uzoq muddatli","ipa":"ˌlɒŋˈtɜːm"},{"en":"recover","uz":"tuzalmoq, o'ziga kelmoq","ipa":"rɪˈkʌv.ə"},{"en":"outweigh","uz":"ustun kelmoq","ipa":"ˌaʊtˈweɪ"},{"en":"overall","uz":"umuman olganda","ipa":"ˌəʊ.vərˈɔːl"}],"summary":["advantage / benefit va disadvantage / drawback: the advantage of living in a city, one drawback is that…","Qarama-qarshilik: while / whereas / although + gap, despite / in spite of + ot yoki -ing. although bilan but ishlatilmaydi; ~~despite of~~ emas.","Taqqoslash: much / far / slightly + comparative, not as … as, the more …, the more …, by far the + superlative. ~~very faster~~ xato.","Xulosa: Overall, / All in all, / On balance, va outweigh. Yechim: One solution is to + fe'l."]},{"id":"u23-l3","slug":"grammar-bridge-conditionals-and-the-passive","title":"Grammar bridge: conditionals and the passive","titleUz":"Grammatika ko'prigi: shart gaplar va majhul nisbat takrori","goal":"Nol, birinchi, ikkinchi va uchinchi shart gaplarni hamda majhul nisbatni (is made, was built, will be done, has been repaired, must be finished) aniq farqlaysiz va If I will have time yoki It was happened kabi xatolarni qilmaysiz.","words":[{"en":"provided that","uz":"agar … sharti bilan","ipa":"prəˈvaɪ.dɪd ðæt"},{"en":"as long as","uz":"faqat shu shart bilan, …gina bo'lsa","ipa":"æz lɒŋ æz"},{"en":"supposing","uz":"faraz qilaylik, agar","ipa":"səˈpəʊ.zɪŋ"},{"en":"in case","uz":"ehtiyot uchun, ehtimol bo'lsa","ipa":"ɪn keɪs"},{"en":"trustworthy","uz":"ishonchli","ipa":"ˈtrʌstˌwɜː.ði"},{"en":"make sure","uz":"ishonch hosil qilmoq","ipa":"ˈmeɪk ʃɔːr"},{"en":"rule out","uz":"inkor qilmoq, istisno etmoq","ipa":"ˌruːl ˈaʊt"},{"en":"require","uz":"talab qilmoq","ipa":"rɪˈkwaɪər"},{"en":"permit","uz":"ruxsat bermoq","ipa":"pəˈmɪt"},{"en":"provide","uz":"ta'minlamoq, taqdim etmoq","ipa":"prəˈvaɪd"}],"summary":["Shart gaplar: zero (if + Present, Present), first (if + Present, will), second (if + Past, would), third (if + had + V3, would have + V3).","if dan keyin will / would yo'q: ~~If I will have~~. Maslahat: If I were you, I would…","unless = if not (qo'shimcha inkor yo'q). as long as, provided that, in case, otherwise.","Majhul nisbat: be + V3 — is made, was built, has been repaired, will be done, must be finished. happen va arrive kabi fe'llar majhul bo'lmaydi."]},{"id":"u23-l4","slug":"grammar-bridge-all-tenses","title":"Grammar bridge: all tenses","titleUz":"Grammatika ko'prigi: barcha zamonlar takrori","goal":"Ingliz tilining asosiy zamonlarini (Present, Past, Perfect, Continuous, kelasi zamon shakllari) bir tizimga solasiz, vaqt so'zlariga qarab to'g'ri zamonni tanlaysiz va I live here since 2020, I am knowing, when I will come kabi xatolardan qochasiz.","words":[{"en":"temporary","uz":"vaqtinchalik","ipa":"ˈtem.pər.ər.i"},{"en":"permanent","uz":"doimiy","ipa":"ˈpɜː.mə.nənt"},{"en":"currently","uz":"hozirgi vaqtda","ipa":"ˈkʌr.ənt.li"},{"en":"at present","uz":"hozirda, hozircha","ipa":"æt ˈprez.ənt"},{"en":"for the time being","uz":"hozircha","ipa":"fə ðə taɪm ˈbiː.ɪŋ"},{"en":"ever since","uz":"o'sha vaqtdan beri","ipa":"ˌev.ə ˈsɪns"},{"en":"rapidly","uz":"tez, jadal","ipa":"ˈræp.ɪd.li"},{"en":"previously","uz":"ilgari, avval","ipa":"ˈpriː.vi.əs.li"},{"en":"straight away","uz":"darhol","ipa":"ˌstreɪt əˈweɪ"},{"en":"from time to time","uz":"vaqti-vaqti bilan","ipa":"frəm ˌtaɪm tə ˈtaɪm"}],"summary":["Zamonni vaqt so'zi va ma'no bo'yicha tanlang: every day (Simple), now (Continuous), since / for / ever / yet (Perfect), yesterday / ago (Past Simple).","Present Perfect Continuous jarayon va davomiylikni bildiradi: I've been waiting for an hour. know, like, want kabi holat fe'llari Continuous bo'lmaydi.","O'tgan zamon: Past Simple (voqealar), Past Continuous (fon va jarayon), Past Perfect (undan oldingi ish).","Kelajak: will (qaror, bashorat), going to (reja), Present Continuous (kelishilgan reja). when / as soon as / if dan keyin Present: ~~when I will come~~ emas."]},{"id":"u23-l13","slug":"typical-mistakes-of-uzbek-speakers-at-b1","title":"Typical mistakes of Uzbek speakers at B1","titleUz":"B1 darajada o'zbek tilida so'zlashuvchilarning tipik xatolari","goal":"O'zbek tilidan inglizchaga ko'chadigan eng keng tarqalgan xatolarni topasiz va tuzatasiz: fe'l + predlog, sanalmaydigan otlar, if bilan will, savol tartibi, I am agree va -ing / to tanlovi.","words":[{"en":"confuse","uz":"adashtirmoq, chalkashtirmoq","ipa":"kənˈfjuːz"},{"en":"overuse","uz":"haddan tashqari ko'p ishlatmoq","ipa":"ˌəʊ.vəˈjuːz"},{"en":"accurate","uz":"aniq, to'g'ri","ipa":"ˈæk.jə.rət"},{"en":"careless","uz":"beparvo, e'tiborsiz","ipa":"ˈkeə.ləs"},{"en":"get used to","uz":"o'rganib qolmoq, ko'nikmoq","ipa":"ɡet ˈjuːst tə"}],"summary":["Fe'l + predlog: discuss (predlogsiz), explain to, depend on, listen to, wait for, married to.","advice, information, news, research — sanalmaydi (a/an va -s yo'q). People — ko'plik.","If dan keyin will yo'q; I agree (am yo'q); I am 25 years old; since bilan Present Perfect.","Ichki savolda darak tartibi: Do you know where the bank is? Yangi so'zlar: confuse, overuse, accurate, careless, get used to."]},{"id":"u23-l9","slug":"taking-part-in-a-group-discussion","title":"Taking part in a group discussion","titleUz":"Guruh munozarasida qatnashish","goal":"Guruh munozarasida muloyim qatnashasiz: gapni boshlaysiz (Can I add something?), to'xtatasiz (Sorry to interrupt, but…), boshqalarni taklif qilasiz (What do you think, Sara?) va muhokamani yakunlaysiz (So, to sum up…).","words":[{"en":"contribute","uz":"hissa qo'shmoq, qatnashmoq","ipa":"kənˈtrɪb.juːt"},{"en":"interrupt","uz":"gapini bo'lmoq","ipa":"ˌɪn.təˈrʌpt"},{"en":"bring up","uz":"(mavzuni) ko'tarib chiqmoq","ipa":"ˌbrɪŋ ˈʌp"},{"en":"concern","uz":"xavotir, tashvish","ipa":"kənˈsɜːn"},{"en":"point","uz":"fikr, dalil","ipa":"pɔɪnt"}],"summary":["Gapni boshlash: Can I add something? To'xtatish: Sorry to interrupt, but…. Tugatish: Can I just finish my point?","Boshqalarni taklif qilish: What do you think, Sara? Would you like to say something?","Javob qolipi: I see what you mean, but… va That's a good point. However, …","Yakunlash: So, to sum up…. Yangi so'zlar: contribute, interrupt, bring up, concern, point."]},{"id":"u23-l5","slug":"society-environment-and-health","title":"Society, environment and health","titleUz":"Jamiyat, atrof-muhit va salomatlik: so'zlar va birikmalar","goal":"Jamiyat, atrof-muhit va salomatlik haqida gapirish uchun kerakli so'zlarni va tayyor birikmalarni (reduce pollution, lead a healthy lifestyle, raise awareness) ishlatasiz, so'z oilalarini (pollute, pollution, polluted) ajratasiz va make harm kabi xatolardan qochasiz.","words":[{"en":"society","uz":"jamiyat","ipa":"səˈsaɪ.ə.ti"},{"en":"environment","uz":"atrof-muhit","ipa":"ɪnˈvaɪ.rən.mənt"},{"en":"emissions","uz":"zararli gazlar chiqindisi","ipa":"ɪˈmɪʃ.ənz"},{"en":"recycle","uz":"qayta ishlashga topshirmoq","ipa":"ˌriːˈsaɪ.kəl"},{"en":"global warming","uz":"global isish","ipa":"ˌɡləʊ.bəl ˈwɔː.mɪŋ"},{"en":"sustainable","uz":"barqaror, tabiatga zarar qilmaydigan","ipa":"səˈsteɪ.nə.bəl"},{"en":"obesity","uz":"semizlik","ipa":"əʊˈbiː.sə.ti"},{"en":"reduce","uz":"kamaytirmoq","ipa":"rɪˈdjuːs"},{"en":"mental health","uz":"ruhiy salomatlik","ipa":"ˌmen.təl ˈhelθ"},{"en":"balanced diet","uz":"muvozanatli ovqatlanish","ipa":"ˌbæl.ənst ˈdaɪ.ət"}],"summary":["Mavzu bo'yicha gapirish uchun birikmalarni o'rganing: protect the environment, reduce pollution, lead a healthy lifestyle, take regular exercise.","do harm / cause damage deymiz, make harm demaymiz. take / do exercise, make exercise emas.","waste va population gapda yakka son sifatida ishlatiladi: The population is growing.","So'z oilasi: pollute (fe'l) — pollution (ot) — polluted (sifat); health — healthy; society — social.","Salomatlik: suffer from stress, look after your mental health, a balanced diet."]},{"id":"u23-l6","slug":"giving-a-short-presentation","title":"Giving a short presentation","titleUz":"Qisqa taqdimot qilish: tuzilma va iboralar","goal":"Ikki-uch daqiqalik taqdimotni tuzilma bilan (kirish, asosiy fikrlar, xulosa, savollar) qurasiz, har bosqichda tayyor iboralarni ishlatasiz (I'd like to talk about…, Moving on to…, To sum up…) va talk about o'rniga tell about kabi xatolardan qochasiz.","words":[{"en":"audience","uz":"tinglovchilar, auditoriya","ipa":"ˈɔː.di.əns"},{"en":"topic","uz":"mavzu","ipa":"ˈtɒp.ɪk"},{"en":"slide","uz":"slayd","ipa":"slaɪd"},{"en":"structure","uz":"tuzilma","ipa":"ˈstrʌk.tʃər"},{"en":"summarise","uz":"qisqacha bayon qilmoq","ipa":"ˈsʌm.ə.raɪz"},{"en":"emphasise","uz":"ta'kidlamoq","ipa":"ˈem.fə.saɪz"},{"en":"rehearse","uz":"mashq qilmoq, tayyorlanmoq","ipa":"rɪˈhɜːs"},{"en":"pause","uz":"to'xtab turmoq; pauza","ipa":"pɔːz"},{"en":"eye contact","uz":"ko'z bilan aloqa","ipa":"ˈaɪ ˌkɒn.tækt"},{"en":"convey","uz":"yetkazmoq, bildirmoq","ipa":"kənˈveɪ"}],"summary":["Taqdimot tuzilmasi: opening, outline, main points, conclusion, questions.","Boshlash: Today I'd like to talk about… My talk has three parts. Xato: ~~tell about~~, ~~discuss about~~.","Signal iboralari: First of all… Moving on to… For example… I'd like to emphasise that… To sum up…","Slaydga ishora: As you can see on this slide… I'd like to draw your attention to… Savollar: Are there any questions? That's a good question.","explain something to someone, explain you emas. Sekin gapiring, ko'z aloqasini saqlang, muhim fikrdan keyin to'xtab turing."]},{"id":"u23-l14","slug":"listening-and-speaking-a-two-minute-talk","title":"Listening and speaking: a two-minute talk","titleUz":"Tinglash va gapirish: ikki daqiqalik nutq","goal":"Qisqa nutqni tinglab tuzilmasini tushunasiz (kirish, uchta fikr, xulosa) va o'zingiz ikki daqiqalik nutqni sekin, aniq va pauza bilan aytasiz.","words":[{"en":"pace","uz":"tempo, tezlik","ipa":"peɪs"},{"en":"intonation","uz":"ohang, intonatsiya","ipa":"ˌɪn.təˈneɪ.ʃən"},{"en":"stress","uz":"urg'u berib aytmoq","ipa":"stres"},{"en":"volume","uz":"ovoz balandligi","ipa":"ˈvɒl.juːm"},{"en":"pronounce","uz":"talaffuz qilmoq","ipa":"prəˈnaʊns"}],"summary":["Nutq tuzilmasi: kirish (Today I would like to talk about…), fikrlar (Firstly, Secondly, Finally), qiyinchilik (However), xulosa (In conclusion).","Sekin gapiring, fikrlar orasida to'xtang, muhim so'zlarga urg'u bering.","Oldindan mashq qiling va o'zingizni yozib oling.","Yangi so'zlar: pace, intonation, stress, volume, pronounce."]},{"id":"u23-l10","slug":"disagreeing-politely-and-finding-a-compromise","title":"Disagreeing politely and finding a compromise","titleUz":"Xushmuomala e'tiroz bildirish va kelishuvga erishish","goal":"Boshqa odamning fikriga muloyim e'tiroz bildirasiz (I see your point, but…, I'm afraid I don't agree) va kelishuv taklif qilasiz (Why don't we…?, Let's meet halfway, If you…, I will…).","words":[{"en":"compromise","uz":"kelishuv, yon berish","ipa":"ˈkɒm.prə.maɪz"},{"en":"disagree","uz":"rozi bo'lmaslik","ipa":"ˌdɪs.əˈɡriː"},{"en":"acceptable","uz":"maqbul, qabul qilsa bo'ladigan","ipa":"əkˈsep.tə.bəl"},{"en":"meet halfway","uz":"o'rtada kelishmoq, yon bermoq","ipa":"ˌmiːt hɑːfˈweɪ"},{"en":"alternative","uz":"muqobil variant","ipa":"ɔːlˈtɜː.nə.tɪv"}],"summary":["Muloyim e'tiroz: I see your point, but…, I'm afraid I don't agree, I agree up to a point, but…","Kelishuv: Why don't we…? How about + -ing? Let's meet halfway. Shart: If you…, I will…","Qabul qilish: That sounds fair. I'm happy with that. disagree with somebody.","Yangi so'zlar: compromise, disagree, acceptable, meet halfway, alternative."]},{"id":"u23-l7","slug":"writing-an-opinion-essay","title":"Writing an opinion essay","titleUz":"Yozish: fikr bildiruvchi esse","goal":"120-180 so'zlik fikr bildiruvchi esse yozasiz: kirish, ikkita asosiy abzats va xulosa; bog'lovchi so'zlar va rasmiy uslubni ishlatasiz (In my opinion, Firstly, However, In conclusion), from one side kabi xatolardan qochasiz.","words":[{"en":"paragraph","uz":"abzats","ipa":"ˈpær.ə.ɡrɑːf"},{"en":"introduction","uz":"kirish","ipa":"ˌɪn.trəˈdʌk.ʃən"},{"en":"underline","uz":"alohida ta'kidlamoq","ipa":"ˌʌn.dəˈlaɪn"},{"en":"topic sentence","uz":"abzatsning bosh gapi","ipa":"ˈtɒp.ɪk ˌsen.təns"},{"en":"balanced","uz":"muvozanatli, xolis","ipa":"ˈbæl.ənst"},{"en":"formal","uz":"rasmiy","ipa":"ˈfɔː.məl"},{"en":"firstly","uz":"birinchidan","ipa":"ˈfɜːst.li"},{"en":"to sum up","uz":"xulosa qilib aytganda","ipa":"tə ˈsʌm ʌp"},{"en":"for instance","uz":"masalan","ipa":"fər ˈɪn.stəns"},{"en":"proofread","uz":"xatolarni tekshirib o'qimoq","ipa":"ˈpruːf.riːd"}],"summary":["Esse tuzilmasi: introduction (mavzu + fikr), ikkita body abzats (sabab + misol), conclusion (fikrni takrorlash, yangi fikr yo'q).","Fikr bildirish: In my opinion… I strongly believe that… It is often said that…","Bog'lovchilar: Firstly, For example, In addition, However, Therefore, In conclusion. Xato: ~~from one side~~ → On the one hand.","Rasmiy uslub: qisqartma (don't) va norasmiy so'zlar (kids, loads of) ishlatilmaydi.","Yozgach, proofread: fikr, abzatslar, bog'lovchilar, uslub, grammatika."]},{"id":"u23-l15","slug":"reading-and-writing-summarising-an-article","title":"Reading and writing: summarising an article","titleUz":"O'qish va yozish: maqolani qisqacha bayon qilish","goal":"Qisqa maqolani o'qib asosiy g'oyani topasiz va uni o'z so'zlaringiz bilan 3–4 gapda yozasiz (The article says that…, The writer explains…), fikringizni aralashtirmasdan.","words":[{"en":"key point","uz":"asosiy nuqta","ipa":"ˈkiː ˌpɔɪnt"},{"en":"paraphrase","uz":"o'z so'zlari bilan qayta aytmoq","ipa":"ˈpær.ə.freɪz"},{"en":"main idea","uz":"asosiy g'oya","ipa":"meɪn aɪˈdɪə"},{"en":"detail","uz":"tafsilot","ipa":"ˈdiː.teɪl"},{"en":"shorten","uz":"qisqartirmoq","ipa":"ˈʃɔː.tən"}],"summary":["Summary: birinchi gapda asosiy g'oya (The article is about…), keyin 2–3 muhim fikr, oxirida muallifning xulosasi.","O'z so'zlaringiz bilan yozing (paraphrase): sinonim, boshqa tuzilma, umumiy so'z.","Shaxsiy fikr yo'q. Reporting fe'llar: says, explains, argues, points out, concludes (the writer + -s).","Yangi so'zlar: key point, paraphrase, main idea, detail, shorten."]},{"id":"u23-l8","slug":"b1-final-review","title":"B1 final review","titleUz":"B1 yakuniy takrori: barcha mavzular","goal":"Bu birlikning barcha mavzularini yangi misollarda takrorlaysiz: fikr bildirish, bog'lovchi so'zlar, afzallik va kamchiliklar, shart gaplar, majhul nisbat, barcha zamonlar, taqdimot va esse iboralari — va B1 darajasining 10 ta eng foydali so'zini o'rganasiz.","words":[{"en":"approach","uz":"yondashuv, usul","ipa":"əˈprəʊtʃ"},{"en":"factor","uz":"omil","ipa":"ˈfæk.tər"},{"en":"tackle","uz":"hal qilishga kirishmoq","ipa":"ˈtæk.əl"},{"en":"effect","uz":"ta'sir, natija","ipa":"ɪˈfekt"},{"en":"overcome","uz":"yengib o'tmoq","ipa":"ˌəʊ.vəˈkʌm"},{"en":"issue","uz":"masala, muammo","ipa":"ˈɪʃ.uː"},{"en":"impact","uz":"ta'sir","ipa":"ˈɪm.pækt"},{"en":"attitude","uz":"munosabat, qarash","ipa":"ˈæt.ɪ.tjuːd"},{"en":"influence","uz":"ta'sir qilmoq; ta'sir","ipa":"ˈɪn.flu.əns"},{"en":"major","uz":"katta, jiddiy","ipa":"ˈmeɪ.dʒər"}],"summary":["Fikr: In my view… As far as I'm concerned… I'm convinced that… Rozilik: I agree with you (am agree emas). E'tiroz: I see what you mean, but…","Bog'lovchilar: In addition, However, Therefore, whereas, although. Although … but … birga ishlatilmaydi.","Shart gaplar: zero, first (if + Present, will), second (if + Past, would), third (if + Past Perfect, would have + V3). if dan keyin will yo'q.","Majhul nisbat: am / is / are + V3, was / were + V3, has been + V3, will be + V3, must be + V3.","Zamonlar: aniq vaqt → Past Simple; since / for → Present Perfect; oldingi o'tgan ish → Past Perfect. Taqdimot: To sum up…; esse: introduction, body, conclusion."]},{"id":"u23-l11","slug":"intermediate-final-review","title":"Intermediate: final review","titleUz":"Intermediate: yakuniy takror","goal":"Butun mavzuni yangi misollarda takrorlaysiz: fikr bildirish, bog'lovchi so'zlar, taqqoslash, shart gaplar va majhul nisbat, zamonlar, taqdimot va esse iboralari.","words":[{"en":"reflect","uz":"o'ylab ko'rmoq, mulohaza yuritmoq","ipa":"rɪˈflekt"},{"en":"make progress","uz":"yutuqqa erishmoq, olg'a siljimoq","ipa":"meɪk ˈprəʊ.ɡres"},{"en":"viewpoint","uz":"nuqtai nazar","ipa":"ˈvjuː.pɔɪnt"},{"en":"express","uz":"ifodalamoq","ipa":"ɪkˈspres"},{"en":"balance","uz":"muvozanat","ipa":"ˈbæl.əns"}],"summary":["Fikr: In my view, I'm convinced that…; bog'lovchilar: however, therefore, in addition, in conclusion; Although + but yo'q.","Shart gaplar: if + hozirgi, will; if + o'tgan, would. Majhul: was / were / is / are + V3.","Zamonlar: Present Simple, Continuous, Past Simple, Present Perfect (for / since), future.","Yangi so'zlar: reflect, make progress, viewpoint, express, balance."]}]}]},{"id":"b2","slug":"upper-intermediate","title":"Upper-Intermediate","cefr":"B2","text":"Erkin gaplashaman, murakkab matnlarni o'qiyman.","units":[{"id":"u24","n":24,"title":"Time, habits and change","titleUz":"Vaqt, odatlar va o'zgarish: zamonlar tizimi B2 darajasida","description":"Hikoya zamonlari, Present Perfect Simple va Continuous, o'tgan odatlar, kelasi zamon shakllari, holat va harakat fe'llari, o'zgarish va tendensiyalar lug'ati.","canDo":["Hikoya zamonlarini (Past Simple, Continuous, Perfect, Perfect Continuous) aralashtirib, voqeani izchil hikoya qila olaman","Present Perfect Simple va Continuous bilan natija va davomiylikni farqlayman (for, since, how long)","O'tgan odatlarim haqida used to / would bilan, kelajak rejalarim haqida will be -ing va will have V3 bilan gapiraman","O'zgarish haqida blog yoki izoh yozaman va vaqt bog'lovchilari bilan fikrni ketma-ket bayon qilaman"],"lessons":[{"id":"u24-l1","slug":"narrative-tenses-at-b2","title":"Narrative tenses at B2","titleUz":"Hikoya zamonlari B2 darajasida: Past Simple, Continuous, Perfect va Perfect Continuous","goal":"Hikoyani to'rtta o'tgan zamon bilan tuzasiz: Past Simple (asosiy voqealar), Past Continuous (fon va uzilgan ish), Past Perfect (undan oldingi voqea) va Past Perfect Continuous (oldingi davomli ish va uning natijasi). Zamonni vaqt so'ziga qarab emas, ma'noga qarab tanlaysiz va had ni tushirib qoldirish, was happened kabi xatolardan qochasiz. Bu IELTS Speaking Part 2 va blog hikoyalari uchun kerak.","words":[{"en":"overhear","uz":"tasodifan eshitib qolmoq","ipa":"ˌəʊ.vəˈhɪə"},{"en":"startle","uz":"cho'chitib yubormoq","ipa":"ˈstɑː.təl"},{"en":"stumble","uz":"qoqilmoq; tasodifan duch kelmoq","ipa":"ˈstʌm.bəl"},{"en":"glimpse","uz":"bir lahza ko'rib qolmoq; lahzalik ko'rinish","ipa":"ɡlɪmps"},{"en":"burst into","uz":"birdan ... boshlab yubormoq (kulgi, yig'i)","ipa":"bɜːst ˈɪn.tuː"},{"en":"run into","uz":"tasodifan uchratib qolmoq","ipa":"rʌn ˈɪn.tuː"},{"en":"vanish","uz":"g'oyib bo'lmoq","ipa":"ˈvæn.ɪʃ"},{"en":"ordeal","uz":"og'ir sinov","ipa":"ɔːˈdiːl"},{"en":"out of the blue","uz":"kutilmaganda, to'satdan","ipa":"aʊt əv ðə bluː"},{"en":"end up","uz":"oxiri ... bo'lib qolmoq","ipa":"end ˈʌp"}],"summary":["Hikoyada zamonlar vazifa bo'yicha bo'linadi: Past Simple — asosiy voqealar, Past Continuous — fon va uzilgan ish.","Past Perfect (had + V3) — hikoya paytidan oldin tugagan voqea; Past Perfect Continuous (had been + V-ing) — oldin davom etgan ish va uning natijasi.","Zamonni vaqt so'ziga emas, ma'noga qarab tanlang: When I arrived, it had started / was starting / started.","Tipik xatolar: had ni tushirib qoldirish, ~~was happened~~, davomiylikda ~~was waiting for two hours when~~ → had been waiting, ~~yesterday have met~~.","Tartib bilan aytilgan voqealarda had ishlatmang: I woke up, had breakfast and left."]},{"id":"u24-l12","slug":"past-perfect-continuous-and-time-clauses","title":"Past Perfect Continuous and time clauses","titleUz":"Past Perfect Continuous va vaqt gaplari: by the time, no sooner… than, hardly… when","goal":"O'tgan paytdan oldin davom etgan jarayonni Past Perfect Continuous bilan aytasiz (had been waiting for two hours), by the time, as soon as, after/before + -ing bilan vaqt gaplari tuzasiz va no sooner… than, hardly… when ni o'qiganda taniysiz.","words":[{"en":"soaked","uz":"ho'l bo'lib ketgan","ipa":"səʊkt"},{"en":"stranded","uz":"qolib ketgan (chiqib ketolmay)","ipa":"ˈstræn.dɪd"},{"en":"drag on","uz":"cho'zilib ketmoq","ipa":"dræɡ ɒn"},{"en":"hang around","uz":"bekor aylanib yurmoq, kutib turmoq","ipa":"hæŋ əˈraʊnd"},{"en":"frantic","uz":"xavotirdan o'zini yo'qotgan","ipa":"ˈfræn.tɪk"},{"en":"downpour","uz":"jala","ipa":"ˈdaʊn.pɔː"}],"summary":["Past Perfect Continuous: had been + V-ing: o'tgan paytdan oldin davom etgan jarayon (for / since) yoki ko'rinib turgan natija.","Holat fe'llari bilan Continuous bo'lmaydi: had known, had wanted.","by the time + Past Simple → asosiy gapda Past Perfect; as soon as + Past Simple; after / before + V-ing.","No sooner … than va hardly … when (inversiya: had he) — rasmiy shakllar, asosan o'qishda uchraydi. Yangi so'zlar: soaked, stranded, drag on, hang around, frantic, downpour."]},{"id":"u24-l2","slug":"present-perfect-simple-or-continuous","title":"Present Perfect: simple or continuous?","titleUz":"Present Perfect Simple yoki Continuous: natija, davomiylik, so'nggi o'zgarishlar","goal":"Present Perfect Simple (I've written three emails) va Present Perfect Continuous (I've been writing emails) o'rtasidagi farqni ma'noga qarab tanlaysiz: natija yoki soni (how many) va jarayon yoki davomiylik (how long). lately, recently, so far, by now, since, for bilan so'nggi o'zgarishlar haqida gapirasiz va I am living here since, I have seen him yesterday kabi xatolardan qochasiz. Ish suhbati, hisobot va IELTS Speaking uchun foydali.","words":[{"en":"on track","uz":"rejaga muvofiq, yo'lida","ipa":"ɒn træk"},{"en":"behind schedule","uz":"jadvaldan orqada","ipa":"bɪˌhaɪnd ˈʃed.juːl"},{"en":"ahead of schedule","uz":"jadvaldan oldin","ipa":"əˌhed əv ˈʃed.juːl"},{"en":"meet a deadline","uz":"muddatga ulgurmoq","ipa":"miːt ə ˈded.laɪn"},{"en":"juggle","uz":"bir nechta ishni birga olib bormoq","ipa":"ˈdʒʌɡ.əl"},{"en":"burnt out","uz":"charchab, kuch-quvvatdan ketgan","ipa":"bɜːnt aʊt"},{"en":"take up","uz":"(hobbi, mashg'ulot) boshlamoq","ipa":"teɪk ʌp"},{"en":"get the hang of","uz":"ko'nikib, uddasidan chiqmoq","ipa":"ɡet ðə hæŋ əv"},{"en":"fall behind","uz":"orqada qolmoq","ipa":"fɔːl bɪˈhaɪnd"},{"en":"overhaul","uz":"tubdan qayta ko'rib chiqmoq","ipa":"ˌəʊ.vəˈhɔːl"}],"summary":["Simple (have + V3) — natija va son (how many); Continuous (have been + V-ing) — jarayon va davomiylik (how long).","Continuous vaqtinchalik vaziyat va so'nggi o'zgarishlar uchun qulay: I've been staying…, Prices have been rising lately.","since (nuqta) va for (muddat) bilan Present Perfect; aniq o'tgan vaqt (yesterday, last week) bilan Past Simple.","Holat fe'llari (know, have, like, belong) Continuous bo'lmaydi: have known, has had.","It's the first time … have + V3 va superlativ + ever doim Present Perfect bilan keladi."]},{"id":"u24-l3","slug":"past-habits-used-to-would-and-be-used-to","title":"Past habits: used to, would and be used to","titleUz":"O'tgan odatlar: used to, would; be used to va get used to","goal":"O'tgan odatlar va holatlarni used to va would bilan aytasiz, ularning farqini bilasiz (would holat fe'llari bilan ishlatilmaydi). be used to va get used to (ko'nikkan bo'lmoq / ko'nikmoq) dan keyin -ing kelishini eslab, I am used to play, I used to going, I didn't used to kabi xatolardan qochasiz. Bolalik, ish va hayotdagi o'zgarishlar haqida gapirishda yordam beradi.","words":[{"en":"kick the habit","uz":"odatdan voz kechmoq","ipa":"kɪk ðə ˈhæb.ɪt"},{"en":"creature of habit","uz":"odatlariga sodiq inson","ipa":"ˈkriː.tʃər əv ˈhæb.ɪt"},{"en":"second nature","uz":"ikkinchi tabiat, odatga aylangan","ipa":"ˌsek.ənd ˈneɪ.tʃə"},{"en":"out of habit","uz":"odatga ko'ra","ipa":"aʊt əv ˈhæb.ɪt"},{"en":"get into the habit of","uz":"... odatini orttirmoq","ipa":"ɡet ˈɪn.tuː ðə ˈhæb.ɪt əv"},{"en":"back then","uz":"o'sha paytda, o'sha vaqtlarda","ipa":"bæk ðen"},{"en":"accustomed to","uz":"... ga o'rganib qolgan","ipa":"əˈkʌs.təmd tuː"},{"en":"fond of","uz":"yaxshi ko'radigan, mehr qo'ygan","ipa":"fɒnd əv"},{"en":"upbringing","uz":"tarbiya, voyaga yetkazish","ipa":"ˈʌp.brɪŋ.ɪŋ"},{"en":"adapt to","uz":"moslashmoq","ipa":"əˈdæpt tuː"}],"summary":["used to + V1 — o'tgan odat va holat; would + V1 — faqat takrorlanuvchi harakat (vaqt konteksti berilgandan keyin).","Inkor va savol: didn't use to, Did you use to…? (used emas, use).","Aniq son yoki aniq vaqt bo'lsa Past Simple: I visited Rome twice. (~~used to visit twice~~).","be used to / get used to + -ing yoki ot — ko'nikkan bo'lish / ko'nikish; to — predlog.","Tipik xatolar: ~~I am used to play~~, ~~I used to going~~, ~~didn't used to~~, ~~I would be shy~~."]},{"id":"u24-l4","slug":"talking-about-the-future","title":"Talking about the future","titleUz":"Kelasi zamon: will, going to, Future Continuous va Future Perfect","goal":"Kelajak haqida gapirishda will, going to, Present Continuous va Present Simpleni ma'noga qarab tanlaysiz (qaror, reja, kelishuv, jadval). Future Continuous (this time tomorrow I'll be flying) va Future Perfect (by 2030 I will have saved…)ni ishlatasiz, vaqt gaplarida will dan qochasiz va be about to, be due to, be likely to shakllarini bilasiz. Ish uchrashuvlari, rejalar va IELTS Speaking Part 2 uchun kerak.","words":[{"en":"anticipate","uz":"oldindan ko'ra bilmoq, kutmoq","ipa":"ænˈtɪs.ɪ.peɪt"},{"en":"foresee","uz":"oldindan ko'rmoq, bashorat qilmoq","ipa":"fɔːˈsiː"},{"en":"on the horizon","uz":"yaqin kelajakda kutilayotgan","ipa":"ɒn ðə həˈraɪ.zən"},{"en":"in the pipeline","uz":"tayyorlanayotgan, rejada","ipa":"ɪn ðə ˈpaɪp.laɪn"},{"en":"likelihood","uz":"ehtimollik","ipa":"ˈlaɪk.li.hʊd"},{"en":"be due to","uz":"rejaga ko'ra ... kerak","ipa":"biː djuː tuː"},{"en":"on the verge of","uz":"... arafasida","ipa":"ɒn ðə vɜːdʒ əv"},{"en":"look ahead","uz":"kelajakka nazar tashlamoq","ipa":"lʊk əˈhed"},{"en":"set a goal","uz":"maqsad qo'ymoq","ipa":"set ə ɡəʊl"},{"en":"aim to","uz":"... ni maqsad qilmoq","ipa":"eɪm tuː"}],"summary":["will — shu zahoti qaror, fikr, va'da; going to — oldindan reja va dalilga asoslangan bashorat; Present Continuous — kelishuv; Present Simple — jadval.","Future Continuous (will be + V-ing) — kelajakdagi paytda davom etayotgan ish; Future Perfect (will have + V3) — shu paytgacha tugagan ish (by, by the time).","when, as soon as, until, before, if, by the time dan keyin Present Simple, will emas: ~~When I will arrive~~.","be about to, be due to, be likely to, be on the verge of — yaqin kelajak va ehtimol qoliplari; keyin V1 (yoki -ing).","Tipik xatolar: ~~I think I go~~, ~~about to starting~~, ~~By 2030 I will save~~ (→ will have saved)."]},{"id":"u24-l13","slug":"stative-and-dynamic-verbs","title":"Stative and dynamic verbs","titleUz":"Holat va harakat fe'llari: think, have, see, taste, be","goal":"Holat fe'llari (know, believe, want, belong) odatda Continuous bo'lmasligini bilasiz, ikki ma'noli fe'llarni (think, have, see, taste, look, be) farqlaysiz va bu qoida Present Perfect hamda kelasi zamon shakllarida qanday ishlashini tushunasiz.","words":[{"en":"possess","uz":"ega bo'lmoq, egalik qilmoq","ipa":"pəˈzes"},{"en":"resemble","uz":"o'xshamoq","ipa":"rɪˈzem.bəl"},{"en":"consist of","uz":"...dan iborat bo'lmoq","ipa":"kənˈsɪst əv"},{"en":"contain","uz":"o'z ichiga olmoq","ipa":"kənˈteɪn"},{"en":"owe","uz":"qarzdor bo'lmoq","ipa":"əʊ"},{"en":"appear","uz":"ko'rinmoq, tuyulmoq","ipa":"əˈpɪər"}],"summary":["Holat fe'llari (know, believe, want, need, belong, contain) odatda Continuous bo'lmaydi: I know, I've known her for years.","Ikki ma'noli fe'llar: think (fikr) / am thinking (jarayon); have (ega) / am having (lunch, a meeting); see (tushunmoq) / am seeing (uchrashmoq).","be + being vaqtincha xulqni bildiradi: He is being rude today.","Yangi so'zlar: possess, resemble, consist of, contain, owe, appear."]},{"id":"u24-l9","slug":"catching-up-with-an-old-friend","title":"Catching up with an old friend","titleUz":"Eski do'st bilan uchrashuv: hayotingizdagi o'zgarishlar haqida gapirish","goal":"Eski do'stingiz bilan yillar o'tib uchrashganda small talk boshlaysiz (What have you been up to?), nima o'zgarganini (Present Perfect), avval nima qilganingizni (used to) va kelasi yilgi rejalaringizni (will be doing) tabiiy gapirib berasiz.","words":[{"en":"drift apart","uz":"bir-biridan uzoqlashmoq (munosabat susayishi)","ipa":"drɪft əˈpɑːt"},{"en":"hectic","uz":"shov-shuvli, juda band","ipa":"ˈhek.tɪk"},{"en":"rusty","uz":"zanglagan; (ko'nikma) esdan chiqqan","ipa":"ˈrʌs.ti"},{"en":"relocate","uz":"boshqa joyga ko'chmoq (ish yoki yashash uchun)","ipa":"ˌriː.ləʊˈkeɪt"},{"en":"get promoted","uz":"lavozimi oshmoq","ipa":"get prəˈməʊ.tɪd"},{"en":"life-changing","uz":"hayotni o'zgartiradigan","ipa":"ˌlaɪf ˈtʃeɪn.dʒɪŋ"}],"summary":["What have you been up to? va You haven't changed a bit! — eski do'st bilan suhbat uchun tayyor iboralar.","Hozirgacha davom etayotgan holat: I've lived here since 2019 (since + nuqta, for + muddat); know, have bilan Continuous ishlatilmaydi.","Tugagan odat: used to + V1; kelasi yilgi jarayon: will be + V-ing.","Yangi so'zlar: drift apart, hectic, rusty, relocate, get promoted, life-changing."]},{"id":"u24-l5","slug":"change-trends-and-development","title":"Change, trends and development","titleUz":"O'zgarish va rivojlanish: so'zlar va birikmalar (rise, decline, steady, boom)","goal":"O'zgarish va tendensiyalar haqida aniq gapirasiz va yozasiz: a sharp rise, a steady increase, a slump, an upturn kabi birikmalarni, boom, overtake, transform, evolve, stagnate kabi fe'llarni bilasiz. rise / raise, increase by / to va ot–fe'l shakllarini adashtirmaysiz. IELTS Writing Task 1, ish hisoboti va yangiliklarni tushunish uchun kerak.","words":[{"en":"steady","uz":"bir maromdagi, barqaror","ipa":"ˈsted.i"},{"en":"boom","uz":"keskin o'sish, gullab-yashnash","ipa":"buːm"},{"en":"slump","uz":"keskin pasayish","ipa":"slʌmp"},{"en":"upturn","uz":"yaxshilanish, ko'tarilishga burilish","ipa":"ˈʌp.tɜːn"},{"en":"downturn","uz":"tanazzul, pasayish davri","ipa":"ˈdaʊn.tɜːn"},{"en":"stagnate","uz":"o'smay turib qolmoq","ipa":"stæɡˈneɪt"},{"en":"gain momentum","uz":"tezlashmoq, kuch olmoq","ipa":"ˌɡeɪn məˈmen.təm"},{"en":"overtake","uz":"quvib o'tmoq, ortda qoldirmoq","ipa":"ˌəʊ.vəˈteɪk"},{"en":"transform","uz":"butunlay o'zgartirmoq","ipa":"trænsˈfɔːm"},{"en":"evolve","uz":"asta-sekin rivojlanmoq","ipa":"ɪˈvɒlv"}],"summary":["O'zgarishni sifat + ot (a sharp rise) yoki fe'l + ravish (rose sharply) bilan yozing: sifat otni, ravish fe'lni tasvirlaydi.","boom va slump — keskin o'zgarish, upturn va downturn — yaxshilanish va pasayish davri, stagnate — o'smay turib qolish.","rise (rose, risen) to'ldiruvchisiz; raise (raised) to'ldiruvchi bilan. by — miqdor, to — daraja, from … to ….","overtake + to'g'ridan-to'g'ri to'ldiruvchi (predlogsiz); transform … into; evolve majhul nisbatda ishlatilmaydi.","Tendensiyani tasvirlashda: Overall, … ; from … to … ; by …; between … and …."]},{"id":"u24-l6","slug":"time-linkers-and-sequencing","title":"Time linkers and sequencing","titleUz":"Vaqt bog'lovchilari va ketma-ketlik: while, as soon as, by the time, eventually, meanwhile","goal":"Voqealar ketma-ketligini nutqda va yozuvda aniq ifodalaysiz: first of all, afterwards, in the meantime, eventually, from then on, ever since. while / whereas, as soon as / once / the moment / until / by the time bog'lovchilarini to'g'ri tanlaysiz, vaqt gaplarida will dan qochasiz va tinish belgilarini to'g'ri qo'yasiz. Hikoya, e-mail, hisobot va IELTS Speaking uchun kerak.","words":[{"en":"at the outset","uz":"boshida, dastlab","ipa":"ət ði ˈaʊt.set"},{"en":"first and foremost","uz":"avvalo, birinchi navbatda","ipa":"ˌfɜːst ənd ˈfɔː.məʊst"},{"en":"beforehand","uz":"oldindan","ipa":"bɪˈfɔː.hænd"},{"en":"prior to","uz":"…dan oldin (rasmiy)","ipa":"ˈpraɪ.ə tuː"},{"en":"simultaneously","uz":"bir vaqtda","ipa":"ˌsɪm.əlˈteɪ.ni.əs.li"},{"en":"thereafter","uz":"undan keyin (rasmiy)","ipa":"ðeərˈɑːf.tər"},{"en":"shortly","uz":"tez orada","ipa":"ˈʃɔːt.li"},{"en":"in due course","uz":"o'z vaqtida, kerakli paytda","ipa":"ɪn ˌdjuː ˈkɔːs"},{"en":"all along","uz":"butun vaqt davomida","ipa":"ˌɔːl əˈlɒŋ"},{"en":"up until now","uz":"hozirgacha","ipa":"ˌʌp ənˈtɪl naʊ"}],"summary":["Ketma-ketlik iboralari: first and foremost / at the outset → afterwards / thereafter → meanwhile / simultaneously → eventually → ever since / up until now.","when, as soon as, once, the moment, until, by the time dan keyin kelajakda ham Present keladi, will emas.","while + gap, during + ot; whereas faqat qarama-qarshilik; prior to + -ing/ot (rasmiy before).","Rasmiy: shortly, thereafter, in due course, at the outset, prior to; norasmiy: soon, after that, later, at the start, before.","Gap boshidagi bog'lovchi gapdan keyin vergul: When I arrive, I'll call. at the end of (ot) va in the end (oxir-oqibat) ni adashtirmang."]},{"id":"u24-l14","slug":"listening-and-speaking-a-talk-about-change","title":"Listening and speaking: a talk about change","titleUz":"Tinglash va gapirish: o'zgarish haqida podkast va 2 daqiqalik nutq","goal":"O'zgarish haqidagi podkastni tinglab asosiy fikrni va tafsilotlarni topasiz, signal so'zlarga (used to, these days, as a result) e'tibor berasiz va «Mening shahrim qanday o'zgargan» mavzusida 1-2 daqiqalik nutqni reja bilan aytasiz.","words":[{"en":"decade","uz":"o'n yillik","ipa":"ˈdek.eɪd"},{"en":"commute","uz":"ishga qatnamoq","ipa":"kəˈmjuːt"},{"en":"congestion","uz":"tirbandlik","ipa":"kənˈdʒes.tʃən"},{"en":"regeneration","uz":"qayta tiklash (hududni)","ipa":"rɪˌdʒen.əˈreɪ.ʃən"},{"en":"fade away","uz":"asta-sekin yo'qolmoq","ipa":"feɪd əˈweɪ"},{"en":"podcast","uz":"podkast (audio dastur)","ipa":"ˈpɒd.kɑːst"}],"summary":["Tinglashda avval asosiy fikr (gist), keyin tafsilotlar; signal so'zlar (used to, these days, as a result, by this time next year) zamonni oldindan ko'rsatadi.","Nutq rejasi: boshlash → o'tmish → asosiy o'zgarish → hozir → kelajak → xulosa (120-150 so'z).","Xatolar: before ten years emas → ten years ago; in last years emas → in recent years.","Yangi so'zlar: decade, commute, congestion, regeneration, fade away, podcast."]},{"id":"u24-l10","slug":"rescheduling-plans","title":"Rescheduling plans","titleUz":"Rejalarni o'zgartirish: uchrashuvni ko'chirish va uzr so'rash","goal":"Uchrashuv yoki safarni muloyim o'zgartirasiz: uzr so'raysiz (I'm afraid I won't be able to…), o'zgartirishni so'raysiz (Would it be possible to…?), kechikish haqida xabar berasiz (I'll be arriving a bit later) va muqobil taklif qilasiz.","words":[{"en":"tied up","uz":"band (vaqti yo'q)","ipa":"taɪd ʌp"},{"en":"clash","uz":"to'g'ri kelib qolmoq (vaqt jihatdan)","ipa":"klæʃ"},{"en":"bring forward","uz":"oldinga surmoq (ertaroq qilmoq)","ipa":"brɪŋ ˈfɔː.wəd"},{"en":"push back","uz":"orqaga surmoq (kechroq qilmoq)","ipa":"pʊʃ bæk"},{"en":"short notice","uz":"qisqa ogohlantirish","ipa":"ʃɔːt ˈnəʊ.tɪs"},{"en":"make up for","uz":"o'rnini qoplamoq","ipa":"meɪk ʌp fɔː"}],"summary":["Muloyim rad: I'm afraid I won't be able to… (will + can emas!). So'rov: Would it be possible to + V1?","push back = kechroqqa, bring forward = ertaroqqa surmoq. Kelishilgan reja: Present Continuous; kechikish: I'll be arriving…","Tartib: uzr → sabab → muqobil → kechirim. Sorry to disturb, sorry for being late.","Yangi so'zlar: tied up, clash, bring forward, push back, short notice, make up for."]},{"id":"u24-l7","slug":"writing-a-personal-blog-post-about-change","title":"Writing: a personal blog post about change","titleUz":"Yozish: o'zgarish haqida blog yozuvi (hikoya + fikr)","goal":"O'zgarish haqida 200–250 so'zli shaxsiy blog yozuvini yozasiz: qiziqarli birinchi gap, hikoya zamonlari, used to / would, Present Perfect (hozirgi natija) va kelajak rejalari, abzaslar va oxirida o'quvchiga savol. Norasmiy, lekin nazorat qilingan uslub: qisqartmalar bor, lekin xato va jargon yo'q. Blog, ijtimoiy tarmoq va IELTS Writing uchun kerak.","words":[{"en":"reflect on","uz":"…ni o'ylab ko'rmoq, mulohaza qilmoq","ipa":"rɪˈflekt ɒn"},{"en":"candid","uz":"ochiq, samimiy","ipa":"ˈkæn.dɪd"},{"en":"relatable","uz":"tanish, o'zingga o'xshash","ipa":"rɪˈleɪ.tə.bəl"},{"en":"anecdote","uz":"kichik hikoya, voqea","ipa":"ˈæn.ɪk.dəʊt"},{"en":"comfort zone","uz":"qulaylik doirasi","ipa":"ˈkʌm.fət ˌzəʊn"},{"en":"personal growth","uz":"shaxsiy o'sish","ipa":"ˌpɜː.sən.əl ˈɡrəʊθ"},{"en":"eye-opening","uz":"ko'zni ochuvchi","ipa":"ˈaɪ ˌəʊ.pən.ɪŋ"},{"en":"rewarding","uz":"mamnuniyat keltiradigan, foydali","ipa":"rɪˈwɔː.dɪŋ"},{"en":"to this day","uz":"bugungi kunga qadar","ipa":"tə ðɪs ˈdeɪ"},{"en":"self-doubt","uz":"o'ziga ishonchsizlik","ipa":"ˌself ˈdaʊt"}],"summary":["Blog tuzilishi: sarlavha, hook, avval, burilish nuqtasi, hozir, kelajak, yakun savoli; hajmi 200–250 so'z, 4–5 abzas.","Birinchi gap qiziqarli bo'lsin: savol, kutilmagan fakt yoki qisqa sahna. In this blog I will tell about… dan qoching.","Zamonlar: used to (holat), would (odat), Past Simple/Continuous/Perfect (hikoya), Present Perfect (natija), will / going to (kelajak).","Aniq o'tgan vaqt (last year, in 2019) bilan Past Simple; since/for bilan Present Perfect.","Uslub: norasmiy, lekin nazorat ostida: qisqartmalar bor, gonna va jargon yo'q. Yakunda o'quvchiga savol."]},{"id":"u24-l15","slug":"reading-and-writing-a-magazine-article","title":"Reading and writing: a magazine article","titleUz":"O'qish va yozish: jurnal maqolasi — chet elga ko'chib borish","goal":"Jurnal maqolasini o'qib, asosiy fikr, tafsilot va olmosh (reference) savollariga javob berasiz, True / False / Not given ni farqlaysiz va maqolaga 120 so'zli izoh yozasiz: kamida uch xil zamon va shakl bilan.","words":[{"en":"expat","uz":"chet elda yashovchi (ish uchun ko'chgan) kishi","ipa":"ˈeks.pæt"},{"en":"bureaucracy","uz":"byurokratiya, rasmiy hujjatbozlik","ipa":"bjʊəˈrɒk.rə.si"},{"en":"integrate","uz":"singishib ketmoq, moslashmoq","ipa":"ˈɪn.tɪ.ɡreɪt"},{"en":"put down roots","uz":"ildiz otmoq, o'rnashib olmoq","ipa":"pʊt daʊn ruːts"},{"en":"newcomer","uz":"yangi kelgan odam","ipa":"ˈnjuːˌkʌm.ə"},{"en":"fit in","uz":"jamoaga moslashmoq, o'ziniki bo'lmoq","ipa":"fɪt ɪn"}],"summary":["O'qishda avval skimming (gist), keyin kalit so'z bo'yicha scanning (tafsilot); olmosh savolida oldingi gapga qayting.","False — matn aksini aytadi; Not given — matnda bu haqida umuman yo'q. Taxmin qilmang.","Izoh tuzilmasi: munosabat → o'tmish (Past Perfect, used to) → hozir (Present Perfect) → kelajak (will have / will be) → savol.","Xatolar: since three years emas → for three years; last year has moved emas → moved; used to live ≠ used to living.","Yangi so'zlar: expat, bureaucracy, integrate, put down roots, newcomer, fit in."]},{"id":"u24-l8","slug":"unit-review-tenses-and-time","title":"Unit review: tenses and time","titleUz":"Bosqich takrori: zamonlar va vaqt ifodalari","goal":"Bosqichni takrorlaysiz: hikoya zamonlari (Past Simple, Continuous, Perfect, Perfect Continuous), Present Perfect Simple va Continuous, used to / would / be used to, kelasi zamon shakllari, holat va harakat fe'llari, vaqt bog'lovchilari va o'zgarish lug'ati. Hammasini yangi misollarda tekshirasiz va o'z xatolaringizni topasiz.","words":[{"en":"habitual","uz":"odatiy, doimiy","ipa":"həˈbɪtʃ.u.əl"},{"en":"turn over a new leaf","uz":"yangi sahifa ochmoq, o'zgarishga qaror qilmoq","ipa":"tɜːn ˌəʊ.və ə ˌnjuː ˈliːf"},{"en":"in the long run","uz":"uzoq muddatda","ipa":"ɪn ðə ˌlɒŋ ˈrʌn"},{"en":"keep track of","uz":"kuzatib bormoq, hisobini yuritmoq","ipa":"ˌkiːp ˈtræk əv"},{"en":"stick to","uz":"amal qilmoq, rioya qilmoq","ipa":"ˈstɪk tuː"},{"en":"mindset","uz":"fikrlash tarzi","ipa":"ˈmaɪnd.set"},{"en":"set in","uz":"(yomon narsa) boshlanmoq, kirib kelmoq","ipa":"ˌset ˈɪn"},{"en":"lasting","uz":"uzoq davom etadigan","ipa":"ˈlɑː.stɪŋ"},{"en":"emerge","uz":"paydo bo'lmoq, ko'rinmoq","ipa":"ɪˈmɜːdʒ"},{"en":"outlook","uz":"qarash, istiqbol","ipa":"ˈaʊt.lʊk"}],"summary":["Hikoya zamonlari: Past Simple (voqea), Past Continuous (fon), Past Perfect (oldingi), Past Perfect Continuous (oldingi davomli ish).","Present Perfect Simple — natija, soni; Continuous — jarayon, davomiylik. Aniq o'tgan vaqt bilan Past Simple; holat fe'llari Continuous bo'lmaydi.","used to (holat va odat), would (faqat odat), be / get used to + -ing (ko'nikish).","Kelasi zamon: will, going to, Present Continuous, will be -ing, will have V3, be about to; vaqt gaplarida will yo'q.","Bog'lovchilar va lug'at: while / whereas, as soon as, by the time, prior to; o'zgarish: steady, rise / raise, stagnate, overtake."]},{"id":"u24-l11","slug":"time-habits-and-change-final-review","title":"Time, habits and change: final review","titleUz":"Vaqt, odatlar va o'zgarish: yakuniy takror","goal":"Bosqichdagi hamma mavzuni takrorlaysiz: hikoya zamonlari, Present Perfect Simple / Continuous, used to / would / be used to, kelasi zamon shakllari, holat va harakat fe'llari va vaqt bog'lovchilari. Xatolarni topasiz va 1 daqiqalik nutq aytasiz.","words":[{"en":"lifelong","uz":"umrbod, butun hayot davomidagi","ipa":"ˈlaɪf.lɒŋ"},{"en":"willpower","uz":"iroda kuchi","ipa":"ˈwɪlˌpaʊ.ə"},{"en":"ingrained","uz":"chuqur ildiz otgan, singib ketgan","ipa":"ɪnˈɡreɪnd"},{"en":"self-discipline","uz":"o'zini tutish, intizom","ipa":"ˌself ˈdɪs.ə.plɪn"},{"en":"relapse","uz":"eski odatga qaytib qolish","ipa":"ˈriː.læps"},{"en":"resolution","uz":"(yangi yil) va'dasi, qat'iy qaror","ipa":"ˌrez.əˈluː.ʃən"}],"summary":["Hikoya zamonlari: Past Simple (asosiy voqea), Continuous (fon), Perfect (oldingi voqea), Perfect Continuous (oldingi davomiy jarayon).","Present Perfect: Simple — natija va son; Continuous — davomiylik (for, since, how long). ago → Past Simple.","used to (odat va holat), would (faqat odat), be / get used to + -ing (ko'nikish).","Kelajak: will be + -ing, will have + V3; when / as soon as / by the time dan keyin Present. know, believe, want — -ing yo'q.","Yangi so'zlar: lifelong, willpower, ingrained, self-discipline, relapse, resolution."]}]},{"id":"u25","n":25,"title":"Imagination, regret and speculation","titleUz":"Tasavvur, pushaymonlik va taxmin: aralash shartlar, wish, modal perfect","description":"Aralash shart gaplar, if o'rniga ishlatiladigan so'zlar, wish va if only, would rather, o'tgan zamon taxmin modallari, his-tuyg'ular va xarakter lug'ati.","canDo":["Aralash shart gaplar bilan o'tgan qarorlarning bugungi hayotga ta'sirini tushuntiraman (If I had moved, I would be living there now)","Wish, if only va would rather bilan pushaymon va xohishlarimni to'g'ri ifodalayman","Must have, can't have, might have va should have bilan o'tgan voqea haqida taxmin va baho beraman","Qiyin qaror haqida maslahat beraman, uzr so'rayman va 'Nima qilgan bo'lardingiz?' savoliga javob yozaman"],"lessons":[{"id":"u25-l1","slug":"mixed-conditionals","title":"Mixed conditionals","titleUz":"Aralash shart gaplar: If I had studied harder, I would be a doctor now","goal":"Aralash shart gaplarni (mixed conditionals) to'g'ri tuzasiz: o'tgan sabab → hozirgi natija (If I had studied harder, I would be a doctor now) va hozirgi holat → o'tgan natija (If I weren't so shy, I would have asked her). Suhbat, intervyu va IELTS speaking'da hayotingiz haqida pishiq gapirasiz va If I would have known kabi xatodan qochasiz.","words":[{"en":"hindsight","uz":"keyin anglash, o'tgan voqeaga hozirgi nazar","ipa":"ˈhaɪnd.saɪt"},{"en":"gamble","uz":"tavakkal, xavfli qaror","ipa":"ˈɡæm.bəl"},{"en":"seize","uz":"(imkoniyatdan) darhol foydalanmoq","ipa":"siːz"},{"en":"pass up","uz":"(imkoniyatni) qo'ldan chiqarmoq, rad etmoq","ipa":"pɑːs ʌp"},{"en":"take the plunge","uz":"jur'at etib qaror qilmoq","ipa":"teɪk ðə plʌndʒ"},{"en":"career path","uz":"kasbiy yo'l","ipa":"kəˈrɪə pɑːθ"},{"en":"impulsive","uz":"o'ylamay, bir lahzada qaror qiladigan","ipa":"ɪmˈpʌl.sɪv"},{"en":"foresee","uz":"oldindan ko'rmoq, bashorat qilmoq","ipa":"fɔːˈsiː"},{"en":"setback","uz":"to'siq, muvaffaqiyatsizlik, orqaga tortuvchi hodisa","ipa":"ˈset.bæk"},{"en":"stroke of luck","uz":"kutilmagan omad","ipa":"strəʊk əv lʌk"}],"summary":["Aralash shart gap: if-qism va asosiy qism turli vaqtga tegishli. Mixed A: If + Past Perfect, … would + V1 (o'tgan sabab → hozirgi natija).","Mixed B: If + Past Simple (were), … would have + V3 (hozirgi holat yoki xarakter → o'tgan natija): If I weren't so shy, I would have asked her.","Natijaning vaqtini now / yesterday / last year so'zlari va asosiy qismning shakli aniqlaydi. would o'rniga could, might ham mumkin.","Nutqda 'd ikki xil: if-qismda had, asosiy qismda would. Rasmiy: Had I known, …","Xato: ~~If I would have known~~ → If I had known; ~~If I didn't miss the train~~ → If I hadn't missed the train."]},{"id":"u25-l12","slug":"alternatives-to-if","title":"Alternatives to if","titleUz":"If o'rniga: unless, as long as, otherwise, but for, supposing, provided that","goal":"If o'rniga unless, as long as, provided that, on condition that, otherwise, but for, supposing va in case ni to'g'ri tanlaysiz, rasmiy va norasmiy uslubni farqlaysiz va unless you don't kabi xatolardan qochasiz.","words":[{"en":"on condition that","uz":"... sharti bilan (rasmiy)","ipa":"ɒn kənˈdɪʃn ðæt"},{"en":"but for","uz":"... bo'lmaganda","ipa":"bʌt fɔː"},{"en":"in the event of","uz":"... yuz bergan taqdirda","ipa":"ɪn ði ɪˈvent əv"},{"en":"precaution","uz":"ehtiyot chorasi","ipa":"prɪˈkɔːʃn"},{"en":"contingency","uz":"kutilmagan holatga zaxira reja","ipa":"kənˈtɪndʒənsi"},{"en":"proviso","uz":"shart, kelishuvdagi qayd","ipa":"prəˈvaɪzəʊ"}],"summary":["Unless = if ... not; unless'dan keyin inkor kerak emas: unless you hurry.","As long as, provided (that), on condition that = faqat shu shart bilan. Keyin will yo'q: hozirgi zamon.","Otherwise / or else = aks holda; but for + ot = ... bo'lmaganda (ko'pincha would have + V3).","In case = ehtiyot chorasi (shart emas): Take an umbrella in case it rains.","Yangi iboralar: on condition that, but for, in the event of, precaution, contingency, proviso."]},{"id":"u25-l2","slug":"wish-if-only-and-regrets","title":"Wish, if only and regrets","titleUz":"Wish va if only: hozirgi, o'tgan va kelasi zamon pushaymonligi","goal":"I wish va If only bilan hozirgi holatdan norozilik (I wish I lived by the sea), o'tgan zamon pushaymonligi (I wish I had studied harder) va birovning xatti-harakatidan noroziligingizni (I wish you would stop) aytasiz. I wish I have va I wish you will kabi xatolardan qochasiz.","words":[{"en":"remorse","uz":"vijdon azobi, chuqur pushaymonlik","ipa":"rɪˈmɔːs"},{"en":"wistful","uz":"sog'inch bilan o'ylaydigan, mahzun","ipa":"ˈwɪst.fəl"},{"en":"yearn","uz":"intiqlik bilan orzu qilmoq","ipa":"jɜːn"},{"en":"dwell on","uz":"(bir narsani) tinmay o'ylayvermoq","ipa":"dwel ɒn"},{"en":"come to terms with","uz":"(og'ir voqeani) qabul qilmoq, ko'nikmoq","ipa":"kʌm tə tɜːmz wɪð"},{"en":"second thoughts","uz":"ikkilanish, qarorga shubha","ipa":"ˈsek.ənd θɔːts"},{"en":"irreversible","uz":"qaytarib bo'lmaydigan","ipa":"ˌɪr.ɪˈvɜː.sə.bəl"},{"en":"make amends","uz":"xatoni to'g'rilamoq, kechirim olish uchun harakat qilmoq","ipa":"meɪk əˈmendz"},{"en":"pang","uz":"o'tkir og'riq, ichki sanchiq (his-tuyg'u)","ipa":"pæŋ"},{"en":"missed opportunity","uz":"qo'ldan boy berilgan imkoniyat","ipa":"mɪst ˌɒp.əˈtʃuː.nə.ti"}],"summary":["Wish + Past Simple — hozirgi holatdan norozilik: I wish I had more time. Be uchun were: I wish I were taller.","Wish + Past Perfect — o'tgan pushaymonlik: I wish I had studied harder. If only — xuddi shu, lekin kuchliroq: If only I hadn't said that!","Wish + would — boshqa odam yoki vaziyatdan norozilik: I wish you would stop. O'zimiz haqimizda would ishlatilmaydi: I wish I could…","Wish — haqiqatga teskari narsa, hope — mumkin bo'lgan narsa: I hope you pass.","Xatolar: ~~I wish I have~~ → I wish I had; ~~I wish you will~~ → I wish you would; ~~If only I didn't say~~ → If only I hadn't said."]},{"id":"u25-l3","slug":"would-rather-its-time-and-as-if","title":"Would rather, it's time and as if","titleUz":"Would rather, had better, it's time, as if / as though","goal":"Would rather, had better, it's (high) time va as if / as though qoliplarini ishlatasiz: o'z va birovning tanlovi haqida (I'd rather you came tomorrow), kuchli maslahat va ogohlantirish (You'd better hurry), «vaqt bo'ldi» (It's time we left) va haqiqatga o'xshamaydigan taqqoslash (He talks as if he knew everything) aytasiz. I'd rather to stay va It's time we go kabi xatolardan qochasiz.","words":[{"en":"preferably","uz":"iloji bo'lsa, afzal tarzda","ipa":"ˈpref.ər.ə.bli"},{"en":"procrastinate","uz":"ishni keyinga surib yurmoq","ipa":"prəʊˈkræs.tɪ.neɪt"},{"en":"overdue","uz":"muddati o'tgan, kechikkan","ipa":"ˌəʊ.vəˈdjuː"},{"en":"get a move on","uz":"tezroq harakat qilmoq","ipa":"ɡet ə muːv ɒn"},{"en":"childish","uz":"bolalarcha (salbiy ma'noda)","ipa":"ˈtʃaɪl.dɪʃ"},{"en":"immature","uz":"pishmagan, yetilmagan","ipa":"ˌɪm.əˈtʃʊər"},{"en":"grown-up","uz":"katta odam, voyaga yetgan","ipa":"ˈɡrəʊn.ʌp"},{"en":"behave","uz":"o'zini tutmoq, xulq-atvor qilmoq","ipa":"bɪˈheɪv"},{"en":"snap out of it","uz":"(yomon kayfiyatdan) o'ziga kelmoq","ipa":"snæp aʊt əv ɪt"},{"en":"stay put","uz":"joyida qolmoq, qimirlamaslik","ipa":"steɪ pʊt"}],"summary":["Would rather + V1 — o'z tanlovim (I'd rather stay); boshqa odamdan istak: would rather + ega + Past Simple (I'd rather you called tomorrow), o'tgan uchun Past Perfect.","Had better + V1 — kuchli maslahat va ogohlantirish (You'd better hurry); inkori had better not; to kerak emas.","It's (high) time + ega + Past Simple — vaqt bo'ldi, kechikdi (It's time we left); umumiy: It's time to + V1.","As if / as though: haqiqatga mos emas bo'lsa Past Simple (were) yoki Past Perfect, mos yoki mumkin bo'lsa Present.","Xatolar: ~~I'd rather to stay~~ → I'd rather stay; ~~It's time we go~~ → It's time we went; ~~You had better to go~~ → You'd better go."]},{"id":"u25-l4","slug":"modals-of-deduction-in-the-past","title":"Modals of deduction in the past","titleUz":"Taxmin modallari: must have, can't have, might have, could have","goal":"O'tgan voqea haqida qanchalik ishonchingizga qarab taxmin qilasiz: must have + V3 (deyarli aniq), can't / couldn't have + V3 (deyarli mumkin emas), might / may / could have + V3 (ehtimol). Continuous shakllarini (must have been working) ishlatasiz, hozirgi taxmin (must be) bilan farqlaysiz va mustn't have kabi xatolardan qochasiz.","words":[{"en":"culprit","uz":"aybdor, aybdor shaxs yoki sabab","ipa":"ˈkʌl.prɪt"},{"en":"baffled","uz":"boshi qotgan, hayron","ipa":"ˈbæf.əld"},{"en":"jump to conclusions","uz":"shoshilib xulosa chiqarmoq","ipa":"dʒʌmp tə kənˈkluː.ʒənz"},{"en":"alibi","uz":"alibi (voqea joyida bo'lmaganlik isboti)","ipa":"ˈæl.ɪ.baɪ"},{"en":"puzzling","uz":"boshni qotiradigan, tushunib bo'lmas","ipa":"ˈpʌz.lɪŋ"},{"en":"tamper with","uz":"ruxsatsiz aralashmoq, buzmoq","ipa":"ˈtæm.pə wɪð"},{"en":"misleading","uz":"chalg'ituvchi, adashtiradigan","ipa":"ˌmɪsˈliː.dɪŋ"},{"en":"hunch","uz":"ichki sezgi, taxmin","ipa":"hʌntʃ"},{"en":"deduce","uz":"xulosa chiqarmoq (dalillardan)","ipa":"dɪˈdjuːs"},{"en":"go missing","uz":"yo'qolmoq, bedarak ketmoq","ipa":"ɡəʊ ˈmɪs.ɪŋ"}],"summary":["Must have + V3 — o'tgan voqea haqida deyarli aniq «ha» xulosasi (It must have rained); can't / couldn't have + V3 — deyarli aniq «yo'q» (He can't have known).","Might / may / could have + V3 — ehtimol; might not / may not have + V3 — «balki bo'lmagan» (can't have emas, u kuchliroq).","Jarayon uchun modal + have been + V-ing (must have been sleeping); hozirgi taxmin modal + V1 (must be tired).","Inkor taxmin uchun standart shakl can't / couldn't have; mustn't have standart Britaniya ingliz tilida ishlatilmaydi.","Xatolar: ~~mustn't have known~~ → can't have known; ~~must have wait~~ → must have waited; ~~might have take~~ → might have taken."]},{"id":"u25-l13","slug":"criticism-and-regret-should-have-neednt-have","title":"Criticism and regret: should have, needn't have","titleUz":"Tanqid va afsus: should have, shouldn't have, needn't have, didn't need to","goal":"O'tgan zamondagi xato, tanqid va afsusni ifodalaysiz (should have, ought to have, shouldn't have, could have), needn't have va didn't need to farqini bilasiz va tanqidni muloyim yoki qattiq ohangda ayta olasiz.","words":[{"en":"foresight","uz":"ilgarilab ko'ra bilish, uzoqni ko'zlash","ipa":"ˈfɔːsaɪt"},{"en":"in retrospect","uz":"orqaga qarab, keyin o'ylab","ipa":"ɪn ˈretrəspekt"},{"en":"regrettable","uz":"afsusli, afsuslanarli","ipa":"rɪˈɡretəbəl"},{"en":"needlessly","uz":"keraksiz, behuda","ipa":"ˈniːdləsli"},{"en":"learn the hard way","uz":"achchiq tajriba orqali o'rganmoq","ipa":"lɜːn ðə hɑːd weɪ"}],"summary":["Should have / ought to have + V3 — qilinmagan ish (afsus, tanqid); shouldn't have + V3 — qilingan, lekin noto'g'ri ish.","Could have + V3 — imkoniyat bor edi, ishlatilmadi. Must have esa tanqid emas, taxmin.","Needn't have + V3 — qildim, behuda ekan; didn't need to + fe'l — kerak emas edi (odatda qilinmagan).","Boshqaga qattiq tanqid qilmang: It might have been better to… / I wish you'd… muloyimroq. O'z xatongiz uchun should have tabiiy.","Yangi so'zlar: foresight, in retrospect, regrettable, needlessly, learn the hard way."]},{"id":"u25-l9","slug":"giving-advice-on-a-difficult-decision","title":"Giving advice on a difficult decision","titleUz":"Qiyin qaror haqida maslahat berish","goal":"Do'stingiz qiyin qaror oldida turganda (masalan, chet eldagi ish taklifi) muloyim va qo'llab-quvvatlovchi maslahat berasiz: If I were you, I'd…, Have you thought about…?, You might want to…, va shart gaplar bilan oqibatlarni tasavvur qildirasiz.","words":[{"en":"sleep on it","uz":"bir kecha o'ylab ko'rmoq (qarorni keyinga qoldirib)","ipa":"sliːp ɒn ɪt"},{"en":"think it over","uz":"puxta o'ylab ko'rmoq","ipa":"θɪŋk ɪt ˈəʊvə"},{"en":"leap of faith","uz":"ishonib qilingan tavakkal","ipa":"liːp əv feɪθ"},{"en":"risky","uz":"xavfli, tavakkal talab qiladigan","ipa":"ˈrɪski"},{"en":"stability","uz":"barqarorlik","ipa":"stəˈbɪləti"},{"en":"rush into","uz":"shoshilib qaror qilmoq","ipa":"rʌʃ ˈɪntuː"}],"summary":["Yumshoq maslahat: If I were you, I'd…, Have you thought about + -ing?, You might want to…, I'd think twice before…","If I were you da would yo'q: If I would be you xato. Modaldan keyin to yo'q, advise dan keyin to bor.","Oqibatlarni tasavvur qildiring: If you stayed, you'd have… (second), If you hadn't…, you wouldn't have… (aralash).","Avval his-tuyg'uni tan oling, keyin variantlarni ayting, qarorni do'stingizga qoldiring: In the end, it's your decision.","Yangi so'zlar: sleep on it, think it over, leap of faith, risky, stability, rush into."]},{"id":"u25-l5","slug":"feelings-personality-and-character","title":"Feelings, personality and character","titleUz":"Hissiyotlar, shaxs va xarakter: so'zlar va birikmalar","goal":"Hissiyotlar va xarakterni aniq va nozik tasvirlaysiz: resentful, easy-going, down-to-earth, self-conscious, tolerant, insecure, gullible, wary, open-minded, disillusioned so'zlarini to'g'ri predlog bilan (wary of, tolerant of, disillusioned with) ishlatasiz, -ed / -ing sifatlarini (bored / boring) adashtirmaysiz va intervyu yoki IELTS Speaking'da odam haqida boy gapirasiz.","words":[{"en":"resentful","uz":"xafa, alamli (ichida saqlagan)","ipa":"rɪˈzent.fəl"},{"en":"easy-going","uz":"xotirjam, sodda munosabatli","ipa":"ˌiː.ziˈɡəʊ.ɪŋ"},{"en":"down-to-earth","uz":"oddiy, real fikrlaydigan","ipa":"ˌdaʊn tu ˈɜːθ"},{"en":"self-conscious","uz":"o'zini noqulay his qilgan, uyalgan","ipa":"ˌself ˈkɒn.ʃəs"},{"en":"tolerant","uz":"bag'rikeng, sabr-toqatli","ipa":"ˈtɒl.ər.ənt"},{"en":"insecure","uz":"ishonchsiz, o'ziga ishonmaydigan","ipa":"ˌɪn.sɪˈkjʊər"},{"en":"gullible","uz":"tez ishonuvchan, aldanuvchan","ipa":"ˈɡʌl.ə.bəl"},{"en":"wary","uz":"ehtiyotkor, shubhalanuvchi","ipa":"ˈweə.ri"},{"en":"open-minded","uz":"yangi g'oyalarga ochiq","ipa":"ˌəʊ.pənˈmaɪn.dɪd"},{"en":"disillusioned","uz":"umidi puchga chiqqan, ko'ngli qolgan","ipa":"ˌdɪs.ɪˈluː.ʒənd"}],"summary":["Xarakter: easy-going, down-to-earth, tolerant, open-minded (ijobiy), gullible (salbiy).","His: resentful (alam), self-conscious (noqulaylik), insecure (ishonchsizlik), wary (ehtiyotkorlik), disillusioned (ko'ngli qolish).","Predloglar: tolerant of, wary of, jealous of, proud of; resentful of/about; self-conscious / insecure about; disillusioned with.","-ed — his (kim?): bored, exhausted; -ing — sabab (nima?): boring, exhausting.","Xatolar: ~~jealous from~~ → jealous of; ~~wary from~~ → wary of; ~~The film was bored~~ → The film was boring."]},{"id":"u25-l6","slug":"speculating-and-hedging","title":"Speculating and hedging","titleUz":"Taxmin qilish va ehtiyotkor gapirish: perhaps, presumably, it seems that, tend to","goal":"Fikringizni ehtiyotkor va ishonchli bildirasiz: presumably, apparently, seemingly, supposedly kabi ravishlar, it seems that, tend to, is likely to, there's a chance kabi qoliplar va to some extent, by and large kabi yumshatuvchi iboralar. IELTS Speaking Part 3 va ish suhbatida mutlaq gaplar (All people…, Everyone…) o'rniga aniq, adolatli javob berasiz va tend to being, It is seemed that kabi xatolardan qochasiz.","words":[{"en":"seemingly","uz":"ko'rinishidan, go'yo","ipa":"ˈsiː.mɪŋ.li"},{"en":"supposedly","uz":"ular aytishicha (ishonmay)","ipa":"səˈpəʊ.zɪd.li"},{"en":"undoubtedly","uz":"shubhasiz","ipa":"ʌnˈdaʊ.tɪd.li"},{"en":"conceivably","uz":"aqlga sig'adigan darajada, ehtimol","ipa":"kənˈsiː.və.bli"},{"en":"tentative","uz":"dastlabki, aniq bo'lmagan","ipa":"ˈten.tə.tɪv"},{"en":"by and large","uz":"umuman olganda","ipa":"baɪ ənd lɑːdʒ"},{"en":"in all probability","uz":"katta ehtimol bilan","ipa":"ɪn ɔːl ˌprɒb.əˈbɪl.ə.ti"},{"en":"more often than not","uz":"ko'pincha","ipa":"mɔːr ˈɒf.ən ðən nɒt"},{"en":"up to a point","uz":"ma'lum darajaga qadar","ipa":"ʌp tə ə pɔɪnt"},{"en":"as far as I can tell","uz":"men tushunganimcha","ipa":"æz fɑːr æz aɪ kæn tel"}],"summary":["Hedging — mutlaq gaplar o'rniga ehtiyotkor, adolatli til: tend to, it seems that, is likely to, to some extent.","Ravishlar: undoubtedly (shubhasiz), presumably (mantiqiy taxmin), apparently (eshitishimcha), seemingly (ko'rinishidan), supposedly (aytishicha, ishonmay).","Qoliplar: It seems / appears that + gap; seem to + V1; tend to + V1; is likely to + V1; There's a chance that…","Yumshatuvchilar: to some extent, up to a point, by and large, more often than not, in all probability, as far as I can tell.","Xatolar: ~~tends arriving~~ → tends to arrive; ~~It is seemed~~ → It seems; ~~likely to rises~~ → likely to rise."]},{"id":"u25-l14","slug":"listening-and-speaking-what-would-you-do","title":"Listening and speaking: what would you do?","titleUz":"Tinglash va gapirish: 'Nima qilgan bo'lardingiz?' suhbati","goal":"Ikki do'stning dilemma haqidagi suhbatini tinglab, fikr va sababni ushlaysiz; IELTS Speaking 3 uslubidagi What would you do if…? va What would you have done…? savollariga 1-2 daqiqada tuzilgan javob berasiz.","words":[{"en":"tempting","uz":"vasvasa soladigan, jozibali","ipa":"ˈtemptɪŋ"},{"en":"commitment","uz":"majburiyat, sadoqat","ipa":"kəˈmɪtmənt"},{"en":"trade-off","uz":"yutuq va yo'qotish almashinuvi","ipa":"ˈtreɪd ɒf"},{"en":"indecisive","uz":"qaror qilolmaydigan, ikkilanuvchan","ipa":"ˌɪndɪˈsaɪsɪv"},{"en":"fresh start","uz":"yangi boshlanish","ipa":"freʃ stɑːt"},{"en":"put yourself in someone's shoes","uz":"o'zini birovning o'rniga qo'ymoq","ipa":"pʊt jɔːˈself ɪn ˈsʌmwʌnz ʃuːz"}],"summary":["Tinglashda muammo, maslahat va sababni toping; 'd ni fe'l shakliga qarab ajrating: 'd + V1 = would, 'd + V3 = had.","Taxminiy javob iboralari: That's a tough one, I'd probably…, It depends on…, If it were me, I'd…, If I'd been in his place, I'd have…","Javob rejasi: pozitsiya → sabab → muqobil → shaxsiy misol, 1-2 daqiqa.","Tez nutqda would have /woodəv/ zaif aytiladi; ritm uchun kuchli so'zlarni ajrating.","Yangi so'zlar: tempting, commitment, trade-off, indecisive, fresh start, put yourself in someone's shoes."]},{"id":"u25-l10","slug":"apologising-and-making-up-for-a-mistake","title":"Apologising and making up for a mistake","titleUz":"Uzr so'rash va xatoni to'g'rilash: rasmiy va norasmiy","goal":"Ishda yoki do'stingiz bilan xato qilganingizda to'g'ri darajada uzr so'raysiz (rasmiy va norasmiy), qisqa izoh berasiz, xatoni tuzatishni taklif qilasiz (I'll put it right) va boshqalarning uzrini muloyim qabul qilasiz.","words":[{"en":"oversight","uz":"e'tiborsizlik, ko'zdan qochirish","ipa":"ˈəʊvəsaɪt"},{"en":"slip-up","uz":"kichik xato, yanglishish","ipa":"ˈslɪp ʌp"},{"en":"make up for","uz":"o'rnini to'ldirmoq, kompensatsiya qilmoq","ipa":"meɪk ʌp fɔː"},{"en":"put right","uz":"tuzatmoq","ipa":"pʊt raɪt"},{"en":"take responsibility","uz":"mas'uliyatni o'z zimmasiga olmoq","ipa":"teɪk rɪˌspɒnsəˈbɪləti"},{"en":"apologetic","uz":"uzr so'rayotgandek, uzrxoh","ipa":"əˌpɒləˈdʒetɪk"}],"summary":["Uzr darajasi vaziyatga mos bo'lsin: Sorry (do'st) → I'm really sorry → I apologise for… → I deeply regret… (rasmiy).","Apologise for + ot / -ing, apologise to + kishi: I apologise you xato.","Yaxshi uzr: uzr + qisqa izoh + tuzatish (put right, make up for) + va'da (It won't happen again).","O'tgan xato uchun: should have + V3: I should have told you, should tell emas.","Yangi so'zlar: oversight, slip-up, make up for, put right, take responsibility, apologetic."]},{"id":"u25-l7","slug":"writing-the-day-that-changed-my-life","title":"Writing: the day that changed my life","titleUz":"Yozish: 'Hayotimni o'zgartirgan kun' — tasviriy hikoya","goal":"Tasviriy hikoya (reflective story) yozasiz, taxminan 250 so'z: kuchli boshlanish, o'tgan zamonlar, burilish nuqtasi va oxirida fikr yuritish. Hikoyada aralash shart gaplar (If I hadn't…, I wouldn't be…), wish va his-tuyg'u so'zlaridan foydalanasiz. IELTS Writing, universitet insholari va shaxsiy xatlar uchun foydali.","words":[{"en":"pivotal","uz":"hal qiluvchi, burilish yasovchi","ipa":"ˈpɪv.ə.təl"},{"en":"in the nick of time","uz":"oxirgi daqiqada, zo'rg'a ulgurib","ipa":"ɪn ðə nɪk əv taɪm"},{"en":"against all odds","uz":"hamma ehtimolga qarshi","ipa":"əˈɡenst ɔːl ɒdz"},{"en":"sink in","uz":"ongga yetib bormoq, anglab yetmoq","ipa":"sɪŋk ɪn"},{"en":"twist of fate","uz":"taqdir o'yini, kutilmagan taqdir burilishi","ipa":"ˌtwɪst əv ˈfeɪt"},{"en":"gratitude","uz":"minnatdorchilik","ipa":"ˈɡræt.ɪ.tjuːd"},{"en":"cherish","uz":"qadrlab saqlamoq, aziz tutmoq","ipa":"ˈtʃer.ɪʃ"},{"en":"resilient","uz":"chidamli, tez tiklanadigan","ipa":"rɪˈzɪl.i.ənt"},{"en":"lingering","uz":"uzoq saqlanib qoluvchi, ketmaydigan","ipa":"ˈlɪŋ.ɡər.ɪŋ"},{"en":"fortunate","uz":"omadli, baxtli","ipa":"ˈfɔː.tʃən.ət"}],"summary":["Tasviriy hikoya: boshlanish (hook), vaziyat, burilish nuqtasi, oqibat, fikr yuritish; taxminan 250 so'z, 4–5 abzats.","Zamonlar: Past Simple — voqealar, Past Continuous — fon, Past Perfect — oldingi ish, used to / would — odat.","Reflection: If I hadn't…, I wouldn't be… (aralash shart) va I wish I had… (pushaymon).","So'zlar: pivotal, in the nick of time, against all odds, sink in, twist of fate, gratitude, cherish, resilient, lingering, fortunate.","Xatolar: If I would have emas If I had; I wish I didn't go emas I wish I hadn't gone; my life will change emas would change."]},{"id":"u25-l15","slug":"reading-and-writing-an-opinion-column","title":"Reading and writing: an opinion column","titleUz":"O'qish va yozish: gazeta ustuni — 'Agar qaytadan boshlasam…'","goal":"Pushaymonlik haqidagi gazeta ustunini o'qib, uning asosiy g'oyasi, tafsilotlari va muallifning munosabatini topasiz, keyin ustunga 120 so'zlik izoh yozasiz: qisman rozilik, shaxsiy misol va yumshatilgan fikr bilan.","words":[{"en":"columnist","uz":"ustun muallifi, kolumnist","ipa":"ˈkɒl.əm.nɪst"},{"en":"reminisce","uz":"xotiralarga berilmoq, o'tmishni eslamoq","ipa":"ˌrem.ɪˈnɪs"},{"en":"rose-tinted","uz":"go'zallashtirilgan, optimistik","ipa":"ˌrəʊz ˈtɪn.tɪd"},{"en":"closure","uz":"(og'riqli voqeadan keyingi) xotirjamlik, yakun","ipa":"ˈkləʊ.ʒər"},{"en":"make peace with","uz":"yarashmoq, qabul qilmoq","ipa":"meɪk piːs wɪð"},{"en":"what-if","uz":"'agar shunday bo'lganida' degan xayol","ipa":"ˈwɒt.ɪf"}],"summary":["Ustun — muallifning shaxsiy fikri; savollar: gist (asosiy g'oya), detail (tafsilot), attitude (munosabat).","Munosabat savolida so'zni emas, ma'noni qidiring; baholovchi so'zlarga e'tibor bering.","Ustun tili: aralash va uchinchi shart, would have + V3, Perhaps / Presumably / To some extent bilan yumshatish.","Yangi so'zlar: columnist, reminisce, rose-tinted, closure, make peace with, what-if.","120 so'zlik izoh: fikr, shaxsiy misol, qarama-qarshi fikr, xulosa."]},{"id":"u25-l8","slug":"unit-review-conditionals-wishes-and-speculation","title":"Unit review: conditionals, wishes and speculation","titleUz":"Bosqich takrori: shart gaplar, wish va taxmin","goal":"Bosqichni takrorlaysiz: aralash shart gaplar, if o'rniga ishlatiladigan so'zlar, wish / if only, would rather, had better, it's time, as if, must / can't / might have + V3, should have / needn't have, shuningdek his-tuyg'u va taxmin lug'atini yangi misollarda tekshirasiz.","words":[{"en":"hypothetical","uz":"faraziy, taxminiy","ipa":"ˌhaɪ.pəˈθet.ɪ.kəl"},{"en":"reconsider","uz":"qayta ko'rib chiqmoq, qayta o'ylamoq","ipa":"ˌriː.kənˈsɪd.ər"},{"en":"decisive","uz":"qat'iy, hal qiluvchi","ipa":"dɪˈsaɪ.sɪv"},{"en":"regardless of","uz":"…ga qaramay, …dan qat'i nazar","ipa":"rɪˈɡɑːd.ləs əv"},{"en":"conceivable","uz":"tasavvur qilsa bo'ladigan, mumkin","ipa":"kənˈsiː.və.bəl"},{"en":"wishful thinking","uz":"xomxayol, orzuni haqiqat deb o'ylash","ipa":"ˌwɪʃ.fəl ˈθɪŋ.kɪŋ"},{"en":"blessing in disguise","uz":"niqoblangan baxt","ipa":"ˌbles.ɪŋ ɪn dɪsˈɡaɪz"},{"en":"cut your losses","uz":"ko'proq yo'qotmaslik uchun to'xtamoq","ipa":"kʌt jɔː ˈlɒs.ɪz"},{"en":"no-brainer","uz":"o'ylab o'tirmasdan hal qilinadigan oson qaror","ipa":"ˌnəʊˈbreɪ.nər"},{"en":"in two minds","uz":"ikkilanib turgan","ipa":"ɪn tuː maɪndz"}],"summary":["Aralash shart: If I had… (sabab o'tgan), I would be… (natija hozir) va If I were…, I would have…; If dan keyin would yo'q.","If o'rniga: unless (= if … not), as long as / provided that, otherwise, but for, supposing, in case (ehtiyot chorasi).","wish / would rather / it's time / as if: Past Simple — hozirgi haqiqiy emas; Past Perfect — o'tgan haqiqiy emas.","must / might / can't have + V3 — taxmin; should have / needn't have — baho va keraksiz ish. Inkor taxmin uchun standart shakl can't have (mustn't have ishlatilmaydi).","Yumshatuvchi so'zlar (presumably, tend to, it seems that), his-tuyg'u sifatlari (-ed / -ing) va yangi ibora: wishful thinking, blessing in disguise, cut your losses."]},{"id":"u25-l11","slug":"imagination-and-regret-final-review","title":"Imagination and regret: final review","titleUz":"Tasavvur va pushaymonlik: yakuniy takror","goal":"Bosqichdagi hamma mavzuni takrorlaysiz: aralash shartlar, if o'rniga ishlatiladigan so'zlar, wish / would rather / it's time, o'tgan zamon modallari, maslahat berish, uzr so'rash va ehtiyotkor gapirish iboralari.","words":[{"en":"second-guess","uz":"o'z qaroridan shubhalanmoq","ipa":"ˌsek.əndˈɡes"},{"en":"take stock","uz":"vaziyatni baholab olmoq","ipa":"teɪk stɒk"},{"en":"life lesson","uz":"hayotiy saboq","ipa":"laɪf ˈles.ən"},{"en":"stand by","uz":"(qarorida) qat'iy turmoq, yoniga tushmoq","ipa":"stænd baɪ"},{"en":"come to a decision","uz":"qarorga kelmoq","ipa":"kʌm tuː ə dɪˈsɪʒ.ən"},{"en":"hard-won","uz":"qiyinchilik bilan qo'lga kiritilgan","ipa":"ˌhɑːdˈwʌn"}],"summary":["Aralash shart: sabab va natija vaqtini alohida o'ylang; If dan keyin would yo'q.","If o'rniga: unless (inkor ma'noli!), as long as / provided that, otherwise, but for, supposing, in case.","wish, if only, would rather, it's time, as if — o'tgan zamon shakli haqiqiy bo'lmagan hozirgi uchun; Past Perfect — o'tgan uchun.","must / might / can't have + V3 — taxmin; should have / needn't have — tanqid va keraksiz ish.","Maslahat: If I were you, I'd…; uzr: I should have…, It won't happen again; ehtiyotkor fikr: presumably, tend to, it seems that."]}]},{"id":"u26","n":26,"title":"Media, technology and society","titleUz":"Ommaviy axborot va texnologiya: majhul nisbat chuqur, causative, ko'chirma gap","description":"Majhul nisbat barcha zamonlarda, reporting passive, causative, ko'chirma gap B2 darajasida, ommaviy axborot va texnologiya lug'ati, fikr bildirish.","canDo":["Majhul nisbatni barcha zamonlarda va modal fe'llar bilan ishlataman (is being built, has been announced, should have been told)","Yangilik uslubida reporting passive ishlataman (It is said that…, He is believed to have…) va ko'chirma gapni to'g'ri tuzaman","Xizmat va yoqimsiz voqealarni causative bilan ayta olaman (I had my laptop repaired) va texnik muammo haqida xabar beraman","Texnologiya haqida fikr bildiraman, rozi yoki qisman rozi bo'laman va 250 so'zli fikr maqolasi yozaman"],"lessons":[{"id":"u26-l1","slug":"passive-voice-all-tenses","title":"Passive voice: all tenses","titleUz":"Majhul nisbat barcha zamonlarda: is being built, has been done, will have been completed","goal":"Majhul nisbat (passive) ni barcha zamonlarda tuzasiz: is being built, has been announced, will have been completed, should have been told. Passive'ni qachon tanlashni (diqqat nimada, ish qiluvchi noma'lum, rasmiy uslub) bilasiz va The accident was happened, The bridge is building kabi xatolardan qochasiz.","words":[{"en":"inaugurate","uz":"rasman ochmoq (marosim bilan)","ipa":"ɪˈnɔː.ɡjə.reɪt"},{"en":"relocate","uz":"boshqa joyga ko'chirmoq, ko'chmoq","ipa":"ˌriː.ləʊˈkeɪt"},{"en":"compensate","uz":"tovon to'lamoq, qoplamoq","ipa":"ˈkɒm.pen.seɪt"},{"en":"refurbish","uz":"qayta ta'mirlamoq, yangilamoq","ipa":"ˌriːˈfɜː.bɪʃ"},{"en":"dismantle","uz":"qismlarga ajratib olmoq","ipa":"dɪsˈmæn.təl"},{"en":"unveil","uz":"(yangi narsani) ommaga taqdim etmoq","ipa":"ʌnˈveɪl"},{"en":"authorise","uz":"ruxsat bermoq, vakolat bermoq","ipa":"ˈɔː.θə.raɪz"},{"en":"contractor","uz":"pudratchi","ipa":"kənˈtræk.tə"},{"en":"behind schedule","uz":"jadvaldan orqada","ipa":"bɪˈhaɪnd ˈʃed.juːl"},{"en":"under construction","uz":"qurilmoqda, qurilish ostida","ipa":"ˌʌn.də kənˈstrʌk.ʃən"}],"summary":["Passive = be + V3. Zamon be qismida: is being built, has been announced, had been deleted, will have been finished.","being — jarayon davom etyapti; been — ish tugagan yoki o'tgan. Ikkalasini ham tushirib qoldirmang.","Modal passive: must be done, can be solved, should have been told, might have been lost.","Passive: ish qiluvchi noma'lum, ahamiyatsiz yoki diqqat natijada bo'lganda, rasmiy va yangilik uslubida. by faqat yangi yoki muhim ish qiluvchi uchun.","O'timsiz fe'llar (happen, occur, arrive) passive bo'lmaydi: ~~was happened~~. Ish qiluvchi: by + odam/kuch; vosita: with."]},{"id":"u26-l12","slug":"passive-with-gerunds-and-infinitives","title":"Passive with gerunds and infinitives","titleUz":"Majhul nisbat: being asked, to be told, get + V3","goal":"Majhul nisbatni gerund (I hate being interrupted) va infinitive (She wants to be promoted) bilan ishlatasiz, so'zlashuvdagi get-passive (get fired) ni bilasiz va ikki to'ldiruvchili fe'llarda majhul gap tuzasiz (I was given a book).","words":[{"en":"promote","uz":"lavozimda ko'tarmoq; targ'ib qilmoq","ipa":"prəˈməʊt"},{"en":"dismiss","uz":"ishdan bo'shatmoq; rad etmoq","ipa":"dɪsˈmɪs"},{"en":"appoint","uz":"tayinlamoq","ipa":"əˈpɔɪnt"},{"en":"nominate","uz":"nomzod qilib ko'rsatmoq","ipa":"ˈnɒm.ɪ.neɪt"},{"en":"recruit","uz":"ishga yollamoq, jalb qilmoq","ipa":"rɪˈkruːt"}],"summary":["being + V3 — gerund majhul: I hate being interrupted, without being told.","to be + V3 — infinitiv majhul: She wants to be promoted; o'tgan voqea: to have been + V3.","get + V3 — so'zlashuv: get fired, get stolen, get married; rasmiy yozuvda be + V3.","Ikki to'ldiruvchi: I was given a book (to kerak emas), I was told to wait.","Yangi so'zlar: promote, dismiss, appoint, nominate, recruit."]},{"id":"u26-l2","slug":"reporting-passives","title":"Reporting passives","titleUz":"Reporting passive: It is said that…, He is believed to…, She is thought to have…","goal":"Yangilik va ilmiy uslubdagi reporting passive ni tuzasiz va tushunasiz: It is said that he is rich. / He is said to be rich. / She is thought to have left. Aktiv gapni reporting passive'ga aylantirasiz va is suggested to, is expected will kabi xatolardan qochasiz.","words":[{"en":"allege","uz":"(isbotsiz) da'vo qilmoq","ipa":"əˈledʒ"},{"en":"reportedly","uz":"xabarlarga ko'ra","ipa":"rɪˈpɔː.tɪd.li"},{"en":"speculate","uz":"taxmin qilmoq, o'ylab topmoq","ipa":"ˈspek.jə.leɪt"},{"en":"estimate","uz":"taxminan baholamoq","ipa":"ˈes.tɪ.meɪt"},{"en":"unconfirmed","uz":"tasdiqlanmagan","ipa":"ˌʌn.kənˈfɜːmd"},{"en":"credible","uz":"ishonarli, ishonchli","ipa":"ˈkred.ə.bəl"},{"en":"hoax","uz":"yolg'on xabar, aldov","ipa":"həʊks"},{"en":"undisclosed","uz":"oshkor qilinmagan","ipa":"ˌʌn.dɪˈskləʊzd"},{"en":"sceptical","uz":"shubha bilan qaraydigan","ipa":"ˈskep.tɪ.kəl"},{"en":"be regarded as","uz":"deb hisoblanmoq","ipa":"bi rɪˈɡɑː.dɪd æz"}],"summary":["Reporting passive ikki qolipda: It is said that + gap va Ega + is said to + fe'l. Ma'no bir xil, ikkinchisi ixchamroq.","to dan keyin: to + V (hozir/doim), to be + V-ing (hozir davom etyapti), to have + V3 (oldin bo'lgan).","Ko'p ishlatiladigan fe'llar: say, believe, think, report, know, expect, estimate, consider, claim, allege. will ishlatilmaydi: are expected to rise.","suggest (va propose) faqat It is suggested that… bilan keladi; recommend ikkala qolipda ham keladi.","Xatolar: is said that he…, to escape last night, expected will rise, is suggested to."]},{"id":"u26-l3","slug":"causative-have-get-something-done","title":"Causative: have / get something done","titleUz":"Causative: have / get something done, make / let / allow","goal":"Causative tuzilmalarni ishlatasiz: I had my hair cut. I'm getting my laptop repaired. She had her bag stolen. Shuningdek make / let / allow / force / enable qoliplarini to'g'ri tuzasiz va I cut my hair (boshqa odam kesgan bo'lsa), made me to wait kabi xatolardan qochasiz.","words":[{"en":"alter","uz":"o'zgartirmoq (kiyimni o'lchamga)","ipa":"ˈɔːl.tə"},{"en":"upgrade","uz":"yangilamoq, kuchaytirmoq","ipa":"ʌpˈɡreɪd"},{"en":"insure","uz":"sug'urtalamoq","ipa":"ɪnˈʃɔː"},{"en":"inspect","uz":"tekshirmoq, ko'zdan kechirmoq","ipa":"ɪnˈspekt"},{"en":"diagnose","uz":"nosozlikni yoki kasallikni aniqlamoq","ipa":"ˈdaɪ.əɡ.nəʊz"},{"en":"engrave","uz":"o'yib yozmoq","ipa":"ɪnˈɡreɪv"},{"en":"overhaul","uz":"to'liq ta'mirlamoq, qayta ko'rib chiqmoq","ipa":"ˌəʊ.vəˈhɔːl"},{"en":"tailor","uz":"buyurtma bo'yicha tikmoq; tikuvchi","ipa":"ˈteɪ.lə"},{"en":"reinforce","uz":"mustahkamlamoq","ipa":"ˌriː.ɪnˈfɔːs"},{"en":"customise","uz":"xohishga qarab sozlamoq, moslashtirmoq","ipa":"ˈkʌs.tə.maɪz"}],"summary":["have / get + object + V3 — ishni boshqa odam qiladi: I had my hair cut. I'm getting my laptop repaired. Object — ikki fe'l orasida.","Xuddi shu qolip yomon tajribani ham bildiradi: She had her bag stolen. Bu yerda ish qiluvchini ko'rsatmaymiz.","have someone do (to'siz), get someone to do (to bilan): I had him check it. I got him to check it.","make / let + kim + V (to'siz); allow / force / enable / require + kim + to V. Passive: was made to, was allowed to.","Xatolar: I cut my hair (boshqa kesgan bo'lsa), have repaired my phone, made me to wait, allow students use."]},{"id":"u26-l4","slug":"reported-speech-advanced","title":"Reported speech: advanced","titleUz":"Ko'chirma gap B2: zamon siljishi istisnolari, savollar va modallar","goal":"Ko'chirma gapni B2 darajasida ishlatasiz: zamon siljishi (backshift) qachon kerak va qachon kerak emasligini bilasiz, savol (She asked if…) va buyruq / iltimos (He told me to…) ni to'g'ri ko'chirasiz, vaqt va joy so'zlarini almashtirasiz hamda He said me, asked where did I live kabi xatolardan qochasiz.","words":[{"en":"state","uz":"(rasmiy) bildirmoq, bayon qilmoq","ipa":"steɪt"},{"en":"respond","uz":"javob bermoq, munosabat bildirmoq","ipa":"rɪˈspɒnd"},{"en":"observe","uz":"payqab aytmoq, kuzatmoq","ipa":"əbˈzɜːv"},{"en":"imply","uz":"ishora qilmoq, bilvosita anglatmoq","ipa":"ɪmˈplaɪ"},{"en":"reckon","uz":"o'ylamoq, hisoblamoq (norasmiy)","ipa":"ˈrek.ən"},{"en":"mutter","uz":"g'o'ldiramoq, past ovozda aytmoq","ipa":"ˈmʌt.ə"},{"en":"reaffirm","uz":"qayta tasdiqlamoq","ipa":"ˌriː.əˈfɜːm"},{"en":"specify","uz":"aniq ko'rsatmoq, belgilab bermoq","ipa":"ˈspes.ɪ.faɪ"},{"en":"go on to say","uz":"so'ngra shunday deb qo'shimcha qilmoq","ipa":"ɡəʊ ɒn tə seɪ"},{"en":"make it clear","uz":"aniq aytib qo'ymoq, ravshan qilmoq","ipa":"meɪk ɪt klɪə"}],"summary":["Backshift: Present → Past, Present Perfect / Past Simple → Past Perfect, will → would, can → could, may → might; Past Perfect va would, could, should, might o'zgarmaydi.","Istisnolar: gap hali ham to'g'ri bo'lsa, umumiy haqiqat bo'lsa yoki ko'chiruvchi fe'l hozirgi zamonda bo'lsa (She says…), zamon siljimasligi mumkin.","Vaqt va joy: now → then, today → that day, yesterday → the day before, tomorrow → the next day, here → there.","Savol: so'roq tartibi yo'q, do/did yo'q: She asked where I lived. He asked if / whether I was ready.","Buyruq: told / asked + kim + (not) to + V. Xatolar: said me, where did I live, told us don't, said she will."]},{"id":"u26-l13","slug":"reporting-verbs-and-patterns","title":"Reporting verbs and patterns","titleUz":"Reporting fe'llari: admit, deny, accuse, insist, suggest, warn + qoliplar","goal":"said o'rniga aniq reporting fe'llarini ishlatasiz (admit, deny, accuse, insist, suggest, warn, promise) va har birining qolipini bilasiz: that-gap, to-infinitive, object + to, -ing, predlog + -ing. Yangiliklarda va intervyuda gapni aniq yetkazasiz.","words":[{"en":"contend","uz":"qat'iy da'vo qilmoq, fikr bildirmoq","ipa":"kənˈtend"},{"en":"concede","uz":"tan olmoq, yon bermoq","ipa":"kənˈsiːd"},{"en":"retract","uz":"(bayonotdan) qaytmoq, qaytarib olmoq","ipa":"rɪˈtrækt"},{"en":"assert","uz":"qat'iy tasdiqlamoq","ipa":"əˈsɜːt"},{"en":"vow","uz":"qasam ichmoq, jiddiy va'da bermoq","ipa":"vaʊ"}],"summary":["Reporting fe'li o'z qolipini talab qiladi: that-gap, to-infinitive, object + to, -ing, predlog + -ing.","promise / refuse / agree / threaten + to, advise / warn / remind + kim + to, admit / deny / suggest + -ing.","accuse sb of -ing, blame sb for, apologise for, insist on — predlogdan keyin faqat -ing.","Xatolar: suggested me to, denied to take, accused me to steal.","Yangi so'zlar: contend, concede, retract, assert, vow."]},{"id":"u26-l9","slug":"reporting-a-problem-with-technology","title":"Reporting a problem with technology","titleUz":"Texnik muammo haqida xabar berish: servis markazi va online yordam","goal":"Noutbuk yoki telefon buzilganda servis markaziga qo'ng'iroq qilasiz yoki chatda yozasiz: muammoni aniq tasvirlaysiz (it keeps freezing, it won't turn on), nima qilib ko'rganingizni aytasiz va muloyim, lekin qat'iy ravishda ta'mirlash yoki pulni qaytarishni so'raysiz.","words":[{"en":"malfunction","uz":"nosozlik, ishdan chiqish","ipa":"mælˈfʌŋk.ʃən"},{"en":"overheat","uz":"haddan tashqari qizib ketmoq","ipa":"ˌəʊ.vəˈhiːt"},{"en":"troubleshoot","uz":"nosozlik sababini topib tuzatmoq","ipa":"ˈtrʌb.əl.ʃuːt"},{"en":"unresponsive","uz":"javob bermaydigan (qurilma, ekran)","ipa":"ˌʌn.rɪˈspɒn.sɪv"},{"en":"reset","uz":"boshlang'ich holatga qaytarmoq","ipa":"ˌriːˈset"},{"en":"technician","uz":"texnik mutaxassis, usta","ipa":"tekˈnɪʃ.ən"}],"summary":["Muammo: it keeps freezing (takror), it won't turn on (yoqilmayapti), it overheats, unresponsive.","Xabarda uch narsa bo'lsin: muammo, qachon boshlangan (after the update), nimalar urinib ko'rilgan (I've already restarted it).","Ta'mirlatish: have / get + narsa + V3 (get it repaired, have the battery replaced).","Muloyim, lekin qat'iy: I'm afraid that isn't acceptable. I'd like…","Xato: I bought it since two weeks → two weeks ago; has broke → broke / has broken."]},{"id":"u26-l5","slug":"media-and-technology","title":"Media and technology","titleUz":"Ommaviy axborot va texnologiya: so'zlar (headline, bias, algorithm, viral, privacy)","goal":"Ommaviy axborot va texnologiya haqidagi B2 so'zlarini (censorship, misinformation, algorithm, viral, subscription, breakthrough, addictive, surveillance…) va ularning birikmalarini (go viral, spread misinformation, raise awareness) ishlatasiz, so'z oilalarini (subscribe → subscription) bilasiz va a news, informations, addicted of kabi xatolardan qochasiz.","words":[{"en":"censorship","uz":"senzura, ma'lumotni cheklash","ipa":"ˈsen.sə.ʃɪp"},{"en":"misinformation","uz":"noto'g'ri ma'lumot","ipa":"ˌmɪs.ɪn.fəˈmeɪ.ʃən"},{"en":"algorithm","uz":"algoritm","ipa":"ˈæl.ɡə.rɪ.ðəm"},{"en":"viral","uz":"tez tarqalgan (internetda)","ipa":"ˈvaɪ.rəl"},{"en":"subscription","uz":"obuna","ipa":"səbˈskrɪp.ʃən"},{"en":"breakthrough","uz":"katta kashfiyot, yutuq","ipa":"ˈbreɪk.θruː"},{"en":"addictive","uz":"odat qilib qo'yadigan","ipa":"əˈdɪk.tɪv"},{"en":"surveillance","uz":"kuzatuv, nazorat","ipa":"səˈveɪ.ləns"},{"en":"influencer","uz":"ijtimoiy tarmoqdagi ta'sirchan shaxs, influenser","ipa":"ˈɪn.flu.ən.sə"},{"en":"clickbait","uz":"aldamchi, bosishga undovchi sarlavha","ipa":"ˈklɪk.beɪt"}],"summary":["Media so'zlari: censorship, misinformation, clickbait, influencer; texnologiya: algorithm, viral, subscription, breakthrough, addictive, surveillance.","Birikmalar: go viral, break the news, spread misinformation, raise awareness of, cancel a subscription, highly addictive, under surveillance.","So'z oilalari: censor → censorship, subscribe → subscription → subscriber, addict → addictive / addicted, influence → influencer; break through → breakthrough.","Sanalmaydigan otlar: news, information, misinformation ko'plikda ishlatilmaydi: The news is good. a lot of information.","Xatolar: addicted of (to'g'risi to), rise awareness (to'g'risi raise), a news, informations."]},{"id":"u26-l6","slug":"expressing-opinions-and-responding","title":"Expressing opinions and responding","titleUz":"Fikr bildirish va javob berish: In my view, I tend to think, to a certain extent","goal":"Muhokamada fikringizni aniq bildirasiz (In my view…, I tend to think…), ishonch darajasini tanlaysiz (undeniably / probably / I have reservations), rozi bo'lasiz, qisman rozi bo'lasiz yoki muloyim rad etasiz (I couldn't agree more, up to a point, I beg to differ) va I am agree, According to me kabi xatolardan qochasiz.","words":[{"en":"in my view","uz":"menimcha, mening nuqtai nazarimcha","ipa":"ɪn maɪ vjuː"},{"en":"I tend to think","uz":"men ko'proq shunday o'ylayman","ipa":"aɪ tend tə θɪŋk"},{"en":"to a certain extent","uz":"ma'lum darajada","ipa":"tu ə ˈsɜː.tən ɪkˈstent"},{"en":"I'm not entirely convinced","uz":"men to'liq ishonmayman","ipa":"aɪm nɒt ɪnˈtaɪə.li kənˈvɪnst"},{"en":"debatable","uz":"bahsli, munozarali","ipa":"dɪˈbeɪ.tə.bəl"},{"en":"admittedly","uz":"tan olish kerakki","ipa":"ədˈmɪt.ɪd.li"},{"en":"undeniably","uz":"inkor qilib bo'lmaydigan darajada","ipa":"ˌʌn.dɪˈnaɪ.ə.bli"},{"en":"reservations","uz":"shubhalar, e'tirozlar","ipa":"ˌrez.əˈveɪ.ʃənz"},{"en":"beg to differ","uz":"(muloyim) boshqacha fikrdaman","ipa":"beɡ tə ˈdɪf.ər"},{"en":"dubious","uz":"shubhali, ishonchsiz","ipa":"ˈdjuː.bi.əs"}],"summary":["Fikr bildirish: In my view / In my opinion, As far as I'm concerned, I tend to think, It seems to me that, I'm convinced that.","Ishonch darajasi: undeniably (juda), probably (ehtimol), to a certain extent / up to a point (qisman), I have reservations / dubious (shubha).","Rozilik: I couldn't agree more (to'liq), I agree up to a point (qisman), I see your point, but…, That's debatable, I'm afraid I beg to differ (muloyim norozilik).","Formula: tan olish + but + o'z fikringiz + sabab; Admittedly, …, but …","Xatolar: I am agree (to'g'risi I agree), agree to you (agree with), According to me (In my opinion), I am thinking that (I think)."]},{"id":"u26-l14","slug":"listening-and-speaking-a-news-discussion","title":"Listening and speaking: a news discussion","titleUz":"Tinglash va gapirish: yangiliklar muhokamasi","goal":"Radio yangiliklarini va studiyadagi muhokamani tinglab, asosiy fikr, tafsilot va ekspert fikrini ajratib olasiz; so'ng 1 daqiqada yangilikni reporting tili (according to…, it was reported that…, she said that…) bilan ovoz chiqarib qayta aytasiz.","words":[{"en":"anchor","uz":"yangiliklar boshlovchisi, studiya boshlovchisi","ipa":"ˈæŋ.kər"},{"en":"correspondent","uz":"muxbir (joyidan xabar beruvchi)","ipa":"ˌkɒr.ɪˈspɒn.dənt"},{"en":"commentator","uz":"sharhlovchi","ipa":"ˈkɒm.ən.teɪ.tər"},{"en":"viewership","uz":"tomoshabinlar soni, auditoriya","ipa":"ˈvjuː.ə.ʃɪp"},{"en":"panel","uz":"ekspertlar guruhi, muhokama paneli","ipa":"ˈpæn.əl"}],"summary":["Tinglashda avval asosiy fikr (kim, nima, qayerda), keyin tafsilot va raqamlarni ushlang.","Ekspertning fikri (to a certain extent, I'd say, ought to) ni yangilik faktlaridan ajrating.","Xulosada manba: According to…, It was reported that…, … said that…; zamon bir pog'ona orqaga: will → would.","1 daqiqalik xulosa: nima bo'ldi, nima uchun, kim nima dedi, sizning fikringiz.","Yangi so'zlar: anchor, correspondent, commentator, viewership, panel."]},{"id":"u26-l10","slug":"talking-about-privacy-and-social-media","title":"Talking about privacy and social media","titleUz":"Ijtimoiy tarmoq va maxfiylik haqida suhbatlashish: fikr bildirish va rozi bo'lmaslik","goal":"Hamkasb bilan internetda ma'lumot ulashish haqida suhbatlashasiz: fikringizni aytasiz, muloyim rozi bo'lmaysiz, sabab va misol keltirasiz va umumiy fikrlarda majhul nisbatdan foydalanasiz (data is collected, accounts are hacked).","words":[{"en":"hack","uz":"buzib kirmoq (kompyuter, akkaunt)","ipa":"hæk"},{"en":"data breach","uz":"ma'lumotlarning sizib chiqishi","ipa":"ˈdeɪ.tə briːtʃ"},{"en":"consent","uz":"rozilik","ipa":"kənˈsent"},{"en":"digital footprint","uz":"raqamli iz (internetdagi izlaringiz)","ipa":"ˌdɪdʒ.ɪ.təl ˈfʊt.prɪnt"},{"en":"encrypt","uz":"shifrlamoq","ipa":"ɪnˈkrɪpt"},{"en":"disclose","uz":"oshkor qilmoq, ma'lum qilmoq","ipa":"dɪsˈkləʊz"}],"summary":["Fikr: I'd say that…, rozilik: I couldn't agree more, muloyim rad: I see your point, but…","agree — fe'l: I agree with you. I am agree xato.","Umumiy gaplarda majhul nisbat: data is collected, accounts are hacked, passwords should be encrypted.","Fikrni sabab (because, so) va misol (for instance) bilan qo'llab-quvvatlang.","Yangi so'zlar: hack, data breach, consent, digital footprint, encrypt, disclose."]},{"id":"u26-l7","slug":"writing-an-opinion-article-about-technology","title":"Writing: an opinion article about technology","titleUz":"Yozish: texnologiya haqida fikr maqolasi (opinion article)","goal":"Maktab yoki universitet jurnali uchun 250 so'zli opinion article yozasiz: sarlavha, hook, thesis, ikkita dalil, counter-argument va xulosa. Bu bosqichning passive, reporting passive va causative qoliplarini rasmiy-neytral uslubda ishlatasiz.","words":[{"en":"ubiquitous","uz":"hamma joyda uchraydigan","ipa":"juːˈbɪk.wɪ.təs"},{"en":"scrutiny","uz":"sinchkov tekshiruv","ipa":"ˈskruː.tɪ.ni"},{"en":"safeguard","uz":"himoya qilmoq; himoya choralari","ipa":"ˈseɪf.ɡɑːd"},{"en":"strike a balance","uz":"muvozanat topmoq","ipa":"straɪk ə ˈbæl.əns"},{"en":"a double-edged sword","uz":"ikki tomonlama qurol","ipa":"ə ˌdʌb.l edʒd ˈsɔːd"},{"en":"take for granted","uz":"oddiy hol deb bilmoq","ipa":"teɪk fə ˈɡrɑːn.tɪd"},{"en":"overreliance","uz":"haddan ziyod tayanish","ipa":"ˌəʊ.və.rɪˈlaɪ.əns"},{"en":"detrimental","uz":"zararli","ipa":"ˌdet.rɪˈmen.təl"},{"en":"tangible","uz":"sezilarli, aniq, moddiy","ipa":"ˈtæn.dʒə.bəl"},{"en":"on the whole","uz":"umuman olganda","ipa":"ɒn ðə ˈhəʊl"}],"summary":["Opinion article: sarlavha, hook + thesis, ikkita dalil (fikr, misol, tushuntirish), counter-argument, xulosa. Taxminan 250 so'z.","Thesis aniq pozitsiya bildiradi: Although …, I would argue that …. In this article I will write about… — thesis emas.","Qarshi fikr: Some people argue that… / Admittedly, … Yet …; qarshi tomonni boshlash: On the other hand (in other hand emas).","Maqolada passive (data is collected), reporting passive (is widely believed to be…) va causative (had it supervised) neytral uslub beradi; o'z fikringiz uchun In my view, According to me emas.","Yangi so'zlar: ubiquitous, scrutiny, safeguard, strike a balance, a double-edged sword, take for granted, overreliance, detrimental, tangible, on the whole."]},{"id":"u26-l15","slug":"reading-and-writing-a-news-report","title":"Reading and writing: a news report","titleUz":"O'qish va yozish: yangilik hisoboti va uning xulosasi","goal":"Yangilik hisobotini o'qib, asosiy fikr va tafsilotlarni topasiz, True / False / Not given savollariga javob berasiz va 100-120 so'zli xulosani o'z so'zlaringiz bilan, reporting fe'llari va majhul nisbat bilan yozasiz.","words":[{"en":"authorities","uz":"rasmiy idoralar, hokimiyat","ipa":"ɔːˈθɒr.ɪ.tiz"},{"en":"investigate","uz":"tergov qilmoq, o'rganmoq","ipa":"ɪnˈves.tɪ.geɪt"},{"en":"outage","uz":"uzilish (elektr, tarmoq)","ipa":"ˈaʊ.tɪdʒ"},{"en":"allegedly","uz":"aytilishicha (isbotlanmagan)","ipa":"əˈledʒ.ɪd.li"},{"en":"cyberattack","uz":"kiberhujum","ipa":"ˈsaɪ.bər.ə.tæk"},{"en":"restore","uz":"tiklamoq, qayta ishga tushirmoq","ipa":"rɪˈstɔː"}],"summary":["Yangilik hisoboti: avval asosiy voqea, keyin tafsilot, oxirida fon va kelajak.","Hisobotda ko'p: has been launched, is believed to have been…, is expected to…, are reported to have been…","True / False / Not given: False — matn aksini aytadi; Not given — matnda umuman yo'q.","Xulosa (100-120 so'z): o'z so'zlaringiz bilan, reporting fe'llari bilan, shaxsiy fikrsiz.","Yangi so'zlar: authorities, investigate, outage, allegedly, cyberattack, restore."]},{"id":"u26-l8","slug":"unit-review-passive-causative-and-reporting","title":"Unit review: passive, causative and reporting","titleUz":"Bosqich takrori: majhul nisbat, causative va ko'chirma gap","goal":"Bosqichni yangi misollarda takrorlaysiz: passive (barcha zamonlar, being / to be / get), reporting passive, causative (have / get something done), ko'chirma gap (zamon siljishi, savollar, reporting fe'llari) va fikr bildirish iboralari. Natijada o'z bilimingizni tekshirib, zaif joylarni topasiz.","words":[{"en":"phishing","uz":"aldov orqali parol va ma'lumot o'g'irlash (fishing)","ipa":"ˈfɪʃ.ɪŋ"},{"en":"paywall","uz":"pullik kirish to'sig'i","ipa":"ˈpeɪ.wɔːl"},{"en":"livestream","uz":"jonli efir","ipa":"ˈlaɪv.striːm"},{"en":"whistleblower","uz":"qoidabuzarlikni fosh qiluvchi xodim","ipa":"ˈwɪs.l.bləʊ.ər"},{"en":"malware","uz":"zararli dastur","ipa":"ˈmæl.weə"},{"en":"fact-check","uz":"faktlarni tekshirmoq","ipa":"ˈfækt.tʃek"},{"en":"firewall","uz":"xavfsizlik devori (tarmoqni himoya qiluvchi dastur)","ipa":"ˈfaɪə.wɔːl"},{"en":"wearable","uz":"taqiladigan qurilma","ipa":"ˈweə.rə.bəl"},{"en":"troll","uz":"internetda tahqirlovchi, qasddan tortishuv chiqaruvchi","ipa":"trɒl"},{"en":"deepfake","uz":"sun'iy intellekt yordamida yasalgan soxta video","ipa":"ˈdiːp.feɪk"}],"summary":["Passive = be + V3 barcha zamonlarda (is being tested, has been shared, will have been updated), modal (should have been warned), being / to be / get + V3.","Reporting passive: It is said that… / is said to + V / to be V-ing / to have V3; kelajak uchun is expected to, will emas.","Causative: have / get + object + V3 (had my phone repaired, got it fixed); have + kim + V, get + kim + to V; make / let to'siz, allow / force to bilan.","Ko'chirma gap: zamon bir pog'ona orqaga, savolda so'roq tartibi yo'q (asked where I lived); fe'l qolipi: admit -ing, promise to V, warn sb to V, insist on -ing.","Yangi so'zlar: phishing, paywall, livestream, whistleblower, malware, fact-check, firewall, wearable, troll, deepfake. Fikr bildirish: In my view, I see your point, but…, up to a point."]},{"id":"u26-l11","slug":"media-and-technology-final-review","title":"Media and technology: final review","titleUz":"Ommaviy axborot va texnologiya: yakuniy takror","goal":"Bosqichdagi hamma mavzuni yana bir bor takrorlaysiz: passive va reporting passive, causative, ko'chirma gap va reporting fe'llari, media-texnologiya so'zlari hamda fikr bildirish iboralari. Hammasi yangi misollarda.","words":[{"en":"cyberbullying","uz":"internetdagi ta'qib va tahqirlash","ipa":"ˈsaɪ.bəˌbʊl.i.ɪŋ"},{"en":"obsolete","uz":"eskirgan, kerak bo'lmay qolgan","ipa":"ˈɒb.sə.liːt"},{"en":"streaming","uz":"onlayn video/audio ko'rish yoki tinglash","ipa":"ˈstriː.mɪŋ"},{"en":"bandwidth","uz":"internet o'tkazuvchanligi","ipa":"ˈbænd.wɪtθ"},{"en":"digital detox","uz":"raqamli qurilmalardan dam olish davri","ipa":"ˌdɪdʒ.ɪ.təl ˈdiː.tɒks"},{"en":"digital divide","uz":"raqamli tengsizlik","ipa":"ˌdɪdʒ.ɪ.təl dɪˈvaɪd"}],"summary":["Passive: be + V3 barcha zamonlarda (is being upgraded, had been removed, will have been saved), modal va to be / being + V3.","Reporting passive: is said to be losing, is believed to have been hacked; to dan keyin vaqtga qarab shakl tanlanadi.","Causative: have / get + object + V3; make / let + kim + V (to'siz); get + kim + to V.","Ko'chirma gap: zamon orqaga, savolda so'roq tartibi yo'q; deny / admit -ing, warn + kim + to V.","Yangi so'zlar: cyberbullying, obsolete, streaming, bandwidth, digital detox, digital divide; fikr bildirish: up to a point, I'd say that…"]}]},{"id":"u27","n":27,"title":"Work, business and formal communication","titleUz":"Ish, biznes va rasmiy muloqot: gerund / infinitive, rasmiy uslub, phrasal verbs","description":"Gerund va infinitive qoliplari, fe'l + predlog, rasmiy va norasmiy uslub, ish phrasal verbs, majburiyat va ruxsat, nominalizatsiya, yig'ilish, intervyu va rasmiy xatlar.","canDo":["Gerund va infinitive qoliplarini to'g'ri tanlayman (decide to go, avoid making, look forward to meeting)","Ish joyidagi qoidalar va ruxsatlar haqida mustn't, don't have to, be supposed to bilan aniq gapiraman","Rasmiy va norasmiy uslubni farqlayman, rasmiy email va cover letter yozaman","Yig'ilishda fikr bildiraman, muloyim e'tiroz bildiraman va taklif kiritaman; ishga intervyuda o'zimni tanishtiraman"],"lessons":[{"id":"u27-l1","slug":"gerund-or-infinitive-verb-patterns","title":"Gerund or infinitive? Verb patterns","titleUz":"Gerund yoki infinitive: remember to do / doing, stop, try, regret, go on","goal":"Fe'ldan keyin -ing (gerund) yoki to + fe'l (infinitive) kerakligini ishonch bilan tanlaysiz. remember, forget, stop, try, regret, go on, mean fe'llarida ma'no o'zgarishini ajratasiz, ish va intervyuda decide to, avoid -ing, persuade someone to qoliplarini ishlatasiz va I look forward to meet, suggest to go kabi tipik xatolardan qochasiz.","words":[{"en":"undertake","uz":"o'z zimmasiga olmoq, majburiyat olmoq","ipa":"ˌʌn.dəˈteɪk"},{"en":"resent","uz":"ranjimoq, norozi bo'lmoq","ipa":"rɪˈzent"},{"en":"refrain","uz":"o'zini tiymoq, qilmaslik","ipa":"rɪˈfreɪn"},{"en":"contemplate","uz":"jiddiy o'ylab ko'rmoq","ipa":"ˈkɒn.təm.pleɪt"},{"en":"oblige","uz":"majbur qilmoq","ipa":"əˈblaɪdʒ"},{"en":"keen","uz":"ishtiyoqli, qiziqqan","ipa":"kiːn"},{"en":"capable","uz":"qodir, uddalay oladigan","ipa":"ˈkeɪ.pə.bəl"},{"en":"inclined","uz":"moyil, ko'ngli tortadigan","ipa":"ɪnˈklaɪnd"},{"en":"dread","uz":"qo'rqib kutmoq, yomon ko'rmoq","ipa":"dred"},{"en":"tempted","uz":"vasvasaga tushgan, ko'ngli tortgan","ipa":"ˈtemp.tɪd"}],"summary":["Ikkinchi fe'lning shaklini birinchi fe'l belgilaydi: -ing (enjoy, avoid, suggest, consider, admit) yoki to (decide, manage, afford, refuse, plan, hope).","Ob'ekt + to + fe'l: persuade, remind, warn, encourage, oblige. make / let dan keyin to siz: made me work.","Ma'no o'zgaradi: remember / forget / stop / try / regret / go on to = keyingi ish yoki maqsad; -ing = o'tgan ish yoki jarayon.","Predlogdan keyin doim -ing: look forward to seeing, instead of going, capable of leading.","O'zbekcha xatolar: ~~look forward to meet~~ → meeting; ~~suggest to go~~ → suggest going; ~~decide leaving~~ → decide to leave."]},{"id":"u27-l12","slug":"verbs-followed-by-prepositions","title":"Verbs followed by prepositions","titleUz":"Fe'l + predlog: depend on, apologise for, succeed in, insist on, object to","goal":"Fe'l, sifat va otlardan keyin keladigan qat'iy predloglarni (rely on, succeed in, insist on, object to, responsible for) to'g'ri ishlatasiz, predlogdan keyin -ing qo'yasiz va o'zbek tilidan kelib chiqadigan xatolarni (discuss about, marry with, enter to) tuzatasiz.","words":[{"en":"rely on","uz":"tayanmoq, ishonmoq","ipa":"rɪˈlaɪ ɒn"},{"en":"succeed in","uz":"muvaffaq bo'lmoq","ipa":"səkˈsiːd ɪn"},{"en":"insist on","uz":"turib olmoq, talab qilmoq","ipa":"ɪnˈsɪst ɒn"},{"en":"object to","uz":"qarshi bo'lmoq, e'tiroz bildirmoq","ipa":"əbˈdʒekt tuː"},{"en":"comply with","uz":"rioya qilmoq, amal qilmoq","ipa":"kəmˈplaɪ wɪð"},{"en":"be responsible for","uz":"mas'ul bo'lmoq","ipa":"bi rɪˈspɒn.sə.bəl fɔː"},{"en":"be capable of","uz":"qodir bo'lmoq","ipa":"bi ˈkeɪ.pə.bəl ɒv"}],"summary":["Fe'llar o'z predlogi bilan yodlanadi: rely on, succeed in, insist on, object to, comply with, apologise for / to.","Predlogdan keyin fe'l -ing bo'ladi: succeed in finding, object to working, apologise for being late.","Sifat va ot ham predlog talab qiladi: responsible for, capable of, a reason for, a solution to, an increase in.","Predlogsiz fe'llar: discuss, marry, enter, contact (xato: discuss about, marry with, enter to, contact with).","Yangi so'zlar: rely on, succeed in, insist on, object to, comply with, be responsible for, be capable of."]},{"id":"u27-l2","slug":"formal-and-informal-register","title":"Formal and informal register","titleUz":"Rasmiy va norasmiy uslub: so'z tanlash, qisqartmalar, passive","goal":"Gapning uslubini (register) auditoriyaga moslaysiz: do'stingizga norasmiy, mijoz yoki rahbarga rasmiy yozasiz. find out → discover, get → obtain, buy → purchase kabi almashtirishlarni, passive, yumshatuvchi iboralar (I would be grateful if…) va rasmiy ochilish/yakunlash formulalarini ishlatasiz hamda I want, gonna, mate kabi rasmiy matnga to'g'ri kelmaydigan so'zlarni topib to'g'rilaysiz.","words":[{"en":"obtain","uz":"olmoq, qo'lga kiritmoq (rasmiy)","ipa":"əbˈteɪn"},{"en":"commence","uz":"boshlanmoq, boshlamoq (rasmiy)","ipa":"kəˈmens"},{"en":"purchase","uz":"sotib olmoq (rasmiy)","ipa":"ˈpɜː.tʃəs"},{"en":"ascertain","uz":"aniqlamoq, aniq bilib olmoq (rasmiy)","ipa":"ˌæs.əˈteɪn"},{"en":"adequate","uz":"yetarli, qoniqarli","ipa":"ˈæd.ɪ.kwət"},{"en":"terminate","uz":"tugatmoq, bekor qilmoq (shartnomani)","ipa":"ˈtɜː.mɪ.neɪt"},{"en":"subsequently","uz":"keyinroq, undan keyin","ipa":"ˈsʌb.sɪ.kwənt.li"},{"en":"furthermore","uz":"bundan tashqari","ipa":"ˌfɜː.ðəˈmɔː"},{"en":"endeavour","uz":"intilmoq, harakat qilmoq (rasmiy)","ipa":"ɪnˈdev.ə"},{"en":"reside","uz":"yashamoq, istiqomat qilmoq","ipa":"rɪˈzaɪd"}],"summary":["Uslubni o'quvchiga moslang: tanish bo'lmagan yoki yuqori odamga rasmiy, hamkasbga neytral, do'stga norasmiy. Shubhada bir pog'ona rasmiyroq yozing.","Rasmiy so'zlar: obtain, purchase, commence, terminate, approximately, sufficient, subsequently, furthermore; phrasal verb o'rniga: find out → discover, put off → postpone.","Rasmiy gap: qisqartma yo'q, passive, however / therefore / furthermore, I would like, I would be grateful if you could….","Yumshatish: I was wondering if…, I'm afraid…, It seems that…. Ochilish: Dear Mr / Ms; yakun: Kind regards, Yours sincerely.","Xatolar: ~~I want to know~~ → I would like to know; ~~gonna / wanna~~ rasmiy matnda yo'q; ~~mate~~ rasmiy xatda o'rinsiz."]},{"id":"u27-l3","slug":"phrasal-verbs-at-work","title":"Phrasal verbs at work","titleUz":"Phrasal verbs ish va biznesda: separable, inseparable, three-part","goal":"Ish joyida eng ko'p uchraydigan phrasal verblarni to'g'ri ishlatasiz: separable (turn it down), inseparable (look into it) va three-part (put up with, come up with, get on with) turlarini farqlaysiz, olmosh o'rni qoidasini bilasiz, 10 ta yangi ish phrasal verb'ini (take on, follow up, step down, draw up) gapda qo'llaysiz va ularni rasmiy fe'llar bilan almashtira olasiz.","words":[{"en":"take on","uz":"ishga olmoq; zimmasiga olmoq","ipa":"teɪk ɒn"},{"en":"follow up","uz":"yana murojaat qilmoq, davom ettirmoq","ipa":"ˌfɒl.əʊ ˈʌp"},{"en":"put up with","uz":"chidamoq, toqat qilmoq","ipa":"ˌpʊt ˈʌp wɪð"},{"en":"get on with","uz":"ishni davom ettirmoq; til topishmoq","ipa":"ˌɡet ˈɒn wɪð"},{"en":"step down","uz":"lavozimdan ketmoq","ipa":"ˌstep ˈdaʊn"},{"en":"cut back on","uz":"qisqartirmoq (xarajatni)","ipa":"ˌkʌt ˈbæk ɒn"},{"en":"draw up","uz":"tuzmoq, tayyorlamoq (hujjat)","ipa":"ˌdrɔː ˈʌp"},{"en":"bring forward","uz":"oldinga surmoq, erta qilmoq","ipa":"ˌbrɪŋ ˈfɔː.wəd"},{"en":"hold up","uz":"kechiktirmoq, to'xtatib turmoq","ipa":"ˌhəʊld ˈʌp"},{"en":"fall through","uz":"amalga oshmay qolmoq","ipa":"ˌfɔːl ˈθruː"}],"summary":["Phrasal verb = fe'l + particle; ma'nosi ko'pincha alohida o'rganiladi. Turlari: intransitive, separable, inseparable, three-part.","Separable: ot ikki joyda tura oladi (called off the meeting / called the meeting off), olmosh faqat o'rtada (called it off).","Inseparable va uch qismli: ob'ekt oxirida (look into it, put up with it, come up with an idea).","Ish uchun: take on, follow up, step down, draw up, bring forward, hold up, fall through, cut back on, put up with, get on with.","Rasmiy almashtirish: turn down → reject, call off → cancel, look into → investigate, cut back on → reduce. Xato: ~~turn down it~~, ~~come up an idea~~."]},{"id":"u27-l4","slug":"obligation-permission-and-necessity","title":"Obligation, permission and necessity","titleUz":"Majburiyat, ruxsat va zaruriyat: must, have to, be allowed to, be supposed to, need","goal":"Ish joyi qoidalari va siyosatini (policy) aniq ifodalaysiz: must / have to / need to farqini, mustn't / don't have to / needn't ning butunlay boshqa ma'nolarini, be allowed to, be supposed to, be required to ni, shuningdek o'tgan zamon shakllarini (had to, was allowed to, needn't have done) ishlatasiz va You don't have to smoke here (taqiq o'rniga) kabi xavfli xatolardan qochasiz.","words":[{"en":"prohibit","uz":"taqiqlamoq","ipa":"prəˈhɪb.ɪt"},{"en":"abide by","uz":"(qoidaga) rioya qilmoq, bo'ysunmoq","ipa":"əˈbaɪd baɪ"},{"en":"entitled","uz":"huquqi bor","ipa":"ɪnˈtaɪ.təld"},{"en":"mandatory","uz":"majburiy","ipa":"ˈmæn.də.tər.i"},{"en":"dress code","uz":"kiyinish qoidasi","ipa":"ˈdres kəʊd"},{"en":"exempt","uz":"ozod qilingan, majburiyatdan xoli","ipa":"ɪɡˈzempt"},{"en":"enforce","uz":"joriy qilmoq, bajarishga majburlamoq","ipa":"ɪnˈfɔːs"},{"en":"restriction","uz":"cheklov","ipa":"rɪˈstrɪk.ʃən"},{"en":"stipulate","uz":"shart qilib qo'ymoq, qat'iy belgilamoq","ipa":"ˈstɪp.jə.leɪt"},{"en":"disciplinary","uz":"intizomiy","ipa":"ˌdɪs.əˈplɪn.ər.i"}],"summary":["Majburiyat: must (so'zlovchining fikri yoki yozma qoida), have to (tashqi qoida), need to (zarurat), be required to (rasmiy talab).","Inkor: mustn't = taqiq; don't have to / don't need to / needn't = shart emas. Bu ikkisini adashtirmang!","Ruxsat: can (norasmiy), be allowed to (neytral), be permitted to (rasmiy). be supposed to = kutilgan yoki rejalangan, amalda bajarilmasligi mumkin.","O'tgan zamon: had to, was allowed to, didn't have to; needn't have + V3 = qilingan, lekin keraksiz ish. Must ning o'tgan zamoni yo'q.","Xatolar: ~~must to go~~ → must go; ~~I must work yesterday~~ → had to; ~~Do I must…?~~ → Must I…? / Do I have to…?"]},{"id":"u27-l13","slug":"nominalisation-from-verbs-to-nouns","title":"Nominalisation: from verbs to nouns","titleUz":"Nominalizatsiya: fe'ldan otga (decide → decision) — rasmiy matn uchun","goal":"Fe'l va sifatlarni otga aylantirib (decide → decision, efficient → efficiency) rasmiy matnni qisqa va jiddiy yozasiz, -tion, -ment, -ness, -ity qo'shimchalarini va ularning predloglarini bilasiz, oddiy gapni rasmiy shaklga o'zgartira olasiz.","words":[{"en":"implementation","uz":"joriy etish, amalga oshirish","ipa":"ˌɪm.plɪ.menˈteɪ.ʃən"},{"en":"assessment","uz":"baholash","ipa":"əˈses.mənt"},{"en":"reduction","uz":"kamayish, qisqarish","ipa":"rɪˈdʌk.ʃən"},{"en":"efficiency","uz":"samaradorlik","ipa":"ɪˈfɪʃ.ən.si"},{"en":"expansion","uz":"kengayish","ipa":"ɪkˈspæn.ʃən"},{"en":"shortage","uz":"yetishmovchilik","ipa":"ˈʃɔː.tɪdʒ"}],"summary":["Nominalizatsiya: fe'l yoki sifat → ot (decide → decision, efficient → efficiency). Rasmiy yozuvda gapni qisqartiradi.","Qo'shimchalar: -tion (reduction), -ment (assessment), -al (arrival), -ness / -ity (availability), -ency (efficiency); ba'zilari alohida: growth, failure.","Predloglar: an increase / a reduction in, the implementation of, a shortage of, a decision to.","Xatolar: the decide, the arrive, increase of prices → the decision, the arrival, increase in prices.","Yangi so'zlar: implementation, assessment, reduction, efficiency, expansion, shortage."]},{"id":"u27-l9","slug":"a-job-interview","title":"A job interview","titleUz":"Ishga intervyu: tajriba va kuchli tomonlaringiz haqida gapirish","goal":"Ishga intervyuda Tell me about yourself, strengths / weaknesses, Why this job? kabi savollarga STAR tuzilmasi bilan javob berasiz, tajribani Present Perfect bilan aytasiz, gerund va infinitiv qoliplarini to'g'ri ishlatasiz va oxirida o'zingiz savol berasiz.","words":[{"en":"track record","uz":"o'tgan yutuqlar, natijalar tarixi","ipa":"ˈtræk ˌrekɔːd"},{"en":"take the initiative","uz":"tashabbus ko'rsatmoq","ipa":"teɪk ði ɪˈnɪʃ.ə.tɪv"},{"en":"work under pressure","uz":"bosim ostida ishlamoq","ipa":"wɜːk ˈʌn.də ˈpreʃ.ə"},{"en":"self-motivated","uz":"o'zini o'zi rag'batlantiradigan","ipa":"ˌself ˈməʊ.tɪ.veɪ.tɪd"},{"en":"be shortlisted","uz":"qisqa ro'yxatga kiritilmoq","ipa":"bi ˈʃɔːt.lɪs.tɪd"},{"en":"team player","uz":"jamoada yaxshi ishlaydigan odam","ipa":"tiːm ˈpleɪ.ə"}],"summary":["Intervyu savollariga STAR bilan javob bering: Situation, Task, Action, Result.","Tajriba va davomiylik: Present Perfect (I've worked here for three years); aniq vaqt bo'lsa Past Simple (in 2021 I introduced…).","Predlogdan keyin -ing: good at working, responsible for training, look forward to meeting. would like / manage dan keyin to + V1.","Oxirida savol bering: What would a typical day look like?, What are the next steps?","Yangi so'zlar: track record, take the initiative, work under pressure, self-motivated, be shortlisted, team player."]},{"id":"u27-l5","slug":"work-careers-and-business","title":"Work, careers and business","titleUz":"Ish, karyera va biznes: so'zlar va birikmalar (workforce, promotion, deadline, negotiate)","goal":"Ish, karyera va biznes haqida B2 darajada gapirasiz va yozasiz: workforce, redundant, turnover, entrepreneur, profit, recruit, merger, payroll, lay off, negotiate so'zlarini, shuningdek meet a deadline, make a profit, run a business, hand in your notice, apply for a position, be made redundant kabi birikmalarni to'g'ri ishlatasiz va make a business, apply to a position kabi xatolarni tuzatasiz.","words":[{"en":"workforce","uz":"xodimlar, ishchi kuchi","ipa":"ˈwɜːk.fɔːs"},{"en":"redundant","uz":"ish o'rni qisqartirilgan","ipa":"rɪˈdʌn.dənt"},{"en":"negotiate","uz":"muzokara olib bormoq","ipa":"nɪˈɡəʊ.ʃi.eɪt"},{"en":"turnover","uz":"aylanma; kadrlar almashinuvi","ipa":"ˈtɜːnˌəʊ.və"},{"en":"entrepreneur","uz":"tadbirkor","ipa":"ˌɒn.trə.prəˈnɜː"},{"en":"profit","uz":"foyda","ipa":"ˈprɒf.ɪt"},{"en":"recruit","uz":"ishga yollamoq (yangi xodimni)","ipa":"rɪˈkruːt"},{"en":"merger","uz":"kompaniyalarning birlashishi","ipa":"ˈmɜː.dʒə"},{"en":"payroll","uz":"ish haqi ro'yxati","ipa":"ˈpeɪ.rəʊl"},{"en":"lay off","uz":"ishdan bo'shatmoq (kerak bo'lmagani uchun)","ipa":"ˌleɪ ˈɒf"}],"summary":["Kompaniya: workforce (xodimlar), recruit (yollamoq), payroll (ish haqi ro'yxati), turnover (aylanma / kadrlar almashinuvi), lay off va be made redundant.","Biznes: entrepreneur, profit, merger, negotiate. Negotiate ob'ektli fe'l: negotiate a deal / the price.","Birikmalar: meet / miss a deadline, make a profit / loss, run / set up a business, apply for a position, hand in your notice, win a contract.","So'z oilasi: employ → employer, employee, employment; promote → promotion; qualify → qualification.","Xatolar: ~~make a business~~ → run a business; ~~make the deadline~~ → meet the deadline; ~~apply to a position~~ → apply for."]},{"id":"u27-l6","slug":"meetings-and-negotiating","title":"Meetings and negotiating","titleUz":"Yig'ilish va muzokara: fikr bildirish, rozi bo'lish, taklif kiritish, kelishuvga erishish","goal":"Ish yig'ilishida va muzokarada ishonch bilan qatnashasiz: yig'ilishni ochasiz va kun tartibi (agenda) haqida gapirasiz, fikr bildirasiz, muloyimlik bilan rozi bo'lasiz yoki e'tiroz bildirasiz, so'zni bo'lasiz, aniqlashtirishni so'raysiz, taklif (I suggest we…) va shartli taklif (If you could…, we would…) kiritasiz, kelishuvga erishasiz va harakat rejasini (action points) umumlashtirasiz.","words":[{"en":"minutes","uz":"yig'ilish bayonnomasi","ipa":"ˈmɪn.ɪts"},{"en":"proposal","uz":"taklif, loyiha","ipa":"prəˈpəʊ.zəl"},{"en":"consensus","uz":"umumiy kelishuv","ipa":"kənˈsen.səs"},{"en":"clarify","uz":"aniqlashtirmoq","ipa":"ˈklær.ɪ.faɪ"},{"en":"stakeholder","uz":"manfaatdor tomon","ipa":"ˈsteɪkˌhəʊl.də"},{"en":"action point","uz":"harakat bandi, bajariladigan vazifa","ipa":"ˈæk.ʃən pɔɪnt"},{"en":"constructive","uz":"konstruktiv, foydali","ipa":"kənˈstrʌk.tɪv"},{"en":"objection","uz":"e'tiroz","ipa":"əbˈdʒek.ʃən"},{"en":"adjourn","uz":"(yig'ilishni) to'xtatmoq, keyinga qoldirmoq","ipa":"əˈdʒɜːn"},{"en":"put forward","uz":"(taklifni) ilgari surmoq","ipa":"ˌpʊt ˈfɔː.wəd"}],"summary":["Yig'ilish bosqichlari: ochish, kun tartibi, fikr, aniqlashtirish, taklif, kelishuv, umumlashtirish; har birining tayyor iboralari bor.","Fikr va e'tiroz yumshatiladi: I take your point, but… / I'm not sure I agree / As I see it…. I agree with you, ~~I am agree~~.","So'zni bo'lish: Sorry to interrupt, but…. Aniqlash: Could you clarify…? Just to check, are you saying…? Explain something to someone.","Taklif: How about + -ing, I suggest (that) we + fe'l, Let's + fe'l; shartli: If you could…, we would…, provided that, as long as.","Yakun: kim + will + nima + by qachon (action point). So'zlar: minutes, proposal, consensus, stakeholder, objection, adjourn."]},{"id":"u27-l14","slug":"listening-and-speaking-a-work-meeting","title":"Listening and speaking: a work meeting","titleUz":"Tinglash va gapirish: ish yig'ilishi","goal":"Ish yig'ilishini tinglab kim nimani qaror qilishini (who decides what) aniqlaysiz, yig'ilish iboralarini bilasiz va bir daqiqalik taklif (proposal) ni tuzilma bo'yicha ovoz chiqarib aytasiz.","words":[{"en":"deliverable","uz":"topshiriladigan natija (loyiha doirasida)","ipa":"dɪˈlɪv.ər.ə.bəl"},{"en":"brainstorm","uz":"birgalikda g'oya izlamoq","ipa":"ˈbreɪn.stɔːm"},{"en":"allocate","uz":"ajratmoq, taqsimlamoq","ipa":"ˈæl.ə.keɪt"},{"en":"take the minutes","uz":"yig'ilish bayonnomasini yuritmoq","ipa":"teɪk ðə ˈmɪn.ɪts"},{"en":"on board","uz":"(loyiha/rejaga) qo'shilgan, rozi","ipa":"ɒn bɔːd"},{"en":"raise a concern","uz":"xavotirni bildirmoq","ipa":"reɪz ə kənˈsɜːn"}],"summary":["Yig'ilishni tinglaganda aniqlang: mavzu, taklif, sabab, kim nimani qaror qiladi (I will approve…, I'll send…).","Taklif: I'd like to propose that we…, How about + -ing?, If we could…, we would…","Taklif tuzilmasi: taklif → sabab → foyda / shart → keyingi qadam; xulosa: to sum up.","Yig'ilish so'zlari: deliverable, brainstorm, allocate, take the minutes, on board, raise a concern."]},{"id":"u27-l10","slug":"a-phone-call-to-a-client","title":"A phone call to a client","titleUz":"Mijoz bilan telefon suhbati: ma'lumot berish va xabar qoldirish","goal":"Mijozga rasmiy qo'ng'iroq qilasiz: o'zingizni tanishtirasiz, kechikish sababini tushuntirasiz, xabar qoldirasiz yoki qabul qilasiz, ism va raqamlarni harflab / raqamlab tasdiqlaysiz va muloyim yakunlaysiz.","words":[{"en":"hold the line","uz":"(telefonda) kutib turmoq","ipa":"həʊld ðə laɪn"},{"en":"put through","uz":"telefonda ulab bermoq","ipa":"ˈpʊt θruː"},{"en":"get back to","uz":"keyinroq javob bermoq, qayta qo'ng'iroq qilmoq","ipa":"ˌget ˈbæk tuː"},{"en":"take a message","uz":"xabar qabul qilmoq","ipa":"teɪk ə ˈmes.ɪdʒ"},{"en":"bear with me","uz":"sabr qiling, bir daqiqa kuting","ipa":"beə wɪð miː"},{"en":"on behalf of","uz":"...nomidan","ipa":"ɒn bɪˈhɑːf ɒv"}],"summary":["Telefonda o'zingizni This is … bilan tanishtiring, maqsadni I'm calling about / to… bilan ayting.","Muloyimlik: Could I speak to…?, I'm afraid…, I was wondering if…, Just to confirm…; kechikish haqida majhul nisbat: has been held up.","Ism va raqam: spell, double O, raqamlarni bittadan va guruhlab ayting; tushunmasangiz Could you repeat that, please?","Xatolar: Who are you speaking? → Who's calling?; I want to speak with… → Could I speak to…?; Wait a little → Hold the line.","Yangi so'zlar: hold the line, put through, get back to, take a message, bear with me, on behalf of."]},{"id":"u27-l7","slug":"writing-a-formal-email-and-a-cover-letter","title":"Writing: a formal email and a cover letter","titleUz":"Yozish: rasmiy email va qo'shimcha xat (cover letter)","goal":"Ikki turdagi rasmiy matn yozasiz: shikoyat yoki so'rov emaili (taxminan 150 so'z) va cover letter (taxminan 200 so'z). Mavzu qatori, murojaat (Dear Mr / Ms, Dear Sir or Madam), maqsad jumlasi, muloyim so'rov (I would be grateful if you could…) va yakun (Yours sincerely / faithfully) ni to'g'ri tuzasiz hamda I am writing for apply, I will be grateful if you will kabi xatolardan qochasiz.","words":[{"en":"reimburse","uz":"xarajatni qaytarmoq","ipa":"ˌriː.ɪmˈbɜːs"},{"en":"unsatisfactory","uz":"qoniqarsiz","ipa":"ˌʌn.sæt.ɪsˈfæk.tər.i"},{"en":"dissatisfied","uz":"norozi, qoniqmagan","ipa":"dɪˈsæt.ɪs.faɪd"},{"en":"prompt","uz":"tezkor, o'z vaqtidagi","ipa":"prɒmpt"},{"en":"enthusiasm","uz":"ishtiyoq, g'ayrat","ipa":"ɪnˈθjuː.zi.æz.əm"},{"en":"referee","uz":"tavsiya beruvchi shaxs","ipa":"ˌref.əˈriː"},{"en":"accomplishment","uz":"yutuq, erishilgan natija","ipa":"əˈkʌm.plɪʃ.mənt"},{"en":"inquire","uz":"so'ramoq, ma'lumot olmoq (rasmiy)","ipa":"ɪnˈkwaɪə"},{"en":"dispatch","uz":"jo'natmoq","ipa":"dɪˈspætʃ"},{"en":"remedy","uz":"chora; muammoni hal qilish","ipa":"ˈrem.ə.di"}],"summary":["Rasmiy email: subject → Dear… → maqsad → tafsilot → so'rov → yakun → imzo. Ism noma'lum: Dear Sir or Madam … Yours faithfully; ism ma'lum: Dear Mr / Ms … Yours sincerely.","Maqsad: I am writing to + fe'l (to apply, to complain, to enquire). So'rov: I would be grateful if you could…. Kutish: I look forward to hearing from you.","Cover letter: 1) lavozim va manba, 2) dalilli tajriba, 3) nega bu kompaniya, 4) intervyu so'rash va minnatdorchilik.","Rasmiy ohang: qisqartma yo'q, however / furthermore / therefore, dalillar (raqam, natija), qat'iy, lekin qo'pol emas.","Xatolar: ~~I am writing for apply~~ → to apply; ~~I will be grateful if you will~~ → would … could; ~~look forward to hear~~ → hearing."]},{"id":"u27-l15","slug":"reading-and-writing-a-job-advert-and-cv","title":"Reading and writing: a job advert and CV","titleUz":"O'qish va yozish: ish e'loni va CV","goal":"Ish e'loni va CV ni o'qib, talablarni tajriba bilan solishtirasiz, CV ga xos iboralarni (proficient in, in charge of, hands-on experience of) bilasiz va 100-120 so'zli ariza xulosasi yozasiz.","words":[{"en":"in charge of","uz":"rahbarlik qiladigan, mas'ul","ipa":"ɪn ˈtʃɑːdʒ ɒv"},{"en":"closing date","uz":"topshirish muddati","ipa":"ˈkləʊ.zɪŋ deɪt"},{"en":"responsibilities","uz":"majburiyatlar, vazifalar","ipa":"rɪˌspɒn.sɪˈbɪl.ə.tiz"},{"en":"candidate","uz":"nomzod","ipa":"ˈkæn.dɪ.dət"},{"en":"competent","uz":"malakali, o'z ishini biladigan","ipa":"ˈkɒm.pɪ.tənt"},{"en":"feedback","uz":"fikr-mulohaza, baho","ipa":"ˈfiːd.bæk"}],"summary":["Ish e'lonida uch narsani toping: responsibilities, requirements, closing date; keyin CV dagi tajriba bilan solishtiring.","CV iboralari: in charge of, hands-on experience of, proficient in, be responsible for + -ing; harakat fe'llari Past Simple da (introduced, managed).","Xatolar: I am graduated → I graduated; writing for apply → writing to apply; 4 years experience → four years' experience.","Ariza xulosasi (100-120 so'z): maqsad → tajriba (Present Perfect) → raqamli natija → ko'nikma → I look forward to hearing from you.","Yangi so'zlar: in charge of, closing date, responsibilities, candidate, competent, feedback."]},{"id":"u27-l8","slug":"unit-review-work-and-formal-english","title":"Unit review: work and formal English","titleUz":"Bosqich takrori: ish va rasmiy ingliz tili","goal":"Bosqichni takrorlaysiz: gerund va infinitive (decide to, avoid -ing, remember to / doing), rasmiy va norasmiy uslub, ish phrasal verb'lari (put it off, come up with), must / have to / needn't / be supposed to, ish lug'ati, yig'ilish iboralari va rasmiy xat qoidalarini yangi misollarda tekshirasiz hamda 10 ta yangi so'z (delegate, implement, invoice, appoint…) o'rganasiz.","words":[{"en":"delegate","uz":"(vazifani) topshirmoq","ipa":"ˈdel.ɪ.ɡeɪt"},{"en":"implement","uz":"amalda joriy qilmoq","ipa":"ˈɪm.plɪ.ment"},{"en":"confidential","uz":"maxfiy","ipa":"ˌkɒn.fɪˈden.ʃəl"},{"en":"outstanding","uz":"to'lanmagan; hal etilmagan","ipa":"aʊtˈstæn.dɪŋ"},{"en":"invoice","uz":"hisob-faktura","ipa":"ˈɪn.vɔɪs"},{"en":"appoint","uz":"tayinlamoq","ipa":"əˈpɔɪnt"},{"en":"attendance","uz":"qatnashish, ishtirok","ipa":"əˈten.dəns"},{"en":"demonstrate","uz":"namoyish qilmoq, ko'rsatmoq","ipa":"ˈdem.ən.streɪt"},{"en":"contract","uz":"shartnoma","ipa":"ˈkɒn.trækt"},{"en":"objective","uz":"maqsad, vazifa","ipa":"əbˈdʒek.tɪv"}],"summary":["Gerund / infinitive: decide, agree, manage + to; avoid, consider, suggest + -ing; persuade somebody to; predlogdan keyin -ing (look forward to meeting).","Uslub: rasmiy matnda qisqartma yo'q, passive, obtain / purchase / postpone; I would be grateful if you could…; murojaat va yakun mos (Dear Mr… Yours sincerely).","Phrasal verb: separable'da olmosh o'rtada (put it off), uch qismli ajralmaydi (put up with it). Modal: mustn't (taqiq) ≠ don't have to (shart emas); o'tgan zamon had to.","Lug'at va yig'ilish: meet a deadline, run a business, hand in your notice; I take your point, Could you clarify…?, I suggest we…, If you could…, we would….","Yangi so'zlar: delegate, implement, confidential, outstanding, invoice, appoint, attendance, demonstrate, contract, objective."]},{"id":"u27-l11","slug":"work-and-business-final-review","title":"Work and business: final review","titleUz":"Ish va biznes: yakuniy takror","goal":"Bosqichdagi hamma mavzuni takrorlaysiz: gerund / infinitive, fe'l + predlog, phrasal verbs, majburiyat va ruxsat, rasmiy uslub va nominalizatsiya, yig'ilish va rasmiy xat iboralari. Ish haqidagi 6 ta yangi so'zni ham o'rganasiz.","words":[{"en":"revenue","uz":"daromad (tushum)","ipa":"ˈrev.ən.juː"},{"en":"strategy","uz":"strategiya","ipa":"ˈstræt.ə.dʒi"},{"en":"outsource","uz":"ishni tashqi kompaniyaga topshirmoq","ipa":"ˈaʊt.sɔːs"},{"en":"supply chain","uz":"yetkazib berish zanjiri","ipa":"səˈplaɪ tʃeɪn"},{"en":"market share","uz":"bozor ulushi","ipa":"ˈmɑː.kɪt ʃeə"},{"en":"scope","uz":"qamrov, ko'lam","ipa":"skəʊp"}],"summary":["Gerund / infinitive: decide, manage + to; avoid, consider, suggest + -ing; remember to do (keyingi ish) va remember doing (o'tgan ish).","Predloglar (insist on, succeed in, responsible for, look forward to) dan keyin -ing; discuss, marry, enter predlogsiz.","Phrasal verbs: separable'da olmosh o'rtada (turned it down); mustn't (taqiq) ≠ don't have to (shart emas); o'tgan zamon — had to.","Rasmiy uslub: qisqartmasiz, obtain / purchase / postpone, nominalizatsiya (an increase in prices), I would be grateful if you could…","Yangi so'zlar: revenue, strategy, outsource, supply chain, market share, scope."]}]},{"id":"u28","n":28,"title":"Argument and emphasis","titleUz":"Dalil va urg'u: cleft gaplar, inversiya, bog'lovchilar va essay","description":"Cleft gaplar, inversiya, qarama-qarshilik va sabab-natija bog'lovchilari, sifatdosh gaplari, akademik lug'at, munozara va essay yozish.","canDo":["Cleft gaplar (It was … that, What I need is …) va emphatic do bilan fikrimni ta'kidlayman","Inversiyani (Never have I, Not only did she, Had I known) to'g'ri tuzaman va me'yorida ishlataman","Although, despite, however, consequently, so as not to kabi bog'lovchilarni xatosiz ishlataman","Essay yozaman va munozarada dalil keltiraman: thesis, topic sentence, qarshi fikr va xulosa bilan"],"lessons":[{"id":"u28-l1","slug":"cleft-sentences","title":"Cleft sentences","titleUz":"Cleft gaplar: It was John who…, What I need is…, All I want is…","goal":"Cleft gaplar (cleft sentences) bilan gapning bir bo'lagini ajratib ko'rsatasiz: It was the price that worried me. What I need is a holiday. All I want is some peace. Qachon it-cleft, qachon wh-cleft kerakligini bilasiz, gapda yangi yoki to'g'rilanayotgan ma'lumotni urg'u bilan aytasiz va What I need it is… kabi xatolardan qochasiz.","words":[{"en":"genuinely","uz":"chin dildan, haqiqatan","ipa":"ˈdʒen.ju.ɪn.li"},{"en":"motivation","uz":"motivatsiya, ishtiyoq","ipa":"ˌməʊ.tɪˈveɪ.ʃən"},{"en":"flaw","uz":"kamchilik, nuqson","ipa":"flɔː"},{"en":"fundamental","uz":"asosiy, tub","ipa":"ˌfʌn.dəˈmen.təl"},{"en":"initiative","uz":"tashabbus","ipa":"ɪˈnɪʃ.ə.tɪv"},{"en":"resentment","uz":"ginaxonlik, ichki norozilik","ipa":"rɪˈzent.mənt"},{"en":"emphasis","uz":"urg'u, ahamiyat berish","ipa":"ˈem.fə.sɪs"},{"en":"notion","uz":"tushuncha, g'oya","ipa":"ˈnəʊ.ʃən"},{"en":"unaware","uz":"bexabar, ogoh emas","ipa":"ˌʌn.əˈweər"},{"en":"prioritise","uz":"ustuvor qilmoq, birinchi o'ringa qo'ymoq","ipa":"praɪˈɒr.ɪ.taɪz"}],"summary":["It-cleft: It + be + ajratilgan bo'lak + that / who + …. Odam uchun who / that, vaqt, joy va narsa uchun that.","Wh-cleft: What I need is …, What surprised me was …, All I want is …, The thing that …. Teskari: A holiday is what I need.","Maqsad: yangi ma'lumotni ajratish, xatoni to'g'rilash (It wasn't Tom who…), ikki narsani qarama-qarshi qo'yish. Bir paragrafda 1–2 tadan ko'p ishlatmang.","Xatolar: ortiqcha olmosh (~~What I need it is~~, ~~who he called~~), vaqt/joy bilan who (~~It was in 2019 who~~), What … did was dan keyin zamonli fe'l (~~was shouted~~)."]},{"id":"u28-l12","slug":"fronting-and-emphasis","title":"Fronting and emphasis","titleUz":"Urg'u uchun: emphatic do/does/did, so, such, how, rhetorical structures","goal":"Gapga urg'u berishning kichik vositalarini bilasiz: emphatic do (I did tell you), so / such (such a pity, so many), how / what undovlari (What a day!), fronting (Down came the rain) va the more… the more…. Gapirishda urg'uni ohang bilan berasiz.","words":[{"en":"utterly","uz":"butunlay, mutlaqo","ipa":"ˈʌt.ə.li"},{"en":"sheer","uz":"sof, butunlay (kuchli ta'kid)","ipa":"ʃɪə"},{"en":"downright","uz":"mutlaqo, shak-shubhasiz (salbiy ma'noda)","ipa":"ˈdaʊn.raɪt"},{"en":"tremendous","uz":"ulkan, ajoyib","ipa":"trəˈmen.dəs"},{"en":"frankly","uz":"ochig'ini aytganda","ipa":"ˈfræŋk.li"},{"en":"indeed","uz":"haqiqatan ham, darhaqiqat","ipa":"ɪnˈdiːd"}],"summary":["Emphatic do: I did tell you, She does look tired — tasdiqni kuchaytiradi; keyin V1. Urg'u do/does/did ga tushadi.","so + sifat/ravish, such (a) + (sifat) + ot; undovlarda How + sifat, What (a) + ot.","Fronting (Down came the rain, Gone are the days…) kitobiy; the more…, the more… ikki jarayonni bog'laydi.","Xatolar: does likes → does like; so lovely day → such a lovely day; How awful weather → What awful weather; more I read, more… → the more I read, the more…","Yangi so'zlar: utterly, sheer, downright, tremendous, frankly, indeed."]},{"id":"u28-l2","slug":"inversion-after-negative-adverbs","title":"Inversion after negative adverbs","titleUz":"Inversiya: Never have I…, Not only… but also, Hardly… when, Only when…","goal":"Inversiya (inversion) ni bilasiz: gap never, rarely, seldom, hardly, no sooner, not only, only after, under no circumstances, little bilan boshlansa, yordamchi fe'l egadan oldin keladi: Never have I seen…, Not only did he…, Hardly had she…. Shu bilan birga so do I / neither have I va Had I known…, Should you need…, Were I you… tuzilmalarini to'g'ri ishlatasiz va Never I have seen kabi xatolardan qochasiz.","words":[{"en":"seldom","uz":"kamdan-kam","ipa":"ˈsel.dəm"},{"en":"scarcely","uz":"zo'rg'a, deyarli ... emas","ipa":"ˈskeəs.li"},{"en":"mishap","uz":"kichik baxtsiz hodisa, noqulaylik","ipa":"ˈmɪs.hæp"},{"en":"commitment","uz":"majburiyat, sadoqat","ipa":"kəˈmɪt.mənt"},{"en":"unforeseen","uz":"oldindan ko'rilmagan, kutilmagan","ipa":"ˌʌn.fɔːˈsiːn"},{"en":"under no circumstances","uz":"hech qanday sharoitda","ipa":"ˌʌn.də nəʊ ˈsɜː.kəm.stɑːn.sɪz"},{"en":"no sooner … than","uz":"…ishi bilan (shu zahoti)","ipa":"nəʊ ˈsuː.nə ðæn"},{"en":"hardly … when","uz":"…ganda (shu zahoti)","ipa":"ˈhɑːd.li wen"},{"en":"little did I know","uz":"bilmas edim","ipa":"ˈlɪt.əl dɪd aɪ nəʊ"},{"en":"only then","uz":"faqat o'shanda","ipa":"ˈəʊn.li ðen"}],"summary":["Salbiy/cheklovchi so'z gap boshida bo'lsa (never, rarely, seldom, hardly, no sooner, not only, only after, under no circumstances, little), yordamchi fe'l egadan oldin keladi: Never have I seen…","Yordamchi yo'q bo'lsa — do / does / did qo'shing, asosiy fe'l asl shaklda: Rarely does she call. Hardly … when, No sooner … than — Past Perfect + Past Simple.","Only when / after / then dan keyin inversiya bosh gapda: Only then did I understand. So / Neither / Nor + yordamchi + ega: So do I, Neither have I.","Rasmiy shart gaplar: Had I known…, Should you need…, Were I you… (if siz). Xato: ~~Never I have seen~~, ~~Rarely he calls~~, ~~Not only he was late~~.","Inversiya rasmiy va adabiy uslubda. Bir matnda 1–3 tadan ortiq ishlatmang."]},{"id":"u28-l3","slug":"concession-and-contrast-linkers","title":"Concession and contrast linkers","titleUz":"Qarama-qarshi va to'sqinlik bog'lovchilari: although, even though, despite, whereas, nevertheless, in spite of","goal":"Qarama-qarshi fikrlarni (concession va contrast) to'g'ri bog'laysiz: although / even though / though, despite / in spite of, however / nevertheless / nonetheless / even so / all the same, whereas / while / on the other hand. Qaysi so'zdan keyin gap, qaysisidan keyin ot yoki -ing kelishini, tinish belgilarini bilasiz va despite of, although … but xatolaridan qochasiz.","words":[{"en":"nonetheless","uz":"shunga qaramay, baribir","ipa":"ˌnʌn.ðəˈles"},{"en":"albeit","uz":"garchi … bo'lsa ham","ipa":"ɔːlˈbiː.ɪt"},{"en":"tempting","uz":"jozibali, vasvasaga soladigan","ipa":"ˈtemp.tɪŋ"},{"en":"trade-off","uz":"almashinuv, bir narsani olish uchun boshqasidan voz kechish","ipa":"ˈtreɪd.ɒf"},{"en":"by contrast","uz":"aksincha, farqli o'laroq","ipa":"baɪ ˈkɒn.trɑːst"},{"en":"even so","uz":"shunday bo'lsa ham","ipa":"ˌiː.vən ˈsəʊ"},{"en":"all the same","uz":"baribir, shunga qaramay","ipa":"ˌɔːl ðə ˈseɪm"},{"en":"in spite of","uz":"…ga qaramay","ipa":"ɪn ˈspaɪt ɒv"},{"en":"conversely","uz":"teskarisi, aksincha","ipa":"ˈkɒn.vɜːs.li"},{"en":"pitfall","uz":"yashirin xavf, tuzoq","ipa":"ˈpɪt.fɔːl"}],"summary":["Although / even though / though + gap; despite / in spite of + ot, -ing yoki the fact that + gap. ~~Despite of~~ va ~~Despite he was~~ xato.","However, nevertheless, nonetheless, even so, all the same — yangi gap boshida, vergul bilan (yoki ; dan keyin). Vergul bilan ikki gapni bog'lash (~~…, however …~~) xato.","Whereas / while — ikki farqni bir gapda bog'laydi; in contrast / on the other hand yangi gapni boshlaydi.","Bitta gapda ikkita bog'lovchi bo'lmaydi: ~~Although … but~~, ~~Although … however~~. Albeit — rasmiy, qisqa: a good, albeit expensive, option."]},{"id":"u28-l4","slug":"cause-result-and-purpose","title":"Cause, result and purpose","titleUz":"Sabab, natija va maqsad: owing to, consequently, so… that, in order to, so as not to","goal":"Sabab (because, because of, owing to, as, since), natija (so, therefore, consequently, as a result, hence, so … that, such … that) va maqsad (to, in order to, so as (not) to, so that) ni aniq va uslubga mos ifodalaysiz. Qaysi so'zdan keyin gap, qaysisidan keyin ot kelishini bilasiz va because of it was, for to go kabi xatolardan qochasiz.","words":[{"en":"hence","uz":"shuning uchun, demak","ipa":"hens"},{"en":"shortfall","uz":"kamomad, yetishmovchilik","ipa":"ˈʃɔːt.fɔːl"},{"en":"ensure","uz":"ta'minlamoq, kafolatlamoq","ipa":"ɪnˈʃɔː"},{"en":"trigger","uz":"sabab bo'lmoq, qo'zg'atmoq","ipa":"ˈtrɪɡ.ə"},{"en":"stem from","uz":"…dan kelib chiqmoq","ipa":"stem frɒm"},{"en":"result in","uz":"…ga olib kelmoq, natijasida … bo'lmoq","ipa":"rɪˈzʌlt ɪn"},{"en":"owing to","uz":"…tufayli (rasmiy)","ipa":"ˈəʊ.ɪŋ tuː"},{"en":"consequently","uz":"natijada, shu sababli","ipa":"ˈkɒn.sɪ.kwənt.li"},{"en":"so as to","uz":"…ish maqsadida (rasmiy)","ipa":"səʊ əz tuː"},{"en":"lead to","uz":"…ga olib kelmoq","ipa":"liːd tuː"}],"summary":["Sabab: because / as / since + gap; because of / owing to / due to / thanks to + ot. Rasmiy hisobotda owing to, due to (odatda be dan keyin).","Natija: so (oddiy); therefore, consequently, as a result, hence (rasmiy, yangi gap boshida, vergul bilan). so + sifat + that, such a + sifat + ot + that.","Maqsad: to, in order to, so as to + fe'l; inkor — in order not to / so as not to; ega boshqa yoki modal kerak bo'lsa — so that + can/could/will/would.","Xatolar: ~~because of it was~~, ~~for to go~~, ~~so that catch~~, ~~so good film~~. Fe'llar: result in, lead to, trigger, stem from."]},{"id":"u28-l13","slug":"participle-clauses","title":"Participle clauses","titleUz":"Sifatdosh gaplari: Having finished, Walking home, Built in 1900","goal":"Sifatdosh gaplarini (Walking home, …, Built in 1900, …, Having finished, …) tuzasiz, bir xil ega qoidasini bilasiz (dangling participle xatosi), qisqargan nisbiy gaplarni (the man standing there) ishlatasiz va yozma nutqni ixchamroq qilasiz.","words":[{"en":"abandoned","uz":"tashlab ketilgan, egasiz","ipa":"əˈbæn.dənd"},{"en":"derelict","uz":"tashlandiq va xaroba","ipa":"ˈder.ə.lɪkt"},{"en":"stranded","uz":"qolib ketgan (yo'lda, yordamsiz)","ipa":"ˈstræn.dɪd"},{"en":"founded","uz":"asos solingan","ipa":"ˈfaʊn.dɪd"},{"en":"restore","uz":"tiklamoq, asl holiga qaytarmoq","ipa":"rɪˈstɔː"},{"en":"weary","uz":"charchagan, toliqqan","ipa":"ˈwɪə.ri"}],"summary":["Sifatdosh gapi ikki harakatni bog'laydi: -ing (aktiv), V3 (majhul), having + V3 (oldin tugagan harakat); inkor — Not + -ing.","Bir xil ega qoidasi: sifatdosh va bosh gap egasi bir kishi/narsa bo'lishi kerak. Aks holda — dangling participle (Walking home, the rain started).","Qisqargan nisbiy gap: the man standing there (= who is standing), the book written by… (= which was written).","Xatolar: Finished the work, he… → Having finished…; Waiting for the bus, my phone rang → While I was waiting…; sits next to me → sitting next to me; building → built.","Yangi so'zlar: abandoned, derelict, stranded, founded, restore, weary."]},{"id":"u28-l9","slug":"taking-part-in-a-debate","title":"Taking part in a debate","titleUz":"Munozarada qatnashish: fikr bildirish, qarshi chiqish, so'zni olish","goal":"Sinf yoki klub munozarasida so'zni muloyim olasiz (May I come in here?), o'z pozitsiyangizni aytasiz, raqibning dalilini rad etasiz (I take your point, but…), ritorik savol berasiz va nutqni qisqa xulosa bilan tugatasiz.","words":[{"en":"dispute","uz":"bahslashmoq, rad etmoq (haqiqatligini)","ipa":"dɪˈspjuːt"},{"en":"interject","uz":"gapni bo'lib, qisqa fikr aytmoq","ipa":"ˌɪn.təˈdʒekt"},{"en":"cite","uz":"dalil sifatida keltirmoq","ipa":"saɪt"},{"en":"eloquent","uz":"notiq, ta'sirchan gapiradigan","ipa":"ˈel.ə.kwənt"},{"en":"impartial","uz":"betaraf, xolis","ipa":"ɪmˈpɑː.ʃəl"},{"en":"moderator","uz":"munozara boshqaruvchisi","ipa":"ˈmɒd.ə.reɪ.tə"}],"summary":["Munozara bosqichlari: so'zni olish (May I come in here?), pozitsiya (I'm firmly in favour of…), dalil, rad etish, xulosa (To sum up…).","Qarshi chiqishda avval qisman rozilik: I take your point, but…, I concede that…; nevertheless…","Ritorik savol javob kutmaydi va fikrni kuchaytiradi: Wouldn't that be fairer…? Nutqda 1-2 tadan oshirmang.","Xatolar: I am agree → I agree; According to me → In my opinion; against of → against; discuss about → discuss.","Yangi so'zlar: dispute, interject, cite, eloquent, impartial, moderator."]},{"id":"u28-l5","slug":"academic-and-formal-vocabulary","title":"Academic and formal vocabulary","titleUz":"Akademik va rasmiy lug'at: collocations (draw attention to, raise concern, play a role)","goal":"Essay, ma'ruza va rasmiy suhbatda ishlatiladigan akademik so'zlar va collocation larni o'zlashtirasiz: significant, crucial, undermine, perspective, implication, controversial, play a role, raise concern, draw a conclusion, reach a consensus, draw attention to. So'z oilalarini (significant → significance → significantly) va rasmiy sinonimlarni bilasiz, make a conclusion, rised concern kabi xatolardan qochasiz.","words":[{"en":"significant","uz":"sezilarli, muhim","ipa":"sɪɡˈnɪf.ɪ.kənt"},{"en":"crucial","uz":"hal qiluvchi, juda muhim","ipa":"ˈkruː.ʃəl"},{"en":"undermine","uz":"zaiflashtirmoq, asta-sekin buzmoq","ipa":"ˌʌn.dəˈmaɪn"},{"en":"perspective","uz":"nuqtai nazar, qarash","ipa":"pəˈspek.tɪv"},{"en":"implication","uz":"oqibat, yashirin ma'no","ipa":"ˌɪm.plɪˈkeɪ.ʃən"},{"en":"controversial","uz":"munozarali","ipa":"ˌkɒn.trəˈvɜː.ʃəl"},{"en":"raise concern","uz":"xavotir uyg'otmoq","ipa":"reɪz kənˈsɜːn"},{"en":"play a role","uz":"rol o'ynamoq","ipa":"pleɪ ə rəʊl"},{"en":"draw a conclusion","uz":"xulosa chiqarmoq","ipa":"drɔː ə kənˈkluː.ʒən"},{"en":"reach a consensus","uz":"umumiy kelishuvga erishmoq","ipa":"riːtʃ ə kənˈsen.səs"}],"summary":["Akademik so'zlar: significant, crucial, controversial, undermine, perspective, implication — fikrni aniqroq va kuchliroq qiladi (very important → crucial).","Collocation: play a role (in), raise concern(s), draw a conclusion, reach a consensus, draw attention to. Fe'lni so'zma-so'z tarjima qilmang: ~~make a conclusion~~, ~~do a role~~.","So'z oilasi: significant / significance / significantly, controversial / controversy, imply / implication. Ot oldidan sifat, fe'l oldidan ravish kerak.","Raise (o'tkazma: raised concerns) va rise (o'timsiz: prices rise) ni aralashtirmang."]},{"id":"u28-l6","slug":"structuring-an-argument","title":"Structuring an argument","titleUz":"Fikrni tuzish: introduction, thesis, topic sentence, examples, conclusion","goal":"Essay va nutqda fikrni izchil tuzasiz: introduction (hook, background, thesis), body paragraph (topic sentence, explanation, example, link), counter-argument va refutation, conclusion. Signposting iboralarini (Firstly, Moreover, Admittedly, On the contrary, In conclusion) o'rnida ishlatasiz va At last, In my opinion I think, Because of this reason kabi xatolardan qochasiz.","words":[{"en":"thesis","uz":"tezis, asosiy da'vo","ipa":"ˈθiː.sɪs"},{"en":"counter-argument","uz":"qarshi dalil","ipa":"ˈkaʊn.tə ˌɑː.ɡjə.mənt"},{"en":"refute","uz":"rad etmoq, isbotlab inkor qilmoq","ipa":"rɪˈfjuːt"},{"en":"rebuttal","uz":"rad javobi","ipa":"rɪˈbʌt.əl"},{"en":"coherent","uz":"izchil, mantiqan bog'langan","ipa":"kəʊˈhɪə.rənt"},{"en":"elaborate","uz":"batafsil ochib bermoq","ipa":"ɪˈlæb.ə.reɪt"},{"en":"persuasive","uz":"ishontiruvchi","ipa":"pəˈsweɪ.sɪv"},{"en":"assert","uz":"qat'iy da'vo qilmoq","ipa":"əˈsɜːt"},{"en":"concede","uz":"tan olmoq, ruxsat bermoq (haqligini)","ipa":"kənˈsiːd"},{"en":"signpost","uz":"matnda yo'l ko'rsatuvchi ibora","ipa":"ˈsaɪn.pəʊst"}],"summary":["Essay tuzilishi: Introduction (hook, background, thesis) → Body 1–2 (topic sentence, explanation, example, link) → counter-argument + refutation → Conclusion.","Thesis — bitta aniq, bahsli gap. Body paragraph — bitta fikr; PEEL: Point, Explanation, Example, Link. Dalilsiz da'vo ishontirmaydi (elaborate).","Qarshi fikr: concede → refute (Admittedly, … However, …). Xulosa: thesis yangi so'zlar bilan, yangi dalilsiz.","Signpost: Firstly, Moreover, For example, However, Therefore, In conclusion. Xatolar: ~~At last~~, ~~In my opinion I think~~, ~~Firstly of all~~, ~~Because of this reason~~."]},{"id":"u28-l14","slug":"listening-and-speaking-a-lecture-and-a-long-turn","title":"Listening and speaking: a lecture and a long turn","titleUz":"Tinglash va gapirish: ma'ruza va 2 daqiqalik nutq","goal":"Qisqa ma'ruzani tinglab qaydlar yozasiz (sabablar, muammolar, misollar), ma'ruzachining signposting iboralarini ajratasiz va Is it better to live in a city or in the countryside? mavzusida 1-2 daqiqalik nutqni aniq tuzilma bilan aytasiz.","words":[{"en":"urbanisation","uz":"shaharlashuv","ipa":"ˌɜː.bən.aɪˈzeɪ.ʃən"},{"en":"rural","uz":"qishloq (joyga oid)","ipa":"ˈrʊə.rəl"},{"en":"sprawl","uz":"shaharning tartibsiz yoyilishi","ipa":"sprɔːl"},{"en":"migration","uz":"ko'chish, migratsiya","ipa":"maɪˈɡreɪ.ʃən"},{"en":"anonymity","uz":"noma'lumlik, anonimlik","ipa":"ˌæn.əˈnɪm.ə.ti"},{"en":"isolation","uz":"yakkalanib qolish","ipa":"ˌaɪ.səˈleɪ.ʃən"}],"summary":["Ma'ruzada hamma so'zni emas, kalit so'z va tuzilma belgilarini yozing (first, second, however, meanwhile, next week).","Qaydlar jadvali: Topic, Causes, Problems, Next. Sabablarni sonini eshiting (three main reasons).","Uzoq nutq: pozitsiya → dalil 1 → dalil 2 → qarshi fikr + rad etish → xulosa (Admittedly… Nevertheless… To sum up…).","Urg'u uchun bitta Not only … but also yoki What matters most is… yetarli. In my opinion I think demang.","Yangi so'zlar: urbanisation, rural, sprawl, migration, anonymity, isolation."]},{"id":"u28-l10","slug":"disagreeing-politely","title":"Disagreeing politely","titleUz":"Muloyim qarshi chiqish va o'z fikrida turish","goal":"Hamkasb yoki do'stingizning taklifiga ziddiyatsiz qarshi chiqasiz: fikrni yumshatasiz (I see what you mean, but…), qisman rozilik bildirasiz, muqobil taklif qilasiz va o'z pozitsiyangizda muloyim turib olasiz. Kerakli joyda What worries me is… va Not only would… bilan urg'u berasiz.","words":[{"en":"tactful","uz":"xushmuomala, ehtiyotkor (gapirishda)","ipa":"ˈtækt.fəl"},{"en":"objection","uz":"e'tiroz","ipa":"əbˈdʒek.ʃən"},{"en":"common ground","uz":"umumiy til, kelishuv nuqtasi","ipa":"ˌkɒm.ən ˈɡraʊnd"},{"en":"take on board","uz":"inobatga olmoq, qabul qilmoq (maslahatni)","ipa":"teɪk ɒn ˈbɔːd"},{"en":"stand firm","uz":"pozitsiyada qat'iy turmoq","ipa":"stænd ˈfɜːm"},{"en":"hesitant","uz":"ikkilanayotgan, tortinayotgan","ipa":"ˈhez.ɪ.tənt"}],"summary":["Muloyim qarshi chiqish qadamlari: tushunish (I see what you mean) → qisman rozilik → yumshoq qarshi fikr (I'm afraid I can't quite agree) → muqobil (How about…?).","Urg'u uchun: What worries me is…, It's the timing that…, Not only would it…, but…, All I'm saying is…","Pozitsiyada turish: I understand, but I'd still prefer…, Let's agree to differ. Ton yumshoq, fikr o'zgarmaydi.","Xatolar: agree you → agree with you; different opinion → a different opinion; Why not we…? → Why don't we…?; sure to agree → sure I agree.","Yangi so'zlar: tactful, objection, common ground, take on board, stand firm, hesitant."]},{"id":"u28-l7","slug":"writing-a-for-and-against-and-opinion-essay","title":"Writing: a for-and-against and opinion essay","titleUz":"Yozish: 'for and against' va opinion essay (250 so'z)","goal":"IELTS Writing Task 2 uslubidagi 250 so'zli essay yozasiz: 5 daqiqada reja tuzasiz, opinion va for-and-against savollarini farqlaysiz, bog'lovchilar (although, despite, consequently), cleft va inversiya orqali urg'u berasiz, fikrni hedging (tend to, arguably, to some extent) bilan yumshatasiz va band 6.5 ro'yxati bo'yicha o'zingizni tekshirasiz.","words":[{"en":"arguably","uz":"bahslashsa bo'ladigan darajada, ehtimol","ipa":"ˈɑː.ɡju.ə.bli"},{"en":"plausible","uz":"ishonarli, ehtimolga yaqin","ipa":"ˈplɔː.zə.bəl"},{"en":"hedge","uz":"fikrni yumshatmoq (ehtiyotkorona ifodalamoq)","ipa":"hedʒ"},{"en":"on balance","uz":"hammasini tortib ko'rganda","ipa":"ɒn ˈbæl.əns"},{"en":"to some extent","uz":"ma'lum darajada","ipa":"tə sʌm ɪkˈstent"},{"en":"the vast majority","uz":"aksariyat ko'pchilik","ipa":"ðə vɑːst məˈdʒɒr.ə.ti"},{"en":"tend to","uz":"…ga moyil bo'lmoq, odatda …","ipa":"tend tuː"},{"en":"rephrase","uz":"boshqacha so'zlar bilan ifodalamoq","ipa":"ˌriːˈfreɪz"},{"en":"concise","uz":"ixcham, aniq","ipa":"kənˈsaɪs"},{"en":"cohesion","uz":"bog'lanish, uyg'unlik","ipa":"kəʊˈhiː.ʒən"}],"summary":["Task 2: 40 daqiqa — 5 reja, 30 yozish, 5 tekshirish; 250+ so'z. Savolning barcha qismiga javob bering (opinion, for-and-against).","Rejada: pozitsiya, 2 ta dalil + misol, qarshi fikr + refutation. Har paragrafda topic sentence, misol va link.","Urg'u: although, despite, consequently; 1–2 ta cleft yoki inversiya. Ortiqcha murakkablik tabiiylikni buzadi.","Hedging: tend to, arguably, may, to some extent, the vast majority, on balance. Xatolar: ~~I am agree~~, ~~All teenagers~~, ~~The reason is because~~, ~~From one hand~~."]},{"id":"u28-l15","slug":"reading-and-writing-improving-a-model-essay","title":"Reading and writing: improving a model essay","titleUz":"O'qish va yozish: essay namunasini tahlil qilish va yaxshilash","goal":"Zaif essayni o'qib, uning kamchiliklarini topasiz (takror, zaif bog'lanish, mavzudan chetga chiqish, qamrovli da'vo, noaniq so'zlar), keyin xulosani (60 so'z) va bitta paragrafni qayta yozasiz.","words":[{"en":"repetitive","uz":"takroriy, bir xil","ipa":"rɪˈpet.ə.tɪv"},{"en":"vague","uz":"noaniq, tumanli","ipa":"veɪɡ"},{"en":"irrelevant","uz":"mavzuga aloqasiz","ipa":"ɪˈrel.ə.vənt"},{"en":"wordy","uz":"ortiqcha so'zli","ipa":"ˈwɜː.di"},{"en":"digress","uz":"mavzudan chetga chiqmoq","ipa":"daɪˈɡres"},{"en":"sweeping","uz":"qamrovli, umumlashtirilgan","ipa":"ˈswiː.pɪŋ"}],"summary":["Essayni tekshirishda kamchiliklar: repetitive, vague, wordy, irrelevant, sweeping va bog'lovchilarning yo'qligi.","Mavzuga aloqasiz gapni o'chiring (digress qilmang); har gap savolga javob bersin.","Qamrovli da'voni yumshating: Most children tend to…, It is widely believed that….","Xulosa (taxminan 60 so'z): To sum up + pozitsiya + asosiy dalillar (Although… outweigh) + yangi dalilsiz.","Yangi so'zlar: repetitive, vague, irrelevant, wordy, digress, sweeping."]},{"id":"u28-l8","slug":"unit-review-argument-and-emphasis","title":"Unit review: argument and emphasis","titleUz":"Bosqich takrori: dalil, urg'u va bog'lovchilar","goal":"Bosqichni takrorlaysiz: cleft gaplar (It was … that, What I need is), inversiya (Never have I, Not only did, Had I known), qarama-qarshi bog'lovchilar (although, despite, however, whereas), sabab, natija va maqsad (owing to, consequently, so … that, so as not to), akademik lug'at, essay tuzilishi va hedging. Hammasini yangi misollarda tekshirasiz va birgalikda ishlatasiz.","words":[{"en":"advocate","uz":"targ'ib qilmoq, qo'llab-quvvatlamoq","ipa":"ˈæd.və.keɪt"},{"en":"bolster","uz":"mustahkamlamoq, kuchaytirmoq","ipa":"ˈbəʊl.stə"},{"en":"underlying","uz":"asosiy, tub (yashirin)","ipa":"ˌʌn.dəˈlaɪ.ɪŋ"},{"en":"rationale","uz":"asos, mantiqiy tushuntirish","ipa":"ˌræʃ.əˈnɑːl"},{"en":"stance","uz":"pozitsiya, qarash","ipa":"stæns"},{"en":"premise","uz":"dastlabki asos, shart","ipa":"ˈprem.ɪs"},{"en":"oversimplify","uz":"haddan tashqari soddalashtirmoq","ipa":"ˌəʊ.vəˈsɪm.plɪ.faɪ"},{"en":"nuance","uz":"nozik farq, nuans","ipa":"ˈnjuː.ɑːns"},{"en":"compelling","uz":"ishontiruvchi, kuchli","ipa":"kəmˈpel.ɪŋ"},{"en":"rhetorical","uz":"ritorik, ta'sir qilish uchun","ipa":"rɪˈtɒr.ɪ.kəl"}],"summary":["Cleft: It was … that/who …, What I need is …, All I want is …. Ortiqcha olmosh yo'q (~~What I need it is~~).","Inversiya: salbiy so'z + yordamchi + ega (Never have I, Rarely does he, Not only did, Hardly had … when, Had I known).","Bog'lovchilar: although + gap, despite + ot/-ing, however, nevertheless; sabab because / because of / owing to; natija so / consequently / so … that; maqsad to / so as not to / so that.","Dalil va essay: thesis, topic sentence, misol, qarshi fikr + rad etish, xulosa; akademik collocation (draw a conclusion, raise concerns); hedging (tend to, arguably)."]},{"id":"u28-l11","slug":"argument-and-emphasis-final-review","title":"Argument and emphasis: final review","titleUz":"Dalil va urg'u: yakuniy takror","goal":"Bosqichdagi hamma mavzuni takrorlaysiz: cleft gaplar, inversiya, qarama-qarshi va sabab-natija bog'lovchilari, sifatdosh gaplari va essay iboralari. Dalil bilan gapirish uchun 6 ta yangi so'z ham o'rganasiz.","words":[{"en":"viable","uz":"amalga oshiriladigan, maqbul","ipa":"ˈvaɪ.ə.bəl"},{"en":"undeniable","uz":"inkor etib bo'lmaydigan","ipa":"ˌʌn.dɪˈnaɪ.ə.bəl"},{"en":"thrive","uz":"gullab-yashnamoq, muvaffaqiyatli rivojlanmoq","ipa":"θraɪv"},{"en":"flawed","uz":"kamchiligi bor, xato","ipa":"flɔːd"},{"en":"disparity","uz":"katta tafovut, nomutanosiblik","ipa":"dɪˈspær.ə.ti"},{"en":"notable","uz":"diqqatga sazovor, sezilarli","ipa":"ˈnəʊ.tə.bəl"}],"summary":["Cleft: It was … that / who …, What I need is …, All I want is …; emphatic do (I did warn you), so / such. Ortiqcha olmosh yo'q.","Inversiya: salbiy so'z + yordamchi + ega (Never have I, Rarely does she, Not only was he, Hardly had … when, Had I known).","Bog'lovchilar: although + gap, despite + ot / -ing, nevertheless; because of / owing to, consequently; so as not to.","Sifatdosh gapi: -ing, V3, having + V3; ega bir xil bo'lsin (Walking home, I…).","Yangi so'zlar: viable, undeniable, thrive, flawed, disparity, notable."]}]},{"id":"u29","n":29,"title":"Environment, health and the modern world","titleUz":"Atrof-muhit, salomatlik va zamonaviy dunyo: taqqoslash, miqdor, artikl, grafik tavsifi","description":"Taqqoslash B2, miqdor so'zlari, artikl va aniqlovchilar, sifat va ravish, so/such/too/enough, atrof-muhit va salomatlik lug'ati, grafik va ma'lumotlarni tasvirlash.","canDo":["Ikki narsani aniq solishtiraman (far cheaper, the more… the better, twice as expensive as)","Miqdor so'zlarini to'g'ri kelishuv bilan ishlataman (a great deal of, hardly any, the number of / a number of)","Atrof-muhit va salomatlik haqida gapiraman va shifokorga simptomlarni tushuntiraman","Grafik yoki jadvalni 150 so'zli hisobotda tasvirlayman (overview, from … to, by, per cent)"],"lessons":[{"id":"u29-l1","slug":"comparison-at-b2","title":"Comparison at B2","titleUz":"Taqqoslash B2: the more… the more, twice as… as, far / considerably + comparative","goal":"Taqqoslashni B2 darajasida ishlatasiz: far / considerably / slightly + comparative bilan farq kattaligini aytasiz, the more… the more bilan o'zaro bog'liqlikni ifodalaysiz, twice as… as, half as many as bilan miqdorni solishtirasiz va more better, than me am, very bigger kabi xatolardan qochasiz. Bu ish hisobotlari, suhbat va IELTS Writing uchun juda kerak.","words":[{"en":"substantially","uz":"sezilarli darajada, anchagina","ipa":"səbˈstæn.ʃəl.i"},{"en":"marginally","uz":"ozgina, arzimas darajada","ipa":"ˈmɑː.dʒɪ.nəl.i"},{"en":"significantly","uz":"muhim darajada, ancha","ipa":"sɪɡˈnɪf.ɪ.kənt.li"},{"en":"roughly","uz":"taxminan","ipa":"ˈrʌf.li"},{"en":"outnumber","uz":"sonda oshib ketmoq","ipa":"ˌaʊtˈnʌm.bə"},{"en":"exceed","uz":"oshib ketmoq, chegaradan o'tmoq","ipa":"ɪkˈsiːd"},{"en":"surpass","uz":"ustun kelmoq, o'tib ketmoq","ipa":"səˈpɑːs"},{"en":"ratio","uz":"nisbat","ipa":"ˈreɪ.ʃi.əʊ"},{"en":"gap","uz":"farq, tafovut","ipa":"ɡæp"},{"en":"in comparison with","uz":"…ga nisbatan, …bilan solishtirganda","ipa":"ɪn kəmˈpær.ɪ.sən wɪð"}],"summary":["Farq darajasi: far / much / considerably / substantially (katta), slightly / marginally / a bit (kichik) + comparative. Very ishlatilmaydi.","The + comparative, the + comparative (The more you read, the better you write). Davomli o'zgarish: more and more, colder and colder.","Ko'paytiruvchi: twice / three times / half as … as (half as much, half as many). Fewer + sanaladigan, less + sanalmaydigan.","Xatolar: ~~more better~~, ~~very bigger~~, ~~taller from me~~, ~~Less people~~ → better, much bigger, taller than me, Fewer people."]},{"id":"u29-l12","slug":"superlatives-and-expressions-of-degree","title":"Superlatives and expressions of degree","titleUz":"Superlative va daraja ifodalari: by far, nowhere near, as… as ever, not quite","goal":"Superlativeni B2 darajasida ishlatasiz (by far the most, one of the + ko'plik, the second largest, the best … I've ever seen), daraja ifodalarini (nowhere near, not nearly, rather, barely, no sooner … than) aniq tanlaysiz va ularning kuchini farqlaysiz.","words":[{"en":"nowhere near","uz":"yaqin ham emas, juda uzoq","ipa":"ˌnəʊweə ˈnɪə"},{"en":"not nearly","uz":"unchalik emas, ancha kam","ipa":"nɒt ˈnɪəli"},{"en":"barely","uz":"zo'rg'a, arang","ipa":"ˈbeəli"},{"en":"rather","uz":"ancha, birmuncha","ipa":"ˈrɑːðə"},{"en":"no sooner","uz":"... bilan bir vaqtda (no sooner … than)","ipa":"nəʊ ˈsuːnə"}],"summary":["Superlative: the + -est / the most, kuchaytirish by far / easily, one of the + ko'plik, the second largest; in (joy) va of (guruh) bilan.","Tajriba: the best … I've ever seen (Present Perfect + ever).","Daraja: nowhere near / not nearly as … as (juda uzoq), barely / hardly (zo'rg'a), almost / nearly (deyarli), rather / quite (ancha / yetarlicha).","Rasmiy: No sooner had + ega + V3 + than …, Hardly had … when … (inversiya).","Yangi so'z va iboralar: nowhere near, not nearly, barely, rather, no sooner."]},{"id":"u29-l2","slug":"quantifiers-and-agreement","title":"Quantifiers and agreement","titleUz":"Miqdor so'zlari: a great deal of, a majority of, hardly any, the number of / a number of","goal":"Miqdor so'zlarini sanaladigan va sanalmaydigan otlar bilan to'g'ri tanlaysiz (a great deal of, plenty of, a handful of, hardly any, few / a few), the number of / a number of farqini bilasiz, the majority of people are va each of the students has kabi gaplarda fe'lni to'g'ri moslashtirasiz va foiz hamda kasrlarni ishlatasiz.","words":[{"en":"majority","uz":"ko'pchilik","ipa":"məˈdʒɒr.ə.ti"},{"en":"minority","uz":"ozchilik","ipa":"maɪˈnɒr.ə.ti"},{"en":"proportion","uz":"ulush, nisbat","ipa":"prəˈpɔː.ʃən"},{"en":"negligible","uz":"arzimas, e'tiborga olmasa ham bo'ladigan","ipa":"ˈneɡ.lɪ.dʒə.bəl"},{"en":"a handful of","uz":"bir hovuch, juda oz sondagi","ipa":"ə ˈhænd.fʊl əv"},{"en":"shortage","uz":"tanqislik, yetishmovchilik","ipa":"ˈʃɔː.tɪdʒ"},{"en":"surplus","uz":"ortiqcha miqdor, ortiqcha","ipa":"ˈsɜː.pləs"},{"en":"sufficient","uz":"yetarli","ipa":"səˈfɪʃ.ənt"},{"en":"scarce","uz":"kamyob, tanqis","ipa":"skeəs"},{"en":"abundant","uz":"mo'l, serob","ipa":"əˈbʌn.dənt"}],"summary":["Sanaladigan: many, a few / few, fewer, a number of, a handful of. Sanalmaydigan: much, a little / little, less, a great deal of. Ikkalasi: a lot of, plenty of, hardly any.","A few / a little — yetarli (ijobiy); few / little / hardly any — kam (salbiy). Hardly any bilan not ishlatilmaydi.","The number of + birlik fe'l (is); a number of + ko'plik fe'l (are). Each of → birlik; the majority of + ko'plik ot → ko'plik.","Foiz va kasrlarda fe'l of dan keyingi otga moslashadi: a quarter of the water is, forty per cent of the students are.","Xatolar: ~~much people~~, ~~informations~~, ~~the number are~~, ~~each have~~."]},{"id":"u29-l3","slug":"articles-and-determiners-advanced","title":"Articles and determiners (advanced)","titleUz":"Artikl va aniqlovchilar B2: umumiy the, zero article, such a, quite a, what a","goal":"Artikllarni B2 darajasida ishlatasiz: umumiy fikr (tigers, the tiger, the elderly, the internet), joy nomlari (the Alps, Lake Baikal), muassasalar (in hospital / the hospital), such a / what a / quite a / half an hour, shuningdek another, other, others, the other, each, every, all farqini bilasiz va a good news kabi tipik xatolardan qochasiz.","words":[{"en":"species","uz":"tur (biologik)","ipa":"ˈspiː.ʃiːz"},{"en":"habitat","uz":"yashash muhiti","ipa":"ˈhæb.ɪ.tæt"},{"en":"ecosystem","uz":"ekotizim","ipa":"ˈiː.kəʊˌsɪs.təm"},{"en":"endangered","uz":"yo'qolish xavfi ostidagi","ipa":"ɪnˈdeɪn.dʒəd"},{"en":"institution","uz":"muassasa, tashkilot","ipa":"ˌɪn.stɪˈtjuː.ʃən"},{"en":"generation","uz":"avlod","ipa":"ˌdʒen.əˈreɪ.ʃən"},{"en":"the elderly","uz":"keksalar","ipa":"ðə ˈel.dəl.i"},{"en":"the homeless","uz":"uysizlar","ipa":"ðə ˈhəʊm.ləs"},{"en":"the public","uz":"keng jamoatchilik","ipa":"ðə ˈpʌb.lɪk"},{"en":"the media","uz":"ommaviy axborot vositalari","ipa":"ðə ˈmiː.di.ə"}],"summary":["Umumiy fikr: ko'plik artiklsiz (Tigers are…), the + birlik (The tiger is…), the + sifat odamlar guruhi (the elderly).","The bilan: daryo, dengiz, tog' tizmasi, ko'plik davlatlar (the Alps, the Netherlands). Artiklsiz: bitta tog', ko'l, qit'a, ko'pchilik davlatlar. In hospital / at school — vazifasi; the hospital — bino.","Such a + sifat + ot, what a + sifat + ot!, quite a, half an hour, twice a week: artikl sifatdan oldin emas, keyin.","Another + birlik; other + ko'plik; others, the other(s); each / every / all; this / that matnda fikrni bog'laydi.","Xatolar: ~~The life~~, ~~a good news~~, ~~a such~~, ~~Aral Sea~~ → Life, good news, such a, the Aral Sea."]},{"id":"u29-l4","slug":"adjectives-adverbs-and-modifying","title":"Adjectives, adverbs and modifying","titleUz":"Sifat va ravishlar: tartib, kuchaytirish, ravish o'rni","goal":"Sifat va ravishlarni B2 darajasida ishlatasiz: sifatlar tartibi (a beautiful old stone bridge), gradable / non-gradable sifatlarni to'g'ri kuchaytirasiz (very good, absolutely wonderful), ravishning o'rni va ma'nosi o'zgargan ravishlarni (hard / hardly, late / lately), compound adjectives (a ten-minute walk) va the + sifat ni bilasiz hamda speaks English good, a ten-minutes walk kabi xatolardan qochasiz.","words":[{"en":"short-term","uz":"qisqa muddatli","ipa":"ˌʃɔːtˈtɜːm"},{"en":"eco-friendly","uz":"ekologik toza, tabiatga zarar keltirmaydigan","ipa":"ˌiː.kəʊˈfrend.li"},{"en":"user-friendly","uz":"foydalanishga qulay","ipa":"ˌjuː.zəˈfrend.li"},{"en":"time-consuming","uz":"ko'p vaqt oladigan","ipa":"ˈtaɪm kənˌsjuː.mɪŋ"},{"en":"thought-provoking","uz":"o'ylantiradigan","ipa":"ˈθɔːt prəˌvəʊ.kɪŋ"},{"en":"far-reaching","uz":"uzoqqa boruvchi, keng ko'lamli","ipa":"ˌfɑːˈriː.tʃɪŋ"},{"en":"hands-on","uz":"amaliy, bevosita ishtirokli","ipa":"ˌhændzˈɒn"},{"en":"utterly","uz":"butunlay, mutlaqo","ipa":"ˈʌt.ə.li"},{"en":"absolutely","uz":"mutlaqo, butunlay","ipa":"ˈæb.sə.luːt.li"},{"en":"fairly","uz":"ancha, ma'lum darajada","ipa":"ˈfeə.li"}],"summary":["Gradable (good, cold, tired) → very, extremely, fairly, rather. Non-gradable (wonderful, freezing, exhausted) → absolutely, utterly, completely.","Sifatlar tartibi: fikr → o'lcham → yosh → shakl → rang → kelib chiqish → material → maqsad (a beautiful old stone bridge).","Ravish o'rni: boshida (Fortunately,), o'rtada (always, rarely), oxirida (carefully). Hard / hardly, late / lately, high / highly — ma'nosi boshqa.","Compound adjective: son + birlik (a ten-minute walk), user-friendly, time-consuming. Good — sifat, well — ravish."]},{"id":"u29-l13","slug":"so-such-too-and-enough","title":"So, such, too and enough","titleUz":"So, such, too, enough, (not) as… as: daraja va yetarlilik","goal":"so / such (kuchli daraja va natija), too (ortiqcha, salbiy) va enough (yetarlilik) so'zlarini to'g'ri o'rinda ishlatasiz: so tired that…, such a long queue, too hot to walk, not big enough, enough water.","words":[{"en":"insufficient","uz":"yetarli emas, yetmaydigan","ipa":"ˌɪn.səˈfɪʃ.ənt"},{"en":"adequate","uz":"yetarli, qoniqarli","ipa":"ˈædɪkwət"},{"en":"excessive","uz":"haddan tashqari","ipa":"ɪkˈsesɪv"},{"en":"dwindle","uz":"kamayib bormoq, ozayib bormoq","ipa":"ˈdwɪn.dəl"},{"en":"ample","uz":"yetarli va mo'l, bemalol yetadigan","ipa":"ˈæm.pəl"}],"summary":["so + sifat/ravish (so tired), so many / so much + ot; such (a) + sifat + ot (such a long queue). Natija: that.","too + sifat — ortiqcha va salbiy (too cold to swim); enough sifatdan keyin (big enough), otdan oldin (enough water).","not enough va too ma'nosi yaqin, lekin too kuchliroq va salbiyroq; very … to deb bo'lmaydi.","Xatolar: enough big → big enough; so a nice day → such a nice day; too much cars → too many cars.","Yangi so'zlar: insufficient, adequate, excessive, dwindle, ample."]},{"id":"u29-l9","slug":"at-the-doctors","title":"At the doctor's","titleUz":"Shifokorda: simptomlarni tasvirlash va maslahat olish","goal":"Shifokor qabulida simptomlarni aniq tasvirlaysiz (I've had a sore throat for three days), davomiylikni for / since bilan aytasiz, hardly any / a few / very little bilan miqdorni bildirasiz va shifokorning maslahatini (You should… / I'd recommend… / You'd better…) tushunib, savol bera olasiz.","words":[{"en":"prescribe","uz":"(dori) yozib bermoq","ipa":"prɪˈskraɪb"},{"en":"dizzy","uz":"boshi aylangan","ipa":"ˈdɪzi"},{"en":"dose","uz":"doza, bir martalik miqdor","ipa":"dəʊs"},{"en":"infection","uz":"infeksiya, yuqumli kasallik","ipa":"ɪnˈfekʃn"},{"en":"ointment","uz":"malham","ipa":"ˈɔɪntmənt"},{"en":"pharmacist","uz":"dorixonachi, farmatsevt","ipa":"ˈfɑːməsɪst"}],"summary":["Simptom hozirgacha davom etayotgan bo'lsa: Present Perfect + for (muddat) yoki since (boshlanish): I've had a cough for a week / since Monday.","Miqdor: a few / few (sanaladigan), a little / little (sanalmaydigan), hardly any = deyarli yo'q. A few, a little ijobiy; few, little salbiy.","Maslahat: You should… / I'd recommend… / You'd better… + to'siz fe'l; to yo'q.","Xatolar: I have a cough since Monday → I've had a cough since Monday; should to rest → should rest; a few energy → very little energy.","Yangi so'zlar: prescribe, dizzy, dose, infection, ointment, pharmacist."]},{"id":"u29-l5","slug":"environment-and-health","title":"Environment and health","titleUz":"Atrof-muhit va salomatlik: so'zlar va birikmalar (carbon footprint, sustainable, diet)","goal":"Atrof-muhit va salomatlik mavzusida 10 ta B2 so'z va ularning birikmalarini (reduce waste, take exercise, suffer from, raise awareness) o'rganasiz, so'z oilalarini (conserve – conservation, nutrition – nutritious) bilasiz, bu mavzudagi tipik xatolardan (suffer of, make sport, the nature) qochasiz va IELTS Speaking / Writing da shu so'zlarni tabiiy ishlatasiz.","words":[{"en":"carbon footprint","uz":"uglerod izi","ipa":"ˌkɑː.bən ˈfʊt.prɪnt"},{"en":"renewable","uz":"qayta tiklanadigan","ipa":"rɪˈnjuː.ə.bəl"},{"en":"wildlife","uz":"yovvoyi tabiat","ipa":"ˈwaɪld.laɪf"},{"en":"sedentary","uz":"kam harakatli, o'tirib ishlaydigan","ipa":"ˈsed.ən.tri"},{"en":"immune system","uz":"immunitet tizimi","ipa":"ɪˈmjuːn ˌsɪs.təm"},{"en":"chronic","uz":"surunkali","ipa":"ˈkrɒn.ɪk"},{"en":"nutrition","uz":"oziqlanish","ipa":"njuːˈtrɪʃ.ən"},{"en":"deplete","uz":"tugatmoq, kamaytirmoq","ipa":"dɪˈpliːt"},{"en":"conserve","uz":"asramoq, tejamoq","ipa":"kənˈsɜːv"},{"en":"biodiversity","uz":"biologik xilma-xillik","ipa":"ˌbaɪ.əʊ.daɪˈvɜː.sə.ti"}],"summary":["Atrof-muhit: carbon footprint, renewable, wildlife, deplete, conserve. biodiversity. Salomatlik: sedentary, immune system, chronic, nutrition.","Birikmalar: reduce waste / cut emissions, protect wildlife, raise awareness, take exercise, suffer from, make a difference.","So'z oilalari: conserve – conservation, nutrition – nutritious, renew – renewable, health – healthy – healthily.","Xatolar: ~~suffer of~~, ~~make sport~~, ~~the nature~~, ~~eat healthy~~ → suffer from, do sport, nature, eat healthily."]},{"id":"u29-l6","slug":"describing-graphs-and-data","title":"Describing graphs and data","titleUz":"Grafik va ma'lumotlarni tasvirlash: trend tili, taqqoslash, raqamlar (IELTS Task 1 ko'prigi)","goal":"Jadval, chiziqli grafik va doira diagramma (pie chart) ni inglizcha tasvirlaysiz: trend fe'llari va otlari (rise, fluctuate, peak, plummet), daraja va tezlik ravishlari (sharply, gradually, slightly), raqam predloglari (rose from… to…, by, at), ulush (a quarter, 40 per cent, the majority) va overview gapini tuzasiz. Bu IELTS Task 1 va ish hisobotlariga bevosita ko'prik.","words":[{"en":"fluctuate","uz":"tebranib turmoq, o'zgarib turmoq","ipa":"ˈflʌk.tʃu.eɪt"},{"en":"plummet","uz":"keskin pasaymoq","ipa":"ˈplʌm.ɪt"},{"en":"soar","uz":"keskin ko'tarilmoq","ipa":"sɔː"},{"en":"peak","uz":"eng yuqori nuqtaga yetmoq; cho'qqi","ipa":"piːk"},{"en":"level off","uz":"barqarorlashmoq, o'zgarmay qolmoq","ipa":"ˌlev.əl ˈɒf"},{"en":"surge","uz":"keskin ko'tarilmoq, to'lqin","ipa":"sɜːdʒ"},{"en":"dip","uz":"ozgina pasaymoq; ozgina pasayish","ipa":"dɪp"},{"en":"account for","uz":"…ni tashkil qilmoq","ipa":"əˈkaʊnt fɔː"},{"en":"upward trend","uz":"o'sish tendensiyasi","ipa":"ˌʌp.wəd ˈtrend"},{"en":"remain stable","uz":"barqaror qolmoq","ipa":"rɪˌmeɪn ˈsteɪ.bəl"}],"summary":["Tavsif tuzilmasi: kirish → overview → asosiy bo'lim 1 → asosiy bo'lim 2. Overview'da raqamlarsiz umumiy tendensiya.","Trend fe'llari: rise, climb, soar, surge / fall, dip, plummet / fluctuate / level off, remain stable / peak. Trend ma'nosida hammasi o'timsiz, passive emas.","Raqam predloglari: from … to …, by (o'zgarish miqdori), to (oxirgi qiymat), at (daraja, cho'qqi), between … and ….","Ulush: account for, make up, the majority, a quarter, nearly half, one in five. Per cent hech qachon -s olmaydi."]},{"id":"u29-l14","slug":"listening-and-speaking-a-science-lecture","title":"Listening and speaking: a science lecture","titleUz":"Tinglash va gapirish: ilmiy ma'ruza — konspekt yuritish va qisqacha aytib berish","goal":"Qisqa ilmiy ma'ruzani tinglab asosiy fikrlar va tafsilotlarni konspektga yozasiz, ma'ruzachining signposting iboralarini (First…, Another point…, To sum up…) tanib olasiz va ma'ruzani 1 daqiqada o'z so'zlaringiz bilan ayta olasiz.","words":[{"en":"urban","uz":"shahar, shaharga oid","ipa":"ˈɜːbən"},{"en":"canopy","uz":"daraxt shox-barglari (tepa qismi)","ipa":"ˈkænəpi"},{"en":"absorb","uz":"yutmoq, o'ziga singdirmoq","ipa":"əbˈzɔːb"},{"en":"shade","uz":"soya","ipa":"ʃeɪd"},{"en":"wellbeing","uz":"farovonlik, o'zini yaxshi his qilish","ipa":"ˈwelbiːɪŋ"}],"summary":["Tinglashdan oldin ma'ruzachining rejasini toping (I'll make three main points), keyin kalit so'z va raqamlarni konspektga yozing.","Signposting: First, Second, Third, Another point is that, To sum up, In conclusion. Ular fikrlar o'rnini ko'rsatadi.","Qisqacha mazmun: mavzu → 3 asosiy fikr → xulosa; 80–100 so'z, o'z so'zlaringiz bilan.","Xatolar: explained us → explained to us; told that → said that / told us that; The lecture is talking → The lecture is about.","Yangi so'zlar: urban, canopy, absorb, shade, wellbeing."]},{"id":"u29-l10","slug":"discussing-a-solution-to-a-problem","title":"Discussing a solution to a problem","titleUz":"Muammoning yechimini muhokama qilish: tavsiya va ustuvorlik","goal":"Mahalla yig'ilishida taklif berasiz (I'd like to propose… / One option would be to…), variantlarni taqqoslaysiz (far cheaper than, much more effective than), ustuvorlikni belgilaysiz (The most important thing is…) va umumiy rejaga kelishasiz.","words":[{"en":"litter","uz":"axlat (ko'chada tashlab ketilgan)","ipa":"ˈlɪtə"},{"en":"congestion","uz":"tirbandlik, gavjumlik","ipa":"kənˈdʒestʃən"},{"en":"proposal","uz":"taklif, loyiha","ipa":"prəˈpəʊzl"},{"en":"enforce","uz":"(qoida, qonunni) amalda qo'llamoq","ipa":"ɪnˈfɔːs"},{"en":"initiative","uz":"tashabbus","ipa":"ɪˈnɪʃətɪv"},{"en":"landfill","uz":"chiqindi poligoni","ipa":"ˈlændfɪl"}],"summary":["Taklif: I'd like to propose… / One option would be to… / Why don't we…?; suggest / propose + -ing yoki that we + to'siz fe'l.","Taqqoslash: far / much / slightly + comparative + than, not as … as, the more …, the less …; more cheaper va very cheaper xato.","Ustuvorlik: The most important thing is to…, First and foremost…, Our top priority should be…; kelishish: Shall we agree…? / Let's do that.","Xatolar: suggest to put → suggest putting; more effective that → more effective than; the most important is → the most important thing is.","Yangi so'zlar: litter, congestion, proposal, enforce, initiative, landfill."]},{"id":"u29-l7","slug":"writing-a-report-describing-data","title":"Writing: a report describing data","titleUz":"Yozish: ma'lumotlar bo'yicha hisobot (report)","goal":"Jadval yoki diagrammaga qarab 150 so'zli hisobot yozasiz (IELTS Task 1 uslubida, 20 daqiqada): kirish (paraphrase), overview, ikkita asosiy bo'lim, taqqoslash va bog'lovchilar (whereas, respectively, in contrast), shaxsiy fikrsiz va to'g'ri zamon hamda predloglar bilan. Yozgandan keyin tekshiruv ro'yxati bilan xatolarni topasiz.","words":[{"en":"overview","uz":"umumiy ko'rinish, umumlashtirish","ipa":"ˈəʊ.və.vjuː"},{"en":"respectively","uz":"mos ravishda","ipa":"rɪˈspek.tɪv.li"},{"en":"approximately","uz":"taxminan","ipa":"əˈprɒk.sɪ.mət.li"},{"en":"illustrate","uz":"ko'rsatib bermoq, tasvirlamoq","ipa":"ˈɪl.ə.streɪt"},{"en":"category","uz":"toifa, kategoriya","ipa":"ˈkæt.ə.ɡər.i"},{"en":"key feature","uz":"asosiy xususiyat","ipa":"kiː ˈfiː.tʃə"},{"en":"comparable","uz":"taqqoslasa bo'ladigan, o'xshash","ipa":"ˈkɒm.pər.ə.bəl"},{"en":"in terms of","uz":"…jihatdan, …nuqtai nazaridan","ipa":"ɪn tɜːmz əv"},{"en":"noteworthy","uz":"e'tiborga loyiq","ipa":"ˈnəʊtˌwɜː.ði"},{"en":"tendency","uz":"moyillik, yo'nalish","ipa":"ˈten.dən.si"}],"summary":["Hisobot: kirish (paraphrase) → overview → asosiy bo'lim 1 → asosiy bo'lim 2. Kamida 150 so'z, 20 daqiqa. Fikr va keraksiz xulosa yo'q.","Overview: raqamsiz umumiy tendensiya (Overall, … whereas …); eng katta o'zgarishni ko'rsating (the biggest rise was…).","Bog'lash: whereas, by contrast, similarly, as a result, respectively, approximately, in terms of.","Tekshiring: zamon (o'tgan yillar — o'tgan zamon), predlog (from … to, by, at), raqam, per cent."]},{"id":"u29-l15","slug":"reading-and-writing-an-article-about-climate","title":"Reading and writing: an article about climate","titleUz":"O'qish va yozish: iqlim haqida maqola — asosiy fikr va qisqacha mazmun","goal":"Iqlim haqidagi maqolani o'qib, asosiy fikrni topasiz, abzatslarga sarlavha tanlaysiz, True / False / Not given savollariga javob berasiz, so'zlarning ma'nosini kontekstdan taxmin qilasiz va 100-120 so'zli qisqacha mazmun yozasiz.","words":[{"en":"greenhouse gas","uz":"issiqxona gazi","ipa":"ˈɡriːn.haʊs ɡæs"},{"en":"fossil fuel","uz":"qazilma yoqilg'i","ipa":"ˈfɒs.əl ˈfjuː.əl"},{"en":"mitigate","uz":"ta'sirini kamaytirmoq, yumshatmoq","ipa":"ˈmɪt.ɪ.ɡeɪt"},{"en":"adaptation","uz":"moslashish (o'zgargan sharoitga)","ipa":"ˌæd.æpˈteɪ.ʃən"},{"en":"sustainability","uz":"barqarorlik","ipa":"səˌsteɪ.nəˈbɪl.ə.ti"},{"en":"heatwave","uz":"jazirama issiq davri","ipa":"ˈhiːt.weɪv"}],"summary":["O'qishda avval asosiy fikr va har bir abzatsning sarlavhasi; True / False — matn aksini aytadi, Not given — matnda yo'q.","Notanish so'zni kontekstdan taxmin qiling: mitigate the problem by cutting emissions → muammoni yumshatmoq.","Qisqacha mazmun: 100-120 so'z, o'z so'zlaringiz bilan, fikrsiz, Present Simple va bog'lovchilar (as a result, however).","Xatolar: ~~I think…~~ (shaxsiy fikr), nusxa ko'chirish, ~~explained us~~ → explained to us, ~~activity are~~ → activity is.","Yangi so'zlar: greenhouse gas, fossil fuel, mitigate, adaptation, sustainability, heatwave."]},{"id":"u29-l8","slug":"unit-review-comparison-quantity-and-data","title":"Unit review: comparison, quantity and data","titleUz":"Bosqich takrori: taqqoslash, miqdor va ma'lumotlar tavsifi","goal":"Bosqichni takrorlaysiz: taqqoslash (far better, the more… the more, twice as… as), miqdor so'zlari va moslashuv (a great deal of, the number of / a number of), artikl (the elderly, such a, in hospital), sifat va ravish (absolutely wonderful, hard / hardly) va ma'lumotlar tavsifi (rose from… to…, peaked at, account for) ni yangi misollarda tekshirasiz va tipik xatolarni tuzatasiz.","words":[{"en":"deteriorate","uz":"yomonlashmoq","ipa":"dɪˈtɪə.ri.ə.reɪt"},{"en":"drought","uz":"qurg'oqchilik","ipa":"draʊt"},{"en":"alarming","uz":"xavotirli, tashvishli","ipa":"əˈlɑː.mɪŋ"},{"en":"vulnerable","uz":"himoyasiz, zaif","ipa":"ˈvʌl.nər.ə.bəl"},{"en":"threat","uz":"tahdid","ipa":"θret"},{"en":"shrink","uz":"kichrayib bormoq, qisqarmoq","ipa":"ʃrɪŋk"},{"en":"consumption","uz":"iste'mol","ipa":"kənˈsʌmp.ʃən"},{"en":"household","uz":"xonadon, oila xo'jaligi","ipa":"ˈhaʊs.həʊld"},{"en":"per capita","uz":"jon boshiga","ipa":"pə ˈkæp.ɪ.tə"},{"en":"curb","uz":"jilovlamoq, cheklamoq","ipa":"kɜːb"}],"summary":["Taqqoslash: far / much / marginally + comparative; the more… the more; twice / half as … as; fewer + sanaladigan, less + sanalmaydigan; very comparative oldida emas.","Miqdor: a great deal of, hardly any, a handful of; the number of → is, a number of → are, each of → has, foiz/kasr — of dan keyingi otga moslashadi.","Artikl va sifat: the elderly, the Alps, in hospital, such a / what a; gradable → very, non-gradable → absolutely; tartib: fikr → o'lcham → yosh → rang → material.","Ma'lumotlar: kirish → overview → 2 bo'lim; rose from … to …, by, at; account for; o'tgan yil — o'tgan zamon; fikr yo'q."]},{"id":"u29-l11","slug":"environment-health-and-the-modern-world-final-review","title":"Environment, health and the modern world: final review","titleUz":"Atrof-muhit va salomatlik: yakuniy takror","goal":"Bosqichdagi hamma mavzuni takrorlaysiz: taqqoslash, miqdor so'zlari va kelishuv, artikl, sifat va ravish, so / such / too / enough, daraja ifodalari va ma'lumotlarni tasvirlash. Yangi misollarda o'zingizni tekshirasiz va tipik xatolarni tuzatasiz.","words":[{"en":"air quality","uz":"havo sifati","ipa":"ˈeə ˌkwɒl.ə.ti"},{"en":"outbreak","uz":"(kasallik) avj olishi","ipa":"ˈaʊt.breɪk"},{"en":"vaccine","uz":"emlash vaktsinasi","ipa":"ˈvæk.siːn"},{"en":"deforestation","uz":"o'rmonlarning kesilishi","ipa":"diːˌfɒr.ɪˈsteɪ.ʃən"},{"en":"life expectancy","uz":"o'rtacha umr uzunligi","ipa":"laɪf ɪkˈspek.tən.si"}],"summary":["Taqqoslash: far / much + comparative (very yo'q); the more…, the better…; twice as … as; fewer + sanaladigan, less + sanalmaydigan.","Miqdor: the number of → is, a number of → are, hardly any, foiz va kasrda fe'l of dan keyingi otga mos; per cent -s olmaydi.","Artikl va sifat: the elderly, the Aral Sea, such a / what a; tartib: fikr → o'lcham → yosh → rang → material; so, such, too, big enough.","Ma'lumotlar: o'tgan zamon, from … to, by, at, overview raqamsiz, fikr yo'q.","Yangi so'zlar: air quality, outbreak, vaccine, deforestation, life expectancy."]}]},{"id":"u30","n":30,"title":"Culture, ideas and the B2 finish","titleUz":"Madaniyat, g'oyalar va B2 yakuni: idiomalar, ellipsis, nutq oqimi, uzun javob","description":"Idiomalar va collocation, ellipsis, nisbiy gaplar B2, nutq belgilari, savol shakllari, madaniyat va san'at lug'ati, uzun javob berish, taqdimot va B2 yakuniy takrori.","canDo":["Idioma va collocation'larni o'rinli ishlataman (a piece of cake, hit the nail on the head, make a decision, heavy rain)","So do I / Neither can I / I hope so bilan javob beraman va whose, whom, which bilan fikrni boyitaman","Nutq belgilari bilan ravon gapiraman, 2 daqiqalik javob (cue card) va qisqa taqdimot qilaman","250 so'zli sharh yoki hikoya yozaman va mehmonga 100-120 so'zli tavsiya yozaman"],"lessons":[{"id":"u30-l1","slug":"idioms-and-fixed-expressions","title":"Idioms and fixed expressions","titleUz":"Idioma va tayyor iboralar: ishlatilishi va o'zbekcha ekvivalentlari","goal":"10 ta keng tarqalgan idioma (a piece of cake, under the weather, break the ice, the last straw…) ning ma'nosini, qaysi vaziyatda ishlatilishini va qanchalik norasmiy ekanini bilasiz. Idiomani so'zma-so'z tarjima qilmaysiz, uni o'zgartirmasdan aytasiz (on the head, a piece of cake) va nutqda me'yorida ishlatasiz.","words":[{"en":"a piece of cake","uz":"juda oson ish","ipa":"ə piːs əv keɪk"},{"en":"under the weather","uz":"o'zini yomon his qilmoq","ipa":"ˈʌn.də ðə ˈweð.ə"},{"en":"once in a blue moon","uz":"oyda-yilda bir, juda kamdan-kam","ipa":"wʌns ɪn ə bluː muːn"},{"en":"break the ice","uz":"muzni buzmoq, suhbatni boshlamoq","ipa":"breɪk ði aɪs"},{"en":"the last straw","uz":"sabr kosasini to'ldirgan oxirgi voqea","ipa":"ðə lɑːst strɔː"},{"en":"on the same page","uz":"bir fikrda, bir xil tushunchada","ipa":"ɒn ðə seɪm peɪdʒ"},{"en":"hit the nail on the head","uz":"aynan to'g'ri aytmoq","ipa":"hɪt ðə neɪl ɒn ðə hed"},{"en":"call it a day","uz":"bugungi ishni tugatmoq","ipa":"kɔːl ɪt ə deɪ"},{"en":"cost an arm and a leg","uz":"juda qimmat turmoq","ipa":"kɒst ən ɑːm ənd ə leg"},{"en":"the ball is in your court","uz":"navbat sizda, qaror sizniki","ipa":"ðə bɔːl ɪz ɪn jɔː kɔːt"}],"summary":["Idioma — o'zgarmas ibora, ma'nosi so'zlardan chiqmaydi: a piece of cake = juda oson, under the weather = o'zini yomon his qilmoq.","Idioma tarkibini o'zgartirib bo'lmaydi; faqat fe'l zamoni va olmosh o'zgaradi: It cost an arm and a leg.","Idiomalar asosan norasmiy nutqda ishlatiladi. Rasmiy yozuvda kam; Speaking da 1–2 ta o'rinli idioma yetarli.","Tipik xatolar: ~~hit the nail in the head~~ → on the head; ~~under weather~~ → under the weather; ~~call a day~~ → call it a day.","Idiomaning ma'nosini oling, inglizcha tasvirni o'zbekchaga so'zma-so'z ko'chirmang."]},{"id":"u30-l12","slug":"collocations-and-word-formation","title":"Collocations and word formation","titleUz":"So'z yasalishi va collocation: prefix, suffix, adj + noun, verb + noun","goal":"Prefiks va suffikslar yordamida bitta so'zdan butun so'z oilasini yasaysiz (depend → dependable → dependence), so'zning qaysi turkum ekanini taniysiz va kuchli collocationlarni to'g'ri ishlatasiz (make a decision, do research, heavy rain).","words":[{"en":"dependable","uz":"ishonchli, tayanch bo'ladigan","ipa":"dɪˈpen.də.bəl"},{"en":"improvement","uz":"yaxshilanish, taraqqiyot","ipa":"ɪmˈpruːv.mənt"},{"en":"disagreement","uz":"kelishmovchilik","ipa":"ˌdɪs.əˈɡriː.mənt"},{"en":"reinforce","uz":"mustahkamlamoq, kuchaytirmoq","ipa":"ˌriː.ɪnˈfɔːs"},{"en":"overcrowded","uz":"haddan tashqari gavjum","ipa":"ˌəʊ.vəˈkraʊ.dɪd"},{"en":"enlarge","uz":"kattalashtirmoq, kengaytirmoq","ipa":"ɪnˈlɑːdʒ"}],"summary":["Prefikslar ma'noni o'zgartiradi: un-, dis-, mis-, over-, under-, re-, mal-, en-.","Suffikslar turkumni o'zgartiradi: -able (sifat), -ment / -ness / -ity (ot), -ise (fe'l).","Kuchli collocation: make a decision / a mistake / progress; do research / homework / business; heavy rain.","Xatolar: do a mistake → make a mistake; strong rain → heavy rain; a research → some research.","Yangi so'zlar: dependable, improvement, disagreement, reinforce, overcrowded, enlarge."]},{"id":"u30-l2","slug":"ellipsis-substitution-and-avoiding-repetition","title":"Ellipsis, substitution and avoiding repetition","titleUz":"Ellipsis va almashtirish: so do I, neither am I, I think so, to avoid repetition","goal":"Gapni takrorlamasdan, tabiiy gapirasiz: So do I. Neither can I. I think so. I hope not. She can swim, but I can't. I'd love to. Ellipsis (tushirib qoldirish) va almashtirish (so, not, one, do so) qoidalarini bilasiz va Neither I can, I don't hope so kabi xatolardan qochasiz.","words":[{"en":"likewise","uz":"xuddi shunday, sizga ham","ipa":"ˈlaɪk.waɪz"},{"en":"same here","uz":"menda ham shunday","ipa":"seɪm hɪə"},{"en":"fair enough","uz":"to'g'ri aytasiz, mayli","ipa":"feər ɪˈnʌf"},{"en":"by all means","uz":"marhamat, albatta","ipa":"baɪ ɔːl miːnz"},{"en":"not necessarily","uz":"shart emas, har doim ham emas","ipa":"nɒt ˌnes.əˈser.əl.i"},{"en":"I'm afraid not","uz":"afsuski, yo'q","ipa":"aɪm əˈfreɪd nɒt"},{"en":"I suppose so","uz":"menimcha, shunday (ikkilanib)","ipa":"aɪ səˈpəʊz səʊ"},{"en":"I couldn't agree more","uz":"bunga to'liq qo'shilaman","ipa":"aɪ ˈkʊd.ənt əˈɡriː mɔː"},{"en":"no wonder","uz":"ajablanarli emas","ipa":"nəʊ ˈwʌn.də"},{"en":"that goes without saying","uz":"bu o'z-o'zidan ma'lum","ipa":"ðæt ɡəʊz wɪðˈaʊt ˈseɪ.ɪŋ"}],"summary":["«Men ham»: So + yordamchi fe'l + ega (So do I); inkorga: Neither / Nor + yordamchi fe'l + ega (Neither can I).","Yordamchi fe'l birinchi gapdagi zamon va fe'lga mos: I'm… → So am I; I've… → So have I; I went… → So did I.","Ellipsis: She can swim, but I can't. To-infinitivdan keyin to qoladi: I'd love to.","Qisqa javob: I think so / I don't think so; I hope so / I hope not; I'm afraid so / not. I don't hope so — xato.","One / ones sanaladigan otni almashtiradi: the red one, the cheap ones."]},{"id":"u30-l3","slug":"relative-clauses-advanced","title":"Relative clauses: advanced","titleUz":"Nisbiy gaplar B2: whose, of which, whom, qisqargan nisbiy gaplar, where / when / why","goal":"Nisbiy gaplarni B2 darajada ishlatasiz: whose, whom, to whom, some of whom, all of which, butun gapga qaytuvchi which, qisqargan shakllar (the man standing there, the book written by…) va where / when / why. The man who I spoke to him kabi xatodan qochasiz va vergulni to'g'ri qo'yasiz.","words":[{"en":"ancestor","uz":"ajdod, ota-bobo","ipa":"ˈæn.ses.tə"},{"en":"descendant","uz":"avlod, nasl","ipa":"dɪˈsen.dənt"},{"en":"mentor","uz":"murabbiy, ustoz","ipa":"ˈmen.tɔː"},{"en":"sibling","uz":"aka-uka yoki opa-singil","ipa":"ˈsɪb.lɪŋ"},{"en":"spouse","uz":"turmush o'rtog'i","ipa":"spaʊs"},{"en":"neighbouring","uz":"qo'shni (hudud, shahar)","ipa":"ˈneɪ.bər.ɪŋ"},{"en":"whereabouts","uz":"turgan joyi, qayerdaligi","ipa":"ˈweə.rə.baʊts"},{"en":"scholar","uz":"olim, ilmli kishi","ipa":"ˈskɒl.ə"},{"en":"pioneer","uz":"kashshof, yo'l ochuvchi","ipa":"ˌpaɪ.əˈnɪə"},{"en":"inheritance","uz":"meros","ipa":"ɪnˈher.ɪ.təns"}],"summary":["Whose + ot egalikni bildiradi (a man whose son…), her / his qo'shilmaydi. Whom to'ldiruvchi: to whom (rasmiy), the person I spoke to (norasmiy).","Which butun gapga qaytadi: He passed, which surprised us. Vergul majburiy. Vergulli gapda that yo'q.","Miqdor + of whom / of which: two of whom, all of which — guruhning bir qismi haqida.","Qisqargan shakllar: -ing (the man standing there), V3 (the book written by…), to-inf (the first to arrive).","Xatolar: ~~The man who I spoke to him~~; ~~the hotel where we stayed there~~; ~~whose her~~; ~~, what~~."]},{"id":"u30-l4","slug":"discourse-markers-in-speaking","title":"Discourse markers in speaking","titleUz":"Nutq belgilari: well, actually, as a matter of fact, to be honest, by the way","goal":"Gapirganda nutq belgilari (discourse markers) bilan fikrni boshlaysiz, o'ylash uchun vaqt olasiz, mavzuni o'zgartirasiz va gapni qisqartirasiz: well, I mean, to be honest, as a matter of fact, by the way, speaking of which, to cut a long story short. Pauzadagi «eee…» o'rniga tayyor iboralarni aytasiz va actually ni noto'g'ri ishlatmaysiz.","words":[{"en":"as a matter of fact","uz":"aslida, to'g'risi","ipa":"æz ə ˈmæt.ər əv fækt"},{"en":"come to think of it","uz":"eslasam, o'ylab ko'rsam","ipa":"kʌm tə θɪŋk əv ɪt"},{"en":"mind you","uz":"biroq, shunga qaramay","ipa":"maɪnd juː"},{"en":"speaking of which","uz":"gap shu haqda ketganda","ipa":"ˈspiː.kɪŋ əv wɪtʃ"},{"en":"to cut a long story short","uz":"uzoq cho'zmay aytganda","ipa":"tə kʌt ə lɒŋ ˈstɔː.ri ʃɔːt"},{"en":"filler","uz":"to'ldiruvchi so'z («eee», «ya'ni»)","ipa":"ˈfɪl.ə"},{"en":"on second thoughts","uz":"qayta o'ylab ko'rsam","ipa":"ɒn ˈsek.ənd θɔːts"},{"en":"to be fair","uz":"adolat uchun aytsam","ipa":"tə bi feə"},{"en":"what I mean is","uz":"aytmoqchi bo'lganim","ipa":"wɒt aɪ miːn ɪz"},{"en":"to put it another way","uz":"boshqacha aytganda","ipa":"tə pʊt ɪt əˈnʌð.ə weɪ"}],"summary":["Nutq belgilari suhbatni ravon qiladi: o'ylash uchun well, let me think; rostini aytish uchun to be honest, to be fair; aniqlashtirish uchun what I mean is.","Actually / as a matter of fact = aslida. «Hozir» ma'nosida emas: u uchun currently / at the moment / nowadays.","Mavzuni boshqarish: by the way, speaking of which (bog'liq mavzu), anyway, on second thoughts, to cut a long story short.","Tayyor iboralarda artikl va predlog o'zgarmaydi: ~~as matter of fact~~, ~~to cut long story short~~, ~~speaking about which~~, ~~to say the truth~~.","Ortiqcha ishlatmang: har gapda you know yoki I mean nutqni sun'iy qiladi."]},{"id":"u30-l13","slug":"question-forms-indirect-negative-and-echo","title":"Question forms: indirect, negative and echo","titleUz":"Savol shakllari: indirect, negative, echo savollar","goal":"Indirect (Do you know where…?), negative (Isn't it…?), echo (Is she?) va subject (Who called you?) savollarini to'g'ri tuzasiz, tagni buyruq va inkor gap bilan ishlatasiz hamda ohang orqali muloyimlik va hayratni ifodalaysiz.","words":[{"en":"curious","uz":"qiziquvchan, qiziqib turgan","ipa":"ˈkjʊə.ri.əs"},{"en":"puzzled","uz":"hayron, boshi qotgan","ipa":"ˈpʌz.əld"},{"en":"rhetorical","uz":"ritorik (javob kutilmaydigan)","ipa":"rɪˈtɒr.ɪ.kəl"},{"en":"probe","uz":"sinchiklab so'ramoq, chuqur surishtirmoq","ipa":"prəʊb"},{"en":"bluntly","uz":"dangal, dag'allik bilan","ipa":"ˈblʌnt.li"}],"summary":["Indirect savol: Could you tell me where the station is? Darak tartibi, do/does/did yo'q; ha/yo'q uchun if / whether.","Subject savol: Who called you? (so'roq so'zi ega), did kerak emas.","Negative savol: Isn't it…? Don't you think…? Javob faktga qarab: Yes, it is. / No, it isn't.","Echo savol: She's moving. — Is she? Yordamchi fe'l gapdagidek. Tag: Open it, will you? Let's go, shall we? Nobody came, did they?","Yangi so'zlar: curious, puzzled, rhetorical, probe, bluntly."]},{"id":"u30-l9","slug":"talking-about-culture-and-traditions","title":"Talking about culture and traditions","titleUz":"Madaniyat va an'analar haqida suhbat: o'z mamlakatingizni tushuntirish","goal":"Chet ellik do'stingizga Navro'z, palov, to'y kabi an'anani tushuntirasiz: nima, qachon, kim bilan va nima uchun qilinishini aytasiz, whose / where / which bilan jumlani boyitasiz va noto'g'ri tushunchani muloyim tuzatasiz.","words":[{"en":"ritual","uz":"marosim, odat tusiga kirgan harakat","ipa":"ˈrɪtʃ.u.əl"},{"en":"heirloom","uz":"avloddan avlodga o'tadigan qimmatli buyum, oilaviy yodgorlik","ipa":"ˈeə.luːm"},{"en":"gathering","uz":"yig'ilish, yig'in","ipa":"ˈɡæð.ər.ɪŋ"},{"en":"symbolise","uz":"ramziy ma'no bermoq, ifodalamoq","ipa":"ˈsɪm.bəl.aɪz"},{"en":"customary","uz":"odatiy, an'anaga ko'ra qabul qilingan","ipa":"ˈkʌs.tə.mər.i"},{"en":"festive","uz":"bayramona","ipa":"ˈfes.tɪv"}],"summary":["Madaniyatni tushuntirishda nima + ma'no + tarix + hozirgi holat ni ayting: symbolise, passed down, customary, These days…","Gapni boyiting: whose (a man whose family…), where (a yard where…), , which (butun gapga ishora).","Xato: who his family, where … there, that vergulli gapda. To'g'risi: whose family, where, , which.","Bayramlar haqida majhul nisbat ishlating: is celebrated, is cooked, has been passed down.","Muloyim tuzatish: Not exactly… It is actually…, That is a common idea, but in fact…"]},{"id":"u30-l5","slug":"arts-culture-and-travel","title":"Arts, culture and travel","titleUz":"San'at, madaniyat va sayohat: so'zlar va birikmalar","goal":"San'at, madaniyat va sayohat haqida B2 darajada gapirasiz va yozasiz: exhibition, masterpiece, customs, folklore, craftsmanship, breathtaking, vibrant, steeped in history, overrated, restore. Collocation larni (hold an exhibition, restore a painting, a vibrant atmosphere) to'g'ri ishlatasiz va customs / custom, folklore (sanalmaydigan ot) kabi xatolardan qochasiz.","words":[{"en":"exhibition","uz":"ko'rgazma","ipa":"ˌek.sɪˈbɪʃ.ən"},{"en":"masterpiece","uz":"durdona asar","ipa":"ˈmɑː.stə.piːs"},{"en":"customs","uz":"urf-odatlar; bojxona","ipa":"ˈkʌs.təmz"},{"en":"folklore","uz":"folklor, xalq og'zaki ijodi","ipa":"ˈfəʊk.lɔː"},{"en":"breathtaking","uz":"nafasni qaytaradigan darajada go'zal","ipa":"ˈbreθˌteɪ.kɪŋ"},{"en":"vibrant","uz":"jonli, rang-barang","ipa":"ˈvaɪ.brənt"},{"en":"steeped in history","uz":"tarixga boy","ipa":"stiːpt ɪn ˈhɪs.tər.i"},{"en":"craftsmanship","uz":"hunarmandlik mahorati","ipa":"ˈkrɑːfts.mən.ʃɪp"},{"en":"overrated","uz":"haddan tashqari maqtalgan","ipa":"ˌəʊ.vəˈreɪ.tɪd"},{"en":"restore","uz":"tiklamoq, restavratsiya qilmoq","ipa":"rɪˈstɔː"}],"summary":["San'at: exhibition (ko'rgazma), masterpiece (durdona), craftsmanship (mahorat, sanalmaydi), restore (tiklamoq).","Madaniyat: customs (odat-urf; the customs officer — bojxona), folklore (sanalmaydi, folklores emas).","Baho: breathtaking (kuchli sifat), vibrant (jonli), steeped in history (tarixga boy), overrated (haddan tashqari maqtalgan).","Collocation: hold / stage / put on an exhibition, stage a performance, restore a painting; make an exhibition — xato.","Predlog: ~~steeped on history~~ → steeped in history."]},{"id":"u30-l6","slug":"telling-a-story-and-giving-a-long-answer","title":"Telling a story and giving a long answer","titleUz":"Hikoya qilish va uzun javob berish: IELTS Part 2 uslubi (2 daqiqa)","goal":"2 daqiqalik uzun javobni (IELTS Speaking Part 2, ish suhbati, tanishuv) tuzasiz: kirish, voqea, tafsilot, his-tuyg'u va xulosa. To'g'ri hikoya zamonlari (Past Simple, Past Continuous, Past Perfect), bog'lovchilar, nutq belgilari va 1–2 ta idiomadan foydalanasiz. Pauzada vaqt olasiz va I have visited … last year, I was very exciting kabi xatolardan qochasiz.","words":[{"en":"overwhelmed","uz":"ta'sirlanib ketgan, hayajondan ezilgan","ipa":"ˌəʊ.vəˈwelmd"},{"en":"vividly","uz":"jonli, ravshan","ipa":"ˈvɪv.ɪd.li"},{"en":"stick in my mind","uz":"esimda qolmoq","ipa":"stɪk ɪn maɪ maɪnd"},{"en":"look back on","uz":"o'tmishga nazar tashlamoq","ipa":"lʊk bæk ɒn"},{"en":"it dawned on me","uz":"birdan xayolimga keldi","ipa":"ɪt dɔːnd ɒn miː"},{"en":"out of the blue","uz":"kutilmaganda","ipa":"aʊt əv ðə bluː"},{"en":"dramatic","uz":"keskin, kuchli o'zgargan","ipa":"drəˈmæt.ɪk"},{"en":"stumble upon","uz":"tasodifan topib olmoq","ipa":"ˈstʌm.bəl əˌpɒn"},{"en":"a sense of achievement","uz":"erishgan narsadan qoniqish","ipa":"ə sens əv əˈtʃiːv.mənt"},{"en":"literally","uz":"so'zma-so'z, haqiqatan","ipa":"ˈlɪt.ər.əl.i"}],"summary":["Uzun javob 5 qadam: kirish, nima/qachon/kim, tafsilot, his-tuyg'u, nega muhim. 2 daqiqa taxminan 250–300 so'z.","Hikoya zamonlari: Past Simple (voqea), Past Continuous (fon), Past Perfect (oldin bo'lgan); xulosa — Present.","Bog'lovchilar: at first, then, after a while, by the time, in the end; fikr: looking back, what struck me…","Pauza uchun: Let me see… It's a kind of… Anyway, where was I?; 1–2 ta idioma yetarli (out of the blue).","Xatolar: ~~I go~~ → went; ~~have visited last year~~ → visited; ~~very exciting~~ → excited; ~~tell about~~ → tell you about."]},{"id":"u30-l14","slug":"listening-and-speaking-a-long-turn","title":"Listening and speaking: a long turn","titleUz":"Tinglash va gapirish: 2 daqiqalik nutq (cue card)","goal":"Ikkita namunaviy 2 daqiqalik javobni tinglab, ularning tuzilishini (kirish, tafsilot, his-tuyg'u, xulosa) ajratasiz, vaqt yutish va bog'lash iboralarini bilasiz hamda Describe a place you would like to visit kartasi bo'yicha o'zingiz ovoz chiqarib javob berasiz.","words":[{"en":"tranquil","uz":"sokin, tinch","ipa":"ˈtræŋ.kwɪl"},{"en":"fascinated","uz":"mahliyo bo'lgan, juda qiziqib qolgan","ipa":"ˈfæs.ɪ.neɪ.tɪd"},{"en":"yearn","uz":"sog'inib orzu qilmoq (for bilan)","ipa":"jɜːn"},{"en":"immerse","uz":"sho'ng'itmoq, to'liq berilmoq","ipa":"ɪˈmɜːs"},{"en":"awe-inspiring","uz":"hayratga soladigan, ulug'vor","ipa":"ˈɔː.ɪn.spaɪə.rɪŋ"}],"summary":["Cue card: bir daqiqa tayyorlanasiz, ikki daqiqa to'xtamay gapirasiz.","Tuzilma: kirish → tafsilot → his-tuyg'u → sabab → yakun.","Foydali iboralar: I'd like to talk about…, First of all…, To be honest…, The reason is that…, To sum up…","Xatolar: aniq vaqt + Past Simple (I visited…last year); fascinated by; to'xtab qolmang, Well, let me think… deng.","Yangi so'zlar: tranquil, fascinated, yearn, immerse, awe-inspiring."]},{"id":"u30-l10","slug":"giving-and-responding-to-a-presentation","title":"Giving and responding to a presentation","titleUz":"Taqdimot qilish va savollarga javob berish","goal":"3 daqiqalik taqdimotni ochasiz, signposting iboralari bilan (I'll start by…, Moving on to…) tartibli olib borasiz, xulosa qilasiz va tinglovchilarning savollariga, jumladan qiyin savolga ham, xotirjam javob berasiz.","words":[{"en":"overview","uz":"umumiy ko'rinish, qisqacha tavsif","ipa":"ˈəʊ.və.vjuː"},{"en":"signpost","uz":"(nutqda) yo'l ko'rsatmoq, rejani oldindan aytmoq","ipa":"ˈsaɪn.pəʊst"},{"en":"elaborate","uz":"batafsil tushuntirmoq (on bilan)","ipa":"ɪˈlæb.ə.reɪt"},{"en":"recap","uz":"qisqacha takrorlamoq","ipa":"ˈriː.kæp"},{"en":"concise","uz":"qisqa va aniq","ipa":"kənˈsaɪs"},{"en":"clarify","uz":"aniqlashtirmoq","ipa":"ˈklær.ɪ.faɪ"}],"summary":["Taqdimot tuzilishi: ochish → reja → qismlar → xulosa → savollar.","Signposting: I'll start by…, Moving on to…, That brings me to…, To sum up…","elaborate on, clarify what…, recap — aniq va professional so'zlar. attention sanalmaydi.","Qiyin savolda: That's a good point. Let me think… I'll check and get back to you. Hech qachon to'qimang.","Yangi so'zlar: overview, signpost, elaborate, recap, concise, clarify."]},{"id":"u30-l7","slug":"writing-a-review-or-a-story-b2-final-task","title":"Writing: a review or a story (B2 final task)","titleUz":"Yozish: sharh va hikoya (B2 yakuniy topshirig'i)","goal":"B2 yakuniy yozma topshirig'ini bajarasiz: kitob, film yoki joy haqida 250 so'zli sharh (review) yoki berilgan birinchi gap bo'yicha hikoya. Tuzilma (kirish, mazmun, baho, kamchilik, tavsiya), tavsifiy so'zlar (gripping, convincing, thought-provoking), balansli baho (although, despite, admittedly) va o'z ishingizni B2 tekshiruv ro'yxati bo'yicha baholashni o'rganasiz.","words":[{"en":"gripping","uz":"diqqatni tortadigan","ipa":"ˈɡrɪp.ɪŋ"},{"en":"predictable","uz":"oldindan bilinadigan","ipa":"prɪˈdɪk.tə.bəl"},{"en":"thought-provoking","uz":"o'ylantiradigan","ipa":"ˈθɔːt prəˌvəʊ.kɪŋ"},{"en":"well-paced","uz":"sur'ati to'g'ri tanlangan","ipa":"ˌwel ˈpeɪst"},{"en":"storyline","uz":"syujet chizig'i","ipa":"ˈstɔː.ri.laɪn"},{"en":"portray","uz":"tasvirlamoq, rolni ijro etmoq","ipa":"pɔːˈtreɪ"},{"en":"convincing","uz":"ishonarli","ipa":"kənˈvɪn.sɪŋ"},{"en":"cast","uz":"aktyorlar tarkibi","ipa":"kɑːst"},{"en":"soundtrack","uz":"film musiqasi","ipa":"ˈsaʊnd.træk"},{"en":"highly recommended","uz":"qattiq tavsiya etiladi","ipa":"ˈhaɪ.li ˌrek.əˈmen.dɪd"}],"summary":["Sharh tuzilmasi: kirish → mazmun → baho → kamchilik → tavsiya; hikoya: boshlanish → rivojlanish → kulminatsiya → yechim.","Sharh so'zlari: gripping, predictable, thought-provoking, well-paced, storyline, portray, convincing, cast, soundtrack, highly recommended.","Muvozanat: although + gap, despite + ot / -ing, however, admittedly, on the whole. Although … but va despite of — xato.","Xatolar: ~~recommend to read~~ → recommend reading / that you read; ~~tells about~~ → tells the story of; ~~played very good~~ → played well.","O'zingizni tekshiring: mazmun, tuzilma, lug'at, bog'lovchilar, aniqlik; hajm 230–270 so'z."]},{"id":"u30-l15","slug":"reading-and-writing-an-article-about-travel","title":"Reading and writing: an article about travel","titleUz":"O'qish va yozish: sayohat maqolasi","goal":"Sayohat maqolasini o'qib, umumiy ma'no, tafsilot va muallifning fikri savollariga javob berasiz, idioma va bog'lovchilarni (however, admittedly, provided that) tanib olasiz va mehmonga 100-120 so'zli tavsiya yozasiz.","words":[{"en":"must-see","uz":"albatta ko'rish kerak bo'lgan","ipa":"ˈmʌst.siː"},{"en":"tourist trap","uz":"sayyohlar tuzog'i (qimmat, olomon joy)","ipa":"ˈtʊə.rɪst træp"},{"en":"cobbled","uz":"toshyo'l bilan qoplangan","ipa":"ˈkɒb.əld"},{"en":"hidden gem","uz":"yashirin durdona (kam tanilgan yaxshi joy)","ipa":"ˌhɪd.ən ˈdʒem"},{"en":"word of mouth","uz":"og'izdan-og'izga o'tgan gap","ipa":"ˌwɜːd əv ˈmaʊθ"},{"en":"unspoilt","uz":"buzilmagan, tabiiy holida qolgan","ipa":"ʌnˈspɔɪlt"}],"summary":["Maqolada uch turdagi savol: gist (asosiy fikr), detail (tafsilot), writer's opinion (muallifning fikri: in my opinion…).","Iboralar: off the beaten track, by word of mouth, a hidden gem, a tourist trap; bog'lovchilar: admittedly, even so, however, provided that, whatever.","Tavsiya (100-120 so'z): asosiy maslahat → nima qilish → amaliy maslahat → sabab va yakun.","Xatolar: ~~despite of~~ → despite; ~~recommend to go~~ → recommend going / that you go.","Yangi so'zlar: must-see, tourist trap, cobbled, hidden gem, word of mouth, unspoilt."]},{"id":"u30-l8","slug":"unit-review-the-whole-upper-intermediate-level","title":"Unit review: the whole Upper-Intermediate level","titleUz":"Bosqich takrori: butun Upper-Intermediate darajasi","goal":"Butun Upper-Intermediate (B2) bosqichini takrorlaysiz: zamonlar, aralash shart gaplar va wish, passive va reported speech, rasmiy uslub, cleft va inversion, taqqoslash va miqdor, hamda bu bosqichdagi idioma, ellipsis, nisbiy gap va nutq belgilari. Yangi misollarda o'zingizni tekshirasiz va tipik xatolarni tuzatasiz.","words":[{"en":"proficiency","uz":"mahorat, malaka darajasi","ipa":"prəˈfɪʃ.ən.si"},{"en":"fluency","uz":"ravonlik","ipa":"ˈfluː.ən.si"},{"en":"hurdle","uz":"to'siq, qiyinchilik","ipa":"ˈhɜː.dəl"},{"en":"persevere","uz":"qat'iyat bilan davom etmoq","ipa":"ˌpɜː.sɪˈvɪə"},{"en":"consolidate","uz":"mustahkamlamoq","ipa":"kənˈsɒl.ɪ.deɪt"},{"en":"accuracy","uz":"aniqlik, to'g'rilik","ipa":"ˈæk.jər.ə.si"},{"en":"self-assessment","uz":"o'z-o'zini baholash","ipa":"ˌself əˈses.mənt"},{"en":"range","uz":"doira, xilma-xillik","ipa":"reɪndʒ"},{"en":"keep up with","uz":"ulgurib bormoq, hamnafas bo'lmoq","ipa":"kiːp ʌp wɪð"},{"en":"refine","uz":"takomillashtirmoq, sayqal bermoq","ipa":"rɪˈfaɪn"}],"summary":["u24–u25: Past Perfect / Perfect Continuous, Future Perfect, aralash shartlar, wish, must / can't + have + V3; if dan keyin would yo'q.","u26–u27: passive (barcha zamonlar), reporting passive, causative, reported speech, gerund / infinitive (suggest + -ing), rasmiy uslub va majburiyat.","u28–u29: cleft, inversion (Never have I…), concession, cause/result, taqqoslash (the more… the better), miqdor so'zlari, artikl.","u30: idiomalar, ellipsis (So do I / Neither can I), nisbiy gaplar (whose, of whom, which), nutq belgilari, uzun javob va sharh.","Tipik xatolar: ~~If I would have~~, ~~suggested to go~~, ~~more better~~, ~~Never I have~~, ~~the man who I spoke to him~~."]},{"id":"u30-l11","slug":"upper-intermediate-final-review","title":"Upper-Intermediate: final review","titleUz":"Upper-Intermediate: yakuniy takror","goal":"Butun B2 bosqichini imtihondan oldin qisqa takrorlaysiz: zamonlar, shart gaplar, majhul nisbat, ta'kid, solishtirish, nisbiy gaplar, ellipsis, savol shakllari va mashq uchun o'qish, tinglash, yozish strategiyasi.","words":[{"en":"brush up on","uz":"(bilimni) yangilab olmoq, qayta takrorlamoq","ipa":"brʌʃ ʌp ɒn"},{"en":"thorough","uz":"puxta, har tomonlama to'liq","ipa":"ˈθʌr.ə"},{"en":"nuance","uz":"nozik farq, ma'no ottenkasi","ipa":"ˈnjuː.ɑːns"},{"en":"proficient","uz":"mohir, yetarlicha malakali","ipa":"prəˈfɪʃ.ənt"},{"en":"stamina","uz":"chidamlilik","ipa":"ˈstæm.ɪ.nə"}],"summary":["Zamonlar va shartlar: have been doing, had done, 3-shart (if + had done, would have done), aralash shart, wish + Past Perfect.","Ta'kid va solishtirish: What I need is…, Never have I…, the more…, the more….","Bu bosqich: so do I / neither can I, whose / qisqargan nisbiy gap, to be honest, Could you tell me where…?, idioma va collocation.","Imtihonda: reja tuzing, kalit so'zlarni belgilang, oxirida tekshiring; puxta tayyorgarlik (thorough) va chidamlilik (stamina) ikkalasi muhim.","Yangi so'zlar: brush up on, thorough, nuance, proficient, stamina."]}]}]}];
